// PauseMenu.js — vanilla-style "Game Menu" (Esc) with Options sub-screens.
//
// Layout follows the vanilla GUI grid: 200x20 buttons (98 wide when paired),
// 24 px row pitch, centred title, dark translucent backdrop. Sliders show
// "Label: value" on the bar with a handle 8 px wide. Everything is measured in
// GUI pixels (--u, set by McHud from the vanilla Auto GUI-scale rule).
//
// Replaces the old tabbed SettingsMenu but keeps its interface (isOpen,
// open, close, toggle) so every `game.settingsMenu?.isOpen` guard still works.

const STORE = 'deadlocked.options';
const DEFAULTS = {
  fov: 70, master: 0.8, music: 0.6, sfx: 0.8, sens: 1, invertY: false,
  renderDist: 8, brightness: 0.5, guiScale: 0, bob: true, showFps: false,
};

const KEYS = [
  ['Movement', null],
  ['Walk Forwards', 'W'], ['Walk Backwards', 'S'], ['Strafe Left', 'A'], ['Strafe Right', 'D'],
  ['Jump', 'Space'], ['Sneak', 'Left Shift'], ['Sprint', 'Left Control'],
  ['Gameplay', null],
  ['Attack/Destroy', 'Left Button'], ['Use Item/Place Block', 'Right Button'],
  ['Interact / Swap Offhand', 'F'], ['Reload', 'R'], ['Drop Selected Item', 'Q'],
  ['Inventory', null],
  ['Open/Close Inventory', 'E'], ['Hotbar Slots', '1 - 9'], ['Scroll Hotbar', 'Mouse Wheel'],
  ['Miscellaneous', null],
  ['Open Chat', 'T'], ['Open Command', '/'], ['World Map', 'M'],
  ['Hide HUD', 'F1'], ['Debug Screen', 'F3'], ['Pause', 'Escape'],
];

export class PauseMenu {
  constructor(game) {
    this.game = game;
    this.isOpen = false;
    this.screen = null;
    this.fromTitle = false;
    this.opts = { ...DEFAULTS, ...this._load() };
    game.options = this.opts;

    this.root = document.createElement('div');
    this.root.id = 'mc-pause';
    this.root.style.display = 'none';
    document.body.appendChild(this.root);

    this.applyAll();
    this._bindKeys();
  }

  // ── persistence + live application ──────────────────────────────────────
  _load() { try { return JSON.parse(localStorage.getItem(STORE)) || {}; } catch { return {}; } }
  _save() { try { localStorage.setItem(STORE, JSON.stringify(this.opts)); } catch {} }

  set(key, v) { this.opts[key] = v; this._save(); this.apply(key); }

  applyAll() { for (const k of Object.keys(DEFAULTS)) this.apply(k); }

  apply(key) {
    const g = this.game, o = this.opts;
    const am = g.audioManager;
    switch (key) {
      case 'fov': {
        g.baseFov = o.fov;
        const cam = g.scene?.getCamera?.();
        if (cam && !g._adsActive) { cam.fov = o.fov; cam.updateProjectionMatrix(); }
        break;
      }
      case 'master': am?.setMasterVolume?.(o.master); break;
      case 'music': am?.setMusicVolume?.(o.music); break;
      case 'sfx': am?.setSFXVolume?.(o.sfx); break;
      case 'sens': g.settings?.set?.('controls.mouseSensitivity', o.sens); break;
      case 'invertY': g.settings?.set?.('controls.invertY', o.invertY); break;
      case 'renderDist': if (g.voxelWorld) g.voxelWorld.radius = o.renderDist; break;
      case 'brightness': {
        const r = g.scene?.renderer; if (r) r.toneMappingExposure = 0.78 + o.brightness * 0.28;
        break;
      }
      case 'guiScale': window.__mcGuiScale = o.guiScale; dispatchEvent(new Event('resize')); break;
      case 'showFps': {
        const el = document.getElementById('fps-display'); if (el) el.style.display = o.showFps ? 'block' : 'none';
        break;
      }
    }
  }

  // ── Esc handling ─────────────────────────────────────────────────────────
  // One capture-phase handler decides before any other UI's listener runs, so
  // an Esc that closes the inventory/chat/map never also opens this menu.
  _otherUiOpen() {
    const g = this.game;
    if (g.inventorySystem?.isOpen || g.commandSystem?.isOpen || g.craftingSystem?.isOpen) return true;
    if (g.minimapRenderer?._fullMapEl || g.inCutscene) return true;
    if (document.getElementById('perk-tree-overlay') || document.getElementById('stats-screen')) return true;
    if (g.dialogueSystem?.isDialogueActive) return true;
    const dlg = document.getElementById('npc-dialog');
    if (dlg && getComputedStyle(dlg).display !== 'none') return true;
    const ds = document.getElementById('death-screen');
    if (ds && ds.style.display !== 'none' && ds.style.display !== '') return true;
    if (document.activeElement?.tagName === 'INPUT' && !this.root.contains(document.activeElement)) return true;
    return false;
  }

  _inWorld() { return !!(this.game.isRunning && this.game.player); }

  _bindKeys() {
    addEventListener('keydown', (e) => {
      if (e.key !== 'Escape') return;
      if (this.isOpen) {
        e.preventDefault(); e.stopImmediatePropagation();
        if (this.screen === 'game' || this.fromTitle && this.screen === 'options') this.close();
        else this.show(this._parent(this.screen));
        return;
      }
      if (!this._inWorld() || this._otherUiOpen()) return;
      e.preventDefault(); e.stopImmediatePropagation();
      this.open();
    }, true);

    // The browser consumes the Esc that releases pointer lock (no keydown
    // reaches the page), so losing the lock mid-game opens the menu, like
    // vanilla pausing on focus loss.
    document.addEventListener('pointerlockchange', () => {
      if (document.pointerLockElement) return;
      setTimeout(() => {
        if (document.pointerLockElement || this.isOpen || !this._inWorld()) return;
        if (this.game.isPaused || this._otherUiOpen()) return;
        this.open();
      }, 60);
    });
    addEventListener('blur', () => {
      if (!this.isOpen && this._inWorld() && !this.game.isPaused && !this._otherUiOpen()) this.open();
    });
  }

  _parent(s) {
    return { options: 'game', video: 'options', sound: 'options', controls: this._ctlBack || 'options',
      stats: 'game', achievements: 'game' }[s] || 'game';
  }

  // ── open / close (SettingsMenu-compatible) ────────────────────────────────
  open() {
    if (this.isOpen) return;
    this.fromTitle = !this._inWorld();
    this.isOpen = true;
    this.root.style.display = 'flex';
    this.root.classList.toggle('from-title', this.fromTitle);
    this.game.inputManager?.exitPointerLock?.();
    if (!this.fromTitle) this.game.pause();
    this.show(this.fromTitle ? 'options' : 'game');
  }

  close() {
    if (!this.isOpen) return;
    this.isOpen = false;
    this.root.style.display = 'none';
    this.root.innerHTML = '';
    if (this.fromTitle) {
      document.getElementById('main-menu')?.classList.remove('hidden');
      return;
    }
    this.game.resume();
    this.game.inputManager?.requestPointerLock?.();
  }

  toggle() { this.isOpen ? this.close() : this.open(); }

  // ── widgets ──────────────────────────────────────────────────────────────
  _btn(label, onClick, { wide = false, disabled = false } = {}) {
    const b = document.createElement('button');
    b.className = 'mcp-btn' + (wide ? ' wide' : '');
    b.textContent = label;
    b.disabled = disabled;
    b.addEventListener('click', (e) => { e.stopPropagation(); if (!b.disabled) { this._click(); onClick(); } });
    return b;
  }

  _toggle(label, key, fmt = (v) => (v ? 'ON' : 'OFF'), values = null, wide = false) {
    const b = this._btn('', () => {
      const v = this.opts[key];
      const next = values ? values[(values.indexOf(v) + 1) % values.length] : !v;
      this.set(key, next); b.textContent = `${label}: ${fmt(next)}`;
    }, { wide });
    b.textContent = `${label}: ${fmt(this.opts[key])}`;
    return b;
  }

  _slider(label, key, min, max, step, fmt, wide = false) {
    const el = document.createElement('div');
    el.className = 'mcp-slider' + (wide ? ' wide' : '');
    el.innerHTML = '<div class="mcp-handle"></div><span></span>';
    const handle = el.firstChild, text = el.lastChild;
    const render = () => {
      const t = (this.opts[key] - min) / (max - min);
      handle.style.left = `calc(${t} * (100% - var(--u) * 8))`;
      text.textContent = `${label}: ${fmt(this.opts[key])}`;
    };
    const setFrom = (clientX) => {
      const r = el.getBoundingClientRect(), hw = r.width * 8 / (wide ? 310 : 150);
      const t = Math.max(0, Math.min(1, (clientX - r.left - hw / 2) / (r.width - hw)));
      let v = min + t * (max - min);
      v = Math.round(v / step) * step;
      v = +Math.max(min, Math.min(max, v)).toFixed(4);
      if (v !== this.opts[key]) { this.set(key, v); render(); }
    };
    el.addEventListener('pointerdown', (e) => {
      e.preventDefault(); el.setPointerCapture(e.pointerId); el.classList.add('drag'); setFrom(e.clientX);
      const move = (ev) => setFrom(ev.clientX);
      const up = () => { el.classList.remove('drag'); el.removeEventListener('pointermove', move); el.removeEventListener('pointerup', up); this._click(); };
      el.addEventListener('pointermove', move); el.addEventListener('pointerup', up);
    });
    render();
    return el;
  }

  _row(...items) {
    const r = document.createElement('div');
    r.className = 'mcp-row';
    items.forEach((i) => i && r.appendChild(i));
    return r;
  }

  _click() { try { this.game.audioManager?.playClick?.(); } catch {} }

  _frame(title, { list = false } = {}) {
    this.root.innerHTML = '';
    this.root.className = list ? 'list' : '';
    this.root.classList.toggle('from-title', this.fromTitle);
    const h = document.createElement('div'); h.className = 'mcp-title'; h.textContent = title;
    const body = document.createElement('div'); body.className = list ? 'mcp-list' : 'mcp-body';
    const foot = document.createElement('div'); foot.className = 'mcp-foot';
    this.root.append(h, body, foot);
    return { body, foot };
  }

  _done(foot, to) { foot.appendChild(this._btn('Done', () => (to ? this.show(to) : this.close()), { wide: true })); }

  // ── screens ──────────────────────────────────────────────────────────────
  show(screen) {
    this.screen = screen;
    this[`_screen_${screen}`]();
  }

  _screen_game() {
    const { body } = this._frame('Game Menu');
    this.root.classList.add('game');
    body.append(
      this._row(this._btn('Back to Game', () => this.close(), { wide: true })),
      this._row(this._btn('Achievements', () => this.show('achievements')), this._btn('Statistics', () => this.show('stats'))),
      this._row(this._btn('Options...', () => this.show('options')), this._btn('Controls...', () => { this._ctlBack = 'game'; this.show('controls'); })),
      this._row(this._btn('Credits', () => this.show('credits'), { wide: true })),
      this._gap(),
      this._row(this._btn('Save and Quit to Title', () => this._saveAndQuit(), { wide: true })),
    );
  }

  _saveAndQuit() {
    this._frame('Saving world');
    this.root.classList.add('saving');
    try { this.game.saveGame?.(); } catch {}
    setTimeout(() => this.game.quitToMenu(), 350);
  }

  _gap() { const d = document.createElement('div'); d.className = 'mcp-gap'; return d; }

  _screen_options() {
    const { body, foot } = this._frame('Options');
    const fov = (v) => (v === 70 ? 'Normal' : v === 110 ? 'Quake Pro' : String(v));
    body.append(
      this._row(this._slider('FOV', 'fov', 30, 110, 1, fov), this._toggle('View Bobbing', 'bob')),
      this._gap(),
      this._row(this._btn('Music & Sounds...', () => this.show('sound')), this._btn('Video Settings...', () => this.show('video'))),
      this._row(this._btn('Controls...', () => { this._ctlBack = 'options'; this.show('controls'); }), this._btn('Reset to Defaults', () => {
        Object.assign(this.opts, DEFAULTS); this._save(); this.applyAll(); this.show('options');
      })),
    );
    this._done(foot, this.fromTitle ? null : 'game');
  }

  _screen_sound() {
    const { body, foot } = this._frame('Music & Sound Options');
    const pct = (v) => (v <= 0 ? 'OFF' : Math.round(v * 100) + '%');
    body.append(
      this._row(this._slider('Master Volume', 'master', 0, 1, 0.01, pct, true)),
      this._row(this._slider('Music', 'music', 0, 1, 0.01, pct), this._slider('Sounds', 'sfx', 0, 1, 0.01, pct)),
    );
    this._done(foot, 'options');
  }

  _screen_video() {
    const { body, foot } = this._frame('Video Settings');
    const bright = (v) => (v <= 0 ? 'Moody' : v >= 1 ? 'Bright' : Math.round(v * 100) + '%');
    const gui = (v) => (v ? String(v) : 'Auto');
    body.append(
      this._row(this._slider('Render Distance', 'renderDist', 2, 12, 1, (v) => `${v} chunks`),
        this._slider('Brightness', 'brightness', 0, 1, 0.01, bright)),
      this._row(this._toggle('GUI Scale', 'guiScale', gui, [0, 1, 2, 3, 4]), this._toggle('View Bobbing', 'bob')),
      this._row(this._toggle('Show FPS', 'showFps'), this._slider('FOV', 'fov', 30, 110, 1, (v) => (v === 70 ? 'Normal' : String(v)))),
    );
    this._done(foot, 'options');
  }

  _screen_controls() {
    const { body, foot } = this._frame('Controls', { list: true });
    const x = (v) => Math.round(v * 100) + '%';
    const top = this._row(this._slider('Sensitivity', 'sens', 0.1, 3, 0.01, x), this._toggle('Invert Mouse', 'invertY'));
    top.classList.add('mcp-head');
    this.root.insertBefore(top, body);
    for (const [name, key] of KEYS) {
      const r = document.createElement('div');
      if (!key) { r.className = 'mcp-cat'; r.textContent = name; }
      else { r.className = 'mcp-key'; r.innerHTML = `<span></span><b></b>`; r.firstChild.textContent = name; r.lastChild.textContent = key; }
      body.appendChild(r);
    }
    this._done(foot, this.fromTitle ? 'options' : (this._ctlBack || 'options'));
  }

  _screen_stats() {
    const { body, foot } = this._frame('Statistics', { list: true });
    const g = this.game, p = g.player;
    const t = Math.floor((Date.now() - (g._sessionStartTime || g.survivalStartTime || Date.now())) / 1000);
    const hms = `${Math.floor(t / 3600)}:${String(Math.floor(t / 60) % 60).padStart(2, '0')}:${String(t % 60).padStart(2, '0')}`;
    const km = (m) => (m >= 1000 ? (m / 1000).toFixed(2) + ' km' : m.toFixed(1) + ' m');
    const rows = [
      ['General', null],
      ['Time Played', hms],
      ['Time Since Last Death', (() => { const s = Math.floor((Date.now() - (g.survivalStartTime || Date.now())) / 1000); return `${Math.floor(s / 60)}m ${s % 60}s`; })()],
      ['Deaths', String(g._deaths || 0)],
      ['Distance Walked', km(g.distanceTraveled || 0)],
      ['Combat', null],
      ['Parasites Purged', String(g.zombieKills || 0)],
      ['Headshots', String(g._headshotCount || 0)],
      ['Experience Level', String(p?.level ?? 1)],
      ['Score', String(Math.floor(p?._score || 0))],
    ];
    for (const [k, v] of rows) {
      const r = document.createElement('div');
      if (v === null) { r.className = 'mcp-cat'; r.textContent = k; }
      else { r.className = 'mcp-key stat'; r.innerHTML = '<span></span><b></b>'; r.firstChild.textContent = k; r.lastChild.textContent = v; }
      body.appendChild(r);
    }
    this._done(foot, 'game');
  }

  // third-party assets and their licenses (see CREDITS.md)
  _screen_credits() {
    const { body, foot } = this._frame('Credits', { list: true });
    const rows = [
      ['DEADLOCKED', null],
      ['Game, art, music and sound', 'Original'],
      ["Greenboy's Legendary Guns", null],
      ['Gun models and textures', 'GreenBoyGamerr'],
      ['License', 'MIT, Copyright (c) GreenBoyGamerr'],
      ['Full text', 'models/glg/LICENSE.txt'],
      ['SecurityCraft', null],
      ['Lab device textures', 'The SecurityCraft development team'],
      ['License', 'MIT, Copyright (c) 2025 The SecurityCraft development team'],
      ['Full text', 'textures/securitycraft/LICENSE.txt'],
    ];
    for (const [k, v] of rows) {
      const r = document.createElement('div');
      if (v === null) { r.className = 'mcp-cat'; r.textContent = k; }
      else { r.className = 'mcp-key stat'; r.innerHTML = '<span></span><b></b>'; r.firstChild.textContent = k; r.lastChild.textContent = v; }
      body.appendChild(r);
    }
    this._done(foot, 'game');
  }

  _screen_achievements() {
    const { body, foot } = this._frame('Achievements', { list: true });
    const all = this.game.achievementSystem?.getAll?.() || [];
    const got = all.filter((a) => a.unlocked).length;
    const head = document.createElement('div'); head.className = 'mcp-cat'; head.textContent = `${got} / ${all.length} unlocked`;
    body.appendChild(head);
    for (const a of all) {
      const r = document.createElement('div');
      r.className = 'mcp-ach' + (a.unlocked ? ' done' : '');
      r.innerHTML = '<i></i><div><span></span><small></small></div>';
      r.querySelector('span').textContent = a.name;
      r.querySelector('small').textContent = a.desc;
      body.appendChild(r);
    }
    this._done(foot, 'game');
  }
}
