// EffectsHud.js — vanilla-layout status effect icons, top-right corner.
//
// Vanilla Gui.renderEffects layout: 24x24 framed boxes, 25 px apart, filling
// right-to-left. Beneficial effects sit on the top row (y = 1), harmful ones
// on the row below (y = 27). An 18x18 icon is centred in each box. In the last
// 10 seconds the icon pulses using the vanilla fade formula. All icons are
// original pixel art drawn in code here.

// ── tiny pixel-icon painter ────────────────────────────────────────────────
// fn(x, y) -> CSS colour or null on an 18x18 grid; a darker outline is added
// automatically around the filled shape.
function paint(fn, outline = '#1d1d1d') {
  const N = 18, c = document.createElement('canvas');
  c.width = c.height = N;
  const g = c.getContext('2d');
  const px = [];
  for (let y = 0; y < N; y++) for (let x = 0; x < N; x++) px.push(fn(x, y));
  const at = (x, y) => (x < 0 || y < 0 || x >= N || y >= N ? null : px[y * N + x]);
  for (let y = 0; y < N; y++) for (let x = 0; x < N; x++) {
    let col = at(x, y);
    if (!col && outline && (at(x - 1, y) || at(x + 1, y) || at(x, y - 1) || at(x, y + 1))) col = outline;
    if (col) { g.fillStyle = col; g.fillRect(x, y, 1, 1); }
  }
  return c.toDataURL();
}
const inCircle = (x, y, cx, cy, r) => (x + 0.5 - cx) ** 2 + (y + 0.5 - cy) ** 2 <= r * r;

const ICONS = {
  // red drop pair
  bleeding: () => paint((x, y) => {
    const drop = (cx, top, r) => {
      const cy = top + r * 1.9;
      if (inCircle(x, y, cx, cy, r)) return true;
      const dy = cy - (y + 0.5); if (dy > 0 && dy < r * 1.9) return Math.abs(x + 0.5 - cx) <= r * (1 - dy / (r * 1.9));
      return false;
    };
    if (drop(7, 1, 4.2)) return (x + y) % 5 === 0 && x < 7 && y < 9 ? '#ff8a8a' : y > 10 ? '#8e0b0b' : '#cf1d1d';
    if (drop(13, 8, 2.8)) return x < 13 && y < 12 ? '#ff6b6b' : '#a51212';
    return null;
  }),
  // green parasite cell with dark nuclei and short tendrils
  infected: () => paint((x, y) => {
    const tendril = (x === 2 && y >= 7 && y <= 9) || (x === 15 && y >= 5 && y <= 7) || (y === 2 && x >= 8 && x <= 9) || (y === 15 && x >= 6 && x <= 8);
    if (inCircle(x, y, 9, 9, 6.2)) {
      if (inCircle(x, y, 7, 8, 1.6) || inCircle(x, y, 11.5, 10.5, 1.3) || inCircle(x, y, 9, 12.5, 0.9)) return '#204a14';
      if (inCircle(x, y, 7.5, 6.5, 2.5) && !inCircle(x, y, 9, 9, 4.3)) return '#b7f07a';
      return inCircle(x, y, 9.8, 10, 5) ? '#58b02c' : '#3c8a1e';
    }
    return tendril ? '#3c8a1e' : null;
  }),
  // flame: rounded base, flickering tongue to a point at the top
  burning: () => paint((x, y) => {
    const cx = 9 + (y < 8 ? Math.sin(y * 1.1) * 0.9 : 0), dx = Math.abs(x + 0.5 - cx);
    const body = inCircle(x, y, 9, 12, 5.2) || (y >= 1 && y <= 12 && dx <= (y - 1) / 11 * 5.2);
    if (!body) return null;
    if (inCircle(x, y, 9, 13.2, 2.6) || (y >= 7 && y <= 13 && Math.abs(x + 0.5 - 9) <= (y - 7) / 6 * 2.6)) return y > 12 ? '#fff6b0' : '#ffd23c';
    return y > 9 ? '#ff8a1c' : '#e8410f';
  }),
  // green droplet with bubbles
  poison: () => paint((x, y) => {
    if (inCircle(x, y, 9, 11, 5.2)) return inCircle(x, y, 7.5, 9.5, 1.6) ? '#d6ff9a' : y > 12 ? '#2f7a12' : '#56b31e';
    if (inCircle(x, y, 5, 3.5, 1.6) || inCircle(x, y, 12, 4.5, 1.2)) return '#8fd64a';
    return null;
  }),
  // swirl
  nausea: () => paint((x, y) => {
    const dx = x + 0.5 - 9, dy = y + 0.5 - 9, r = Math.hypot(dx, dy), a = Math.atan2(dy, dx);
    if (r > 7.5) return null;
    const arm = ((a / (Math.PI * 2) + r / 5.5) % 1 + 1) % 1;
    return arm < 0.38 ? (r < 3 ? '#e7ef7a' : '#9fc23a') : null;
  }, '#2f3b14'),
  // snowflake
  freezing: () => paint((x, y) => {
    const dx = x - 8.5, dy = y - 8.5;
    const ax = Math.abs(dx) < 0.6 && Math.abs(dy) < 8, ay = Math.abs(dy) < 0.6 && Math.abs(dx) < 8;
    const d1 = Math.abs(dx - dy) < 0.8 && Math.abs(dx) < 6, d2 = Math.abs(dx + dy) < 0.8 && Math.abs(dx) < 6;
    if (ax || ay || d1 || d2) return Math.abs(dx) < 1.5 && Math.abs(dy) < 1.5 ? '#ffffff' : '#a6e3ff';
    return null;
  }, '#1f3f5c'),
  // spoiled meat chunk with a green tinge (the Hunger effect)
  hunger: () => paint((x, y) => {
    if (inCircle(x, y, 8, 9, 5.4) || inCircle(x, y, 11.5, 7, 3.6)) {
      if (inCircle(x, y, 6.5, 7.5, 1.4) || inCircle(x, y, 11, 11, 1.1)) return '#4e5a1e';
      return y < 7 ? '#a7ad5c' : y > 11 ? '#5f6a2a' : '#87913f';
    }
    if (x >= 13 && x <= 15 && y >= 11 && y <= 15 && x - y < 3 && y - x < 1) return '#e6e0c8';
    return null;
  }, '#2a2f10'),
  // two forward chevrons
  speed: () => paint((x, y) => {
    const chev = (ox) => { const d = Math.abs(y - 8.5), mx = 17 - x; return mx >= ox + d * 0.75 && mx <= ox + d * 0.75 + 2.4 && d <= 6.5; };
    if (chev(9.5 - 6)) return '#7ad0ff';
    if (chev(9.5)) return '#bfe9ff';
    return null;
  }, '#173a52'),
  // lightning bolt
  adrenaline: () => paint((x, y) => {
    const up = y <= 9 && x >= 10 - y * 0.6 && x <= 14 - y * 0.6;
    const down = y >= 8 && x >= 4 + (y - 8) * 0.6 + 2 && x <= 8 + (y - 8) * 0.6 + 2 && y <= 17;
    const bar = y >= 8 && y <= 9 && x >= 5 && x <= 12;
    return up || down || bar ? (x + y < 14 ? '#ffe36b' : '#f08a1a') : null;
  }, '#4a2205'),
  // syringe, diagonal
  morphine: () => paint((x, y) => {
    const u = (x - y) / 1.414, v = (x + y) / 1.414 - 12.7;
    if (Math.abs(u) <= 1.6 && v >= -7 && v <= 3) return v > -1 ? '#9ec7ff' : '#f2f2f2';
    if (Math.abs(u) <= 0.5 && v > 3 && v <= 7) return '#cfcfcf';
    if (Math.abs(u) <= 2.6 && v >= -8.2 && v <= -7) return '#f2f2f2';
    return null;
  }),
  // shield
  immune: () => paint((x, y) => {
    const w = y < 10 ? 6.5 : 6.5 * (1 - (y - 10) / 7);
    if (y < 2 || y > 16 || Math.abs(x + 0.5 - 9) > w) return null;
    if (Math.abs(x + 0.5 - 9) < 1 || (y >= 6 && y <= 7)) return '#e8f4ff';
    return x < 9 ? '#4f8de0' : '#3468b8';
  }),
  // eye
  nightVision: () => paint((x, y) => {
    const dx = x + 0.5 - 9, dy = y + 0.5 - 9;
    if (Math.abs(dy) > 4.5 * Math.cos((dx / 8.5) * Math.PI / 2) || Math.abs(dx) > 8.5) return null;
    if (dx * dx + dy * dy < 4) return '#141c3a';
    if (dx * dx + dy * dy < 12) return '#4c6dff';
    return '#e9ecff';
  }),
};

// beneficial first, then harmful (vanilla sorts by type, then by recency)
const DEFS = [
  { id: 'speed', good: true, test: (p) => p._speedBoostTimer > 0 && !p._adrenalineActive, t: (p) => p._speedBoostTimer },
  { id: 'adrenaline', good: true, test: (p) => p._adrenalineActive, t: (p) => p._speedBoostTimer },
  { id: 'morphine', good: true, test: (p) => p._morphineTimer > 0, t: (p) => p._morphineTimer },
  { id: 'immune', good: true, test: (p) => p._immune || p._immuneInfect },
  { id: 'nightVision', good: true, test: (p) => p.nightVisionOn },
  { id: 'infected', good: false, test: (p) => p._infected && !p._immuneInfect },
  { id: 'bleeding', good: false, test: (p) => p._bleeding, t: (p) => p._bleedTimer },
  { id: 'poison', good: false, test: (p) => p.poisoned },
  { id: 'burning', good: false, test: (p) => p.burned },
  { id: 'nausea', good: false, test: (p) => p._drunkTimer > 0, t: (p) => p._drunkTimer },
  { id: 'freezing', good: false, test: (p) => p._freezeTimer > 0 || ((p.temperature ?? 37) < 35.5 && !p.game?.inFriendHouse), t: (p) => (p._freezeTimer > 0 ? p._freezeTimer : null) },
  { id: 'hunger', good: false, test: (p) => p._hungerFx > 0, t: (p) => p._hungerFx },
];

let _root = null, _urls = null, _boxes = new Map(), _rows = -1;

function ensure() {
  if (_root) return;
  _root = document.createElement('div');
  _root.id = 'mc-effects';
  document.body.appendChild(_root);
  _urls = {};
  for (const [k, f] of Object.entries(ICONS)) _urls[k] = f();
  // 24x24 raised frame: black rim with cut corners, white top-left bevel,
  // grey face, dark bottom-right bevel (same family as the inventory panel)
  const c = document.createElement('canvas'); c.width = c.height = 24;
  const g = c.getContext('2d');
  for (let y = 0; y < 24; y++) for (let x = 0; x < 24; x++) {
    const corner = (x === 0 || x === 23) && (y === 0 || y === 23);
    if (corner) continue;
    let col = '#c6c6c6';
    if (x === 0 || y === 0 || x === 23 || y === 23) col = '#000000';
    else if ((x <= 2 || y <= 2) && x + y < 44 && !(x >= 21 || y >= 21)) col = '#ffffff';
    else if (x >= 21 || y >= 21) col = '#555555';
    if ((x === 1 && y === 1) || (x === 22 && y === 22)) col = '#000000';
    if ((x === 1 && y === 22) || (x === 22 && y === 1)) col = '#8b8b8b';
    g.fillStyle = col; g.fillRect(x, y, 1, 1);
  }
  document.documentElement.style.setProperty('--mc-effect-bg', `url(${c.toDataURL()})`);
}

// Vanilla fade for effects ending within 10 s (k = ticks remaining)
function fade(seconds) {
  if (seconds == null || seconds > 10) return 1;
  const k = Math.max(0, seconds * 20), l = 10 - k / 20;
  const c = (v, a, b) => Math.max(a, Math.min(b, v));
  return c(k / 10 / 5 * 0.5, 0, 0.5) + Math.cos(k * Math.PI / 5) * c(l / 10 * 0.25, 0, 0.25);
}

export function updateEffectsHud(player) {
  if (!player) return;
  ensure();
  let good = 0, bad = 0;
  const seen = new Set();
  for (const d of DEFS) {
    if (!d.test(player)) continue;
    seen.add(d.id);
    let box = _boxes.get(d.id);
    if (!box) {
      box = document.createElement('div');
      box.className = 'mc-effect';
      const img = document.createElement('i');
      img.style.backgroundImage = `url(${_urls[d.id]})`;
      box.appendChild(img);
      _root.appendChild(box);
      _boxes.set(d.id, box);
    }
    const n = d.good ? ++good : ++bad;
    box.style.right = `calc(var(--u) * ${25 * n - 24})`;
    box.style.top = `calc(var(--u) * ${d.good ? 1 : 27})`;
    box.firstChild.style.opacity = fade(d.t ? d.t(player) : null).toFixed(3);
  }
  for (const [id, box] of _boxes) if (!seen.has(id)) { box.remove(); _boxes.delete(id); }
  // push the minimap below the effect rows
  const rows = bad ? 2 : good ? 1 : 0;
  if (rows !== _rows) { _rows = rows; document.documentElement.style.setProperty('--fx-rows', String(rows)); }
}
