import * as THREE from 'three';
import * as CANNON from 'cannon-es';
import { buildHumanModel } from './HumanModel.js';

export class NPC {
  constructor(name, type, x, z, game) {
    this.game = game;
    this.name = name;
    this.type = type;
    this.id = name.toLowerCase().replace(' ', '_');
    this.position = new THREE.Vector3(x, game.terrainGenerator.getHeightAt(x, z) + 1, z);
    this.velocity = new THREE.Vector3();

    this.health = 100;
    this.maxHealth = 100;
    this.isRecruited = false;
    this.dialogues = [];
    this.currentDialogIndex = 0;
    this.distanceToPlayer = 0;

    this.mesh = null;
    this.body = null;
    this.setupPhysics();
    this.createMesh();
  }

  setupPhysics() {
    const shape = new CANNON.Cylinder(0.4, 0.4, 1.8, 8);
    // mass: 0 = kinematic — removed from dynamics solver, no physics pileup
    this.body = new CANNON.Body({ mass: 0 });
    this.body.addShape(shape);
    this.body.position.copy(this.position);
    this.body.fixedRotation = true;
    this.game.physicsWorld.addBody(this.body);
  }

  createMesh() {
    // blocky survivor in vanilla player proportions, outfit by role
    const group = new THREE.Group();
    const rig = buildHumanModel(['mayor', 'merchant', 'soldier', 'scientist'].includes(this.type) ? this.type : 'survivor');
    rig.root.scale.setScalar(1.8 / 32);
    rig.root.position.y = -0.9;               // group origin is the body centre
    group.add(rig.root);
    this.rig = rig;
    group.position.copy(this.position);
    group.traverse((o) => { o.userData.npc = this; });   // hittable by melee/guns
    this.game.scene.addObject(group);
    this.mesh = group;
  }

  createNameTexture(text) {
    const canvas = document.createElement('canvas');
    canvas.width = 256;
    canvas.height = 64;
    const ctx = canvas.getContext('2d');

    ctx.fillStyle = 'rgba(0, 0, 0, 0.8)';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    ctx.fillStyle = '#00ff00';
    ctx.font = '32px Arial';
    ctx.textAlign = 'center';
    ctx.fillText(text, canvas.width / 2, 45);

    const texture = new THREE.CanvasTexture(canvas);
    return texture;
  }

  setupDialogues(dialogues) {
    this.dialogues = dialogues;
  }

  startDialog() {
    this.currentDialogIndex = 0;
  }

  update(deltaTime) {
    if (!this.body || !this.mesh) return;

    // Snap kinematic body to terrain
    const groundY = this.game.terrainGenerator?.getHeightAt(this.body.position.x, this.body.position.z) ?? 0;
    if (isFinite(groundY)) this.body.position.y = groundY + 0.9;

    // knockback from a hit, decaying like vanilla ground friction
    if (this._kb) {
      const vw = this.game.voxelWorld, nx = this.body.position.x + this._kb.x * deltaTime, nz = this.body.position.z + this._kb.z * deltaTime;
      if (!vw || !vw.isSolid(Math.floor(nx), Math.floor(this.body.position.y - 0.4), Math.floor(nz))) { this.body.position.x = nx; this.body.position.z = nz; }
      const f = Math.pow(0.546, deltaTime * 20); this._kb.x *= f; this._kb.z *= f;
      if (Math.abs(this._kb.x) + Math.abs(this._kb.z) < 0.05) this._kb = null;
    }
    this.position.copy(this.body.position);
    this.mesh.position.copy(this.position);

    // turn toward the player when close, idle arm sway otherwise
    const pp = this.game.player?.body?.position;
    if (pp && this.rig) {
      const dx = pp.x - this.position.x, dz = pp.z - this.position.z, d = Math.hypot(dx, dz);
      if (d < 8) {
        const target = Math.atan2(dx, dz);
        let diff = target - this.mesh.rotation.y;
        diff = Math.atan2(Math.sin(diff), Math.cos(diff));
        this.mesh.rotation.y += diff * Math.min(1, deltaTime * 4);
        this.rig.head.rotation.x = -Math.atan2(pp.y + 0.72 - (this.position.y + 0.72), Math.max(0.5, d)) * 0.8;
      }
      this._t = (this._t || 0) + deltaTime;
      const sway = Math.sin(this._t * 1.3) * 0.05;
      this.rig.armR.rotation.x = sway; this.rig.armL.rotation.x = -sway;
    }
  }

  getPosition() {
    return this.position.clone();
  }

  speak(text) {
    console.log(`${this.name}: ${text}`);
  }

  // Hit by the player: red flash (vanilla hurt tint), knockback, damage
  takeDamage(amount, fromPos = null) {
    if (this.health <= 0) return;
    this.health -= amount;
    if (fromPos) {
      const dx = this.position.x - fromPos.x, dz = this.position.z - fromPos.z, d = Math.hypot(dx, dz) || 1;
      this._kb = { x: dx / d * 8, z: dz / d * 8 };
    }
    if (this.mesh) {
      const mats = new Set();
      this.mesh.traverse((o) => { if (o.isMesh && o.material) [].concat(o.material).forEach((m) => mats.add(m)); });
      for (const m of mats) { m.userData.base ??= m.color.clone(); m.color.setRGB(1, 0.35, 0.35); }
      clearTimeout(this._flashT);
      this._flashT = setTimeout(() => { for (const m of mats) if (m.userData.base) m.color.copy(m.userData.base); }, 250);
    }
    if (this.health <= 0) {
      this.die();
    }
  }

  die() {
    if (this.mesh) {
      this.game.scene.removeObject(this.mesh);
    }
    if (this.body) {
      this.game.physicsWorld.removeBody(this.body);
    }
  }

  isAlive() {
    return this.health > 0;
  }

  recruit() {
    this.isRecruited = true;
  }
}
