// Throwables.js — thrown and shot projectiles on the vanilla 20 Hz tick.
//
// Segment tests against blocks and entity boxes every tick, so fast
// projectiles never tunnel. Drag 0.99 per tick for all of them.
//  - Snowball: 1.5 blocks/tick, gravity 0.03. No damage, a light knockback.
//  - Ice ball (26.4): as a snowball, but damage = ceil(1.395 x speed in
//    blocks/tick): 1..4 vanilla HP (x5 for the player's 100 HP scale, x2.5 for
//    the zombies'). The thrower can be hit by their own ball.
//  - Splash potion: 0.5 blocks/tick, gravity 0.05. Shatters on anything and
//    applies its effect to everything within 4 blocks, scaled by distance
//    (a direct hit gets the full duration).
//  - Lingering potion: shatters into a 3-block cloud that lasts 30 s and
//    shrinks over time and with each entity it touches; standing in it
//    applies a quarter of the potion's duration (re-applied once a second).
//  - Arrow: up to 3 blocks/tick from a fully drawn bow, gravity 0.05.
//    Damage ceil(2 x speed), plus a random bonus on a critical (full draw)
//    shot. Tipped arrows add their effect. Arrows that land in a block can be
//    picked up again; arrows that hit something break.
// Frostbites throw ice balls through the same system (owner = the zombie).

import * as THREE from 'three';
import { mcTexture } from '../content/McContent.js';
import { BLOCKS, BLOCK } from '../world/Blocks.js';

const TICK = 0.05;
const SPEED = 1.5;            // blocks per tick
const OWNER_GRACE = 5;        // ticks before the thrower can be hit

// Freezing seconds carried by each potion / arrow
export const FREEZE_SECONDS = {
  mc_splash_potion_freezing: 45, mc_splash_potion_freezing_long: 90,
  mc_lingering_potion_freezing: 45, mc_lingering_potion_freezing_long: 90,
  mc_arrow_freezing: 5, mc_arrow_freezing_long: 11,
};
const isPotion = (k) => /_potion_/.test(k);
const isArrow = (k) => /^mc_arrow/.test(k);

export class Throwables {
  constructor(game) {
    this.game = game;
    this.list = [];
    this.clouds = [];
    this._acc = 0;
    this._mats = {};
  }

  _mat(kind) {
    return this._mats[kind] ??= new THREE.SpriteMaterial({ map: mcTexture(kind), transparent: true, alphaTest: 0.3, depthWrite: true });
  }

  _arrowMesh(kind) {
    const g = new THREE.Group();
    this._arrowMats ??= {
      shaft: new THREE.MeshLambertMaterial({ color: 0x8c6834 }),
      head: new THREE.MeshLambertMaterial({ color: 0x9a9a9a }),
      fl: new THREE.MeshLambertMaterial({ color: 0xe6e6e6 }),
      flF: new THREE.MeshLambertMaterial({ color: 0x8ad0f4 }),
    };
    const M = this._arrowMats;
    const add = (w, h, d, z, m) => { const b = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), m); b.position.z = z; b.userData.noVox = true; b.raycast = () => {}; g.add(b); };
    add(0.035, 0.035, 0.5, 0, M.shaft);
    add(0.07, 0.07, 0.08, 0.27, M.head);
    const fm = /freezing/.test(kind) ? M.flF : M.fl;
    add(0.12, 0.012, 0.1, -0.22, fm);
    add(0.012, 0.12, 0.1, -0.22, fm);
    return g;
  }

  // origin: Vector3, dir: unit Vector3, owner: 'player' | zombie, vel0: extra
  // motion in blocks/tick inherited from the thrower
  spawn(kind, origin, dir, owner, vel0 = null, speed = SPEED, extra = {}) {
    let o;
    if (isArrow(kind)) o = this._arrowMesh(kind);
    else { o = new THREE.Sprite(this._mat(kind)); o.scale.setScalar(isPotion(kind) ? 0.35 : 0.25); }
    o.position.copy(origin);
    o.userData.noVox = true; o.userData.noHit = true;
    o.raycast = () => {};                  // scene raycasts (blood pools, aim) must skip it
    this.game.scene.scene.add(o);
    const v = dir.clone().multiplyScalar(speed);
    if (vel0) v.add(vel0);
    const grav = isPotion(kind) || isArrow(kind) ? 0.05 : 0.03;
    this.list.push({ kind, owner, p: origin.clone(), pp: origin.clone(), v, age: 0, s: o, grav, ...extra });
  }

  // The player throws the held item from the eye along the look direction
  playerThrow(kind) {
    const g = this.game, cam = g.scene.getCamera?.() ?? g.player.camera;
    const eye = new THREE.Vector3(); cam.getWorldPosition(eye);
    const dir = new THREE.Vector3(); cam.getWorldDirection(dir);
    const bv = g.player.body?.velocity;
    const vel0 = bv ? new THREE.Vector3(bv.x * TICK, g.player.isGrounded ? 0 : bv.y * TICK, bv.z * TICK) : null;
    let speed = SPEED;
    if (isPotion(kind)) {
      // vanilla: potions leave 20 degrees above the look direction, slowly
      const right = new THREE.Vector3().crossVectors(dir, new THREE.Vector3(0, 1, 0)).normalize();
      if (right.lengthSq() > 0.5) dir.applyAxisAngle(right, 20 * Math.PI / 180);
      speed = 0.5;
    }
    this.spawn(kind, eye.addScaledVector(dir, 0.3).add(new THREE.Vector3(0, -0.1, 0)), dir, 'player', vel0, speed);
    g.blockInteraction?._sfx?.({ name: 'leaves' }, 0.35);
  }

  // Bow release: power 0..1 from the draw time (vanilla curve)
  playerShoot(kind, power) {
    const g = this.game, cam = g.scene.getCamera?.() ?? g.player.camera;
    const eye = new THREE.Vector3(); cam.getWorldPosition(eye);
    const dir = new THREE.Vector3(); cam.getWorldDirection(dir);
    this.spawn(kind, eye.addScaledVector(dir, 0.4).add(new THREE.Vector3(0, -0.1, 0)), dir, 'player', null, power * 3, { crit: power >= 1 });
    g.blockInteraction?._sfx?.({ name: 'log' }, 0.45);
  }

  update(dt) {
    const g = this.game;
    if ((!this.list.length && !this.clouds.length) || !g.isRunning || g.isPaused) return;
    this._acc = Math.min(this._acc + dt, TICK * 5);
    while (this._acc >= TICK) { this._acc -= TICK; this._tick(); }
    const a = this._acc / TICK;
    for (const t of this.list) {
      t.s.position.lerpVectors(t.pp, t.p, a);
      if (isArrow(t.kind) && t.v.lengthSq() > 1e-6) t.s.lookAt(t.s.position.x + t.v.x, t.s.position.y + t.v.y, t.s.position.z + t.v.z);
    }
    for (const c of this.clouds) {
      c.mesh.scale.setScalar(Math.max(0.01, c.r));
      c.mesh.material.opacity = 0.32 + Math.sin(performance.now() / 300) * 0.05;
    }
  }

  _tick() {
    for (let i = this.list.length - 1; i >= 0; i--) {
      const t = this.list[i];
      t.pp.copy(t.p);
      t.age++;
      const from = t.p.clone(), to = t.p.clone().add(t.v);
      const hit = this._trace(t, from, to);
      if (hit) { this._impact(t, hit); this._remove(i); continue; }
      t.p.copy(to);
      t.v.multiplyScalar(0.99); t.v.y -= t.grav;
      if (t.age > 400 || t.p.y < -40) this._remove(i);
    }
    this._tickClouds();
  }

  // First thing along from->to: an entity box or a solid block
  _trace(t, from, to) {
    const g = this.game, vw = g.voxelWorld;
    const seg = to.clone().sub(from), len = seg.length();
    const steps = Math.max(1, Math.ceil(len / 0.2));
    const P = g.player?.body?.position;
    const zs = g.zombieManager?.zombies ?? [];
    const q = new THREE.Vector3();
    for (let k = 1; k <= steps; k++) {
      q.copy(from).addScaledVector(seg, k / steps);
      if (P && (t.owner !== 'player' || t.age > OWNER_GRACE) && g.player.health > 0 &&
          Math.abs(q.x - P.x) < 0.42 && Math.abs(q.z - P.z) < 0.42 && q.y > P.y - 1.0 && q.y < P.y + 0.9) return { who: 'player', at: q.clone() };
      for (const z of zs) {
        if (z._dead || (z === t.owner && t.age <= OWNER_GRACE)) continue;
        const hw = (z._colHW ?? 0.3) + 0.12, h = z._colH ?? 1.8, feet = z.position.y - 0.9;
        if (Math.abs(q.x - z.position.x) < hw && Math.abs(q.z - z.position.z) < hw && q.y > feet && q.y < feet + h) return { who: z, at: q.clone() };
      }
      if (vw?.isSolid(Math.floor(q.x), Math.floor(q.y), Math.floor(q.z))) {
        // back off to the last free point so dropped arrows don't sit inside the block
        const back = from.clone().addScaledVector(seg, (k - 1) / steps);
        return { who: null, at: q.clone(), free: back };
      }
    }
    return null;
  }

  _impact(t, hit) {
    if (isPotion(t.kind)) { this._shatter(t, hit); return; }
    if (isArrow(t.kind)) { this._arrowHit(t, hit); return; }
    const g = this.game, ice = t.kind === 'mc_ice_ball';
    const speed = t.v.length();
    const dmgHP = ice ? Math.max(1, Math.min(4, Math.ceil(1.395 * speed))) : 0;
    const dir = t.v.clone().setY(0); if (dir.lengthSq() < 1e-6) dir.set(0, 0, 1); dir.normalize();
    if (hit.who === 'player') {
      const p = g.player;
      if (dmgHP && !p.godMode) {
        p._deathCause = t.owner === 'player' ? 'Pummeled by their own ice ball' : 'Pummeled by a Frostbite';
        p.takeDamage(dmgHP * 5, t.owner?.position ?? null);
      }
      if (p.body && !p.godMode) { p.body.velocity.x += dir.x * 3; p.body.velocity.z += dir.z * 3; p.body.velocity.y = Math.max(p.body.velocity.y, 2); }
    } else if (hit.who) {
      const z = hit.who;
      if (dmgHP) {
        z.takeDamage(dmgHP * 2.5);
        // advancement "What Goes Around Comes Around"
        if (z._dead && t.owner === 'player' && /frostbite/.test(z.type)) g.achievementSystem?.grant?.('what_goes_around');
      }
      if (!z._dead) z.knockback?.(hit.at.x - dir.x, hit.at.z - dir.z, ice ? 0.4 : 0.25);
      if (t.owner === 'player' && !z._dead && z.state === 'idle') z.state = 'chasing';
    }
    this._puff(ice ? BLOCK.packed_ice : BLOCK.snow_block, hit.at, 8);
    g.blockInteraction?._sfx?.(ice ? { name: 'ice' } : { name: 'snow' }, ice ? 0.5 : 0.3);
  }

  _puff(blockId, at, n) {
    const bi = this.game.blockInteraction, b = BLOCKS[blockId];
    if (!bi?._spawnParticle || !b) return;
    for (let k = 0; k < n; k++) {
      const r = () => (Math.random() - 0.5) * 0.3;
      bi._spawnParticle(b, at.x + r(), at.y + r(), at.z + r(), r() * 2, Math.random() * 0.6, r() * 2);
    }
  }

  // ── arrows ───────────────────────────────────────────────────────────────
  _arrowHit(t, hit) {
    const g = this.game, speed = t.v.length();
    if (hit.who && hit.who !== 'player') {
      const z = hit.who;
      let dmg = Math.ceil(speed * 2);
      if (t.crit) dmg += Math.floor(Math.random() * (dmg / 2 + 2));
      z.takeDamage(dmg * 2.5);
      const fx = FREEZE_SECONDS[t.kind];
      if (fx && !z._dead) g.freeze?.apply(z, fx);
      const dir = t.v.clone().setY(0).normalize();
      if (!z._dead) { z.knockback?.(hit.at.x - dir.x, hit.at.z - dir.z, 0.3); if (z.state === 'idle') z.state = 'chasing'; }
      g.blockInteraction?._sfx?.({ name: 'log' }, 0.5);
      return;
    }
    if (hit.who === 'player') {
      // only reachable for arrows from other shooters; none yet
      return;
    }
    // stuck in a block: leave it as a pickup
    const at = hit.free ?? hit.at;
    const it = g.worldItemSystem?.spawnItem?.(t.kind, at.x, at.y, at.z, 1);
    if (it) it.respawnsLeft = 0;
    g.blockInteraction?._sfx?.({ name: 'log' }, 0.3);
  }

  // ── potions ──────────────────────────────────────────────────────────────
  _shatter(t, hit) {
    const g = this.game, at = hit.free ?? hit.at;
    const fx = FREEZE_SECONDS[t.kind] ?? 0;
    this._puff(BLOCK.glass, at, 12);
    g.blockInteraction?._sfx?.({ name: 'glass' }, 0.7);
    if (/lingering/.test(t.kind)) { this._makeCloud(at, fx / 4); return; }
    if (!fx) return;
    // splash: full strength on a direct hit, fading to nothing at 4 blocks
    const P = g.player?.body?.position;
    if (P) {
      const d = hit.who === 'player' ? 0 : P.distanceTo(at);
      if (d < 4) g.freeze?.apply('player', fx * (1 - d / 4));
    }
    for (const z of g.zombieManager?.zombies ?? []) {
      if (z._dead) continue;
      const d = hit.who === z ? 0 : z.position.distanceTo(at);
      if (d < 4) g.freeze?.apply(z, fx * (1 - d / 4));
    }
  }

  _makeCloud(at, seconds) {
    const vw = this.game.voxelWorld;
    let y = Math.floor(at.y);
    for (let k = 0; k < 6 && vw && !vw.isSolid(Math.floor(at.x), y - 1, Math.floor(at.z)); k++) y--;
    const geo = new THREE.CircleGeometry(1, 28);
    const mat = new THREE.MeshBasicMaterial({ color: 0x9adcf8, transparent: true, opacity: 0.35, depthWrite: false, side: THREE.DoubleSide });
    const mesh = new THREE.Mesh(geo, mat);
    mesh.rotation.x = -Math.PI / 2;
    mesh.position.set(at.x, y + 0.03, at.z);
    mesh.userData.noVox = true; mesh.raycast = () => {};
    this.game.scene.scene.add(mesh);
    this.clouds.push({ x: at.x, y, z: at.z, r: 3, life: 600, sec: seconds, mesh, cd: new Map(), t: 0 });
  }

  _tickClouds() {
    const g = this.game;
    for (let i = this.clouds.length - 1; i >= 0; i--) {
      const c = this.clouds[i];
      c.life--; c.t++;
      c.r -= 3 / 600;                                  // shrinks to nothing over its life
      if (c.life <= 0 || c.r <= 0.4) { this._dropCloud(i); continue; }
      if (c.t % 5) continue;
      const touch = (key, pos, fn) => {
        if ((c.cd.get(key) ?? 0) > c.t) return;
        if (Math.hypot(pos.x - c.x, pos.z - c.z) > c.r || pos.y - 0.9 < c.y - 0.5 || pos.y - 0.9 > c.y + 1.5) return;
        c.cd.set(key, c.t + 20);
        fn(); c.r -= 0.5 / 3;                          // each touch thins it a little
      };
      const P = g.player?.body?.position;
      if (P) touch('player', P, () => g.freeze?.apply('player', c.sec));
      for (const z of g.zombieManager?.zombies ?? []) if (!z._dead) touch(z, z.position, () => g.freeze?.apply(z, c.sec));
      if (Math.random() < 0.6) {
        const a = Math.random() * Math.PI * 2, r = Math.random() * c.r;
        this._puff(BLOCK.ice, new THREE.Vector3(c.x + Math.cos(a) * r, c.y + 0.3, c.z + Math.sin(a) * r), 1);
      }
    }
  }

  _dropCloud(i) {
    const c = this.clouds[i];
    c.mesh.parent?.remove(c.mesh); c.mesh.geometry.dispose(); c.mesh.material.dispose();
    this.clouds.splice(i, 1);
  }

  _remove(i) {
    const t = this.list[i];
    t.s.parent?.remove(t.s);
    if (isArrow(t.kind)) t.s.traverse((o) => o.geometry?.dispose?.());
    this.list.splice(i, 1);
  }

  clear() {
    for (let i = this.list.length - 1; i >= 0; i--) this._remove(i);
    for (let i = this.clouds.length - 1; i >= 0; i--) this._dropCloud(i);
  }
}
