export const DYE_BASE = {
  white: '#f0f0ec', orange: '#f07c1a', magenta: '#c04cb8', light_blue: '#3aaed8', yellow: '#f6d03a', lime: '#7cc420',
  pink: '#ee8aac', gray: '#4c5458', light_gray: '#9d9d97', cyan: '#169a9c', purple: '#8634b8', blue: '#3a44b0',
  brown: '#845232', green: '#5e7c16', red: '#b42c24', black: '#24242a',
};
{
  const sh = (h, k) => '#' + [1, 3, 5].map((i) => parseInt(h.slice(i, i + 2), 16)).map((v) => Math.round(Math.max(0, Math.min(255, k >= 1 ? v + (255 - v) * (k - 1) : v * k))).toString(16).padStart(2, '0')).join('');
  for (const [c, b] of Object.entries(DYE_BASE)) RAMPS[c + '_dye'] = [sh(b, c === 'black' ? 0.4 : 0.45), sh(b, 0.75), b, sh(b, 1.2), sh(b, 1.45)];
}
