// Material-specific accents: netherite and diamond swords get a darker grip;
// gold armor gets highlight rivets etc. Kept tiny on purpose.
function rampFor(material) { return RAMPS[material] || RAMPS.iron; }

// Paint template `name` recoloured with `material` onto a 16x16 ctx.
// `accent` is another ramp name used for x/y/z pixels.
export function paintSprite(ctx, name, material, accent = null) {
  const tpl = T[name]; if (!tpl) return false;
  const R = rampFor(material), A = accent ? rampFor(accent) : R;
  const handle = STICK;
  const grip = GRIP;
  // grid of {c: colour, o: outline colour}
  const grid = [];
  for (let y = 0; y < 16; y++) {
    const row = []; grid.push(row);
    const s = tpl[y] || '';
    for (let x = 0; x < 16; x++) {
      const k = s[x];
      let c = null, o = null;
      if (k >= '1' && k <= '4') { c = R[+k]; o = R[0]; }
      else if (k === 'a' || k === 'b' || k === 'c') { c = handle[' abc'.indexOf(k)]; o = handle[0]; }
      else if (k === 'x' || k === 'y' || k === 'z') {
        const src = name === 'sword' ? grip : A;
        c = name === 'sword' ? src[' xyz'.indexOf(k)] : A[' xyz'.indexOf(k) + 1]; o = src[0];
      }
      row.push(c ? { c, o } : null);
    }
  }
  // outline: transparent pixels touching a filled pixel (4-neighbour), read
  // from the untouched grid so the outline never spreads.
  const out = [];
  for (let y = 0; y < 16; y++) for (let x = 0; x < 16; x++) {
    if (grid[y][x]) continue;
    const n = [grid[y - 1]?.[x], grid[y + 1]?.[x], grid[y][x - 1], grid[y][x + 1]].find(Boolean);
    if (n) out.push([x, y, n.o]);
  }
  ctx.clearRect(0, 0, 16, 16);
  for (let y = 0; y < 16; y++) for (let x = 0; x < 16; x++) {
    const p = grid[y][x]; if (!p) continue;
    ctx.fillStyle = p.c; ctx.fillRect(x, y, 1, 1);
  }
  for (const [x, y, c] of out) { ctx.fillStyle = c; ctx.fillRect(x, y, 1, 1); }
  return true;
}

export const SPRITE_NAMES = Object.keys(T);
