// HumanModel.js — blocky humanoid in vanilla player proportions (head 8^3,
// body 8x12x4, arms/legs 4x12x4; 1 unit = 1 skin pixel), with an original
// 64x64 skin painted in code using the classic box-UV layout. Outfit colours
// are parameters so survivors/NPCs can share the model.

import * as THREE from 'three';

export const SKIN_W = 64;

// ── Skin painting ──────────────────────────────────────────────────────────
// deterministic per-pixel noise so the skin stays the same every session
export function rnd(x, y, s = 0) {
  let h = (x * 374761393 + y * 668265263 + s * 2147483647) | 0;
  h = (h ^ (h >>> 13)) * 1274126177;
  return ((h ^ (h >>> 16)) >>> 0) / 4294967296;
}
export function shade(hex, f) {
  const n = parseInt(hex.slice(1), 16);
  const c = (v) => Math.max(0, Math.min(255, Math.round(v * f)));
  return `rgb(${c(n >> 16)},${c((n >> 8) & 255)},${c(n & 255)})`;
}

// Face rectangles of a box at texture origin (u,v) with size w,h,d
export function faces(u, v, w, h, d) {
  return {
    top: [u + d, v, w, d], bottom: [u + d + w, v, w, d],
    right: [u, v + d, d, h], front: [u + d, v + d, w, h],
    left: [u + d + w, v + d, d, h], back: [u + 2 * d + w, v + d, w, h],
  };
}

export const OUTFITS = {
  survivor: {},
  mayor: { jacket: ['#1e2a4a', '#2a3a66', '#3a4c80'], shirt: ['#b8b4ac', '#dcd8d0', '#f0ece4'], pants: ['#1c1c24', '#2a2a34', '#383844'], hair: ['#4a4a4a', '#6a6a6a', '#8a8a8a'] },
  merchant: { jacket: ['#7a4416', '#a05a1e', '#c0742e'], shirt: ['#7a6a4a', '#9a8a62', '#b4a47a'], pants: ['#3a2e22', '#4e3e2e', '#62503c'], hair: ['#5a2a12', '#7a3c1a', '#985028'] },
  soldier: { jacket: ['#3a4228', '#4e5834', '#626e42'], shirt: ['#3a4228', '#4e5834', '#626e42'], pants: ['#3a4228', '#4a5432', '#5a663e'], hair: ['#1a1410', '#2a2018', '#3a2c20'] },
  scientist: { jacket: ['#b8bcc0', '#d8dce0', '#eef0f2'], shirt: ['#3a5a7a', '#4a6e94', '#5e84ac'], pants: ['#2a2a30', '#38383e', '#46464e'], hair: ['#8a6a3a', '#a8844a', '#c4a060'] },
};

export function paintSkin(outfit = {}) {
  const cv = document.createElement('canvas');
  cv.width = SKIN_W; cv.height = SKIN_W;
  const g = cv.getContext('2d');
  const px = (x, y, col) => { g.fillStyle = col; g.fillRect(x, y, 1, 1); };
  // Palettes: [dark, base, light]. Fabric gets a sparse, deterministic weave
  // (a few lighter/darker pixels), never full-noise.
  const P = Object.assign({
    skin: ['#a8734e', '#c48d64', '#d6a27a'],
    hair: ['#2a1c12', '#3d2a1c', '#53392a'],
    jacket: ['#33452c', '#45603b', '#577548'],
    shirt: ['#a9a395', '#c9c3b2', '#dcd7c8'],
    pants: ['#283449', '#34445f', '#415475'],
    boot: ['#2a1d13', '#43301f', '#5a432e'],
    belt: ['#21170f', '#36261a', '#4a3524'],
  }, outfit);
  const weave = (x, y, pal, k = 0.06) => {
    const r = rnd(x, y, 3);
    return r < k ? pal[2] : pal[1];
  };
  // paint a face rect with fn(x, y, w, h) -> colour (or null to skip)
  const paint = ([x0, y0, w, h], fn) => {
    for (let y = 0; y < h; y++) for (let x = 0; x < w; x++) {
      const c = fn(x, y, w, h, x0 + x, y0 + y); if (c) px(x0 + x, y0 + y, c);
    }
  };

  // ── Head (0,0) 8x8x8 ──
  const H = faces(0, 0, 8, 8, 8);
  const FACE = [
    'hhhhhhhh',
    'hhHhhhhh',
    'hsssssh.',
    'sBBssBBs',
    'sWEssEWs',
    'sssnnsss',
    'sssMMsss',
    'tsssssst',
  ];
  paint(H.front, (x, y) => {
    const k = FACE[y][x];
    return { h: P.hair[1], H: P.hair[2], s: P.skin[1], '.': P.hair[0], B: P.hair[0], W: '#ece8e0', E: '#3e6a86',
      n: P.skin[0], M: '#9a5e46', t: P.skin[0] }[k];
  });
  paint(H.top, (x, y, w, h, gx, gy) => (x === 3 && y > 1 ? P.hair[0] : weave(gx, gy, P.hair, 0.15)));
  paint(H.bottom, () => P.skin[0]);
  paint(H.back, (x, y, w, h, gx, gy) => (y === 7 ? P.skin[0] : y === 6 && (x === 0 || x === 7) ? P.skin[0] : weave(gx, gy, P.hair, 0.15)));
  // sides: hair on top + toward the back; ear and sideburn
  for (const [side, backIsLeft] of [[H.right, true], [H.left, false]]) {
    paint(side, (x, y, w, h, gx, gy) => {
      const bx = backIsLeft ? x : 7 - x;                 // 0 = back edge
      if (y < 2 || (y < 6 && bx < 3) || (y === 6 && bx < 2)) return weave(gx, gy, P.hair, 0.15);
      if (y < 4 && bx === 6) return P.hair[1];           // sideburn
      if ((y === 4 || y === 5) && bx === 3) return P.skin[0];   // ear
      return y === 7 ? P.skin[0] : P.skin[1];
    });
  }

  // ── Body (16,16) 8x12x4: open jacket over a shirt, belt ──
  const B = faces(16, 16, 8, 12, 4);
  paint(B.front, (x, y, w, h, gx, gy) => {
    if (y === 11) return x === 3 || x === 4 ? '#b49a56' : P.belt[1];
    if (x === 3 || x === 4) return y === 0 ? P.skin[1] : y === 1 && x === 3 ? P.skin[0] : weave(gx, gy, P.shirt, 0.08);
    if (x === 2 || x === 5) return P.jacket[0];                      // lapels
    if (y === 10) return P.jacket[0];                                // hem
    if ((y === 6) && (x === 0 || x === 1 || x === 6 || x === 7)) return P.jacket[0];   // pocket flaps
    if (y === 7 && (x === 1 || x === 6)) return P.jacket[2];
    return weave(gx, gy, P.jacket);
  });
  paint(B.back, (x, y, w, h, gx, gy) => (y === 11 ? P.belt[1] : y === 0 ? P.jacket[0] : y === 10 ? P.jacket[0] : weave(gx, gy, P.jacket)));
  for (const f of [B.left, B.right]) paint(f, (x, y, w, h, gx, gy) => (y === 11 ? P.belt[1] : y === 10 ? P.jacket[0] : weave(gx, gy, P.jacket)));
  paint(B.top, (x, y, w, h, gx, gy) => ((x >= 3 && x <= 4 && y >= 1 && y <= 2) ? P.skin[0] : weave(gx, gy, P.jacket)));
  paint(B.bottom, (x, y, w, h, gx, gy) => weave(gx, gy, P.pants));

  // ── Arms: right (40,16), left (32,48) 4x12x4: sleeve, cuff, hand ──
  for (const [u, v] of [[40, 16], [32, 48]]) {
    const A = faces(u, v, 4, 12, 4);
    const arm = (x, y, w, h, gx, gy) => (y >= 9 ? (y === 11 ? P.skin[0] : P.skin[1]) : y === 8 ? P.jacket[0] : weave(gx, gy, P.jacket));
    for (const f of [A.front, A.back, A.left, A.right]) paint(f, arm);
    paint(A.top, (x, y, w, h, gx, gy) => weave(gx, gy, P.jacket));
    paint(A.bottom, () => P.skin[0]);
  }

  // ── Legs: right (0,16), left (16,48) 4x12x4: trousers, boots ──
  for (const [u, v] of [[0, 16], [16, 48]]) {
    const L = faces(u, v, 4, 12, 4);
    const leg = (x, y, w, h, gx, gy) => {
      if (y === 11) return P.boot[0];
      if (y >= 9) return y === 9 ? P.boot[2] : P.boot[1];
      if (y === 8) return P.pants[0];
      return weave(gx, gy, P.pants);
    };
    for (const f of [L.front, L.back, L.left, L.right]) paint(f, leg);
    paint(L.top, (x, y, w, h, gx, gy) => weave(gx, gy, P.pants));
    paint(L.bottom, () => P.boot[0]);
  }
  const tex = new THREE.CanvasTexture(cv);
  tex.magFilter = THREE.NearestFilter; tex.minFilter = THREE.NearestFilter;
  tex.generateMipmaps = false;
  tex.colorSpace = THREE.SRGBColorSpace;
  return tex;
}

// Box geometry with Minecraft box-UV mapping into the 64x64 skin
export function skinBox(w, h, d, u, v) {
  const geo = new THREE.BoxGeometry(w, h, d);
  const f = faces(u, v, w, h, d);
  // BoxGeometry face order: +x, -x, +y, -y, +z, -z (model faces +z, so its
  // own right side is -x)
  const order = [f.left, f.right, f.top, f.bottom, f.front, f.back];
  const uv = geo.attributes.uv;
  order.forEach(([x, y, fw, fh], i) => {
    const u0 = x / SKIN_W, u1 = (x + fw) / SKIN_W, vt = 1 - y / SKIN_W, vb = 1 - (y + fh) / SKIN_W;
    const k = i * 4;
    uv.setXY(k, u0, vt); uv.setXY(k + 1, u1, vt); uv.setXY(k + 2, u0, vb); uv.setXY(k + 3, u1, vb);
  });
  uv.needsUpdate = true;
  return geo;
}

// Builds the rig. Returns { root, body, head, armR, armL, legR, legL } with
// pivots at neck (y=24), shoulders (y=22, x=+-6) and hips (y=12, x=+-2);
// feet at y=0, model faces +z.
const _skinCache = new Map();
export function buildHumanModel(outfitName = 'survivor', MatClass = THREE.MeshLambertMaterial) {
  const key = outfitName + '|' + MatClass.name;
  let skin = _skinCache.get(key);
  if (!skin) {
    skin = new MatClass({ map: paintSkin(OUTFITS[outfitName] || {}), alphaTest: 0.5 });
    _skinCache.set(key, skin);
  }
  const part = (w, h, d, u, v, py) => { const m = new THREE.Mesh(skinBox(w, h, d, u, v), skin); m.position.y = py; return m; };
  const root = new THREE.Group();
  const body = new THREE.Group();
  const torso = part(8, 12, 4, 16, 16, 18);
  const head = new THREE.Group(); head.position.y = 24; head.add(part(8, 8, 8, 0, 0, 4));
  const armR = new THREE.Group(); armR.position.set(-6, 22, 0); armR.add(part(4, 12, 4, 40, 16, -4));
  const armL = new THREE.Group(); armL.position.set(6, 22, 0); armL.add(part(4, 12, 4, 32, 48, -4));
  const legR = new THREE.Group(); legR.position.set(-2, 12, 0); legR.add(part(4, 12, 4, 0, 16, -6));
  const legL = new THREE.Group(); legL.position.set(2, 12, 0); legL.add(part(4, 12, 4, 16, 48, -6));
  body.add(torso, head, armR, armL, legR, legL);
  root.add(body);
  return { root, body, head, armR, armL, legR, legL };
}
