// ── texture atlas ──────────────────────────────────────────────────────────
const TEX_NAMES = Object.keys(PAINTERS);
const COLS = 16;
export const ATLAS_TILES = COLS;
const _tileIdx = new Map(TEX_NAMES.map((n, i) => [n, i]));
const _tileCanvas = new Map();

export function tileCanvas(name) {
  if (_tileCanvas.has(name)) return _tileCanvas.get(name);
  const p = new Px(hashStr(name));
  (PAINTERS[name] || stone)(p);
  const c = document.createElement('canvas'); c.width = c.height = N;
  c.getContext('2d').putImageData(new ImageData(p.d, N, N), 0, 0);
  _tileCanvas.set(name, c);
  return c;
}

// Each 16px tile sits in a 32px cell with 8px of wrapped padding so mipmaps
// (which vanilla uses to keep distant terrain calm instead of shimmering)
// never bleed neighbouring tiles together.
const CELL = 32, PAD = 8;
const ROWS = (() => { let r = 1; while (r < Math.ceil(TEX_NAMES.length / COLS)) r *= 2; return r; })();
let _atlas = null;
export function atlasTexture() {
  if (_atlas) return _atlas;
  const c = document.createElement('canvas'); c.width = COLS * CELL; c.height = ROWS * CELL;
  const g = c.getContext('2d');
  TEX_NAMES.forEach((n, i) => {
    const t = tileCanvas(n), x0 = (i % COLS) * CELL + PAD, y0 = Math.floor(i / COLS) * CELL + PAD;
    g.save(); g.beginPath(); g.rect(x0 - PAD, y0 - PAD, CELL, CELL); g.clip();
    for (let dy = -1; dy <= 1; dy++) for (let dx = -1; dx <= 1; dx++) g.drawImage(t, x0 + dx * N, y0 + dy * N);
    g.restore();
  });
  const t = new THREE.CanvasTexture(c);
  t.magFilter = THREE.NearestFilter; t.minFilter = THREE.NearestMipmapLinearFilter; t.generateMipmaps = true;
  t.colorSpace = THREE.SRGBColorSpace; t.flipY = false;
  _atlas = t;
  return t;
}
// UV rect [u0, v0, u1, v1] of a texture tile in the atlas (flipY=false: v down)
export function tileUV(name) {
  const i = _tileIdx.get(name) ?? 0, W = COLS * CELL, Hh = ROWS * CELL;
  const u0 = ((i % COLS) * CELL + PAD) / W, v0 = (Math.floor(i / COLS) * CELL + PAD) / Hh;
  return [u0, v0, u0 + N / W, v0 + N / Hh];
}

// Single-texture tiled material (structures/items outside the voxel world)
const _texCache = new Map();
export function blockTexture(name) {
  if (_texCache.has(name)) return _texCache.get(name);
  const t = new THREE.CanvasTexture(tileCanvas(name));
  t.magFilter = THREE.NearestFilter; t.minFilter = THREE.NearestFilter; t.generateMipmaps = false;
  t.wrapS = t.wrapT = THREE.RepeatWrapping; t.colorSpace = THREE.SRGBColorSpace;
  _texCache.set(name, t);
  return t;
}

// ── inventory icons: isometric 3D block like the vanilla GUI ──────────────
const _iconCache = new Map();
// Inventory icons for shaped blocks: the same isometric view as cube icons,
// drawn box by box (back to front) with each face cropped from its texture.
function isoBoxes(g, b, boxes) {
  const P = (x, y, z) => [32 + 26 * (x - z), 4 + 13 * (x + z) + 30 * (1 - y)];
  const q = 1 / N;
  const face = (name, m, sx, sy, sw, sh, dark) => {
    if (sw <= 0 || sh <= 0) return;
    g.save(); g.setTransform(...m);
    g.drawImage(tileCanvas(name), sx, sy, sw, sh, 0, 0, sw, sh);
    if (dark) { g.globalCompositeOperation = 'source-atop'; g.fillStyle = `rgba(0,0,0,${dark})`; g.fillRect(0, 0, sw, sh); }
    g.restore();
  };
  for (const [x0, y0, z0, x1, y1, z1] of boxes) {
    const W = (x1 - x0) * N, H = (y1 - y0) * N, D = (z1 - z0) * N;
    face(b.tex.top, [26 * q, 13 * q, -26 * q, 13 * q, ...P(x0, y1, z0)], x0 * N, z0 * N, W, D, 0);
    face(b.tex.front || b.tex.side, [26 * q, 13 * q, 0, 30 * q, ...P(x0, y1, z1)], x0 * N, (1 - y1) * N, W, H, 0.42);
    face(b.tex.side, [26 * q, -13 * q, 0, 30 * q, ...P(x1, y1, z1)], (1 - z1) * N, (1 - y1) * N, D, H, 0.22);
  }
}

export function blockIconURI(blockId) {
  if (_iconCache.has(blockId)) return _iconCache.get(blockId);
  const b = BLOCKS[blockId]; if (!b) return '';
  const c = document.createElement('canvas'); c.width = c.height = 64;
  const g = c.getContext('2d'); g.imageSmoothingEnabled = false;
  if (b.render === 'cross') {
    g.drawImage(tileCanvas(b.tex.side), 0, 0, 64, 64);
  } else if (b.shape && b.shape !== SHAPE.pillar) {
    isoBoxes(g, b, ITEM_BOXES[b.shape]);
  } else {
    const face = (name, m, dark) => {
      g.save(); g.setTransform(...m);
      g.drawImage(tileCanvas(name), 0, 0);
      if (dark) { g.globalCompositeOperation = 'source-atop'; g.fillStyle = `rgba(0,0,0,${dark})`; g.fillRect(0, 0, N, N); }
      g.restore();
    };
    const k = 26 / 16, h = 13 / 16, d = 30 / 16;
    face(b.tex.top, [k, h, -k, h, 32, 4], 0);
    face(b.tex.front || b.tex.side, [k, h, 0, d, 6, 17], 0.42);
    face(b.tex.side, [k, -h, 0, d, 32, 30], 0.22);
  }
  const uri = c.toDataURL();
  _iconCache.set(blockId, uri);
  return uri;
}

// ── destroy-stage crack overlays (10 stages) ──────────────────────────────
let _cracks = null;
// Block-breaking overlay, 10 stages. Original crack art: a handful of jagged
// 1px fissures radiating from near the centre with short side branches; each
// pixel has an "arrival" time so later stages extend the same cracks rather
// than redrawing them. Pixels are grey levels for vanilla's 2x multiply blend
// (128 = no change, darker = darken, lighter = brighten); transparent = skip.
export function crackTextures() {
  if (_cracks) return _cracks;
  // Shatter pattern: jittered seed points split the face into fragments
  // (nearest-seed cells). Crack pixels are the 1px cell borders. Each crack
  // pixel gets an "age" from its distance to the impact point plus noise, so
  // the web spreads outward stage by stage until it covers the whole face.
  // Deeper cracks (older) are darker; a light chipped rim sits on the upper-
  // left edge of each fissure; late stages darken the inner fragments.
  const r = rng(90210);
  // ~11 randomly scattered fragment seeds (min spacing so no slivers), one
  // near the impact point in the middle
  const seeds = [[7 + r() * 2, 7 + r() * 2]];
  for (let tries = 0; seeds.length < 11 && tries < 500; tries++) {
    const p = [r() * 16, r() * 16];
    if (seeds.every(([sx, sy]) => Math.hypot(sx - p[0], sy - p[1]) > 3.6)) seeds.push(p);
  }
  // per-pixel jitter (domain warp) makes the fissures zig-zag
  const jx = new Float32Array(N * N).map(() => (r() - 0.5) * 1.6);
  const jy = new Float32Array(N * N).map(() => (r() - 0.5) * 1.6);
  const cellOf = new Int8Array(N * N);
  for (let y = 0; y < N; y++) for (let x = 0; x < N; x++) {
    let best = 1e9, bi = 0;
    const px = x + 0.5 + jx[y * N + x], py = y + 0.5 + jy[y * N + x];
    for (let i = 0; i < seeds.length; i++) {
      const d = (px - seeds[i][0]) ** 2 + (py - seeds[i][1]) ** 2;
      if (d < best) { best = d; bi = i; }
    }
    cellOf[y * N + x] = bi;
  }
  const cx = 7.5, cy = 7.5;
  const age = new Float32Array(N * N).fill(Infinity);
  for (let y = 0; y < N; y++) for (let x = 0; x < N; x++) {
    const c = cellOf[y * N + x];
    const border = (x + 1 < N && cellOf[y * N + x + 1] !== c) || (y + 1 < N && cellOf[(y + 1) * N + x] !== c);
    if (border) age[y * N + x] = Math.hypot(x + 0.5 - cx, y + 0.5 - cy) + r() * 2.2;
  }
  // inner fragment darkening for the last stages, by cell distance to centre
  const cellDist = seeds.map(([sx, sy]) => Math.hypot(sx - cx, sy - cy));
  let max = 0;
  for (const a of age) if (a !== Infinity && a > max) max = a;
  _cracks = [];
  for (let s = 0; s < 10; s++) {
    const th = 1.2 + ((s + 1) / 10) * (max - 1.2);
    const c = document.createElement('canvas'); c.width = c.height = N;
    const g = c.getContext('2d');
    const on = (x, y) => x >= 0 && y >= 0 && x < N && y < N && age[y * N + x] <= th;
    const crumble = s >= 6 ? (s - 5) * 1.9 : -1;            // radius of loosened fragments
    for (let y = 0; y < N; y++) for (let x = 0; x < N; x++) {
      const i = y * N + x;
      if (on(x, y)) {
        const deep = age[i] < th * 0.45;
        const v = deep ? 38 : 70;
        g.fillStyle = `rgb(${v},${v},${v})`; g.fillRect(x, y, 1, 1);
      } else if ((on(x + 1, y) || on(x, y + 1)) && ((x * 5 + y * 3) % 4 !== 0)) {
        g.fillStyle = 'rgb(150,150,150)'; g.fillRect(x, y, 1, 1);      // chipped light rim
      } else if (cellDist[cellOf[i]] < crumble && ((x * 7 + y * 11) % 7 === 0)) {
        g.fillStyle = 'rgb(96,96,96)'; g.fillRect(x, y, 1, 1);         // loosened fragment
      }
    }
    const t = new THREE.CanvasTexture(c);
    t.magFilter = THREE.NearestFilter; t.minFilter = THREE.NearestFilter; t.generateMipmaps = false;
    _cracks.push(t);
  }
  return _cracks;
}
