// PlayerPreview3D.js — live 3D player model for the inventory preview box.
//
// An original survivor character built from textured boxes in vanilla
// proportions (head 8x8x8, body 8x12x4, arms/legs 4x12x4; 1 unit = 1 skin
// pixel). The 64x64 skin is painted in code using the classic box-UV layout.
// Rendered by its own small transparent WebGLRenderer, lit with flat ambient +
// one front-left directional light, and posed like vanilla's inventory entity:
// body and head turn toward the mouse pointer. Worn armor shows as slightly
// inflated tinted boxes; the selected hotbar item is held in the right hand.

import * as THREE from 'three';
import { MC_ARMOR, buildMcModel } from '../content/McContent.js';
import { RAMPS } from '../content/ItemArt.js';
import { buildHumanModel } from '../entities/HumanModel.js';
import { extrudeSprite } from '../content/ItemMesh.js';
import { hasItemIcon, itemIconCanvas } from './ItemIcons.js';

// ── Armor ──────────────────────────────────────────────────────────────────
// Vanilla-style armor layer: boxes slightly larger than the body part (1px for
// helmet/chest/boots, 0.5px for leggings), textured per face with plate shapes
// cut out of a transparent texture, so the body shows through the gaps.
// Each face is a w x h texel grid matching the underlying body box.
// mask(face, x, y, w, h) -> true where a plate covers the texel
const ARMOR_PARTS = {
  helmet: (f, x, y, w, h) => {
    if (f === 'bottom') return false;
    if (f === 'top') return true;
    if (f === 'front') return y <= 2 || ((x === 0 || x === w - 1) && y <= 5);
    return y <= 5 || (f === 'back' && y <= 6);
  },
  chest: (f, x, y, w, h) => {
    if (f === 'bottom') return false;
    if (f === 'top') return !(x >= 2 && x <= 5 && y >= 1 && y <= 2);
    if (f === 'front') { if (y === 0 && x >= 2 && x <= 5) return false; if (y === 1 && x >= 3 && x <= 4) return false; }
    return y <= 10;
  },
  shoulder: (f, x, y, w, h) => (f === 'bottom' ? false : f === 'top' ? true : y <= 4),
  waist: (f, x, y, w, h) => (f === 'top' || f === 'bottom' ? false : y >= 9),
  legs: (f, x, y, w, h) => (f === 'top' || f === 'bottom' ? false : y <= 8),
  boots: (f, x, y, w, h) => (f === 'top' ? false : f === 'bottom' ? true : y >= 8),
};
const FACE_DIMS = (w, h, d) => ({ left: [d, h], right: [d, h], top: [w, d], bottom: [w, d], front: [w, h], back: [w, h] });

function paintArmorFace(part, face, w, h, mat) {
  const R = RAMPS[mat] || RAMPS.iron;
  const cv = document.createElement('canvas'); cv.width = w; cv.height = h;
  const g = cv.getContext('2d');
  const m = ARMOR_PARTS[part];
  const on = (x, y) => x >= 0 && y >= 0 && x < w && y < h && m(face, x, y, w, h);
  for (let y = 0; y < h; y++) for (let x = 0; x < w; x++) {
    if (!on(x, y)) continue;
    // mostly flat plate; a lit top rim, a dark lower rim and a few
    // structural lines, like vanilla armor textures
    let k = 2;
    const lowerRim = !on(x, y + 1) || y === h - 1;
    const topRim = !on(x, y - 1) || y === 0;
    if (face === 'top' || face === 'bottom') k = (x + y) % 2 ? 2 : 3;
    else if (lowerRim) k = 1;
    else if (topRim) k = 3;
    if (part === 'chest' && face === 'front' && y === 5) k = 1;                 // plate join
    if (part === 'chest' && face === 'front' && y > 1 && y < 10 && (x === 0 || x === w - 1)) k = 1;
    if (part === 'helmet' && face === 'front' && y === 2) k = 1;               // brow ridge
    if (part === 'legs' && face === 'front' && y === 4) k = 3;                 // knee plate
    if (part === 'legs' && y === 0) k = 1;
    if (part === 'boots' && y === 8 && face !== 'bottom') k = 3;               // cuff
    if (mat === 'iron' && face === 'front' && k === 2 && part === 'chest' && (y === 3 || y === 7) && (x === 1 || x === w - 2)) k = 4;
    if (mat === 'gold' && k === 2 && (x + y) % 6 === 0) k = 3;
    if (mat === 'diamond' && k === 2 && (x - y + 16) % 5 === 0) k = 3;
    if (mat === 'leather' && k === 1 && x % 2 === 0) k = 0;                    // stitching
    g.fillStyle = R[k]; g.fillRect(x, y, 1, 1);
  }
  const t = new THREE.CanvasTexture(cv);
  t.magFilter = t.minFilter = THREE.NearestFilter; t.generateMipmaps = false; t.colorSpace = THREE.SRGBColorSpace;
  return new THREE.MeshLambertMaterial({ map: t, alphaTest: 0.5, transparent: false });
}

const _armorMats = {};
// materials for a body box of size (w,h,d) in BoxGeometry face order
function armorMats(part, mat, w, h, d) {
  const key = `${part}|${mat}|${w}x${h}x${d}`;
  if (_armorMats[key]) return _armorMats[key];
  const dims = FACE_DIMS(w, h, d);
  // BoxGeometry: +x, -x, +y, -y, +z, -z. Model faces +z; its right side is -x.
  const order = ['left', 'right', 'top', 'bottom', 'front', 'back'];
  _armorMats[key] = order.map((f) => paintArmorFace(part, f, dims[f][0], dims[f][1], mat));
  return _armorMats[key];
}

export class PlayerPreview3D {
  constructor(inv) {
    this.inv = inv;
    this.renderer = null;
    this._raf = 0;
    this._mouse = { x: 0, y: 0, has: false };
    this._onMove = (e) => { this._mouse.x = e.clientX; this._mouse.y = e.clientY; this._mouse.has = true; };
  }

  _init() {
    if (this.renderer) return true;
    try {
      this.renderer = new THREE.WebGLRenderer({ alpha: true, antialias: false, premultipliedAlpha: true, powerPreference: 'low-power' });
    } catch (e) { console.warn('Inventory preview: WebGL unavailable', e); return false; }
    this.renderer.setClearColor(0x000000, 0);
    this.renderer.outputColorSpace = THREE.SRGBColorSpace;
    const c = this.renderer.domElement;
    c.className = 'mc-preview-canvas';
    this.scene = new THREE.Scene();
    // vanilla inventory-entity lighting: flat ambient + one front-left light
    this.scene.add(new THREE.AmbientLight(0xffffff, 0.95));
    const sun = new THREE.DirectionalLight(0xffffff, 1.05);
    sun.position.set(-0.6, 1.0, 1.2);
    const fill = new THREE.DirectionalLight(0xffffff, 0.35);
    fill.position.set(0.8, 0.3, 0.6);
    this.scene.add(sun, fill);
    this.camera = new THREE.OrthographicCamera(-1, 1, 1, -1, -100, 100);
    this.camera.position.set(0, 0, 50);

    const { root, body, head, armR, armL, legR, legL } = buildHumanModel('survivor');
    this.scene.add(root);
    Object.assign(this, { root, body, head, armR, armL, legR, legL, armorGroup: [] });
    return true;
  }

  // Attach the canvas to a preview box element (re-laid out on every open)
  attach(box) {
    if (!this._init()) return;
    this.box = box;
    box.appendChild(this.renderer.domElement);
    this._resize();
  }

  _resize() {
    const us = parseFloat(getComputedStyle(document.documentElement).getPropertyValue('--us')) || 2;
    // inner black area of the preview box: 49x70 GUI px
    const W = 49, H = 70;
    this.renderer.setPixelRatio(window.devicePixelRatio || 1);
    this.renderer.setSize(W * us, H * us, true);
    // vanilla scale: a 32px-tall player is ~54 GUI px tall, feet 2px above
    // the bottom edge, centred horizontally
    const k = 54 / 32;
    const w = W / k, h = H / k, bottom = -2 / k;
    Object.assign(this.camera, { left: -w / 2, right: w / 2, bottom, top: bottom + h });
    this.camera.updateProjectionMatrix();
    this._us = us;
  }

  _clearArmor() {
    for (const m of this.armorGroup) m.parent?.remove(m);
    this.armorGroup = [];
  }

  // Rebuild armor pieces + held item from the inventory
  updateEquipment() {
    if (!this.renderer) return;
    const armor = this.inv.armor ?? {};
    const held = this.inv.slots?.[this.inv.selectedSlot] ?? null;
    const sig = ['head', 'chest', 'legs', 'feet'].map((k) => armor[k]?.type ?? '').join('|') + '#' + (held?.type ?? '');
    if (sig === this._sig) return;
    this._sig = sig;
    this._clearArmor();
    // box of body size (w,h,d) inflated by `inf`, centred at y in parent
    const add = (parent, part, mat, w, h, d, inf, y) => {
      const m = new THREE.Mesh(new THREE.BoxGeometry(w + inf * 2, h + inf * 2, d + inf * 2), armorMats(part, mat, w, h, d));
      m.position.y = y; parent.add(m); this.armorGroup.push(m); return m;
    };
    const matOf = (s) => MC_ARMOR[s?.type]?.material ?? (s ? 'iron' : null);
    const mh = matOf(armor.head), mc = matOf(armor.chest), ml = matOf(armor.legs), mf = matOf(armor.feet);
    if (mh) add(this.head, 'helmet', mh, 8, 8, 8, 1, 4);
    if (mc) {
      add(this.body, 'chest', mc, 8, 12, 4, 1, 18);
      add(this.armR, 'shoulder', mc, 4, 12, 4, 1, -4); add(this.armL, 'shoulder', mc, 4, 12, 4, 1, -4);
    }
    if (ml) {
      add(this.body, 'waist', ml, 8, 12, 4, 0.5, 18);
      add(this.legR, 'legs', ml, 4, 12, 4, 0.5, -6); add(this.legL, 'legs', ml, 4, 12, 4, 0.5, -6);
    }
    if (mf) { add(this.legR, 'boots', mf, 4, 12, 4, 1, -6); add(this.legL, 'boots', mf, 4, 12, 4, 1, -6); }
    // Held item in the right hand (arm raised a little, like vanilla)
    this.armR.rotation.x = 0;
    if (held && !MC_ARMOR[held.type]) {
      let model = null;
      try { model = buildMcModel(held.type); } catch { model = null; }
      let flat = false;
      if (!model && hasItemIcon(held.type)) {
        const spr = extrudeSprite(itemIconCanvas(held.type));
        if (spr) { spr.scale.setScalar(0.4); model = new THREE.Group(); model.add(spr); flat = true; }
      }
      if (model) {
        const isTool = flat || /^weapon_/.test(held.type);
        model.scale.setScalar(isTool ? 22 : 20);
        model.position.set(0, -11, isTool ? 4 : 3);
        if (isTool) model.rotation.set(0, -Math.PI / 7, Math.PI / 4);
        else model.rotation.set(0.3, 0.6, 0);
        this.armR.add(model);
        this.armorGroup.push(model);
        this.armR.rotation.x = -0.3;
      }
    }
  }

  start() {
    if (!this.renderer || this._raf) return;
    document.addEventListener('mousemove', this._onMove);
    const loop = () => {
      this._raf = requestAnimationFrame(loop);
      if (!this.box?.isConnected) return;
      const us = parseFloat(getComputedStyle(document.documentElement).getPropertyValue('--us')) || 2;
      if (us !== this._us) this._resize();
      this.updateEquipment();
      this._pose();
      this.renderer.render(this.scene, this.camera);
    };
    loop();
  }

  // Vanilla follow-mouse pose: f = atan(dx/40), g = atan(dy/40) in GUI px
  // measured from the model's centre / eye line; body yaw f*20 deg, head yaw
  // f*40 deg, head pitch g*20 deg, small whole-model tilt.
  _pose() {
    const r = this.box.getBoundingClientRect();
    const us = this._us || 2;
    let f = 0, g = 0;
    if (this._mouse.has) {
      const cx = r.left + r.width / 2, eyeY = r.top + 18 * us;
      f = Math.atan((cx - this._mouse.x) / us / 40);
      g = Math.atan((eyeY - this._mouse.y) / us / 40);
    }
    const D = Math.PI / 180;
    this.body.rotation.y = -f * 20 * D;
    this.head.rotation.y = -f * 20 * D;          // + body = f*40 total
    this.head.rotation.x = -g * 20 * D;
    this.root.rotation.x = -g * 8 * D;
  }

  stop() {
    cancelAnimationFrame(this._raf);
    this._raf = 0;
    document.removeEventListener('mousemove', this._onMove);
  }

  dispose() {
    this.stop();
    this.renderer?.dispose();
    this.renderer?.domElement.remove();
    this.renderer = null;
  }
}
