// LabGenerator.js — buried research labs.
//
// One lab per 160x160 region (60% of regions) plus a guaranteed "starter" lab
// 70-95 blocks from spawn. Positions/rotation come from the world seed, so a
// site is planned exactly once, the first time a chunk near it is generated;
// its blocks go through setBlock (queued as pending edits for chunks that do
// not exist yet), the same path the surface houses use.
//
// Layout (local coords, the entrance tunnel runs toward -z, rotated 0..3):
//   main hall 15x11 with two glass specimen tanks, a desk wall of unlocked
//   storage chests, and a vault room behind a partition holding 2-4 keypad
//   lockers. Every locker gets a fresh random 4-digit code (Math.random, so
//   codes differ every world even on the same seed); each code is written on
//   an Access Memo hidden in one of that lab's unlocked chests.

import { BLOCK } from './Blocks.js';

const RS = 160;                     // region size in blocks
const HALL_W = 17, HALL_D = 13, HALL_H = 6;   // outer box, x 0..16, z 0..12, y 0..6
const LOCKER_LETTERS = 'ABCD';
const LOGS = [
  ['Specimen 7 cracked tank B overnight.', 'We sealed the vault. Codes are', 'in the storage chests, as usual.'],
  ['Growth rate doubled after feeding.', 'Do not open the tanks without', 'a second technician present.'],
  ['Power is failing. Lights on backup.', 'If you read this, the surface', 'teams did not make it.'],
  ['The host tissue keeps moving after', 'death. Burn every sample before', 'leaving the lab.'],
  ['Locker codes rotated again. Memo', 'copies went into storage. Do NOT', 'leave them on the desk.'],
];

function srand(seed) {
  let s = (seed >>> 0) || 1;
  return () => { s ^= s << 13; s >>>= 0; s ^= s >> 17; s ^= s << 5; s >>>= 0; return s / 4294967296; };
}
function hash2(a, b, c = 0) { let h = 2166136261 ^ c; h = Math.imul(h ^ a, 16777619); h = Math.imul(h ^ b, 16777619); return h >>> 0; }

// local direction -> world, for rotation r (0..3)
const ROT = [
  (x, z) => [x, z], (x, z) => [-z, x], (x, z) => [-x, -z], (x, z) => [z, -x],
];
// world unit direction -> block "front" index (VoxelWorld FACES dir)
const FRONT = (dx, dz) => (dz > 0 ? 0 : dx > 0 ? 1 : dz < 0 ? 2 : 3);

export class LabGenerator {
  constructor(game, voxelWorld) {
    this.game = game;
    this.vw = voxelWorld;
    this.seed = voxelWorld.seed;
    this.sites = new Map();          // key -> site | null
    this.labs = [];                  // built labs (minimap, debugging)
  }

  getLabs() { return this.labs; }

  // ── site selection ───────────────────────────────────────────────────────
  _starter() {
    if (this.sites.has('start')) return this.sites.get('start');
    const rnd = srand(hash2(91, 17, this.seed ^ 0x1ab5));
    let site = null;
    for (let tries = 0; tries < 12 && !site; tries++) {
      const a = rnd() * Math.PI * 2, d = 70 + rnd() * 25;
      const s = this._mkSite(Math.round(Math.cos(a) * d), Math.round(Math.sin(a) * d), (rnd() * 4) | 0, 'start');
      if (this._clear(s)) site = s;
    }
    this.sites.set('start', site);
    return site;
  }

  _region(rx, rz) {
    const key = rx + ',' + rz;
    if (this.sites.has(key)) return this.sites.get(key);
    const rnd = srand(hash2(rx, rz, this.seed ^ 0x2c71));
    let site = null;
    if (rnd() < 0.6) {
      const x = rx * RS + 30 + ((rnd() * (RS - 60)) | 0), z = rz * RS + 30 + ((rnd() * (RS - 60)) | 0);
      const s = this._mkSite(x, z, (rnd() * 4) | 0, key);
      const st = this._starter();
      const farFromStarter = !st || Math.hypot(st.ox - x, st.oz - z) > 110;
      if (Math.hypot(x, z) > 60 && farFromStarter && this._clear(s)) site = s;
    }
    this.sites.set(key, site);
    return site;
  }

  _mkSite(ox, oz, rot, key) {
    const s = { ox, oz, rot, key, built: false };
    // conservative world bbox: hall + up to 30 blocks of entrance tunnel
    const xs = [], zs = [];
    for (const [x, z] of [[-2, -32], [HALL_W + 1, -32], [-2, HALL_D + 1], [HALL_W + 1, HALL_D + 1]]) {
      const [wx, wz] = ROT[rot](x, z); xs.push(ox + wx); zs.push(oz + wz);
    }
    s.x0 = Math.min(...xs); s.x1 = Math.max(...xs); s.z0 = Math.min(...zs); s.z1 = Math.max(...zs);
    return s;
  }

  // Not on top of spawn or a surface house
  _clear(s) {
    const nx = Math.max(s.x0, Math.min(0, s.x1)), nz = Math.max(s.z0, Math.min(0, s.z1));
    if (Math.hypot(nx, nz) < 40) return false;
    const bs = this.game.buildingGenerator?.getBuildings?.() ?? [];
    return !bs.some((b) => b.bx0 - 4 < s.x1 && s.x0 < b.bx0 + b.W + 4 && b.bz0 - 4 < s.z1 && s.z0 < b.bz0 + b.D + 4);
  }

  // Called by VoxelWorld.ensureChunk before chunk (cx, cz) is generated
  planAround(cx, cz) {
    const x0 = cx * 16, z0 = cz * 16, M = 24;
    const near = (s) => s && !s.built && s.x0 - M < x0 + 16 && x0 < s.x1 + M && s.z0 - M < z0 + 16 && z0 < s.z1 + M;
    const st = this._starter();
    if (near(st)) this._build(st);
    const ra = Math.floor((x0 - 64) / RS), rb = Math.floor((x0 + 80) / RS);
    const qa = Math.floor((z0 - 64) / RS), qb = Math.floor((z0 + 80) / RS);
    for (let rx = ra; rx <= rb; rx++) for (let rz = qa; rz <= qb; rz++) {
      const s = this._region(rx, rz);
      if (near(s)) this._build(s);
    }
  }

  // ── construction ─────────────────────────────────────────────────────────
  _build(site) {
    site.built = true;
    const vw = this.vw, { ox, oz, rot } = site;
    const rnd = srand(hash2(ox, oz, this.seed ^ 0x4d1));
    const W = (x, z) => { const [a, b] = ROT[rot](x, z); return [ox + a, oz + b]; };
    const face = (dx, dz) => { const [a, b] = ROT[rot](dx, dz); return FRONT(a, b); };
    const ground = (x, z) => { const [wx, wz] = W(x, z); return vw._column(wx, wz).h; };

    // Floor level: 10 below the lowest ground over the hall, so at least
    // four blocks of earth cover the ceiling everywhere
    let minG = Infinity;
    for (let x = 0; x < HALL_W; x += 2) for (let z = 0; z < HALL_D; z += 2) minG = Math.min(minG, ground(x, z));
    const Y0 = Math.max(-32 + 8, minG - 10);

    const vox = new Map();             // "x,y,z" (local) -> [name|null, front]
    const put = (x, y, z, name, front) => vox.set(x + ',' + y + ',' + z, [name, front]);
    const tile = () => (rnd() < 0.07 ? 'lab_tiles_stained' : 'lab_tiles');

    // Hall shell + cleared interior
    for (let x = 0; x < HALL_W; x++) for (let z = 0; z < HALL_D; z++) for (let y = -1; y <= HALL_H; y++) {
      const edge = x === 0 || z === 0 || x === HALL_W - 1 || z === HALL_D - 1;
      if (y === -1) put(x, y, z, 'stone');
      else if (y === 0) put(x, y, z, 'lab_floor');
      else if (y === HALL_H) put(x, y, z, x % 4 === 2 && z % 4 === 2 && !edge ? 'lab_lamp' : tile());
      else put(x, y, z, edge ? tile() : null);
    }
    // Vault partition at x=11 with a hazard-framed doorway (z 5..7, y 1..3)
    for (let z = 1; z < HALL_D - 1; z++) for (let y = 1; y < HALL_H; y++) {
      const door = z >= 5 && z <= 7 && y <= 3;
      put(11, y, z, door ? null : ((z === 4 || z === 8) && y <= 4) || (y === 4 && z >= 5 && z <= 7) ? 'hazard_block' : tile());
    }
    // Entrance doorway in the north wall (x 7..9, y 1..3), hazard frame
    for (let y = 1; y <= 4; y++) { put(6, y, 0, 'hazard_block'); put(10, y, 0, 'hazard_block'); }
    for (let x = 7; x <= 9; x++) { put(x, 4, 0, 'hazard_block'); for (let y = 1; y <= 3; y++) put(x, y, 0, null); }

    // Specimen tanks: steel plinth + cap, glass walls, flesh inside
    for (const cz of [3, 9]) {
      for (let x = 4; x <= 6; x++) for (let z = cz - 1; z <= cz + 1; z++) {
        put(x, 1, z, 'lab_floor'); put(x, 5, z, 'lab_floor');
        const centre = x === 5 && z === cz;
        for (let y = 2; y <= 4; y++) put(x, y, z, centre ? (y === 4 ? 'biomass' : 'flesh_block') : 'glass');
      }
      if (rnd() < 0.5) { put(4, 3, cz - 1, null); put(4, 2, cz - 1, null); put(3, 1, cz - 2, 'biomass'); } // a broken tank
    }

    // Desk wall (x=1): storage chests + crafting table + furnace, facing +x
    const nStorage = rnd() < 0.5 ? 2 : 3;
    const storeZ = nStorage === 2 ? [2, 10] : [2, 6, 10];
    const fx = face(1, 0);
    for (const z of storeZ) put(1, 1, z, 'chest', fx);
    put(1, 1, 4, 'crafting_table', fx);
    put(1, 1, 8, 'furnace', fx);

    // Vault (x 12..15): lockers on the far wall, facing -x
    const nLock = 2 + ((rnd() * 3) | 0);
    const slotsZ = [2, 4, 6, 8, 10];
    const lockZ = [];
    while (lockZ.length < nLock) { const z = slotsZ.splice((rnd() * slotsZ.length) | 0, 1)[0]; lockZ.push(z); }
    lockZ.sort((a, b) => a - b);
    const fl = face(-1, 0);
    for (const z of lockZ) put(15, 1, z, 'keypad_locker', fl);

    // SecurityCraft devices: a keypad wired to each locker, a laser
    // tripwire across the vault doorway with an alarm on either side, a
    // panic button and a username logger on the desk wall
    for (const z of lockZ) put(15, 2, z, 'sc_keypad', fl);
    put(11, 1, 4, 'sc_laser_block'); put(11, 1, 8, 'sc_laser_block');
    put(9, 5, 6, 'sc_alarm'); put(13, 5, 6, 'sc_alarm');
    put(1, 2, 4, 'sc_panic_button');
    put(1, 2, 8, 'sc_username_logger', fx);

    // Entrance tunnel: 3 wide, one block up per block out, until the
    // walking height reaches the surface; then a 2-block landing
    let K = 1;
    const tunnelGround = (k) => Math.max(ground(7, -k), ground(8, -k), ground(9, -k));
    while (K < 30 && Y0 + K + 1 < tunnelGround(K)) K++;
    const steps = K + 2;
    for (let k = 1; k <= steps; k++) {
      const z = -k, fy = Math.min(k, K);                // floor block local y
      const mouth = k === steps;
      for (let x = 6; x <= 10; x++) {
        const wall = x === 6 || x === 10;
        put(x, fy, z, wall ? tile() : 'lab_floor');
        for (let y = fy + 1; y <= fy + 4; y++) put(x, y, z, wall ? (mouth ? 'hazard_block' : tile()) : null);
        put(x, fy + 5, z, mouth ? 'hazard_block' : (!wall && x === 8 && k % 4 === 2 ? 'lab_lamp' : tile()));
        // prop the exposed part of the tube up on the terrain
        const g = ground(x, z) - Y0;
        for (let y = Math.max(g, fy - 8); y < fy; y++) put(x, y, z, wall ? tile() : 'lab_floor');
      }
    }
    // a mine or two on the lower steps of a long tunnel
    if (K >= 5) {
      const ks = new Set([3 + ((rnd() * (K - 3)) | 0), 3 + ((rnd() * (K - 3)) | 0)]);
      for (const k of ks) put(7 + ((rnd() * 3) | 0), k + 1, -k, 'sc_mine');
    }
    // keep the mouth open even when a hill rises right in front of it
    for (let x = 7; x <= 9; x++) for (let y = K + 1; y <= K + 4; y++) put(x, y, -(steps + 1), null);
    // beacon pole beside the mouth: steel post + light, visible from afar
    {
      const px = 12, pz = -steps, g = ground(px, pz) - Y0;
      for (let y = g; y < g + 4; y++) put(px, y, pz, 'lab_floor');
      put(px, g + 4, pz, 'lab_lamp');
    }

    // Write blocks
    for (const [k, [name, front]] of vox) {
      const [x, y, z] = k.split(',').map(Number);
      const [wx, wz] = W(x, z);
      vw.setBlock(wx, Y0 + y, wz, name ? (BLOCK[name] ?? BLOCK.stone) : 0, front);
    }

    // Containers: lockers get random codes, memos go into storage chests
    const cs = this.game.containerSystem;
    let siteNo = 10 + (hash2(ox, oz, this.seed) % 90);
    while (this.labs.some((l) => l.name === `Site ${siteNo}`)) siteNo = siteNo >= 99 ? 10 : siteNo + 1;
    const lab = { name: `Site ${siteNo}`, x: 0, z: 0, lockers: [], storage: [], y: Y0 };
    [lab.x, lab.z] = W(8, -steps);
    lab.hall = W(8, 6);
    const keyAt = (x, y, z) => { const [wx, wz] = W(x, z); return `${wx},${Y0 + y},${wz}`; };
    const storageKeys = storeZ.map((z) => keyAt(1, 1, z));
    const stores = storageKeys.map(() => Array(27).fill(null));
    const free = stores.map(() => [...Array(27).keys()]);
    const stash = (stack) => {
      const i = (Math.random() * stores.length) | 0;
      const s = free[i].splice((Math.random() * free[i].length) | 0, 1)[0];
      stores[i][s] = stack;
    };
    lockZ.forEach((z, i) => {
      const key = keyAt(15, 1, z);
      const code = String(Math.floor(Math.random() * 10000)).padStart(4, '0');
      const label = `${lab.name} - Locker ${LOCKER_LETTERS[i]}`;
      cs?.addLock?.(key, code, label);
      cs?.registerLootChest?.(key, 'lab_vault');
      lab.lockers.push({ key, code, label });
      stash({
        type: 'mc_access_memo', quantity: 1, name: 'Access Memo',
        note: { title: 'Access Memo', lines: [label, `Code: ${code}`], short: `${label}: ${code}` },
      });
    });
    const log = LOGS[(rnd() * LOGS.length) | 0];
    stash({ type: 'mc_access_memo', quantity: 1, name: 'Research Log', note: { title: 'Research Log', lines: [lab.name, ...log], short: `${lab.name} research log` } });
    storageKeys.forEach((key, i) => {
      cs?.presetChest?.(key, stores[i]);
      cs?.registerLootChest?.(key, 'lab_storage');
    });
    lab.storage = storageKeys;
    site.lab = lab;
    this.labs.push(lab);
  }
}
