import * as THREE from 'three';

/**
 * VoxelStyle — a shared "Minecraft pixels, Hytale polish" art toolkit.
 *
 * The whole game was built from organic primitives (capsules, spheres, cones)
 * with smooth shading. This module reskins it into a blocky/voxel aesthetic:
 *
 *   - pixelated procedural textures (NearestFilter, no mipmaps) → the Minecraft
 *     "chunky pixel" surface look,
 *   - flat-shaded, low-spec materials → hard faceted lighting instead of smooth,
 *   - helpers to build models out of boxes,
 *   - blockify(root): a global pass that reskins ANY mesh tree added to the
 *     scene so even untouched systems (buildings, furniture, items, vehicles,
 *     weapon viewmodels) pick up the style.
 *
 * Hytale touch = we keep the richer lighting/shadows and layer a little extra
 * surface detail + saturated palettes on top of the raw Minecraft blockiness.
 */

// ── Pixel-texture plumbing ────────────────────────────────────────────────
const _texCache = new Map();
const _styledMats = new WeakSet();   // materials already blockified
const _styledTex  = new WeakSet();   // textures already set to nearest
const _deCurved   = new WeakSet();   // meshes whose geometry we already boxified

// Any rounded geometry is contraband in this game — circles are illegal, just
// like in Minecraft. These all get swapped for a real cuboid at blockify time.
const CURVED_GEO = new Set([
  'SphereGeometry', 'CylinderGeometry', 'CapsuleGeometry', 'ConeGeometry',
  'TorusGeometry', 'TorusKnotGeometry', 'CircleGeometry', 'LatheGeometry',
  'TubeGeometry', 'RingGeometry', 'DodecahedronGeometry', 'IcosahedronGeometry',
  'OctahedronGeometry', 'TetrahedronGeometry', 'ExtrudeGeometry',
]);

/**
 * deCurve(mesh): if a mesh carries rounded geometry, replace it in-place with a
 * BoxGeometry that fills the same bounding box (same size, same centre). This is
 * what makes the world genuinely blocky instead of just flat-shaded — spheres
 * become cubes, barrels become bars, etc. Opt out with
 * mesh.userData.noVox = true or geometry.userData.noVox = true (e.g. a few
 * UI/FX bits that must stay round).
 */
export function deCurve(mesh) {
  if (!mesh || !mesh.isMesh || _deCurved.has(mesh)) return mesh;
  const geo = mesh.geometry;
  if (!geo || !CURVED_GEO.has(geo.type)) { _deCurved.add(mesh); return mesh; }
  if (mesh.userData?.noVox || geo.userData?.noVox) { _deCurved.add(mesh); return mesh; }

  geo.computeBoundingBox();
  const bb = geo.boundingBox;
  if (!bb) { _deCurved.add(mesh); return mesh; }
  const sx = Math.max(bb.max.x - bb.min.x, 1e-4);
  const sy = Math.max(bb.max.y - bb.min.y, 1e-4);
  const sz = Math.max(bb.max.z - bb.min.z, 1e-4);
  const cx = (bb.max.x + bb.min.x) / 2;
  const cy = (bb.max.y + bb.min.y) / 2;
  const cz = (bb.max.z + bb.min.z) / 2;

  const boxGeo = new THREE.BoxGeometry(sx, sy, sz);
  if (cx || cy || cz) boxGeo.translate(cx, cy, cz);
  boxGeo.userData.__vox = true;
  mesh.geometry = boxGeo;
  try { geo.dispose(); } catch (_) {}
  _deCurved.add(mesh);
  return mesh;
}

export function pixelate(tex) {
  if (!tex || _styledTex.has(tex)) return tex;
  tex.magFilter = THREE.NearestFilter;
  tex.minFilter = THREE.NearestFilter;
  tex.generateMipmaps = false;
  tex.wrapS = THREE.RepeatWrapping;
  tex.wrapT = THREE.RepeatWrapping;
  tex.colorSpace = THREE.SRGBColorSpace;
  tex.anisotropy = 1;
  _styledTex.add(tex);
  return tex;
}

// Small helper: build a hex color string from a THREE.Color-able input
function toColor(c) { return c instanceof THREE.Color ? c : new THREE.Color(c); }

/**
 * A tileable pixel-noise texture derived from a base color: random per-pixel
 * brightness jitter plus a few darker "specks", so flat faces read as a
 * hand-painted Minecraft block rather than a solid fill. Cached by key.
 */
export function noiseTexture(baseColor, {
  size = 8, contrast = 0.14, specks = 0.10, speckDark = 0.45, key = null,
} = {}) {
  const base = toColor(baseColor);
  const cacheKey = key ?? `${base.getHexString()}_${size}_${contrast}_${specks}`;
  if (_texCache.has(cacheKey)) return _texCache.get(cacheKey);

  const cv = document.createElement('canvas');
  cv.width = cv.height = size;
  const ctx = cv.getContext('2d');
  // Deterministic-ish PRNG so a given color always looks the same
  let seed = 0;
  for (const ch of cacheKey) seed = (seed * 31 + ch.charCodeAt(0)) >>> 0;
  const rnd = () => { seed = (seed * 1664525 + 1013904223) >>> 0; return seed / 4294967296; };

  for (let y = 0; y < size; y++) {
    for (let x = 0; x < size; x++) {
      const c = base.clone();
      const jitter = (rnd() - 0.5) * 2 * contrast;
      let mul = 1 + jitter;
      if (rnd() < specks) mul *= speckDark + rnd() * 0.3; // dark fleck
      c.multiplyScalar(mul);
      ctx.fillStyle = `#${c.getHexString()}`;
      ctx.fillRect(x, y, 1, 1);
    }
  }
  const tex = pixelate(new THREE.CanvasTexture(cv));
  _texCache.set(cacheKey, tex);
  return tex;
}

/**
 * Flat-shaded, pixel-textured voxel material. Drop-in replacement for the
 * MeshStandardMaterials the game used everywhere.
 */
export function voxMat(color, {
  rough = 0.95, metal = 0, emissive = null, emissiveIntensity = 1,
  texture = false, size = 8, contrast = 0.14, specks = 0.10, flatShading = true,
  transparent = false, opacity = 1,
} = {}) {
  const mat = new THREE.MeshStandardMaterial({
    color: toColor(color),
    roughness: rough,
    metalness: metal,
    flatShading,
    transparent,
    opacity,
  });
  if (texture) mat.map = noiseTexture(color, { size, contrast, specks });
  if (emissive !== null) {
    mat.emissive = toColor(emissive);
    mat.emissiveIntensity = emissiveIntensity;
  }
  mat.userData.__vox = true;
  _styledMats.add(mat);
  return mat;
}

/** Convenience box-mesh builder for voxel models. */
export function box(w, h, d, mat, x = 0, y = 0, z = 0, parent = null) {
  const m = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), mat);
  m.position.set(x, y, z);
  m.castShadow = true;
  m.receiveShadow = true;
  if (parent) parent.add(m);
  return m;
}

/**
 * blockify(root): reskin a finished mesh tree in-place to the voxel look.
 * Idempotent and cheap (each material/texture handled once via WeakSets), so
 * it's safe to call on every object added to the scene.
 *
 * It flat-shades lit materials, pixelates their textures, AND swaps any rounded
 * geometry for a cuboid (deCurve) so the whole world is genuinely blocky — no
 * circles anywhere, Minecraft-style. Opt out per material with
 * material.userData.noVox = true, or per mesh with mesh.userData.noVox = true.
 */
export function blockify(root) {
  if (!root || !root.traverse) return root;
  root.traverse((obj) => {
    if (!obj.isMesh && !obj.isPoints) return;
    if (obj.isMesh) deCurve(obj);   // circles are illegal — boxify any round geo
    const mats = Array.isArray(obj.material) ? obj.material : [obj.material];
    for (const mat of mats) {
      if (!mat || _styledMats.has(mat) || mat.userData?.noVox) continue;
      // Only lit materials have flatShading; basic/shader materials are left alone.
      if ('flatShading' in mat && (mat.isMeshStandardMaterial || mat.isMeshPhysicalMaterial
          || mat.isMeshPhongMaterial || mat.isMeshLambertMaterial)) {
        mat.flatShading = true;
        mat.needsUpdate = true;
      }
      if (mat.map) pixelate(mat.map);
      if (mat.emissiveMap) pixelate(mat.emissiveMap);
      _styledMats.add(mat);
    }
  });
  return root;
}

// Shared blocky palettes (saturated, Minecraft-ish, Hytale-leaning)
export const PALETTE = {
  grass:  0x5fa83a,
  grassDark: 0x4a8c2e,
  dirt:   0x8a5a33,
  stone:  0x8a8a90,
  sand:   0xd9c88c,
  snow:   0xeef2f6,
  bark:   0x6b4a2a,
  barkDark: 0x4a3119,
  leaf:   0x3f8f2e,
  leafDark: 0x2f6f22,
  pine:   0x2f6b30,
  water:  0x3a78b0,
  cactus: 0x4f9a3a,
};
