// VoxelItems.js — blocky, Minecraft-style world-item models built from cubes.
//
// The old item models were made of curved primitives (Cylinder/Sphere/Cone/
// Torus/Capsule) which the global de-curve funnel then flattens into a single
// crude bounding box — ugly. These models are built entirely from BoxGeometry
// so they pass through untouched and read as deliberate voxel props. Round
// shapes are faked with octagonal rings of thin boxes ("pixel-curved"), which
// is the Minecraft-mod look the player asked for.
//
// buildVoxelItem(type, matFn) -> THREE.Group | null
//   matFn(color, roughness, metalness) -> THREE.Material  (glow-aware; supplied
//   by WorldItemSystem so emissive/rarity glow still works).
// Returns null for types this library does not cover, so the caller can fall
// back to its legacy builder.

import * as THREE from 'three';

// ─── Geometry cache (share BoxGeometry across every spawned item) ────────────
const _geoCache = new Map();
function boxGeo(w, h, d) {
  const k = `${w.toFixed(4)},${h.toFixed(4)},${d.toFixed(4)}`;
  let g = _geoCache.get(k);
  if (!g) { g = new THREE.BoxGeometry(w, h, d); _geoCache.set(k, g); }
  return g;
}

// ─── Core builder ────────────────────────────────────────────────────────────
// cubes: array of { s:[w,h,d], p:[x,y,z], c:color, r?, m?, rot?:[x,y,z] }
function build(cubes, matFn) {
  const g = new THREE.Group();
  for (const cb of cubes) {
    const [w, h, d] = cb.s;
    const mesh = new THREE.Mesh(boxGeo(w, h, d), matFn(cb.c, cb.r ?? 0.6, cb.m ?? 0.1));
    const [x, y, z] = cb.p || [0, 0, 0];
    mesh.position.set(x, y, z);
    if (cb.rot) mesh.rotation.set(cb.rot[0], cb.rot[1], cb.rot[2]);
    mesh.castShadow = false;
    mesh.userData.noVox = true; // already a box — keep de-curve away from it
    g.add(mesh);
  }
  return g;
}

// Octagonal ring of thin boxes → a "pixel-curved" cylinder wall.
// Returns cube specs (merge into a model's cube list).
function ring(radius, height, y, color, r = 0.5, m = 0.2, seg = 8, thick = null) {
  const out = [];
  const t = thick ?? radius * 0.46;          // face plank thickness
  const faceW = 2 * radius * Math.tan(Math.PI / seg) * 1.02;
  for (let i = 0; i < seg; i++) {
    const a = (i / seg) * Math.PI * 2;
    out.push({
      s: [faceW, height, t],
      p: [Math.cos(a) * radius, y, Math.sin(a) * radius],
      c: color, r, m, rot: [0, -a, 0],
    });
  }
  return out;
}

// Solid blocky disc (cap) — a small plus/square cluster, cheap.
function disc(radius, thick, y, color, r = 0.5, m = 0.2) {
  const s = radius * 1.15;
  return [
    { s: [s, thick, s * 0.62], p: [0, y, 0], c: color, r, m },
    { s: [s * 0.62, thick, s], p: [0, y, 0], c: color, r, m },
  ];
}

// ─── Per-item cube recipes ───────────────────────────────────────────────────
// Each returns an array of cube specs. `c` = the item's themed base color.

const MODELS = {
  // Fruit (apple / orange): chunky rounded cube cluster + stem + leaf
  fruit(c) {
    const body = [];
    const u = 0.052;
    // 3x3x3 cluster with corners trimmed → reads round but blocky
    for (let xi = -1; xi <= 1; xi++)
      for (let yi = -1; yi <= 1; yi++)
        for (let zi = -1; zi <= 1; zi++) {
          if (Math.abs(xi) + Math.abs(yi) + Math.abs(zi) === 3) continue; // cut corners
          body.push({ s: [u, u, u], p: [xi * u, yi * u, zi * u], c, r: 0.55, m: 0 });
        }
    body.push({ s: [0.016, 0.06, 0.016], p: [0, u * 1.5 + 0.02, 0], c: 0x5a3a1a, r: 0.9 });
    body.push({ s: [0.06, 0.012, 0.04], p: [0.045, u * 1.5 + 0.03, 0], c: 0x3a7a22, r: 0.85 });
    return body;
  },

  // Banana: stepped yellow arc
  banana() {
    const C = 0xf2c200, T = 0x6b5600;
    return [
      { s: [0.05, 0.05, 0.05], p: [-0.11, 0.02, 0], c: T, r: 0.8 },
      { s: [0.06, 0.055, 0.06], p: [-0.07, 0.07, 0], c: C, r: 0.7 },
      { s: [0.065, 0.06, 0.065], p: [0, 0.09, 0], c: C, r: 0.7 },
      { s: [0.06, 0.055, 0.06], p: [0.07, 0.07, 0], c: C, r: 0.7 },
      { s: [0.05, 0.05, 0.05], p: [0.11, 0.02, 0], c: T, r: 0.8 },
    ];
  },

  // Bread loaf: stepped dome with crust scoring
  bread(c) {
    const crust = c, cut = 0x8a5a24;
    return [
      { s: [0.3, 0.08, 0.14], p: [0, 0, 0], c: crust, r: 0.9 },
      { s: [0.26, 0.07, 0.12], p: [0, 0.07, 0], c: crust, r: 0.9 },
      { s: [0.18, 0.06, 0.1], p: [0, 0.13, 0], c: crust, r: 0.9 },
      { s: [0.33, 0.02, 0.02], p: [-0.06, 0.1, 0.05], c: cut, r: 0.95 },
      { s: [0.33, 0.02, 0.02], p: [0.06, 0.1, -0.03], c: cut, r: 0.95 },
    ];
  },

  // Mushroom (fungal/horror): octagon stem + stepped cap + spore specks
  mushroom(c) {
    return [
      ...ring(0.045, 0.16, 0.02, 0xe7d8c4, 0.85, 0),
      ...ring(0.14, 0.05, 0.12, c, 0.65, 0),
      ...ring(0.1, 0.045, 0.16, c, 0.65, 0),
      { s: [0.05, 0.04, 0.05], p: [0, 0.19, 0], c, r: 0.6 },
      { s: [0.03, 0.03, 0.03], p: [0.07, 0.14, 0.03], c: 0xf4e9c0, r: 0.9 },
      { s: [0.025, 0.025, 0.025], p: [-0.06, 0.13, -0.04], c: 0xf4e9c0, r: 0.9 },
    ];
  },

  // Canned food: octagon can + metal lid + pull ring
  can(c) {
    return [
      ...ring(0.085, 0.14, 0, c, 0.45, 0.4),
      ...disc(0.085, 0.01, 0.076, 0xcfcfcf, 0.3, 0.6),
      { s: [0.05, 0.008, 0.012], p: [0, 0.086, 0.02], c: 0xaaaaaa, r: 0.3, m: 0.6 },
    ];
  },

  // Plastic bottle / drink: octagon body + tapered neck + cap
  bottle(c) {
    return [
      ...ring(0.058, 0.2, 0, c, 0.25, 0.05),
      ...ring(0.04, 0.05, 0.12, c, 0.25, 0.05),
      ...ring(0.03, 0.05, 0.17, c, 0.25, 0.05),
      ...disc(0.035, 0.03, 0.2, 0x202020, 0.5, 0.2),
    ];
  },

  // Wine / spirits bottle: dark glass, long neck, cork
  wine(c) {
    return [
      ...ring(0.052, 0.26, 0, c, 0.15, 0.35),
      ...ring(0.052, 0.04, 0.15, c, 0.15, 0.35),
      ...ring(0.024, 0.14, 0.24, c, 0.15, 0.35),
      ...disc(0.03, 0.045, 0.335, 0x3a2a12, 0.85, 0),
      { s: [0.07, 0.07, 0.014], p: [0, 0.02, 0.05], c: 0xd8c89a, r: 0.9 }, // label
    ];
  },

  // Canteen: flattened octagon flask + cap + strap
  canteen(c) {
    const body = ring(0.07, 0.19, 0, c, 0.55, 0.3).map((b) => ({ ...b, s: [b.s[0], b.s[1], b.s[2] * 0.6] }));
    return [
      ...body,
      ...disc(0.035, 0.035, 0.11, 0x4a4a4a, 0.4, 0.5),
      { s: [0.03, 0.08, 0.016], p: [0.07, 0.04, 0], c: 0x5a3118, r: 0.85 },
    ];
  },

  // Candle: octagon stick + wick + ember
  candle() {
    return [
      ...ring(0.026, 0.18, 0, 0xf1e4bf, 0.8, 0, 6),
      { s: [0.006, 0.03, 0.006], p: [0, 0.1, 0], c: 0x1a1a1a, r: 0.9 },
      { s: [0.02, 0.035, 0.02], p: [0, 0.13, 0], c: 0xffa828, r: 0.3, m: 0 },
    ];
  },

  // Syringe: octagon barrel + colored fluid + plunger + needle
  syringe(c) {
    return [
      ...ring(0.026, 0.26, 0, 0xdfeefb, 0.2, 0.1, 6),
      ...ring(0.021, 0.17, -0.02, c, 0.3, 0, 6),
      { s: [0.05, 0.02, 0.05], p: [0, -0.16, 0], c: 0xbcbcbc, r: 0.4, m: 0.4 },
      { s: [0.012, 0.14, 0.012], p: [0, -0.23, 0], c: 0xbcbcbc, r: 0.4, m: 0.4 },
      { s: [0.006, 0.08, 0.006], p: [0, 0.18, 0], c: 0xcccccc, r: 0.15, m: 0.9 },
    ];
  },

  // Pill bottle: octagon amber body + white cap + label band
  pills() {
    return [
      ...ring(0.05, 0.14, 0, 0xcf7a6a, 0.55, 0.1, 6),
      ...ring(0.055, 0.04, 0.088, 0xf2f2f2, 0.55, 0, 6),
      { s: [0.09, 0.07, 0.016], p: [0, 0, 0.045], c: 0xf5f5f5, r: 0.9 },
    ];
  },

  // Bandage roll: octagon roll on its side + trailing strip
  bandage() {
    const roll = ring(0.065, 0.1, 0, 0xf2e3cd, 0.9, 0).map((b) => ({
      ...b, rot: [Math.PI / 2, b.rot[1], 0],
      p: [b.p[0], b.p[2], b.p[1]],
    }));
    return [...roll, { s: [0.11, 0.055, 0.008], p: [0.09, 0, 0], c: 0xfff4ea, r: 0.9 }];
  },

  // First-aid kit: white box + red cross + latch
  medkit() {
    return [
      { s: [0.3, 0.16, 0.22], p: [0, 0, 0], c: 0xf2f2f2, r: 0.8 },
      { s: [0.18, 0.04, 0.03], p: [0, 0.02, 0.12], c: 0xd41f1f, r: 0.8 },
      { s: [0.04, 0.12, 0.03], p: [0, 0.02, 0.12], c: 0xd41f1f, r: 0.8 },
      { s: [0.06, 0.03, 0.02], p: [0, -0.02, 0.115], c: 0xbbbbbb, r: 0.3, m: 0.6 },
    ];
  },

  // Blood bag: translucent-red pouch + nozzle + tube
  bloodbag() {
    return [
      { s: [0.15, 0.22, 0.045], p: [0, 0, 0], c: 0xb00010, r: 0.5, m: 0.1 },
      { s: [0.1, 0.03, 0.05], p: [0, 0.1, 0], c: 0x800009, r: 0.5 },
      { s: [0.1, 0.03, 0.05], p: [0, -0.1, 0], c: 0x800009, r: 0.5 },
      { s: [0.016, 0.12, 0.016], p: [0, -0.18, 0], c: 0xc33, r: 0.6 },
      { s: [0.09, 0.06, 0.01], p: [0, 0.02, 0.028], c: 0xe8e0d0, r: 0.9 }, // label
    ];
  },

  // Adrenaline auto-injector: octagon pen + orange tip + grip band
  adrenaline() {
    return [
      ...ring(0.028, 0.24, 0, 0xf07000, 0.35, 0.2, 6),
      { s: [0.05, 0.05, 0.05], p: [0, -0.14, 0], c: 0xffaa44, r: 0.4 },
      ...ring(0.031, 0.02, 0.06, 0x2a2a2a, 0.4, 0.3, 6),
    ];
  },

  // Molotov: green glass bottle + rag wick + flame
  molotov() {
    return [
      ...ring(0.05, 0.2, 0, 0x6f8c38, 0.3, 0.15),
      ...ring(0.026, 0.07, 0.13, 0x6f8c38, 0.3, 0.15),
      { s: [0.03, 0.1, 0.03], p: [0, 0.2, 0], c: 0xb5703a, r: 0.9 },
      { s: [0.04, 0.05, 0.04], p: [0, 0.27, 0], c: 0xff6a00, r: 0.4, m: 0 },
    ];
  },

  // Rope coil: octagon torus-ish ring laid flat, doubled
  rope() {
    const flat = (radius, y, col) => ring(radius, 0.04, y, col, 0.9, 0).map((b) => ({
      ...b, s: [b.s[0], 0.045, 0.05],
    }));
    return [...flat(0.1, 0, 0xc39a52), ...flat(0.072, 0.03, 0xb08840)];
  },

  // Ore chunk: jagged grey cube cluster with bright vein pips
  ore(c) {
    return [
      { s: [0.14, 0.12, 0.13], p: [0, 0, 0], c: 0x6b6b6b, r: 0.75, m: 0.1 },
      { s: [0.08, 0.07, 0.08], p: [0.09, 0.05, 0.03], c: 0x6b6b6b, r: 0.75, m: 0.1 },
      { s: [0.07, 0.06, 0.07], p: [-0.07, -0.04, -0.05], c: 0x5a5a5a, r: 0.75, m: 0.1 },
      { s: [0.035, 0.035, 0.035], p: [0.03, 0.06, 0.07], c, r: 0.2, m: 0.8 },
      { s: [0.03, 0.03, 0.03], p: [-0.05, 0.03, 0.06], c, r: 0.2, m: 0.8 },
      { s: [0.028, 0.028, 0.028], p: [0.08, -0.03, -0.04], c, r: 0.2, m: 0.8 },
    ];
  },

  // ── Weapons (crisp blocky viewmodels) ──────────────────────────────────────
  gun(c) {
    return [
      { s: [0.46, 0.08, 0.08], p: [0.04, 0.04, 0], c, r: 0.3, m: 0.75 },
      { s: [0.28, 0.05, 0.075], p: [0.06, 0.09, 0], c: 0x2c2c38, r: 0.2, m: 0.9 },
      { s: [0.08, 0.2, 0.07], p: [-0.12, -0.07, 0], c: 0x24242c, r: 0.4, m: 0.3, rot: [0, 0, -0.28] },
      { s: [0.12, 0.03, 0.05], p: [-0.02, -0.04, 0], c: 0x24242c, r: 0.4, m: 0.3 },
      { s: [0.1, 0.06, 0.055], p: [-0.26, 0.05, 0], c: 0x2c2c38, r: 0.3, m: 0.8 }, // stock
    ];
  },

  blade(c) {
    return [
      { s: [0.05, 0.46, 0.02], p: [0, 0.12, 0], c: 0xd4dce4, r: 0.15, m: 0.9 },
      { s: [0.016, 0.46, 0.024], p: [0.028, 0.12, 0], c: 0xffffff, r: 0.1, m: 1 },
      { s: [0.2, 0.035, 0.035], p: [0, -0.12, 0], c: 0xa8842e, r: 0.4, m: 0.55 },
      { s: [0.05, 0.18, 0.05], p: [0, -0.22, 0], c: 0x5a3418, r: 0.85 },
      { s: [0.07, 0.05, 0.07], p: [0, -0.33, 0], c: 0xa8842e, r: 0.4, m: 0.55 },
    ];
  },

  spear(c) {
    return [
      ...ring(0.02, 0.7, 0, 0x7a5330, 0.9, 0, 4),
      { s: [0.06, 0.16, 0.02], p: [0, 0.44, 0], c: 0xd4dce4, r: 0.15, m: 0.9 },
      { s: [0.02, 0.1, 0.045], p: [0, 0.4, 0], c: 0xd4dce4, r: 0.15, m: 0.9 },
    ];
  },

  axe(c) {
    return [
      ...ring(0.024, 0.5, 0, 0x6f4a26, 0.9, 0, 4),
      { s: [0.16, 0.2, 0.04], p: [0.1, 0.18, 0], c, r: 0.3, m: 0.7 },
      { s: [0.05, 0.2, 0.05], p: [0.19, 0.18, 0], c: 0xc7cdd4, r: 0.2, m: 0.85 },
    ];
  },

  bow(c) {
    const out = [];
    const pts = [[-0.19, 0], [-0.12, 0.12], [0, 0.17], [0.12, 0.12], [0.19, 0]];
    for (let i = 0; i < pts.length - 1; i++) {
      const [ax, ay] = pts[i], [bx, by] = pts[i + 1];
      const mx = (ax + bx) / 2, my = (ay + by) / 2;
      const len = Math.hypot(bx - ax, by - ay);
      const ang = Math.atan2(by - ay, bx - ax);
      out.push({ s: [len, 0.03, 0.03], p: [mx, my, 0], c: 0x7a5330, r: 0.9, rot: [0, 0, ang] });
    }
    out.push({ s: [0.006, 0.34, 0.006], p: [0, 0.04, 0], c: 0xe3d49a, r: 0.9 });
    return out;
  },
};

// ─── Router: type -> model name ──────────────────────────────────────────────
function pick(type, category) {
  if (/apple|orange|tomato|peach/.test(type)) return 'fruit';
  if (/banana/.test(type)) return 'banana';
  if (/bread|loaf|baguette/.test(type)) return 'bread';
  if (/mushroom|fungus|spore_cap/.test(type)) return 'mushroom';
  if (/wine|whiskey|rum|vodka|liquor/.test(type)) return 'wine';
  if (/canteen/.test(type)) return 'canteen';
  if (/candle/.test(type)) return 'candle';
  if (/molotov/.test(type)) return 'molotov';
  if (/blood_bag/.test(type)) return 'bloodbag';
  if (/adrenaline/.test(type)) return 'adrenaline';
  if (/morphine|antibiotics|syringe|inject/.test(type)) return 'syringe';
  if (/bandage|gauze/.test(type)) return 'bandage';
  if (type === 'medical_kit' || /first_aid|medkit/.test(type)) return 'medkit';
  if (/rope/.test(type)) return 'rope';
  if (/ore_/.test(type)) return 'ore';
  if (/drink_|water_bottle|water|milk|juice|soda|beer|energy|coffee|tea|cocoa/.test(type)) return 'bottle';
  if (/sword|knife|dagger|machete/.test(type)) return 'blade';
  if (/spear|lance/.test(type)) return 'spear';
  if (/axe|hatchet/.test(type)) return 'axe';
  if (/\bbow\b|crossbow/.test(type)) return 'bow';
  if (/pistol|rifle|shotgun|smg|found_gun/.test(type)) return 'gun';
  // category fallbacks
  if (category === 'medical' && !/kit/.test(type)) return 'pills';
  if (category === 'food' && !/chips|crisps|popcorn/.test(type)) return 'can';
  return null;
}

export function buildVoxelItem(type, matFn, category) {
  const name = pick(type, category);
  if (!name || !MODELS[name]) return null;
  // base themed color passed through matFn's first arg via caller; we fetch via
  // a sentinel: caller supplies matFn already bound to the item color for `c`.
  const c = matFn.__baseColor ?? 0x999999;
  const cubes = MODELS[name](c);
  return build(cubes, matFn);
}

export const VOXEL_ITEM_NAMES = Object.keys(MODELS);
