// McInventoryScreen.js — Minecraft-style survival inventory (E) and block GUIs.
//
// Original implementation of the vanilla layouts and click rules:
//   - gray beveled 176-wide panel in GUI pixels (--u);
//   - modes: 'survival' (armor column, player preview, offhand, 2x2 crafting),
//     'crafting_table' (3x3 crafting), 'furnace' (input / fuel / flame /
//     arrow / output) and 'chest' (27 slots), each above the player inventory
//     and the separate hotbar row;
//   - a cursor-held stack: left click picks up / places / merges / swaps,
//     right click takes half / places one, shift-click quick-moves between
//     the container and the inventory (or hotbar <-> main inventory);
//     hovering a slot: 1-9 swaps with that hotbar slot, F with the offhand,
//     Q throws one (Ctrl+Q the stack);
//   - crafting output = the shaped/shapeless Minecraft recipe the grid
//     matches; the recipe book fills the grid (legacy recipes are listed only
//     at a crafting table and craft straight from the book).
// Closing returns grid + cursor items to the inventory.

import { isMcItem, mcIconCSS, MC_ARMOR, mcMaxDurability } from '../content/McContent.js';
import { meleeStats } from '../weapons/Melee.js';
import { itemIconAttrs } from './ItemIcons.js';
import { installGuiSprites } from './GuiSprites.js';
import { PlayerPreview3D } from './PlayerPreview3D.js';
import { STONECUTTER } from './CraftingSystem.js';

const u = (n) => `calc(var(--u) * ${n})`;
const esc = (t) => String(t ?? '').replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const ARMOR_KEYS = ['head', 'chest', 'legs', 'feet'];

// Pixel SVG from per-row [x0, x1] spans
function spanSVG(w, h, spans, color) {
  let r = '';
  spans.forEach(([a, b], y) => { if (b >= a) r += `<rect x='${a}' y='${y}' width='${b - a + 1}' height='1' fill='${color}'/>`; });
  return `<svg viewBox='0 0 ${w} ${h}' shape-rendering='crispEdges' width='100%' height='100%'>${r}</svg>`;
}
const FLAME = [[6, 7], [5, 8], [5, 9], [4, 9], [3, 10], [3, 10], [2, 11], [2, 11], [1, 12], [1, 12], [1, 12], [2, 11], [3, 10], [4, 9]];
const FLAME_IN = FLAME.map(([a, b], y) => (y < 4 ? [1, 0] : [a + 2, b - 2]));
// 24x17 arrow: shaft rows 6..10, head columns 14..22 narrowing to the tip
const ARROW = Array.from({ length: 17 }, (_, y) => {
  const d = Math.abs(y - 8);
  return [y >= 6 && y <= 10 ? 0 : 14, 22 - d];
});

export class McInventoryScreen {
  constructor(inv) {
    this.inv = inv;
    this.mode = 'survival';
    this.key = null;                        // "x,y,z" of the open block GUI
    this.gridW = 2;
    this.grid = [null, null, null, null];   // crafting cells (2x2 or 3x3)
    this.cursor = null;                     // { type, quantity, name[, durability] }
    this.bookOpen = true;
    this._tab = 'all';                      // recipe-book category tab
    this._page = 0;
    this._search = '';
    this._next = null;
    this.scIn = null;                       // stonecutter input stack
    this.scSel = -1;                        // selected stonecutter recipe
    this.scScroll = 0;
    this._build();
  }

  get crafting() { return this.inv.game.craftingSystem; }
  get containers() { return this.inv.game.containerSystem; }
  get state() { return this.key && (this.mode === 'chest' || this.mode === 'furnace' || this.mode === 'brewing') ? this.containers?.get(this.key, this.mode) : null; }

  // ── Public: open a block GUI ─────────────────────────────────────────────
  // kind: 'crafting_table' | 'furnace' | 'chest'; key: block position "x,y,z".
  openContainer(kind, key) {
    if (kind === 'lit_furnace') kind = 'furnace';
    if (!['crafting_table', 'furnace', 'chest', 'keypad', 'stonecutter', 'brewing'].includes(kind)) return false;
    if (kind === 'keypad' && this.containers?.lockInfo?.(key)?.unlocked) kind = 'chest';
    if ((kind === 'chest' || kind === 'furnace' || kind === 'brewing') && !this.containers) { console.warn('ContainerSystem not wired'); return false; }
    if (this.inv.isOpen) this.inv.closeInventory();
    this._next = { kind, key: key ?? null };
    this.inv.openInventory();
    return true;
  }

  // ── DOM ────────────────────────────────────────────────────────────────
  _build() {
    const screen = this.inv.screen;
    this.panel = document.getElementById('inv-panel');
    if (!screen || !this.panel) return;
    installGuiSprites();
    screen.classList.add('mc-inv');

    // Recipe book panel (left of the inventory)
    this.book = document.createElement('div');
    this.book.id = 'mc-recipe-book';
    screen.insertBefore(this.book, this.panel.parentElement === screen ? this.panel : null);

    // Floating cursor stack + tooltip
    this.cursorEl = document.createElement('div');
    this.cursorEl.id = 'mc-cursor';
    document.body.appendChild(this.cursorEl);
    this.tip = document.createElement('div');
    this.tip.id = 'mc-tip';
    document.body.appendChild(this.tip);
    // vanilla: tooltip sits 12 GUI px right of / above the pointer and is
    // flipped back on-screen near the edges
    this._mx = 0; this._my = 0;
    screen.addEventListener('mousemove', (e) => {
      this._mx = e.clientX; this._my = e.clientY;
      this.cursorEl.style.transform = `translate(${e.clientX}px, ${e.clientY}px)`;
      this._placeTip();
    });
    screen.addEventListener('contextmenu', (e) => e.preventDefault());
    // Clicking outside the panels with a held stack throws it (vanilla)
    screen.addEventListener('mousedown', (e) => {
      if (e.target !== screen || !this.cursor) return;
      const n = e.button === 2 ? 1 : this.cursor.quantity;
      this._throw(this.cursor, n);
      this.cursor.quantity -= n; if (this.cursor.quantity <= 0) this.cursor = null;
      this._renderCursor();
    });
    // Hover hotkeys (vanilla): 1-9 swap with hotbar, F offhand, Q drop
    document.addEventListener('keydown', (e) => {
      if (!this.inv.isOpen || !this._hoverRef || this.cursor) return;
      const k = e.key.toLowerCase();
      if (k >= '1' && k <= '9') { e.preventDefault(); this._swapRefs(this._hoverRef, { kind: 'inv', i: +k - 1 }); }
      else if (k === 'f') { e.preventDefault(); this._swapRefs(this._hoverRef, { kind: 'offhand' }); }
      else if (k === 'q') {
        e.preventDefault();
        const s = this._get(this._hoverRef); if (!s) return;
        const n = e.ctrlKey ? s.quantity : 1;
        this._throw(s, n);
        this._set(this._hoverRef, s.quantity - n > 0 ? this._copy(s, s.quantity - n) : null);
      } else return;
      this._hover(this._hoverRef);
    });

    // Keypad screen: digits, Backspace, Enter (capture phase so the hotbar
    // number keys do not also fire)
    document.addEventListener('keydown', (e) => {
      if (!this.inv.isOpen || this.mode !== 'keypad') return;
      let k = null;
      if (/^[0-9]$/.test(e.key)) k = e.key;
      else if (e.key === 'Backspace') k = 'DEL';
      else if (e.key === 'Enter') k = 'OK';
      if (!k) return;
      e.preventDefault(); e.stopPropagation();
      this._kpPress(k);
    }, true);

    this._layout();
  }

  // ── Keypad locker ────────────────────────────────────────────────────────
  _layoutKeypad(panel, pos, mk, label) {
    const L = this.containers?.lockInfo?.(this.key);
    this._kp = { entry: '', msg: null, cls: '', until: 0 };
    const W = 124;
    label('Keypad Locker', 0, 6, true).style.width = u(W);
    label(L?.label ?? '', 0, 16, true).style.width = u(W);
    this._kpDisp = pos(mk('mc-kp-display'), 14, 27);
    const keys = ['1', '2', '3', '4', '5', '6', '7', '8', '9', 'CLR', '0', 'OK'];
    keys.forEach((k, i) => {
      const b = pos(mk('mc-kp-btn' + (k.length > 1 ? ' mc-kp-wide' : '')), 14 + (i % 3) * 33, 50 + ((i / 3) | 0) * 21);
      b.textContent = k;
      b.addEventListener('mousedown', (e) => { e.preventDefault(); e.stopPropagation(); this._kpPress(k); });
    });
    panel.style.width = u(W);
    panel.style.height = u(50 + 4 * 21 + 5);
    this._kpRender();
  }

  _kpPress(k) {
    const kp = this._kp; if (!kp || this.mode !== 'keypad') return;
    const g = this.inv.game, L = this.containers?.lockInfo?.(this.key);
    g.audioManager?.playClick?.();
    if (kp.msg && performance.now() < kp.until) return;          // showing a result
    kp.msg = null;
    if (L && L.lockUntil > performance.now()) { this._kpRender(); return; }
    if (/^[0-9]$/.test(k)) { if (kp.entry.length < 4) kp.entry += k; }
    else if (k === 'DEL') kp.entry = kp.entry.slice(0, -1);
    else if (k === 'CLR') kp.entry = '';
    else if (k === 'OK') {
      if (!kp.entry.length) return;
      const r = this.containers?.tryCode?.(this.key, kp.entry);
      kp.entry = '';
      if (r === 'ok') {
        kp.msg = 'GRANTED'; kp.cls = 'good'; kp.until = performance.now() + 700;
        g.audioManager?.playTone?.([880, 1320], 0.09);
        const key = this.key;
        setTimeout(() => { if (this.inv.isOpen && this.mode === 'keypad' && this.key === key) this._enter('chest', key); }, 650);
      } else {
        kp.msg = 'DENIED'; kp.cls = 'bad'; kp.until = performance.now() + 900;
        g.audioManager?.playTone?.([220, 165], 0.14);
      }
    }
    this._kpRender();
  }

  _kpRender() {
    const el = this._kpDisp, kp = this._kp; if (!el || !kp) return;
    const L = this.containers?.lockInfo?.(this.key), now = performance.now();
    let text, cls = '';
    if (kp.msg && now < kp.until) { text = kp.msg; cls = kp.cls; }
    else if (L && L.lockUntil > now) { text = `LOCKED ${Math.ceil((L.lockUntil - now) / 1000)}s`; cls = 'wait'; }
    else { kp.msg = null; text = (kp.entry + '____').slice(0, 4).split('').join(' '); }
    if (el.textContent !== text) el.textContent = text;
    el.className = 'mc-kp-display' + (cls ? ' ' + cls : '');
  }

  // Lay the panel out for the current mode (rebuilt on every open)
  _layout() {
    const panel = this.panel; if (!panel) return;
    panel.innerHTML = '';
    panel.dataset.mode = this.mode;
    const pos = (el, x, y) => { el.style.left = u(x); el.style.top = u(y); return el; };
    const mk = (cls, parent = panel) => { const d = document.createElement('div'); d.className = cls; parent.appendChild(d); return d; };
    const label = (text, x, y, center = false) => {
      const l = pos(mk('mc-label' + (center ? ' mc-label-c' : '')), x, y); l.textContent = text; return l;
    };
    const slot = (x, y, ref, cls = 'mc-slot') => { const s = pos(mk(cls), x, y); this._bindSlot(s, ref); return s; };

    this.gridEls = []; this.outEl = null; this.armorEls = {}; this.offEl = null; this.previewBox = null;
    this.chestEls = []; this.furnEls = {}; this.flameEl = null; this.progEl = null; this.scEls = null;
    let invTop = 83;
    if (this.mode === 'keypad') { this._layoutKeypad(panel, pos, mk, label); return; }

    if (this.mode === 'survival') {
      ARMOR_KEYS.forEach((k, i) => {
        const s = slot(7, 7 + i * 18, { kind: 'armor', k }, 'mc-slot mc-armor-slot');
        s.dataset.armor = k; this.armorEls[k] = s;
      });
      // live 3D player model (follows the mouse like vanilla)
      this.previewBox = pos(mk('mc-player-box'), 25, 7);
      this.offEl = slot(76, 61, { kind: 'offhand' }, 'mc-slot mc-armor-slot');
      this.offEl.dataset.armor = 'offhand';
      label('Crafting', 97, 8);
      this._setGrid(2);
      for (let i = 0; i < 4; i++) this.gridEls.push(slot(97 + (i % 2) * 18, 17 + ((i / 2) | 0) * 18, { kind: 'grid', i }));
      pos(mk('mc-arrow'), 135, 29);
      // the 2x2 result is a plain 18x18 slot in the player inventory
      this.outEl = pos(mk('mc-slot mc-out-slot mc-out-small'), 153, 27);
      this._bookBtn(pos(mk('mc-book-btn'), 104, 61));
    } else if (this.mode === 'crafting_table') {
      label('Crafting', 28, 6);
      this._setGrid(3);
      for (let i = 0; i < 9; i++) this.gridEls.push(slot(29 + (i % 3) * 18, 16 + ((i / 3) | 0) * 18, { kind: 'grid', i }));
      this._bigArrow(pos(mk('mc-big-arrow'), 89, 34), false);
      this.outEl = pos(mk('mc-slot mc-out-slot'), 119, 30);
      this._bookBtn(pos(mk('mc-book-btn'), 5, 34));
      label('Inventory', 8, 72);
    } else if (this.mode === 'furnace') {
      label('Furnace', 0, 6, true);
      this.furnEls.input = slot(55, 16, { kind: 'furnace', f: 'input' });
      this.furnEls.fuel = slot(55, 52, { kind: 'furnace', f: 'fuel' });
      this.furnEls.output = slot(111, 30, { kind: 'furnace', f: 'output' }, 'mc-slot mc-out-slot');
      const fl = pos(mk('mc-flame'), 56, 36);
      fl.innerHTML = `<div class="mc-gauge-bg">${spanSVG(14, 14, FLAME, '#8b8b8b')}</div><div class="mc-gauge-fg">${spanSVG(14, 14, FLAME, '#ff8a1a').replace('</svg>', spanSVG(14, 14, FLAME_IN, '#ffe04a').replace(/^<svg[^>]*>/, ''))}</div>`;
      this.flameEl = fl.querySelector('.mc-gauge-fg');
      this.progEl = this._bigArrow(pos(mk('mc-big-arrow'), 79, 34), true);
      label('Inventory', 8, 72);
    } else if (this.mode === 'brewing') {
      // vanilla layout: ingredient top centre, three bottles below on a
      // forked tube, blaze powder top left with the fuel bar under it
      label('Brewing Stand', 0, 6, true);
      this.furnEls.fuel = slot(17, 16, { kind: 'furnace', f: 'fuel' });
      this.furnEls.ing = slot(79, 16, { kind: 'furnace', f: 'ing' });
      this.furnEls.b0 = slot(56, 50, { kind: 'furnace', f: 'b0' }, 'mc-slot mc-bottle-slot');
      this.furnEls.b1 = slot(79, 57, { kind: 'furnace', f: 'b1' }, 'mc-slot mc-bottle-slot');
      this.furnEls.b2 = slot(102, 50, { kind: 'furnace', f: 'b2' }, 'mc-slot mc-bottle-slot');
      pos(mk('mc-brew-tubes'), 62, 33);
      const fuel = pos(mk('mc-brew-fuel'), 60, 44);
      this.brewFuelEl = mk('mc-brew-fuel-fg', fuel);
      const arrow = pos(mk('mc-brew-arrow'), 97, 16);
      this.progEl = mk('mc-brew-arrow-fg', arrow);
      const bub = pos(mk('mc-brew-bubbles'), 63, 14);
      this.bubEl = mk('mc-brew-bubbles-fg', bub);
      label('Inventory', 8, 72);
    } else if (this.mode === 'stonecutter') {
      // vanilla layout: input left, 4-wide recipe button list, output right
      label('Stonecutter', 8, 4);
      const input = slot(19, 32, { kind: 'sc', f: 'input' });
      const list = pos(mk('mc-sc-list'), 52, 14);
      const bar = pos(mk('mc-sc-scroll'), 119, 15);
      const out = pos(mk('mc-slot mc-out-slot'), 139, 28);
      out.addEventListener('mousedown', (e) => { e.preventDefault(); e.stopPropagation(); this._scTake(e.shiftKey); });
      out.addEventListener('contextmenu', (e) => e.preventDefault());
      list.addEventListener('wheel', (e) => {
        e.preventDefault();
        const rows = Math.ceil(this._scRecipes().length / 4);
        this.scScroll = Math.max(0, Math.min(rows - 3, this.scScroll + Math.sign(e.deltaY)));
        this._renderSC();
      }, { passive: false });
      this.scEls = { input, list, bar, out };
      label('Inventory', 8, 72);
    } else if (this.mode === 'chest') {
      label(this.containers?.locks?.has(this.key) ? 'Keypad Locker' : 'Chest', 8, 6);
      for (let i = 0; i < 27; i++) this.chestEls.push(slot(7 + (i % 9) * 18, 17 + ((i / 9) | 0) * 18, { kind: 'chest', i }));
      label('Inventory', 8, 74);
      invTop = 84;
    }
    if (this.outEl) {
      this.outEl.addEventListener('mousedown', (e) => { e.preventDefault(); e.stopPropagation(); this._takeOutput(e.shiftKey); });
      this.outEl.addEventListener('contextmenu', (e) => e.preventDefault());
    }

    // Main inventory (slots 9..) and hotbar (0..8); slot elements are owned
    // by InventorySystem and re-parented here.
    const els = this.inv._slotEls || [];
    const mainRows = Math.ceil((this.inv.totalSlots - 9) / 9);
    for (let i = 9; i < this.inv.totalSlots; i++) {
      const el = els[i]; if (!el) continue;
      panel.appendChild(el); pos(el, 7 + ((i - 9) % 9) * 18, invTop + (((i - 9) / 9) | 0) * 18);
    }
    const hotY = invTop + mainRows * 18 + 4;
    for (let i = 0; i < 9; i++) {
      const el = els[i]; if (!el) continue;
      panel.appendChild(el); pos(el, 7 + i * 18, hotY);
    }
    els.forEach((el, i) => { if (!el._mcBound) { el._mcBound = true; this._bindSlot(el, { kind: 'inv', i }); } });
    panel.style.width = u(176);
    panel.style.height = u(hotY + 18 + (this.mode === 'chest' ? 8 : 7));
    if (this.book) this.book.style.height = panel.style.height;
  }

  _setGrid(w) {
    if (this.gridW === w && this.grid.length === w * w) return;
    this.gridW = w;
    this.grid = Array(w * w).fill(null);
  }

  _bookBtn(btn) {
    btn.innerHTML = '<i class="mc-book-ico"></i>';
    btn.addEventListener('mousedown', (e) => { e.preventDefault(); e.stopPropagation(); this.bookOpen = !this.bookOpen; this._renderBook(); this._snapToPixels(); });
  }

  _bigArrow(el, withFill) {
    el.innerHTML = `<div class="mc-gauge-bg">${spanSVG(24, 17, ARROW, '#8b8b8b')}</div>` + (withFill ? `<div class="mc-gauge-fg">${spanSVG(24, 17, ARROW, '#ffffff')}</div>` : '');
    return el.querySelector('.mc-gauge-fg');
  }

  _iconHTML(stack, cls = 'inv-qty') {
    if (!stack) return '';
    const cat = this.inv.constructor.getIconCat(stack.type);
    const tex = itemIconAttrs(stack.type);
    return `<div class="item-icon" data-cat="${cat}"${tex}></div>` + this.inv.constructor.durBarHTML(stack)
      + (stack.quantity > 1 ? `<div class="${cls}">${stack.quantity}</div>` : '');
  }

  _name(type) { return this.inv.itemTypes[type]?.name ?? type; }

  // ── Slot access ──────────────────────────────────────────────────────────
  // ref kinds: inv{i} grid{i} armor{k} offhand chest{i} furnace{f}
  _get(ref) {
    switch (ref.kind) {
      case 'grid': return this.grid[ref.i] ?? null;
      case 'armor': return this.inv.armor[ref.k] ?? null;
      case 'offhand': return this.inv.offhand ?? null;
      case 'chest': return this.state?.slots[ref.i] ?? null;
      case 'furnace': return this.state?.[ref.f] ?? null;
      case 'sc': return ref.f === 'input' ? this.scIn : null;
      default: return this.inv.slots[ref.i] ?? null;
    }
  }

  _set(ref, stack) {
    if (stack && stack.quantity <= 0) stack = null;
    switch (ref.kind) {
      case 'grid': this.grid[ref.i] = stack; this._renderGrid(); return;
      case 'armor': this.inv.armor[ref.k] = stack; this._renderEquip(); return;
      case 'offhand': this.inv.offhand = stack; this._renderEquip(); return;
      case 'chest': { const st = this.state; if (st) st.slots[ref.i] = stack; this._renderChest(); return; }
      case 'furnace': { const st = this.state; if (st) st[ref.f] = stack; this._renderFurnace(); return; }
      case 'sc': {
        if (ref.f !== 'input') return;
        if (stack?.type !== this.scIn?.type) { this.scSel = -1; this.scScroll = 0; }
        this.scIn = stack; this._renderSC(); return;
      }
      default:
        this.inv.slots[ref.i] = stack; this.inv._syncSlot(ref.i); this.inv.updateQuickSlotDisplay(); this.inv._updateWeight?.();
    }
  }

  // Can `stack` be placed into ref?
  _accepts(ref, stack) {
    if (!stack) return true;
    if (ref.kind === 'armor') return MC_ARMOR[stack.type]?.slot === ref.k;
    if (ref.kind === 'furnace' && this.mode === 'brewing') {
      const cs = this.containers;
      if (ref.f === 'fuel') return stack.type === 'mc_blaze_powder';
      if (ref.f === 'ing') return !!cs?.isBrewIngredient(stack.type);
      return !!cs?.isBottle(stack.type);
    }
    if (ref.kind === 'furnace') {
      if (ref.f === 'output') return false;
      if (ref.f === 'fuel') return !!this.containers?.isFuel(stack.type);
    }
    return true;
  }
  _cap(ref) { return ref.kind === 'armor' || (ref.kind === 'furnace' && /^b\d$/.test(ref.f ?? '')) ? 1 : Infinity; }

  _stackable(type) { return !!this.inv.itemTypes[type]?.stackable; }
  _copy(s, q = s.quantity) { return { ...s, quantity: q, name: s.name ?? this._name(s.type) }; }

  _bindSlot(el, ref) {
    el.addEventListener('mousedown', (e) => { e.preventDefault(); e.stopPropagation(); this._click(ref, e.button, e.shiftKey); this._hover(ref); });
    el.addEventListener('contextmenu', (e) => e.preventDefault());
    el.addEventListener('mouseenter', () => { this._hoverRef = ref; this._hover(ref); });
    el.addEventListener('mouseleave', () => { this._hoverRef = null; this.tip.style.display = 'none'; });
  }

  _hover(ref) {
    const s = this._get(ref);
    if (!s || this.cursor) { this._hideTip(); return; }
    const def = this.inv.itemTypes[s.type];
    const max = mcMaxDurability(s.type);
    const dur = max && s.durability !== undefined && s.durability < max ? `<div class="mc-tip-sub">Durability: ${s.durability} / ${max}</div>` : '';
    const body = s.note ? s.note.lines.map((l) => `<div class="mc-tip-sub mc-tip-note">${esc(l)}</div>`).join('')
      : meleeStats(s.type) ? this._attackTip(meleeStats(s.type))
      : (def?.effect ? `<div class="mc-tip-sub">${esc(def.effect)}</div>` : '');
    this._tipHTML(`<div class="mc-tip-name r-${def?.rarity ?? 'common'}">${esc(s.note?.title ?? this._name(s.type))}</div>` + body + dur);
  }

  // ── Tooltip ──────────────────────────────────────────────────────────────
  // Vanilla attribute block: "When in Main Hand:" + damage and speed in green
  _attackTip(st) {
    const n = (v) => (Math.round(v * 10) / 10).toString();
    return `<div class="mc-tip-sub mc-tip-attr-h">When in Main Hand:</div>`
      + `<div class="mc-tip-sub mc-tip-attr"> ${n(st.damage)} Attack Damage</div>`
      + `<div class="mc-tip-sub mc-tip-attr"> ${n(st.speed)} Attack Speed</div>`;
  }

  _tipHTML(html) {
    this.tip.innerHTML = html;
    this.tip.style.display = 'block';
    this._placeTip();
  }
  _hideTip() { if (this.tip) this.tip.style.display = 'none'; }
  _placeTip() {
    const t = this.tip; if (!t || t.style.display === 'none') return;
    const us = parseFloat(getComputedStyle(document.documentElement).getPropertyValue('--us')) || 2;
    let x = this._mx + 12 * us, y = this._my - 12 * us;
    const w = t.offsetWidth, h = t.offsetHeight;
    if (x + w > innerWidth - 4 * us) x = this._mx - 16 * us - w;   // flip left like vanilla
    if (y + h > innerHeight - 4 * us) y = innerHeight - 4 * us - h;
    if (y < 4 * us) y = 4 * us;
    // snap to the GUI pixel grid so the 1px border stays crisp
    t.style.transform = `translate(${Math.round(x / us) * us}px, ${Math.round(y / us) * us}px)`;
  }

  _click(ref, button, shift) {
    const slot = this._get(ref);
    if (shift && button === 0) { this._quickMove(ref); this._renderCursor(); return; }
    const c = this.cursor;
    const same = c && slot && slot.type === c.type && this._stackable(slot.type);

    const takeOnly = ref.kind === 'furnace' && ref.f === 'output';
    if (takeOnly || !this._accepts(ref, c)) {
      // Take-only slots (furnace output) or wrong item for the slot
      if (!slot) return;
      if (!c) {
        const take = button === 2 ? Math.ceil(slot.quantity / 2) : slot.quantity;
        this.cursor = this._copy(slot, take);
        this._set(ref, slot.quantity - take > 0 ? this._copy(slot, slot.quantity - take) : null);
        this._onTakeResult(ref, take);
      } else if (same && takeOnly) {
        c.quantity += slot.quantity; this._onTakeResult(ref, slot.quantity); this._set(ref, null);
      }
      this._renderCursor();
      return;
    }

    if (button === 2) {
      if (!c && slot) {                     // take half
        const take = Math.ceil(slot.quantity / 2);
        this.cursor = this._copy(slot, take);
        this._set(ref, slot.quantity - take > 0 ? this._copy(slot, slot.quantity - take) : null);
      } else if (c && (!slot || same)) {    // place one
        if ((slot?.quantity ?? 0) < this._cap(ref)) {
          this._set(ref, this._copy(c, (slot?.quantity ?? 0) + 1));
          c.quantity -= 1; if (c.quantity <= 0) this.cursor = null;
        }
      } else if (c && slot) {
        this.cursor = slot; this._set(ref, c);
      }
    } else {
      if (!c && slot) { this.cursor = slot; this._set(ref, null); }
      else if (c && !slot) {
        const cap = this._cap(ref);
        if (c.quantity <= cap) { this._set(ref, c); this.cursor = null; }
        else { this._set(ref, this._copy(c, cap)); c.quantity -= cap; }
      } else if (c && slot) {
        if (same) { this._set(ref, this._copy(slot, slot.quantity + c.quantity)); this.cursor = null; }
        else if (c.quantity <= this._cap(ref)) { this.cursor = slot; this._set(ref, c); }
      }
    }
    this._renderCursor();
  }

  _onTakeResult(ref, n) {
    if (ref.kind !== 'furnace' || ref.f !== 'output' || n <= 0) return;
    const st = this.state;
    const xp = Math.round(st?.xp ?? 0);
    if (st) st.xp = 0;
    if (xp > 0) this.inv.game.player?.gainXP?.(xp * 5, 'smelt');
  }

  // Swap the stacks in two refs (hover hotkeys), respecting slot rules
  _swapRefs(a, b) {
    if (a.kind === b.kind && a.i === b.i && a.k === b.k && a.f === b.f) return;
    const sa = this._get(a), sb = this._get(b);
    if (!this._accepts(a, sb) || !this._accepts(b, sa)) return;
    if (a.kind === 'furnace' && a.f === 'output' && sb) return;
    this._set(a, sb); this._set(b, sa);
    if (a.kind === 'furnace' && a.f === 'output' && sa) this._onTakeResult(a, sa.quantity);
  }

  // Inventory refs: main inventory then hotbar (vanilla order), or reversed
  _invRefs(order = 'main-first') {
    const main = [...Array(this.inv.totalSlots - 9).keys()].map((k) => ({ kind: 'inv', i: k + 9 }));
    const hot = [...Array(9).keys()].map((i) => ({ kind: 'inv', i }));
    if (order === 'hotbar') return hot;
    if (order === 'main') return main;
    if (order === 'reverse') return [...hot.reverse(), ...main.reverse()];
    return [...main, ...hot];
  }

  // Shift-click
  _quickMove(ref) {
    const s = this._get(ref); if (!s) return;
    let targets;
    if (ref.kind === 'inv') {
      const fromHot = ref.i < 9;
      const other = fromHot ? this._invRefs('main') : this._invRefs('hotbar');
      if (this.mode === 'survival') {
        const k = MC_ARMOR[s.type]?.slot;
        targets = k && !this.inv.armor[k] ? [{ kind: 'armor', k }] : other;
      } else if (this.mode === 'chest') {
        targets = [...Array(27).keys()].map((i) => ({ kind: 'chest', i }));
      } else if (this.mode === 'furnace') {
        const cs = this.containers;
        if (cs?.smeltResult(s.type)) targets = [{ kind: 'furnace', f: 'input' }];
        else if (cs?.isFuel(s.type)) targets = [{ kind: 'furnace', f: 'fuel' }];
        else targets = other;
      } else if (this.mode === 'brewing') {
        const cs = this.containers;
        if (s.type === 'mc_blaze_powder') targets = [{ kind: 'furnace', f: 'fuel' }];
        else if (cs?.isBrewIngredient(s.type)) targets = [{ kind: 'furnace', f: 'ing' }];
        else if (cs?.isBottle(s.type)) targets = ['b0', 'b1', 'b2'].map((f) => ({ kind: 'furnace', f })).filter((r) => !this._get(r));
        else targets = other;
      } else if (this.mode === 'stonecutter' && STONECUTTER[s.type]) {
        targets = [{ kind: 'sc', f: 'input' }];
      } else targets = other;
    } else if (ref.kind === 'chest' || ref.kind === 'furnace' || ref.kind === 'sc') {
      targets = this._invRefs('reverse');
    } else {
      targets = this._invRefs('main-first');
    }
    const left = this._insertRefs(s, targets);
    if (left === s.quantity) return;
    this._set(ref, left > 0 ? this._copy(s, left) : null);
    if (ref.kind === 'furnace' && ref.f === 'output') this._onTakeResult(ref, s.quantity - left);
  }

  // Put a stack into refs (merge first, then empties). Returns leftover.
  _insertRefs(stack, refs) {
    let q = stack.quantity;
    if (!refs.length || !this._accepts(refs[0], stack)) return q;
    if (this._stackable(stack.type)) {
      for (const r of refs) {
        const t = this._get(r);
        if (t && t.type === stack.type && t.quantity + q <= this._cap(r)) { this._set(r, this._copy(t, t.quantity + q)); return 0; }
      }
    }
    for (const r of refs) {
      if (this._get(r)) continue;
      if (this._stackable(stack.type) && this._cap(r) >= q) { this._set(r, this._copy(stack, q)); return 0; }
      this._set(r, this._copy(stack, 1)); q -= 1;
      if (q <= 0) return 0;
    }
    return q;
  }

  _insert(stack) { return this._insertRefs(stack, this._invRefs('hotbar').concat(this._invRefs('main'))); }

  // Throw n of a stack in front of the player
  _throw(stack, n) {
    const p = this.inv.game.player?.body?.position, wis = this.inv.game.worldItemSystem;
    if (!p || !wis?.spawnItem || n <= 0) return;
    let dx = 0, dz = -1;
    const cam = this.inv.game.camera;
    if (cam) { const e = cam.matrixWorld.elements; dx = -e[8]; dz = -e[10]; }
    const l = Math.hypot(dx, dz) || 1;
    const it = wis.spawnItem(stack.type, p.x + dx / l * 1.6, p.y - 0.6, p.z + dz / l * 1.6, n, stack.note ? { note: stack.note } : undefined);
    if (it) it._noPickupUntil = performance.now() + 1500;
  }

  // ── Stonecutter ──────────────────────────────────────────────────────────
  _scRecipes() { return (this.scIn && STONECUTTER[this.scIn.type]) || []; }
  _scResult() {
    const r = this._scRecipes()[this.scSel];
    return r && this.inv.itemTypes[r[0]] ? { type: r[0], quantity: r[1], name: this._name(r[0]) } : null;
  }
  // One input per craft; shift crafts the whole input stack into the inventory
  _scTake(shift) {
    let n = 0;
    while (this.scIn && this.scIn.quantity > 0) {
      const out = this._scResult(); if (!out) break;
      if (shift) {
        if (this._insert(out) > 0) break;
      } else {
        if (this.cursor && !(this.cursor.type === out.type && this._stackable(out.type))) break;
        if (this.cursor) this.cursor.quantity += out.quantity; else this.cursor = out;
      }
      this.scIn.quantity -= 1; n++;
      if (this.scIn.quantity <= 0) { this.scIn = null; this.scSel = -1; }
      if (!shift) break;
    }
    if (n) this.inv.game.audioManager?.playSFX?.('pickup');
    this._renderSC(); this._renderCursor();
  }
  _renderSC() {
    const E = this.scEls; if (this.mode !== 'stonecutter' || !E) return;
    E.input.innerHTML = this._iconHTML(this.scIn);
    const rec = this._scRecipes();
    const rows = Math.ceil(rec.length / 4);
    this.scScroll = Math.max(0, Math.min(Math.max(0, rows - 3), this.scScroll));
    E.list.innerHTML = '';
    for (let k = this.scScroll * 4; k < Math.min(rec.length, (this.scScroll + 3) * 4); k++) {
      const j = k - this.scScroll * 4;
      const b = document.createElement('div');
      b.className = 'mc-sc-btn' + (k === this.scSel ? ' sel' : '');
      b.style.left = u((j % 4) * 16); b.style.top = u(((j / 4) | 0) * 18);
      b.innerHTML = this._iconHTML({ type: rec[k][0], quantity: rec[k][1] });
      b.addEventListener('mousedown', (e) => { e.preventDefault(); e.stopPropagation(); this.scSel = k; this.inv.game.audioManager?.playSFX?.('click'); this._renderSC(); });
      b.addEventListener('mouseenter', () => { if (!this.cursor) this._tipHTML(`<div class="mc-tip-name">${esc(this._name(rec[k][0]))}</div>`); });
      b.addEventListener('mouseleave', () => this._hideTip());
      E.list.appendChild(b);
    }
    const knob = rows > 3 ? (this.scScroll / (rows - 3)) * 41 : 0;
    E.bar.innerHTML = `<div class="mc-sc-knob${rows > 3 ? '' : ' off'}" style="top:${u(knob)}"></div>`;
    E.out.innerHTML = this._iconHTML(this._scResult());
  }

  // ── Crafting ─────────────────────────────────────────────────────────────
  _hasGrid() { return this.mode === 'survival' || this.mode === 'crafting_table'; }
  _match() { return this._hasGrid() ? (this.crafting?.matchGrid?.(this.grid, this.gridW) ?? null) : null; }

  _takeOutput(shift) {
    let r = this._match();
    if (!r) return;
    let crafted = 0;
    do {
      const out = { type: r.result, quantity: r.qty ?? 1, name: this._name(r.result) };
      if (!this.inv.itemTypes[out.type]) return;
      if (shift) {
        if (this._insert(out) > 0) break;
      } else {
        if (this.cursor && !(this.cursor.type === out.type && this._stackable(out.type))) return;
        if (this.cursor) this.cursor.quantity += out.quantity; else this.cursor = out;
      }
      for (let i = 0; i < this.grid.length; i++) if (this.grid[i]) { this.grid[i].quantity -= 1; if (this.grid[i].quantity <= 0) this.grid[i] = null; }
      crafted++;
      r = shift ? this._match() : null;
    } while (r && crafted < 64);
    if (crafted) {
      this.inv.game._craftCount = (this.inv.game._craftCount ?? 0) + crafted;
      this.inv.game.player?.gainXP?.(15 * crafted, 'craft');
      this.inv.game.audioManager?.playSFX?.('pickup');
    }
    this._renderGrid(); this._renderCursor(); this._renderBook();
  }

  _takeFromInv(type) {
    const i = this.inv.slots.findIndex((s) => s && s.type === type);
    if (i < 0) return false;
    const s = this.inv.slots[i];
    this._set({ kind: 'inv', i }, s.quantity > 1 ? this._copy(s, s.quantity - 1) : null);
    return true;
  }

  // Recipe book click. Minecraft recipes are laid into the grid (shift: as
  // deep as the inventory allows); legacy recipes craft straight away.
  _bookClick(r, shift) {
    const cs = this.crafting; if (!cs) return;
    if (!cs.isMcRecipe(r)) {
      if (!cs.canCraft(r)) return;
      let n = 0;
      do { cs.craft(r); n++; } while (shift && cs.canCraft(r) && n < 64);
      this._renderBook();
      return;
    }
    this._clearGrid();
    const plan = cs.planFill(r);
    if (!plan) { this._renderBook(); return; }
    const W = this.gridW;
    if (plan.w > W || plan.h > W) return;
    const placed = [];
    plan.cells.forEach((type, idx) => {
      if (!type) return;
      const x = idx % plan.w, y = (idx / plan.w) | 0, gi = y * W + x;
      if (!this._takeFromInv(type)) return;
      this.grid[gi] = { type, quantity: 1, name: this._name(type) };
      placed.push(gi);
    });
    if (shift) {
      for (let round = 0; round < 63; round++) {
        const need = {};
        for (const gi of placed) { const t = this.grid[gi].type; need[t] = (need[t] ?? 0) + 1; }
        if (!Object.entries(need).every(([t, q]) => this.inv.getItemCount(t) >= q)) break;
        for (const gi of placed) { this._takeFromInv(this.grid[gi].type); this.grid[gi].quantity += 1; }
      }
    }
    this._renderGrid(); this._renderBook();
  }

  _clearGrid() {
    for (let i = 0; i < this.grid.length; i++) {
      const s = this.grid[i]; if (!s) continue;
      const left = this._insert(s);
      if (left > 0) this._throw(s, left);
      this.grid[i] = null;
    }
    this._renderGrid();
  }

  // ── Render ─────────────────────────────────────────────────────────────
  _renderGrid() {
    this.gridEls?.forEach((el, i) => { el.innerHTML = this._iconHTML(this.grid[i]); });
    if (!this.outEl || !this._hasGrid()) return;
    const r = this._match();
    this.outEl.innerHTML = r ? this._iconHTML({ type: r.result, quantity: r.qty ?? 1 }) : '';
    this.outEl.title = r ? this._name(r.result) : '';
  }

  _renderEquip() {
    if (this.mode !== 'survival') return;
    for (const k of ARMOR_KEYS) {
      const el = this.armorEls?.[k]; if (!el) continue;
      const s = this.inv.armor[k];
      el.innerHTML = this._iconHTML(s);
      el.classList.toggle('filled', !!s);
    }
    if (this.offEl) { this.offEl.innerHTML = this._iconHTML(this.inv.offhand); this.offEl.classList.toggle('filled', !!this.inv.offhand); }
  }

  _renderChest() {
    if (this.mode !== 'chest') return;
    const st = this.state;
    this.chestEls.forEach((el, i) => { el.innerHTML = this._iconHTML(st?.slots[i]); });
  }

  _renderFurnace() {
    if (this.mode === 'brewing') { this._renderBrew(); return; }
    if (this.mode !== 'furnace') return;
    const st = this.state; if (!st) return;
    for (const f of ['input', 'fuel', 'output']) {
      const el = this.furnEls[f]; if (!el) continue;
      const s = st[f], sig = s ? `${s.type}:${s.quantity}` : '';
      if (el._sig !== sig) { el._sig = sig; el.innerHTML = this._iconHTML(s); }
    }
    const burn = st.burnLeft > 0 && st.burnMax > 0 ? st.burnLeft / st.burnMax : 0;
    // vanilla: flame shows 1..13 of 14 rows while lit, arrow 0..24 columns
    const rows = burn > 0 ? Math.max(1, Math.ceil(burn * 13)) : 0;
    if (this.flameEl) this.flameEl.style.clipPath = `inset(${((14 - rows) / 14) * 100}% 0 0 0)`;
    const cols = Math.floor(Math.min(1, st.cook / 10) * 24);
    if (this.progEl) this.progEl.style.clipPath = `inset(0 ${((24 - cols) / 24) * 100}% 0 0)`;
  }

  _renderBrew() {
    const st = this.state; if (!st) return;
    for (const f of ['b0', 'b1', 'b2', 'ing', 'fuel']) {
      const el = this.furnEls[f]; if (!el) continue;
      const s = st[f], sig = s ? `${s.type}:${s.quantity}` : '';
      if (el._sig !== sig) { el._sig = sig; el.innerHTML = this._iconHTML(s); }
    }
    // vanilla: the arrow fills top-down over the 20 s brew, bubbles loop
    const k = st.brew > 0 ? 1 - st.brew / 20 : 0;
    if (this.progEl) this.progEl.style.height = `${(k * 100).toFixed(1)}%`;
    if (this.bubEl) {
      const b = st.brew > 0 ? ((performance.now() / 1000 * 0.9) % 1) : 0;
      this.bubEl.style.clipPath = `inset(${((1 - b) * 100).toFixed(1)}% 0 0 0)`;
    }
    if (this.brewFuelEl) this.brewFuelEl.style.width = `${Math.min(100, (st.fuelLeft ?? 0) / 20 * 100).toFixed(1)}%`;
  }

  _renderCursor() {
    if (!this.cursorEl) return;
    this.cursorEl.innerHTML = this._iconHTML(this.cursor);
    this.cursorEl.style.display = this.cursor ? 'block' : 'none';
    if (this.cursor) this._hideTip();
  }

  _bookList() {
    const cs = this.crafting; if (!cs) return [];
    const items = this.inv.itemTypes;
    const mc = (cs.mcRecipes ?? []).filter((r) => items[r.result] && r.w <= this.gridW && r.h <= this.gridW);
    const legacy = this.mode === 'crafting_table' ? cs.recipes.filter((r) => items[r.result] && r.ingredients) : [];
    return [...mc, ...legacy];
  }

  // Recipe category of a recipe result (vanilla crafting-book tabs)
  _recipeCat(r) {
    const id = r.result ?? '';
    if (/^weapon_/.test(id) || MC_ARMOR[id] || /sword|pickaxe|axe|shovel|hoe|helmet|chestplate|leggings|boots|bow|arrow/.test(id)) return 'equipment';
    const def = this.inv.itemTypes[id];
    if (def?.effect === 'building block' || /planks|bricks|cobble|stone|log|glass|wool|table|furnace|chest|_block|slab|stairs|fence|door/.test(id)) return 'building';
    return 'misc';
  }

  // 147x166 vanilla-layout recipe book: search field (25,14), filter toggle
  // (110,12), category tabs down the left edge, 5x4 grid of 25x25 recipe
  // buttons at (11,31), page arrows at (38,137) / (93,137).
  _renderBook() {
    if (!this.book) return;
    const show = this.bookOpen && this._hasGrid();
    this.book.style.display = show ? 'block' : 'none';
    this.inv.screen?.classList.toggle('mc-book-open', !!show);
    if (!show) return;
    const cs = this.crafting; if (!cs) return;
    const filt = this._filter ?? 'all';
    const q = (this._search ?? '').trim().toLowerCase();
    const all = this._bookList();
    let list = all.filter((r) => this._tab === 'all' || this._recipeCat(r) === this._tab);
    if (q) list = list.filter((r) => (r.name ?? this._name(r.result)).toLowerCase().includes(q));
    if (filt === 'craftable') list = list.filter((r) => cs.canCraft(r));
    // vanilla sorts craftable recipes first
    list.sort((a, b) => (cs.canCraft(b) ? 1 : 0) - (cs.canCraft(a) ? 1 : 0));
    const PER = 20;
    const pages = Math.max(1, Math.ceil(list.length / PER));
    this._page = Math.min(this._page ?? 0, pages - 1);

    // Build the static chrome once, then only refresh the dynamic parts
    if (!this._bookBuilt) {
      this._bookBuilt = true;
      this.book.innerHTML = '';
      const add = (cls, x, y, tag = 'div') => {
        const d = document.createElement(tag); d.className = cls;
        if (x !== undefined) { d.style.left = u(x); d.style.top = u(y); }
        this.book.appendChild(d); return d;
      };
      this._bookTabs = add('mc-book-tabs');
      const TABS = [['all', 'mc_crafting_table', 'Search'], ['equipment', 'weapon_iron_sword', 'Equipment'], ['building', 'mc_stone_bricks', 'Building Blocks'], ['misc', 'mc_coal', 'Miscellaneous']];
      this._tabEls = TABS.map(([key, icon, label], i) => {
        const t = document.createElement('div');
        t.className = 'mc-book-tab'; t.dataset.tab = key;
        t.style.top = u(3 + i * 27);
        t.innerHTML = this.inv.itemTypes[icon] ? this._iconHTML({ type: icon, quantity: 1 }) : '';
        t.addEventListener('mousedown', (e) => { e.preventDefault(); e.stopPropagation(); this._tab = key; this._page = 0; this._renderBook(); });
        t.addEventListener('mouseenter', () => this._tipHTML(`<div class="mc-tip-name">${label}</div>`));
        t.addEventListener('mouseleave', () => this._hideTip());
        this._bookTabs.appendChild(t);
        return t;
      });
      const field = add('mc-book-search', 25, 14);
      const inp = document.createElement('input');
      inp.type = 'text'; inp.placeholder = 'Search...'; inp.spellcheck = false; inp.maxLength = 50;
      field.appendChild(inp);
      inp.addEventListener('mousedown', (e) => e.stopPropagation());
      // typing must not trigger game keys (E closes the inventory, 1-9 swap)
      inp.addEventListener('keydown', (e) => { if (e.key !== 'Escape') e.stopPropagation(); if (e.key === 'Enter') inp.blur(); });
      inp.addEventListener('keyup', (e) => e.stopPropagation());
      inp.addEventListener('input', () => { this._search = inp.value; this._page = 0; this._renderBook(); });
      this._bookInput = inp;
      this._filterBtn = add('mc-book-filter', 110, 12);
      this._filterBtn.addEventListener('mousedown', (e) => {
        e.preventDefault(); e.stopPropagation();
        this._filter = (this._filter ?? 'all') === 'all' ? 'craftable' : 'all';
        this._page = 0; this._renderBook();
        this._tipHTML(`<div class="mc-tip-name">${this._filter === 'all' ? 'Showing All' : 'Showing Craftable'}</div>`);
      });
      this._filterBtn.addEventListener('mouseenter', () => this._tipHTML(`<div class="mc-tip-name">${(this._filter ?? 'all') === 'all' ? 'Showing All' : 'Showing Craftable'}</div>`));
      this._filterBtn.addEventListener('mouseleave', () => this._hideTip());
      this._bookGrid = add('mc-book-grid', 11, 31);
      this._prevBtn = add('mc-book-page mc-prev', 38, 137);
      this._nextBtn = add('mc-book-page mc-next', 93, 137);
      this._pageLbl = add('mc-book-pagelbl', 0, 141);
      this._prevBtn.addEventListener('mousedown', (e) => { e.preventDefault(); e.stopPropagation(); this._page = Math.max(0, this._page - 1); this._renderBook(); });
      this._nextBtn.addEventListener('mousedown', (e) => { e.preventDefault(); e.stopPropagation(); this._page += 1; this._renderBook(); });
    }
    this._tabEls.forEach((t) => t.classList.toggle('sel', t.dataset.tab === this._tab));
    if (this._bookInput.value !== this._search) this._bookInput.value = this._search;
    this._filterBtn.classList.toggle('on', filt === 'craftable');
    const multi = pages > 1;
    this._prevBtn.style.display = multi && this._page > 0 ? 'block' : 'none';
    this._nextBtn.style.display = multi && this._page < pages - 1 ? 'block' : 'none';
    this._pageLbl.style.display = multi ? 'block' : 'none';
    this._pageLbl.textContent = `${this._page + 1}/${pages}`;
    if (multi) {
      const us = parseFloat(getComputedStyle(document.documentElement).getPropertyValue('--us')) || 1;
      this._pageLbl.style.left = u(Math.floor((147 - this._pageLbl.offsetWidth / us) / 2));
    }

    const g = this._bookGrid;
    g.innerHTML = '';
    for (const r of list.slice(this._page * PER, this._page * PER + PER)) {
      const b = document.createElement('div');
      const ok = cs.canCraft(r);
      const legacy = !cs.isMcRecipe(r);
      b.className = 'mc-recipe' + (ok ? '' : ' missing') + (legacy ? ' big' : '');
      b.innerHTML = this._iconHTML({ type: r.result, quantity: r.qty ?? 1 });
      b.addEventListener('mousedown', (e) => { e.preventDefault(); e.stopPropagation(); this._bookClick(r, e.shiftKey); });
      b.addEventListener('mouseenter', () => {
        this._tipHTML(`<div class="mc-tip-name">${esc(r.name ?? this._name(r.result))}</div><div class="mc-tip-sub">${esc(cs.describe(r))}</div>`
          + (ok ? '' : `<div class="mc-tip-sub missing">Missing ingredients</div>`));
      });
      b.addEventListener('mouseleave', () => this._hideTip());
      g.appendChild(b);
    }
  }

  // Keep furnaces running (and the gauges live) while the paused GUI is up.
  _startTick() {
    cancelAnimationFrame(this._raf);
    let last = performance.now();
    const step = (now) => {
      if (!this.inv.isOpen) return;
      const dt = Math.min(0.25, (now - last) / 1000); last = now;
      const g = this.inv.game;
      if (g.isPaused && this.containers?.update) this.containers.update(dt);
      if (this.mode === 'furnace' || this.mode === 'brewing') this._renderFurnace();
      if (this.mode === 'keypad') this._kpRender();
      this._raf = requestAnimationFrame(step);
    };
    this._raf = requestAnimationFrame(step);
  }

  onOpen() {
    const req = this._next; this._next = null;
    this._enter(req?.kind ?? 'survival', req?.key ?? null);
    this._startTick();
    this._startPreview();
  }

  // Switch the open screen to a mode (also used keypad -> chest in place)
  _enter(kind, key) {
    this.mode = kind;
    this.key = key;
    this.inv.screen?.setAttribute('data-mode', this.mode);
    this._layout();
    this._renderGrid(); this._renderEquip(); this._renderChest(); this._renderFurnace(); this._renderSC();
    this._renderCursor(); this._renderBook();
    this._snapToPixels();
  }

  // Flex centring can land the panels on a half device pixel (odd widths at
  // odd GUI scales), which blurs every 1px edge; nudge the screen by 1px.
  _snapToPixels() {
    const scr = this.inv.screen; if (!scr || !this.panel) return;
    scr.style.paddingLeft = scr.style.paddingTop = '0px';
    const r = this.panel.getBoundingClientRect();
    if (r.left % 1) scr.style.paddingLeft = '1px';
    if (r.top % 1) scr.style.paddingTop = '1px';
  }

  // 3D player preview: one renderer, reused across opens; only renders while
  // the survival screen is up
  _startPreview() {
    this.preview?.stop();
    if (this.mode !== 'survival' || !this.previewBox) return;
    this.preview ??= new PlayerPreview3D(this.inv);
    this.preview.attach(this.previewBox);
    this.preview.start();
  }

  onClose() {
    cancelAnimationFrame(this._raf);
    this.preview?.stop();
    if (this.cursor) {
      const left = this._insert(this.cursor);
      if (left > 0) this._throw(this.cursor, left);
      this.cursor = null;
    }
    this._clearGrid();
    if (this.scIn) { const left = this._insert(this.scIn); if (left > 0) this._throw(this.scIn, left); this.scIn = null; this.scSel = -1; }
    this._renderCursor();
    this._hoverRef = null;
    this._hideTip();
    this._bookInput?.blur();
    this.mode = 'survival';
    this.key = null;
  }
}
