// ItemMesh.js — turns a 16x16 item sprite into a 3D item, the way vanilla
// builds item models: front/back faces textured with the sprite, and every
// opaque pixel edge gets a 1px side quad coloured with that pixel (darkened
// per side). Used for the first-person held item and for dropped items.

import * as THREE from 'three';

const PX = 1 / 16;

function srgbToLinear(v) { return v <= 0.04045 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4); }

// Shared geometry/texture per source canvas; materials are per-call options.
const _geoCache = new WeakMap();   // canvas -> { tex, edges }

function build(src) {
  let hit = _geoCache.get(src);
  if (hit) return hit;
  const c = document.createElement('canvas'); c.width = c.height = 16;
  const g = c.getContext('2d'); g.imageSmoothingEnabled = false; g.drawImage(src, 0, 0, 16, 16);
  const d = g.getImageData(0, 0, 16, 16).data;
  const opaque = (x, y) => x >= 0 && y >= 0 && x < 16 && y < 16 && d[(y * 16 + x) * 4 + 3] > 127;
  const tex = new THREE.CanvasTexture(c);
  tex.magFilter = THREE.NearestFilter; tex.minFilter = THREE.NearestFilter; tex.generateMipmaps = false;
  tex.colorSpace = THREE.SRGBColorSpace;
  const pos = [], col = [];
  const push = (pts, r, gg, b, k) => { for (const i of [0, 1, 2, 0, 2, 3]) { pos.push(...pts[i]); col.push(srgbToLinear(r * k), srgbToLinear(gg * k), srgbToLinear(b * k)); } };
  const h = PX / 2;
  for (let y = 0; y < 16; y++) for (let x = 0; x < 16; x++) {
    if (!opaque(x, y)) continue;
    const i = (y * 16 + x) * 4, r = d[i] / 255, gg = d[i + 1] / 255, b = d[i + 2] / 255;
    const X0 = x / 16 - 0.5, X1 = X0 + PX, Y1 = 0.5 - y / 16, Y0 = Y1 - PX;
    if (!opaque(x, y - 1)) push([[X0, Y1, h], [X1, Y1, h], [X1, Y1, -h], [X0, Y1, -h]], r, gg, b, 0.95);
    if (!opaque(x, y + 1)) push([[X0, Y0, -h], [X1, Y0, -h], [X1, Y0, h], [X0, Y0, h]], r, gg, b, 0.55);
    if (!opaque(x - 1, y)) push([[X0, Y0, -h], [X0, Y0, h], [X0, Y1, h], [X0, Y1, -h]], r, gg, b, 0.7);
    if (!opaque(x + 1, y)) push([[X1, Y0, h], [X1, Y0, -h], [X1, Y1, -h], [X1, Y1, h]], r, gg, b, 0.75);
  }
  const edges = new THREE.BufferGeometry();
  edges.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
  edges.setAttribute('color', new THREE.Float32BufferAttribute(col, 3));
  hit = { tex, edges };
  _geoCache.set(src, hit);
  return hit;
}

const _plane = new THREE.PlaneGeometry(1, 1);

// Returns a THREE.Group, 1 unit square, centred, 1/16 thick.
//   overlay: true -> drawn on top of the world (first-person hand)
export function extrudeSprite(src, { overlay = false } = {}) {
  if (!src || !src.width) return null;
  const { tex, edges } = build(src);
  const group = new THREE.Group();
  const faceMat = new THREE.MeshBasicMaterial({ map: tex, alphaTest: 0.5, side: THREE.DoubleSide, depthTest: !overlay, toneMapped: false });
  const edgeMat = new THREE.MeshBasicMaterial({ vertexColors: true, side: THREE.DoubleSide, depthTest: !overlay, toneMapped: false });
  const front = new THREE.Mesh(_plane, faceMat); front.position.z = PX / 2;
  const back = new THREE.Mesh(_plane, faceMat); back.position.z = -PX / 2;
  group.add(front, back, new THREE.Mesh(edges, edgeMat));
  group.traverse((o) => { o.userData.noHit = true; o.userData.noVox = true; if (overlay) o.renderOrder = 1000; });
  return group;
}
