// SunShadows.js — real-time sun/moon shadows for the voxel terrain.
//
// One orthographic depth map centred on the player and aligned to the light.
// The box moves in whole shadow-texel steps (in light space), so shadow edges
// stay perfectly still while walking instead of crawling/shimmering.
// Terrain (layer 1) renders with an alpha-tested atlas material so leaves
// and plants cast leafy shadows; mobs (layer 2) render as solid casters.
// The terrain shader samples the map with a soft rotated-disc PCF.

import * as THREE from 'three';

export const SHADOW_LAYER_TERRAIN = 1;
export const SHADOW_LAYER_ENTITY = 2;

export const SHADOW_GLSL = /* glsl */`
uniform sampler2D uShadowMap;
uniform mat4 uShadowMat;
uniform float uShadowTexel;     // 1 / map size
uniform float uShadowOn;
float shadowAt(vec3 wpos, vec3 n, float ndl) {
  if (uShadowOn < 0.5) return 1.0;
  // normal offset (bigger at grazing angles) kills acne without peter-panning
  vec4 sp = uShadowMat * vec4(wpos + n * (0.035 + 0.06 * (1.0 - ndl)), 1.0);
  vec3 p = sp.xyz / sp.w * 0.5 + 0.5;
  if (p.x <= 0.0 || p.x >= 1.0 || p.y <= 0.0 || p.y >= 1.0 || p.z >= 1.0) return 1.0;
  float bias = 0.0006;
  // 12-tap rotated Poisson disc, rotation per pixel to turn banding into fine noise
  float a = fract(sin(dot(gl_FragCoord.xy, vec2(12.9898, 78.233))) * 43758.5453) * 6.2831;
  mat2 R = mat2(cos(a), -sin(a), sin(a), cos(a));
  vec2 D[12];
  D[0] = vec2(-0.326, -0.406); D[1] = vec2(-0.840, -0.074); D[2] = vec2(-0.696, 0.457);
  D[3] = vec2(-0.203, 0.621);  D[4] = vec2(0.962, -0.195);  D[5] = vec2(0.473, -0.480);
  D[6] = vec2(0.519, 0.767);   D[7] = vec2(0.185, -0.893);  D[8] = vec2(0.507, 0.064);
  D[9] = vec2(0.896, 0.412);   D[10] = vec2(-0.322, -0.933); D[11] = vec2(-0.792, -0.598);
  float lit = 0.0;
  float r = 1.6 * uShadowTexel;
  for (int i = 0; i < 12; i++) {
    float d = texture2D(uShadowMap, p.xy + R * D[i] * r).r;
    lit += step(p.z - bias, d);
  }
  lit /= 12.0;
  // fade out towards the edge of the shadowed area
  vec2 e = abs(p.xy - 0.5) * 2.0;
  return mix(lit, 1.0, smoothstep(0.82, 1.0, max(e.x, e.y)));
}
`;

export class SunShadows {
  constructor(renderer, atlas, { size = 2048, half = 64 } = {}) {
    this.renderer = renderer;
    this.size = size;
    this.half = half;
    const dt = new THREE.DepthTexture(size, size);
    dt.type = THREE.UnsignedIntType;
    this.target = new THREE.WebGLRenderTarget(size, size, {
      depthTexture: dt, depthBuffer: true,
      minFilter: THREE.NearestFilter, magFilter: THREE.NearestFilter,
    });
    this.cam = new THREE.OrthographicCamera(-half, half, half, -half, 1, 600);
    this.terrainMat = new THREE.MeshBasicMaterial({ map: atlas, alphaTest: 0.5, side: THREE.DoubleSide, colorWrite: false });
    this.entityMat = new THREE.MeshBasicMaterial({ colorWrite: false, side: THREE.DoubleSide });
    this.matrix = new THREE.Matrix4();
    this.uniforms = {
      uShadowMap: { value: dt },
      uShadowMat: { value: this.matrix },
      uShadowTexel: { value: 1 / size },
      uShadowOn: { value: 0 },
    };
    this._v = new THREE.Vector3();
    this._c = new THREE.Vector3();
    this._frame = 0;
  }

  // focus: world point to centre on (camera); lightDir: normalised, towards light
  render(scene, focus, lightDir, strength) {
    if (strength <= 0.001) { this.uniforms.uShadowOn.value = 0; return; }
    this.uniforms.uShadowOn.value = 1;
    const cam = this.cam, texel = (this.half * 2) / this.size;
    // centre a little ahead is pointless for an FPS; centre on the eye
    cam.position.copy(focus).addScaledVector(lightDir, 300);
    cam.up.set(0, 1, 0);
    if (Math.abs(lightDir.y) > 0.99) cam.up.set(0, 0, 1);
    cam.lookAt(focus);
    cam.updateMatrixWorld(true);
    // snap the focus to whole texels in light space
    const inv = cam.matrixWorldInverse;
    this._c.copy(focus).applyMatrix4(inv);
    const sx = Math.round(this._c.x / texel) * texel - this._c.x;
    const sy = Math.round(this._c.y / texel) * texel - this._c.y;
    this._v.set(sx, sy, 0).applyQuaternion(cam.quaternion);
    cam.position.add(this._v);
    cam.updateMatrixWorld(true);
    cam.updateProjectionMatrix();

    const r = this.renderer;
    const prevTarget = r.getRenderTarget(), prevAuto = r.autoClear, prevOverride = scene.overrideMaterial;
    const prevBg = scene.background, prevFog = scene.fog;
    scene.background = null; scene.fog = null;
    r.setRenderTarget(this.target);
    r.autoClear = false;
    r.clear(true, true, true);
    scene.overrideMaterial = this.terrainMat;
    cam.layers.set(SHADOW_LAYER_TERRAIN);
    r.render(scene, cam);
    scene.overrideMaterial = this.entityMat;
    cam.layers.set(SHADOW_LAYER_ENTITY);
    r.render(scene, cam);
    scene.overrideMaterial = prevOverride;
    scene.background = prevBg; scene.fog = prevFog;
    r.setRenderTarget(prevTarget);
    r.autoClear = prevAuto;

    this.matrix.multiplyMatrices(cam.projectionMatrix, cam.matrixWorldInverse);
  }
}
