// JukeboxSystem.js — jukeboxes and the 26.4 music disc "Flurry".
//
// Right-click a jukebox with a disc to insert it and play; right-click again
// to eject. The record keeps its slot in ContainerSystem ({type:'jukebox',
// disc}) so it is saved with the world and spills when the block breaks.
// Playback is fully synthesised with WebAudio: "Flurry" here is an original
// composition (not the vanilla track), a wintry piece in D minor at 132 BPM:
// soft pad chords, a bell lead, falling snow-flake arpeggios, a sine bass and
// brushed hats. Volume falls off linearly to silence at 64 blocks, like a
// vanilla jukebox, and music notes drift up from a playing jukebox.

import * as THREE from 'three';

export const DISCS = {
  mc_music_disc_flurry: { title: 'Flurry', build: buildFlurry },
};

const RANGE = 64;
const LOOKAHEAD = 0.6;   // seconds of notes scheduled ahead

const midi = (n) => 440 * Math.pow(2, (n - 69) / 12);

// ── the song ────────────────────────────────────────────────────────────────
// Returns { length, events: [{ t, d, n, v, voice }] } (times in seconds).
function buildFlurry() {
  const BPM = 132, B = 60 / BPM, BAR = 4 * B;
  const ev = [];
  const add = (t, d, n, v, voice) => ev.push({ t, d, n, v, voice });
  // chord roots and voicings, two bars each (D minor: i - VI - iv - V)
  const PROG = [
    { bass: 38, pad: [62, 65, 69, 72] },   // Dm(add9-ish)
    { bass: 34, pad: [62, 65, 69, 70] },   // Bbmaj7
    { bass: 31, pad: [62, 67, 70, 74] },   // Gm9
    { bass: 33, pad: [61, 64, 67, 69] },   // A7
  ];
  const SCALE = [62, 64, 65, 67, 69, 70, 72, 74, 76, 77, 79, 81];
  // deterministic little RNG so the tune is identical every play
  let seed = 0x5eed;
  const rnd = () => { seed = (seed * 1103515245 + 12345) & 0x7fffffff; return seed / 0x7fffffff; };

  // two composed melodic phrases (scale-index, beats), reused with variation
  const PHRASE_A = [[4, 1], [5, 0.5], [4, 0.5], [2, 1], [0, 1], [1, 1.5], [2, 0.5], [4, 2],
                    [7, 1], [6, 0.5], [5, 0.5], [4, 1], [2, 1], [3, 1.5], [1, 0.5], [0, 2]];
  const PHRASE_B = [[7, 0.5], [8, 0.5], [9, 1], [8, 1], [7, 1], [5, 1.5], [4, 0.5], [5, 2],
                    [4, 0.5], [5, 0.5], [7, 1], [5, 1], [4, 1], [2, 1], [3, 1], [1, 2]];
  const SECTIONS = [
    { bars: 8, melody: null, arp: true, hats: false },          // intro: snowfall
    { bars: 8, melody: PHRASE_A, arp: true, hats: true },        // A
    { bars: 8, melody: PHRASE_A, arp: true, hats: true, up: 0 }, // A (varied)
    { bars: 8, melody: PHRASE_B, arp: true, hats: true },        // B
    { bars: 8, melody: PHRASE_A, arp: true, hats: true, up: 12 },// A an octave up
    { bars: 4, melody: null, arp: true, hats: false, fade: true },// outro
  ];
  let t0 = 0.2, bar = 0;
  for (const sec of SECTIONS) {
    for (let b = 0; b < sec.bars; b++, bar++) {
      const t = t0 + b * BAR, ch = PROG[Math.floor(bar / 2) % 4];
      const fade = sec.fade ? 1 - b / sec.bars : 1;
      // pad: one held chord per bar
      if (b % 2 === 0) for (const n of ch.pad) add(t, BAR * 2 - 0.05, n - 12, 0.05 * fade, 'pad');
      // bass: root on 1 and the and-of-3
      add(t, B * 1.6, ch.bass, 0.22 * fade, 'bass');
      add(t + 2.5 * B, B * 1.2, ch.bass + (b % 2 ? 7 : 12), 0.16 * fade, 'bass');
      // flurry arpeggio: 16ths drifting down through the chord, high and soft
      if (sec.arp) {
        const tones = [...ch.pad].reverse().map((n) => n + 12);
        for (let s = 0; s < 16; s++) {
          if (rnd() < 0.18) continue;                       // gaps, like gusts
          const n = tones[(s + bar) % tones.length] + (s >= 8 ? -12 : 0) + (rnd() < 0.12 ? 12 : 0);
          add(t + s * B / 4, B / 4, n, (0.035 + rnd() * 0.02) * fade, 'flake');
        }
      }
      if (sec.hats) for (let s = 0; s < 8; s++) add(t + s * B / 2 + (s % 2 ? B * 0.06 : 0), 0.05, 0, s % 2 ? 0.05 : 0.025, 'hat');
    }
    // melody across the section: each phrase spans 8 bars (32 beats)
    if (sec.melody) {
      let bt = 0;
      const varied = sec.up === 0;
      for (const [deg, len] of sec.melody) {
        let d = deg;
        if (varied && rnd() < 0.3) d = Math.max(0, Math.min(SCALE.length - 1, deg + (rnd() < 0.5 ? 1 : -1)));
        const n = SCALE[d] + (sec.up || 0) + 12;
        add(t0 + bt * B * 2, len * B * 2 * 0.95, n, 0.11, 'bell');
        bt += len;
      }
    }
    t0 += sec.bars * BAR;
  }
  add(t0, BAR * 2, 50, 0.05, 'pad'); add(t0, BAR * 2, 57, 0.05, 'pad'); add(t0, BAR * 2, 62, 0.05, 'pad');
  add(t0, 0.6, 86, 0.08, 'bell');
  ev.sort((a, b) => a.t - b.t);
  return { length: t0 + BAR * 2, events: ev };
}

// one note on `ac`, routed into `out`
function playNote(ac, out, e, at, noise) {
  const f = midi(e.n), end = at + e.d;
  const g = ac.createGain();
  g.connect(out);
  const osc = (type, freq, detune = 0) => { const o = ac.createOscillator(); o.type = type; o.frequency.value = freq; o.detune.value = detune; return o; };
  switch (e.voice) {
    case 'pad': {
      const a = osc('triangle', f, -6), b = osc('triangle', f, 6);
      const lp = ac.createBiquadFilter(); lp.type = 'lowpass'; lp.frequency.value = 1400;
      a.connect(lp); b.connect(lp); lp.connect(g);
      g.gain.setValueAtTime(0, at); g.gain.linearRampToValueAtTime(e.v, at + 0.6); g.gain.setValueAtTime(e.v, end - 0.5); g.gain.linearRampToValueAtTime(0, end);
      a.start(at); b.start(at); a.stop(end + 0.05); b.stop(end + 0.05);
      break;
    }
    case 'bell': {
      const a = osc('sine', f), b = osc('sine', f * 2.01), gb = ac.createGain();
      gb.gain.setValueAtTime(e.v * 0.5, at); gb.gain.exponentialRampToValueAtTime(0.0005, at + 0.4);
      a.connect(g); b.connect(gb); gb.connect(out);
      g.gain.setValueAtTime(0, at); g.gain.linearRampToValueAtTime(e.v, at + 0.008); g.gain.exponentialRampToValueAtTime(0.0005, end + 0.4);
      a.start(at); b.start(at); a.stop(end + 0.45); b.stop(at + 0.45);
      break;
    }
    case 'flake': {
      const a = osc('square', f);
      const lp = ac.createBiquadFilter(); lp.type = 'lowpass'; lp.frequency.value = 3200;
      a.connect(lp); lp.connect(g);
      g.gain.setValueAtTime(e.v, at); g.gain.exponentialRampToValueAtTime(0.0003, at + 0.18);
      a.start(at); a.stop(at + 0.2);
      break;
    }
    case 'bass': {
      const a = osc('sine', f);
      a.connect(g);
      g.gain.setValueAtTime(0, at); g.gain.linearRampToValueAtTime(e.v, at + 0.02); g.gain.exponentialRampToValueAtTime(0.0005, end);
      a.start(at); a.stop(end + 0.02);
      break;
    }
    case 'hat': {
      const s = ac.createBufferSource(); s.buffer = noise;
      const hp = ac.createBiquadFilter(); hp.type = 'highpass'; hp.frequency.value = 7000;
      s.connect(hp); hp.connect(g);
      g.gain.setValueAtTime(e.v, at); g.gain.exponentialRampToValueAtTime(0.0003, at + e.d);
      s.start(at); s.stop(at + e.d + 0.01);
      break;
    }
  }
}

// a floating music-note sprite (original glyph)
let _noteTex = null;
function noteTexture() {
  if (_noteTex) return _noteTex;
  const c = document.createElement('canvas'); c.width = c.height = 16;
  const x = c.getContext('2d');
  const px = [[9, 2], [10, 2], [11, 3], [12, 4], [9, 3], [9, 4], [9, 5], [9, 6], [9, 7], [9, 8], [9, 9], [9, 10],
    [6, 10], [7, 10], [8, 10], [5, 11], [6, 11], [7, 11], [8, 11], [9, 11], [5, 12], [6, 12], [7, 12], [8, 12], [6, 13], [7, 13]];
  x.fillStyle = '#000'; for (const [a, b] of px) x.fillRect(a - 1, b, 3, 1), x.fillRect(a, b - 1, 1, 3);
  x.fillStyle = '#fff'; for (const [a, b] of px) x.fillRect(a, b, 1, 1);
  _noteTex = new THREE.CanvasTexture(c); _noteTex.magFilter = THREE.NearestFilter; _noteTex.colorSpace = THREE.SRGBColorSpace;
  return _noteTex;
}

export class JukeboxSystem {
  constructor(game) {
    this.game = game;
    this.playing = new Map();   // key -> { out, song, i, start, pos, noteT }
    this.notes = [];
  }

  _ctx() {
    const am = this.game.audioManager;
    const ac = am?.audioContext;
    if (!ac) return null;
    if (ac.state === 'suspended') ac.resume?.();
    if (!this._noise) {
      this._noise = ac.createBuffer(1, ac.sampleRate * 0.2, ac.sampleRate);
      const d = this._noise.getChannelData(0); for (let i = 0; i < d.length; i++) d[i] = Math.random() * 2 - 1;
    }
    return { ac, dest: am.musicGain ?? am.masterGain ?? ac.destination };
  }

  isDisc(type) { return !!DISCS[type]; }

  // right-click on a jukebox. Returns true when the click was used.
  use(key, x, y, z, item) {
    const cs = this.game.containerSystem, inv = this.game.inventorySystem;
    const st = cs?.get(key, 'jukebox');
    if (!st) return false;
    if (st.disc) { this.eject(key, x, y, z); return true; }
    if (!item || !this.isDisc(item.type)) return false;
    st.disc = { type: item.type, quantity: 1 };
    inv.removeItem(inv.heldSlot ?? 0, 1);
    this.play(key, x, y, z, item.type);
    return true;
  }

  eject(key, x, y, z) {
    const st = this.game.containerSystem?.containers.get(key);
    this.stop(key);
    if (!st?.disc) return;
    this.game.worldItemSystem?.spawnItem?.(st.disc.type, x + 0.5, y + 1.1, z + 0.5, 1);
    st.disc = null;
  }

  play(key, x, y, z, type) {
    this.stop(key);
    const c = this._ctx(), disc = DISCS[type];
    if (!c || !disc) return;
    disc._song ??= disc.build();
    const out = c.ac.createGain(); out.gain.value = 0; out.connect(c.dest);
    this.playing.set(key, { out, song: disc._song, i: 0, start: c.ac.currentTime + 0.05, pos: new THREE.Vector3(x + 0.5, y + 0.5, z + 0.5), noteT: 0 });
    this._nowPlaying(disc.title);
  }

  stop(key) {
    const p = this.playing.get(key);
    if (!p) return;
    try { p.out.gain.cancelScheduledValues(0); p.out.disconnect(); } catch { /* already gone */ }
    this.playing.delete(key);
  }

  // block broken: the disc spills with the container contents; silence it
  onBlockBroken(key) { this.stop(key); }

  update(dt) {
    if (this.playing.size) {
      const c = this._ctx(); if (!c) return;
      const now = c.ac.currentTime, pp = this.game.player?.getPosition?.();
      for (const [key, p] of this.playing) {
        // scheduled notes for the next LOOKAHEAD seconds
        const ev = p.song.events;
        while (p.i < ev.length && p.start + ev[p.i].t < now + LOOKAHEAD) {
          const e = ev[p.i++], at = p.start + e.t;
          if (at >= now - 0.02) playNote(c.ac, p.out, e, Math.max(now, at), this._noise);
        }
        const d = pp ? pp.distanceTo(p.pos) : 0;
        p.out.gain.setTargetAtTime(Math.max(0, 1 - d / RANGE), now, 0.1);
        if (now > p.start + p.song.length + 1) { this.stop(key); continue; }   // finished: the disc stays in
        if ((p.noteT -= dt) <= 0) { p.noteT = 0.9; this._spawnNote(p.pos); }
      }
    }
    for (let i = this.notes.length - 1; i >= 0; i--) {
      const n = this.notes[i];
      n.life -= dt;
      n.s.position.y += dt * 0.6;
      n.s.material.opacity = Math.min(1, n.life);
      if (n.life <= 0) { n.s.parent?.remove(n.s); n.s.material.dispose(); this.notes.splice(i, 1); }
    }
  }

  _spawnNote(pos) {
    const scene = this.game.scene?.scene;
    if (!scene?.add) return;
    const m = new THREE.SpriteMaterial({ map: noteTexture(), transparent: true, depthWrite: false });
    m.color.setHSL(Math.random(), 0.85, 0.6);
    const s = new THREE.Sprite(m);
    s.scale.setScalar(0.35);
    s.position.set(pos.x + (Math.random() - 0.5) * 0.4, pos.y + 0.75, pos.z + (Math.random() - 0.5) * 0.4);
    s.raycast = () => {};
    s.userData.noVox = true;
    scene.add(s);
    this.notes.push({ s, life: 1.6 });
  }

  // vanilla-style action-bar line above the hotbar, cycling colours
  _nowPlaying(title) {
    let el = document.getElementById('now-playing');
    if (!el) {
      el = document.createElement('div');
      el.id = 'now-playing';
      document.body.appendChild(el);
    }
    el.textContent = `Now Playing: ${title}`;
    el.classList.remove('show'); void el.offsetWidth; el.classList.add('show');
    clearTimeout(this._npT);
    this._npT = setTimeout(() => el.classList.remove('show'), 3500);
  }

  clear() {
    for (const key of [...this.playing.keys()]) this.stop(key);
    for (const n of this.notes) { n.s.parent?.remove(n.s); n.s.material.dispose(); }
    this.notes = [];
  }
}
