import * as THREE from 'three';
import { mergeGeometries } from 'three/examples/jsm/utils/BufferGeometryUtils.js';

// One blood "pixel" — a flat Minecraft-style voxel tile used to build splatters.
const BLOOD_PX = 0.11;
const _bloodPixGeo = new THREE.BoxGeometry(BLOOD_PX, 0.02, BLOOD_PX);

// Scratch vector for velocity — reused across all create* calls to avoid per-particle allocation
const _v = new THREE.Vector3();

// Shared geometry cache
const GEO = {
  // Blocky cube particles — circles are illegal (Minecraft-style square puffs).
  tiny:   new THREE.BoxGeometry(0.09, 0.09, 0.09),
  small:  new THREE.BoxGeometry(0.15, 0.15, 0.15),
  medium: new THREE.BoxGeometry(0.28, 0.28, 0.28),
  large:  new THREE.BoxGeometry(0.46, 0.46, 0.46),
  smoke:  new THREE.BoxGeometry(0.62, 0.62, 0.62),
  spark:  new THREE.BoxGeometry(0.04, 0.04, 0.18),
  debris: new THREE.BoxGeometry(0.09, 0.05, 0.09),
};
const _halfScale = new THREE.Vector3(0.5, 0.5, 0.5);
const _zeroScale = new THREE.Vector3(0.01, 0.01, 0.01);

// Material pool — reuse by hex color key
const _matPool = new Map();
function poolMat(color, transparent = false, opacity = 1) {
  const key = `${color}_${transparent}_${Math.round(opacity * 100)}`;
  if (!_matPool.has(key)) {
    _matPool.set(key, new THREE.MeshBasicMaterial({
      color, transparent, opacity,
      depthWrite: !transparent, // transparent particles skip depth write — no z-fighting
    }));
  }
  return _matPool.get(key);
}

export class ParticleSystem {
  constructor(scene) {
    this.scene = scene;
    this.particles = [];
    this.decals = [];                 // persistent blood pools on the ground
    this._downRay = new THREE.Raycaster();
    this._downRay.far = 10;
  }

  _spawn(geo, color, pos, vel, life, gravity = 0, transparent = false, opacity = 1, scaleDown = true) {
    // Transparent particles fade their material per-frame, so they need their own
    // clone — mutating the pooled material makes every particle of that color flicker
    const pooled = poolMat(color, transparent, opacity);
    const mat = transparent ? pooled.clone() : pooled;
    const p = new THREE.Mesh(geo, mat);
    p._ownMat = transparent;
    p.userData.noHit = true; // never absorb weapon raycasts
    p.position.copy(pos);
    p.velocity       = vel.clone();
    p.life           = life;
    p.maxLife        = life;
    p.gravity        = gravity;
    p.baseOpacity    = opacity;
    p.transparent    = transparent;
    p.scaleDown      = scaleDown;
    this.scene.add(p);
    this.particles.push(p);
    return p;
  }

  createMuzzleFlash(position) {
    for (let i = 0; i < 5; i++) {
      this._spawn(GEO.small, 0xffaa00, position,
        _v.set((Math.random()-0.5)*5, (Math.random()-0.5)*5, Math.random()*10),
        0.08, 0, false, 1, true);
    }
    this._spawn(GEO.medium, 0xffffff, position, _v.set(0,0,0), 0.06, 0, true, 0.9);
    for (let i = 0; i < 8; i++) {
      const a = Math.random() * Math.PI * 2, spd = 4 + Math.random() * 8;
      this._spawn(GEO.spark, 0xffdd44, position,
        _v.set(Math.cos(a)*spd, (Math.random()-0.3)*4, Math.sin(a)*spd + 6),
        0.12, -18, false, 1, false);
    }
  }

  // Critical hit: a spray of pale star flecks bursting out of the target and
  // slowing as they drift down (vanilla crit particle behaviour).
  createCrit(position, count = 18) {
    const C = [0xfff6c8, 0xffffff, 0xe8d890, 0xc8b878];
    for (let i = 0; i < count; i++) {
      const u = Math.random() * 2 - 1, a = Math.random() * Math.PI * 2, r = Math.sqrt(1 - u * u);
      const spd = 3 + Math.random() * 3;
      const p = this._spawn(GEO.tiny, C[(Math.random() * C.length) | 0], position,
        _v.set(Math.cos(a) * r * spd, u * spd * 0.7 + 1.5, Math.sin(a) * r * spd),
        0.35 + Math.random() * 0.35, -5, false, 1, true);
      p._drag = 4.5;
    }
  }

  // Sword sweep: a flat pale crescent swept in front of the player.
  createSweep(position, camera) {
    if (!ParticleSystem._sweepTex) {
      const c = document.createElement('canvas'); c.width = 32; c.height = 16;
      const x = c.getContext('2d');
      for (let px = 0; px < 32; px++) for (let py = 0; py < 16; py++) {
        const dx = (px - 15.5) / 15.5, dy = (py - 15) / 14;
        const d = Math.hypot(dx, dy);
        if (d < 0.62 || d > 1.0) continue;
        const edge = (d - 0.62) / 0.38;
        const fadeEnds = Math.min(1, Math.abs(dx) < 0.9 ? 1 : (1 - Math.abs(dx)) * 10);
        const a = (0.35 + 0.65 * edge) * fadeEnds;
        const g = 200 + ((px * 7 + py * 3) % 4) * 14;
        x.fillStyle = `rgba(${g},${g},${g},${a.toFixed(2)})`;
        x.fillRect(px, py, 1, 1);
      }
      const tex = new THREE.CanvasTexture(c);
      tex.magFilter = THREE.NearestFilter; tex.minFilter = THREE.NearestFilter;
      tex.colorSpace = THREE.SRGBColorSpace;
      ParticleSystem._sweepTex = tex;
    }
    const mat = new THREE.MeshBasicMaterial({ map: ParticleSystem._sweepTex, transparent: true, depthWrite: false, side: THREE.DoubleSide, toneMapped: false });
    const m = new THREE.Mesh(ParticleSystem._sweepGeo ??= new THREE.PlaneGeometry(2.2, 1.1), mat);
    m.userData.noHit = true;
    m.position.copy(position);
    if (camera) m.quaternion.copy(camera.quaternion);
    m._ownMat = true;
    m.velocity = new THREE.Vector3();
    m.life = m.maxLife = 0.28;
    m.gravity = 0; m.baseOpacity = 1; m.transparent = true; m.scaleDown = false; m._growing = false;
    m._sweepGrow = true;
    this.scene.add(m);
    this.particles.push(m);
  }

  // Deep arterial reds — darker and wetter than cartoon red.
  static BLOOD = [0x5a0000, 0x6e0202, 0x8a0303, 0x3a0000, 0x4a0606];

  createBlood(position, count = 6) {
    const B = ParticleSystem.BLOOD;
    // Chunky gore droplets that arc and fall under heavy gravity.
    for (let i = 0; i < count; i++) {
      const col = B[(Math.random() * B.length) | 0];
      this._spawn(Math.random() < 0.45 ? GEO.medium : GEO.small, col, position,
        _v.set((Math.random()-0.5)*6, 2.5 + Math.random()*4.5, (Math.random()-0.5)*6),
        0.7 + Math.random()*0.9, -20, false, 1, true);
    }
    // Fine mist spray — fades fast, reads as a violent wet burst.
    for (let i = 0; i < Math.ceil(count*0.6); i++) {
      this._spawn(GEO.tiny, 0x7a0000, position,
        _v.set((Math.random()-0.5)*10, 3 + Math.random()*4, (Math.random()-0.5)*10),
        0.35, -12, true, 0.6, true);
    }
    // Leave a lingering pool on the ground. More blood on big/crit/kill hits.
    if (count >= 10 || Math.random() < 0.4) this.createBloodPool(position);
  }

  // A Minecraft block-pixel blood splatter: an irregular blob of flat voxel
  // tiles (dense core, sparse ragged edges) plus a couple of spurt streaks —
  // "block pixels curving" into an organic splat. Merged to ONE mesh per splat
  // for performance. Raycasts straight down to settle on the real floor.
  createBloodPool(position) {
    _v.set(position.x, position.y + 0.6, position.z);
    this._downRay.set(_v, new THREE.Vector3(0, -1, 0));
    let gy = position.y - 1.0;
    const hits = this._downRay.intersectObjects(this.scene.children, true);
    for (const h of hits) {
      const ud = h.object.userData;
      if (ud?.noHit || ud?.zombie || !h.object.visible) continue;
      gy = h.point.y + 0.02; break;
    }

    const parts = [];
    const put = (gx, gz) => {
      const g = _bloodPixGeo.clone();
      g.translate(gx * BLOOD_PX, 0, gz * BLOOD_PX);
      parts.push(g);
    };
    // Ragged blob — denser toward the centre, frays at the edge.
    const R = 3 + ((Math.random() * 3) | 0);
    for (let gx = -R; gx <= R; gx++) {
      for (let gz = -R; gz <= R; gz++) {
        const dist = Math.hypot(gx, gz) / R;
        if (Math.random() < 1.05 - dist * 1.25) put(gx, gz);
      }
    }
    // A few flung spurt streaks (droplets trailing outward).
    const streaks = 1 + ((Math.random() * 3) | 0);
    for (let s = 0; s < streaks; s++) {
      const ang = Math.random() * Math.PI * 2, len = R + 2 + ((Math.random() * 6) | 0);
      for (let k = R; k < len; k++) {
        if (Math.random() < 0.4) continue;
        put(Math.round(Math.cos(ang) * k), Math.round(Math.sin(ang) * k));
      }
    }
    if (!parts.length) return;

    const geo = mergeGeometries(parts, false);
    parts.forEach(g => g.dispose());
    const mat = new THREE.MeshBasicMaterial({
      color: ParticleSystem.BLOOD[(Math.random()*ParticleSystem.BLOOD.length)|0],
      transparent: true, opacity: 0.95, depthWrite: false,
    });
    const mesh = new THREE.Mesh(geo, mat);
    mesh.userData.noHit = true;
    mesh.userData.noVox = true;   // already blocky — don't let blockify touch it
    mesh.position.set(position.x + (Math.random()-0.5)*0.4, gy, position.z + (Math.random()-0.5)*0.4);
    mesh.rotation.y = Math.random() * Math.PI * 2;
    this.scene.add(mesh);
    this.decals.push({ mesh, life: 22, maxLife: 22, base: 0.95 });
    // Cap total splats — retire the oldest so blood never floods the scene.
    if (this.decals.length > 40) {
      const old = this.decals.shift();
      this.scene.remove(old.mesh); old.mesh.material.dispose(); old.mesh.geometry.dispose();
    }
  }

  createSmoke(position, count = 4) {
    for (let i = 0; i < count; i++) {
      const grey = 0x777777 + Math.floor(Math.random() * 0x222222);
      const p = this._spawn(GEO.smoke, grey, position,
        _v.set((Math.random()-0.5)*1.5, 1 + Math.random()*1.5, (Math.random()-0.5)*1.5),
        2.5, 0, true, 0.5, false);
      p.scale.set(0.4, 0.4, 0.4);
      p._growing = true;
    }
  }

  createExplosion(position) {
    for (let i = 0; i < 18; i++) {
      const a = Math.random()*Math.PI*2, el = Math.random()*Math.PI, spd = 30 + Math.random()*40;
      const col = [0xff4400, 0xff8800, 0xffcc00][Math.floor(Math.random()*3)];
      this._spawn(GEO.medium, col, position,
        _v.set(Math.sin(el)*Math.cos(a)*spd, Math.abs(Math.cos(el))*spd*0.8, Math.sin(el)*Math.sin(a)*spd),
        0.4, -20, false, 1, true);
    }
    for (let i = 0; i < 8; i++) {
      const p = this._spawn(GEO.smoke, 0x555555, position,
        _v.set((Math.random()-0.5)*8, 4 + Math.random()*6, (Math.random()-0.5)*8),
        3, 0, true, 0.6, false);
      p.scale.set(0.3, 0.3, 0.3);
      p._growing = true;
    }
    for (let i = 0; i < 12; i++) {
      const a = Math.random()*Math.PI*2, spd = 15 + Math.random()*20;
      this._spawn(GEO.debris, 0x554433, position,
        _v.set(Math.cos(a)*spd, 8 + Math.random()*12, Math.sin(a)*spd),
        1.2, -18, false, 1, false);
    }
  }

  createAcid(position, count = 10) {
    for (let i = 0; i < count; i++) {
      this._spawn(GEO.small, Math.random() < 0.5 ? 0x44ff44 : 0x88ff22, position,
        _v.set((Math.random()-0.5)*4, 1 + Math.random()*3, (Math.random()-0.5)*4),
        1.5, -9.8, true, 0.85, true);
    }
    for (let i = 0; i < 6; i++) {
      const a = (i/6)*Math.PI*2;
      this._spawn(GEO.tiny, 0x22ff22, position,
        _v.set(Math.cos(a)*5, 0.5, Math.sin(a)*5),
        0.5, 0, true, 0.7, true);
    }
  }

  createScreamRing(position) {
    for (let i = 0; i < 16; i++) {
      const a = (i/16)*Math.PI*2;
      const p = this._spawn(GEO.small, 0xff6600, position,
        _v.set(Math.cos(a)*7, 0.3, Math.sin(a)*7),
        0.7, 0, true, 0.85, true);
      p.scale.set(0.5, 0.5, 0.5);
    }
    for (let i = 0; i < 8; i++) {
      const a = (i/8)*Math.PI*2 + Math.PI/8;
      this._spawn(GEO.tiny, 0xffaa00, position,
        _v.set(Math.cos(a)*4, 0.2, Math.sin(a)*4),
        0.5, 0, true, 0.6, true);
    }
  }

  createBulletImpact(position) {
    for (let i = 0; i < 6; i++) {
      const a = Math.random()*Math.PI*2, spd = 3 + Math.random()*5;
      this._spawn(GEO.spark, 0xffcc44, position,
        _v.set(Math.cos(a)*spd, 1 + Math.random()*2, Math.sin(a)*spd),
        0.25, -16, false, 1, false);
    }
    const p = this._spawn(GEO.smoke, 0xaaaaaa, position,
      _v.set((Math.random()-0.5)*2, 1, (Math.random()-0.5)*2),
      0.5, 0, true, 0.35, false);
    p.scale.set(0.15, 0.15, 0.15);
    p._growing = true;
  }

  createFireEffect(position) {
    for (let i = 0; i < 8; i++) {
      const col = [0xff2200, 0xff8800, 0xffcc00][Math.floor(Math.random()*3)];
      this._spawn(GEO.medium, col, position,
        _v.set((Math.random()-0.5)*2, 2 + Math.random()*3, (Math.random()-0.5)*2),
        0.6 + Math.random()*0.4, 0, true, 0.8, true);
    }
  }

  createLightning(position, count = 8) {
    for (let i = 0; i < count; i++) {
      const a = Math.random()*Math.PI*2, spd = 2 + Math.random()*4;
      this._spawn(GEO.spark, 0x88ccff, position,
        _v.set(Math.cos(a)*spd, 1 + Math.random()*3, Math.sin(a)*spd),
        0.3, -8, true, 0.9, false);
    }
    // Blue core flash
    this._spawn(GEO.medium, 0xaaddff, position, _v.set(0,0,0), 0.1, 0, true, 0.8);
  }

  createHeal(position) {
    for (let i = 0; i < 10; i++) {
      const a = (i/10)*Math.PI*2;
      this._spawn(GEO.tiny, 0x44ff88, position,
        _v.set(Math.cos(a)*1.5, 1.5 + Math.random()*1.5, Math.sin(a)*1.5),
        0.8, 0, true, 0.9, true);
    }
  }

  update(deltaTime) {
    for (let i = this.particles.length - 1; i >= 0; i--) {
      const p = this.particles[i];
      p.life -= deltaTime;

      if (p.life <= 0) {
        this.scene.remove(p);
        if (p._ownMat) p.material.dispose(); // cloned per-particle material
        // Swap-and-pop: O(1) removal vs O(n) splice; safe with backwards iteration
        this.particles[i] = this.particles[this.particles.length - 1];
        this.particles.pop();
        continue;
      }

      if (p.gravity) p.velocity.y += p.gravity * deltaTime;
      if (p._drag) p.velocity.multiplyScalar(Math.max(0, 1 - p._drag * deltaTime));
      p.position.addScaledVector(p.velocity, deltaTime);

      const progress = p.life / p.maxLife; // 1→0

      // Fade transparency particles
      if (p.transparent) {
        p.material.opacity = p.baseOpacity * progress;
      }

      // Grow smoke particles
      if (p._sweepGrow) {
        p.scale.set(1 + (1 - progress) * 0.35, 1 + (1 - progress) * 0.15, 1);
      } else if (p._growing) {
        const grow = 1 + (1 - progress) * 3.5;
        p.scale.setScalar(grow * 0.35);
      } else if (p.scaleDown) {
        // Frame-rate-independent scale shrink from 1→0 over particle lifetime
        p.scale.setScalar(Math.max(0.01, progress));
      }

      // Spin debris
      if (p.geometry === GEO.debris) {
        p.rotation.x += deltaTime * 4;
        p.rotation.z += deltaTime * 3;
      }
    }

    // Blood pools: hold full for a while, then dry out (darken + fade).
    for (let i = this.decals.length - 1; i >= 0; i--) {
      const d = this.decals[i];
      d.life -= deltaTime;
      if (d.life <= 0) {
        this.scene.remove(d.mesh); d.mesh.material.dispose(); d.mesh.geometry.dispose();
        this.decals[i] = this.decals[this.decals.length - 1];
        this.decals.pop();
        continue;
      }
      const f = d.life / d.maxLife;           // 1→0
      if (f < 0.4) d.mesh.material.opacity = d.base * (f / 0.4);  // fade only in last 40%
    }
  }
}
