// GuiSprites.js — original pixel-art sprites for the vanilla-style GUI and HUD.
//
// Every sprite here is drawn in code as a character pixel map and turned into
// a crisp SVG data URL (shape-rendering: crispEdges, one rect per horizontal
// run). Nothing is copied from Minecraft; the art only follows the same
// proportions and colour logic as the vanilla Java Edition GUI.

// rows: array of equal-length strings; pal: char -> css colour ('.' = clear)
export function pixSVG(rows, pal) {
  const h = rows.length, w = Math.max(...rows.map((r) => r.length));
  let r = '';
  rows.forEach((row, y) => {
    let x = 0;
    while (x < row.length) {
      const ch = row[x];
      const col = pal[ch];
      if (!col) { x++; continue; }
      let e = x + 1;
      while (e < row.length && row[e] === ch) e++;
      r += `<rect x='${x}' y='${y}' width='${e - x}' height='1' fill='${col}'/>`;
      x = e;
    }
  });
  return `<svg xmlns='http://www.w3.org/2000/svg' width='${w}' height='${h}' viewBox='0 0 ${w} ${h}' shape-rendering='crispEdges'>${r}</svg>`;
}
export const svgURL = (svg) => `url("data:image/svg+xml,${encodeURIComponent(svg)}")`;
export const pixURL = (rows, pal) => svgURL(pixSVG(rows, pal));

