// state: full|half|empty; halfSide: which half stays lit; flash: white rim;
// ghost: interior drawn white (health just lost, shown while blinking)
export function statIcon(kind, state, { halfSide = 'left', flash = false, ghost = false, variant = null } = {}) {
  const bm = ICON_MAP[kind], pal = ICON_PAL[kind], vr = kind === 'heart' && variant ? HEART_VARIANT[variant] : null;
  let r = '';
  for (let y = 0; y < 9; y++) for (let x = 0; x < 9; x++) {
    const ch = bm[y][x];
    if (ch === '.') continue;
    let col;
    if (ch === 'K') col = flash ? '#ffffff' : pal.K[0];
    else {
      let lit = state === 'full';
      if (state === 'half') lit = halfSide === 'left' ? x <= 4 : x >= 4;
      col = lit ? (vr?.[ch] ?? pal[ch][0]) : ghost ? (y < 3 && x < 3 ? '#ffffff' : '#e8e8e8') : pal[ch][1];
    }
    r += `<rect x='${x}' y='${y}' width='1' height='1' fill='${col}'/>`;
  }
  return svgURL(`<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 9 9' shape-rendering='crispEdges'>${r}</svg>`);
}

// ── Hotbar (182x22) and selector (24x24) ───────────────────────────────────
// Light stone-grey frame with a 1px black outline and a fine speckled stone
// grain; nine sunk 16x16 wells (one per 20px cell) with a heavy dark rim on
// the top/left, a lighter inner shade and a bright lip on the bottom/right,
// filled with a flat mid-grey so the bar reads the same over any terrain.
function hotbarSVG() {
  const R = (x, y, w, h, c, a = 1) => `<rect x='${x}' y='${y}' width='${w}' height='${h}' fill='${c}'${a < 1 ? ` fill-opacity='${a}'` : ''}/>`;
  let r = R(0, 0, 182, 22, '#000');
  r += R(1, 1, 180, 20, '#a9a9a9');
  // stone grain: deterministic speckles in three tones
  let h = 0x9e3779b9;
  const rnd = () => { h ^= h << 13; h >>>= 0; h ^= h >> 17; h ^= h << 5; h >>>= 0; return h / 4294967296; };
  for (let y = 1; y < 21; y++) for (let x = 1; x < 181; x++) {
    const v = rnd();
    if (v < 0.10) r += R(x, y, 1, 1, '#929292');
    else if (v < 0.16) r += R(x, y, 1, 1, '#bdbdbd');
    else if (v < 0.19) r += R(x, y, 1, 1, '#858585');
  }
  r += R(1, 1, 180, 1, '#d6d6d6') + R(1, 1, 1, 20, '#d6d6d6');     // top/left highlight
  r += R(1, 20, 180, 1, '#5e5e5e') + R(180, 1, 1, 20, '#5e5e5e');  // bottom/right shadow
  for (let i = 0; i < 9; i++) {
    const x = 3 + i * 20;
    r += R(x - 1, 2, 18, 18, '#1c1c1c');                                    // dark rim (top/left)
    r += R(x, 19, 17, 1, '#d2d2d2') + R(x + 16, 3, 1, 17, '#d2d2d2');       // bright lip (bottom/right)
    r += R(x, 3, 16, 16, '#666666');                                        // well
    r += R(x, 3, 16, 1, '#474747') + R(x, 3, 1, 16, '#474747');             // inner shade
    if (i < 8) r += R(x + 18, 1, 1, 20, '#8a8a8a');                         // cell seam
  }
  return `<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 182 22' shape-rendering='crispEdges'>${r}</svg>`;
}
// Selector: thick bright frame one pixel larger than the cell on every side
function selectorSVG() {
  const ring = (i, w, tl, br = tl, a = 1) => {
    const o = a < 1 ? ` fill-opacity='${a}'` : '';
    return `<rect x='${i}' y='${i}' width='${w}' height='1' fill='${tl}'${o}/><rect x='${i}' y='${i}' width='1' height='${w}' fill='${tl}'${o}/>`
      + `<rect x='${i}' y='${i + w - 1}' width='${w}' height='1' fill='${br}'${o}/><rect x='${i + w - 1}' y='${i}' width='1' height='${w}' fill='${br}'${o}/>`;
  };
  const r = ring(0, 24, '#000') + ring(1, 22, '#ffffff', '#f0f0f0') + ring(2, 20, '#ffffff', '#e6e6e6')
    + ring(3, 18, '#e6e6e6', '#d4d4d4') + ring(4, 16, '#000', '#000', 0.7);
  return `<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' shape-rendering='crispEdges'>${r}</svg>`;
}
// XP bar 182x5, split into 18 glossy segments with dark gaps (empty skin:
// dim segments). The full skin is clipped by width, so segments never stretch.
function xpSVG(full) {
  let r = `<rect width='182' height='5' fill='#000'/>`;
  for (let i = 0; i < 18; i++) {
    const x0 = 1 + Math.round(i * 180 / 18), x1 = 1 + Math.round((i + 1) * 180 / 18) - 1, w = x1 - x0;
    if (full) {
      r += `<rect x='${x0}' y='1' width='${w}' height='3' fill='#80ff20'/>`
        + `<rect x='${x0 + 1}' y='1' width='${w - 2}' height='1' fill='#d2ff9e'/>`
        + `<rect x='${x0}' y='3' width='${w}' height='1' fill='#4c9e0a'/>`
        + `<rect x='${x0}' y='1' width='1' height='1' fill='#5fc414'/><rect x='${x1 - 1}' y='1' width='1' height='1' fill='#5fc414'/>`;
    } else {
      r += `<rect x='${x0}' y='1' width='${w}' height='3' fill='#2b2b2b'/>`
        + `<rect x='${x0}' y='1' width='${w}' height='1' fill='#3c3c3c'/>`;
    }
  }
  return `<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 182 5' preserveAspectRatio='none' shape-rendering='crispEdges'>${r}</svg>`;
}

