const mirror = (rows) => rows.map((r) => [...r].reverse().join(''));

// 35x27 recipe-book tab (protrudes left of the book); selected tab is drawn
// 2px wider and flush with the panel
function tabSVG(selected) {
  const w = selected ? 35 : 32, h = 27;
  const rows = [];
  for (let y = 0; y < h; y++) {
    let s = '';
    for (let x = 0; x < w; x++) {
      const cornerT = y === 0 && x < 2, cornerB = y === h - 1 && x < 2;
      const cornerT2 = y === 1 && x === 0, cornerB2 = y === h - 2 && x === 0;
      if (cornerT || cornerB || cornerT2 || cornerB2) { s += '.'; continue; }
      if (y === 0 || y === h - 1 || x === 0 || (y === 1 && x === 1) || (y === h - 2 && x === 1)) { s += 'K'; continue; }
      if (y <= 2 || x <= 2) s += 'W';
      else if (y >= h - 3) s += 'S';
      else s += 'C';
    }
    rows.push(s);
  }
  return pixSVG(rows, { K: '#000000', W: selected ? '#ffffff' : '#dadada', C: selected ? '#c6c6c6' : '#a9a9a9', S: selected ? '#555555' : '#5e5e5e' });
}

