let _installed = false;
export function installGuiSprites() {
  if (_installed) return;
  _installed = true;
  const root = document.documentElement.style;
  const set = (k, v) => root.setProperty(k, v);
  set('--mc-panel', pixURL(PANEL, PANEL_PAL));
  set('--mc-btn', pixURL(BTN, PANEL_PAL));
  set('--mc-btn-hover', pixURL(BTN_HOVER, { ...PANEL_PAL, H: '#ffffff', W: '#ffffff', C: '#c6c6c6' }));
  set('--mc-wbtn', pixURL(WBTN, WBTN_PAL));
  set('--mc-wbtn-hover', pixURL(WBTN, { ...WBTN_PAL, K: '#ffffff', M: '#7a7a7a' }));
  set('--mc-wbtn-off', pixURL(WBTN, { K: '#000000', L: '#3a3a3a', M: '#2c2c2c', D: '#222222' }));
  set('--mc-wtrack', pixURL(WBTN, { K: '#000000', L: '#262626', M: '#3b3b3b', D: '#4a4a4a' }));
  set('--mc-field', pixURL(FIELD, { A: '#a0a0a0', K: '#000000' }));
  set('--mc-book-icon', pixURL(BOOK, BOOK_PAL));
  set('--mc-small-arrow', pixURL(SMALL_ARROW, { G: '#8b8b8b' }));
  set('--mc-page-next', pixURL(PAGE_ARROW, { K: '#373737', W: '#ffffff' }));
  set('--mc-page-prev', pixURL(mirror(PAGE_ARROW), { K: '#373737', W: '#ffffff' }));
  set('--mc-page-next-h', pixURL(PAGE_ARROW, { K: '#373737', W: '#a6ff8a' }));
  set('--mc-page-prev-h', pixURL(mirror(PAGE_ARROW), { K: '#373737', W: '#a6ff8a' }));
  set('--mc-tab', svgURL(tabSVG(false)));
  set('--mc-tab-sel', svgURL(tabSVG(true)));
  set('--mc-filter-off', pixURL(FILTER_ICON, { K: '#3a3a3a', C: '#9a9a9a' }));
  set('--mc-filter-on', pixURL(FILTER_ICON, { K: '#1b3b12', C: '#6fc04b' }));
  for (const [k, rows] of Object.entries(SIL)) set(`--mc-sil-${k}`, pixURL(rows, { O: '#b4b4b4' }));
  set('--mc-hotbar', svgURL(hotbarSVG()));
  set('--mc-selector', svgURL(selectorSVG()));
  set('--mc-xp-empty', svgURL(xpSVG(false)));
  set('--mc-xp-full', svgURL(xpSVG(true)));
}
