import { Pistol } from './Pistol.js';
import { Shotgun } from './Shotgun.js';
import { Rifle } from './Rifle.js';
import { SMG } from './SMG.js';
import { Sniper } from './Sniper.js';
import { Melee, pickMob } from './Melee.js';
import { Revolver } from './Revolver.js';
import { SawedOffShotgun } from './SawedOffShotgun.js';
import { MOD_GUNS } from './ModGuns.js';

const MC_TOOL_TIERS = ['wooden', 'stone', 'iron', 'gold', 'diamond', 'netherite'];
const MC_TOOL_KINDS = ['sword', 'pickaxe', 'axe', 'shovel', 'hoe'];
const MC_TIER_LABEL = { wooden: 'Wooden', stone: 'Stone', iron: 'Iron', gold: 'Golden', diamond: 'Diamond', netherite: 'Netherite' };

export class WeaponManager {
 constructor(game) {
 this.game = game;
 this.weapons = [];
 this.currentWeaponIndex = -1; // bare hands
 this.setupStartingWeapons();
 }

 setupStartingWeapons() {
 // Minecraft-style empty start — no default knife. Hands/fists only until you
 // find and pick up a weapon.
 this.currentWeaponIndex = -1;
 }

 addWeapon(weaponClass) {
 const existingIndex = this.weapons.findIndex(w => w.name === weaponClass.name);
 if (existingIndex > -1) {
 this.weapons[existingIndex].addAmmo(weaponClass.reserveAmmo);
 } else {
 this.weapons.push(weaponClass);
 }
 }

 // Vanilla attack indicator under the crosshair: a charge bar while the
 // attack meter refills, and a "ready" pip when fully charged on a mob that
 // is in reach (only for items slower than 5 ticks, like vanilla).
 _updateAttackIndicator() {
 const g = this.game;
 if (!this._atkEl) {
 const el = document.createElement('div');
 el.id = 'mc-attack-indicator';
 el.innerHTML = '<div class="mc-atk-bar"><div class="mc-atk-fill"></div></div><div class="mc-atk-ready"></div>';
 document.body.appendChild(el);
 this._atkEl = el;
 this._atkFill = el.querySelector('.mc-atk-fill');
 this._atkMode = '';
 }
 const w = this.getActiveWeapon();
 let mode = 'none', s = 1;
 const visible = g.isRunning && !g.isPaused && !g.inventorySystem?.isOpen && g.inputManager?.isPointerLocked?.()
 && !document.body.classList.contains('mc-hide-hud') && w && w.magSize <= 0 && w.attackStrength;
 if (visible) {
 s = w.attackStrength(this);
 if (s < 1) mode = 'bar';
 else if (w.attackDelay > 0.25 && g.camera) {
 const o = this._atkO ??= new g.camera.position.constructor();
 const d = this._atkD ??= new g.camera.position.constructor();
 g.camera.getWorldPosition(o); g.camera.getWorldDirection(d);
 if (pickMob(g, o, d, w.range)) mode = 'ready';
 }
 }
 if (mode !== this._atkMode) { this._atkEl.className = mode; this._atkMode = mode; }
 if (mode === 'bar') {
 const px = Math.min(16, Math.floor(s * 17)); // vanilla: (int)(strength * 17)
 if (px !== this._atkPx) { this._atkFill.style.width = `calc(var(--u) * ${px})`; this._atkPx = px; }
 }
 }

 // The weapon a left click swings right now (bare hand = fist)
 getActiveWeapon() {
 return this.getCurrentWeapon() ?? (this._fist ??= new Melee('fist'));
 }

 getCurrentWeapon() {
 return this.weapons[this.currentWeaponIndex] || null;
 }

 switchWeapon(index) {
 if (index >= 0 && index < this.weapons.length) {
 this.currentWeaponIndex = index;
 return true;
 }
 return false;
 }

 switchToNextWeapon() {
 if (this.weapons.length === 0) return;
 this.currentWeaponIndex = (this.currentWeaponIndex + 1) % this.weapons.length;
 }

 switchToPreviousWeapon() {
 if (this.weapons.length === 0) return;
 this.currentWeaponIndex = (this.currentWeaponIndex - 1 + this.weapons.length) % this.weapons.length;
 }

 fireCurrentWeapon(position, direction) {
 // Empty hand punches (vanilla: 1 damage, 3-block reach)
 const weapon = this.getCurrentWeapon() ?? (this._fist ??= new Melee('fist'));
 if (weapon) {
 return weapon.fire(position, direction, this.game);
 }
 return false;
 }

 reloadCurrentWeapon() {
 const weapon = this.getCurrentWeapon();
 if (weapon) {
 return weapon.reload(this.game);
 }
 return false;
 }

 update(deltaTime) {
 this.weapons.forEach(weapon => weapon.update(deltaTime));
 this.clock = (this.clock ?? 0) + deltaTime;
 this.attackTicker = (this.attackTicker ?? 99) + deltaTime; // vanilla attackStrengthTicker
 this._fist?.update(deltaTime);   // bare hand isn't in the list but needs its cooldown
 this.updateAmmoDisplay();
 this.updateWeaponHUD();
 this._updateAttackIndicator();

 // Auto-reload when magazine is empty (skip melee)
 const weapon = this.getCurrentWeapon();
 if (weapon && weapon.magSize > 0 && weapon.ammoInMag === 0 && !weapon.isReloading && weapon.reserveAmmo > 0) {
 weapon.reload(this.game);
 }
 }

 updateAmmoDisplay() {
 const weapon = this.getCurrentWeapon();
 if (!this._ammoDisplayEl) this._ammoDisplayEl = document.getElementById('ammo-display');
 if (!this._ammoCounterEl) this._ammoCounterEl = document.getElementById('ammo-counter');
 if (!this._weaponNameEl) this._weaponNameEl = document.getElementById('weapon-name-display');
 if (!this._reloadContEl) this._reloadContEl = document.getElementById('reload-bar-container');
 if (!this._reloadBarEl) this._reloadBarEl = document.getElementById('reload-bar');
 const ammoDisplay = this._ammoDisplayEl;
 const ammoCounter = this._ammoCounterEl;
 const weaponNameEl = this._weaponNameEl;
 const reloadContainer = this._reloadContEl;
 const reloadBar = this._reloadBarEl;

 if (!ammoDisplay || !weapon) return;

 if (weaponNameEl) weaponNameEl.textContent = weapon.name;

 const isMelee = weapon.magSize <= 0;

 if (isMelee) {
 ammoDisplay.classList.remove('active');
 ammoDisplay.style.opacity = '0';
 if (reloadContainer) reloadContainer.style.display = 'none';
 } else {
 const magAmmo = weapon.ammoInMag || 0;
 const reserveAmmo = weapon.reserveAmmo || 0;
 if (ammoCounter) {
 ammoCounter.textContent = `${magAmmo} / ${reserveAmmo}`;
 const magSize = weapon.magSize || 1;
 const magPct = magAmmo / magSize;
 ammoCounter.classList.toggle('low-ammo', magPct <= 0.30 && magPct > 0.10);
 ammoCounter.classList.toggle('critical-ammo', magPct <= 0.10);
 }
 ammoDisplay.classList.add('active');
 ammoDisplay.style.opacity = '1';

 if (reloadContainer && reloadBar) {
 if (weapon.isReloading) {
 reloadContainer.style.display = 'block';
 reloadBar.style.width = `${(weapon.reloadProgress || 0) * 100}%`;
 } else {
 reloadContainer.style.display = 'none';
 }
 }
 }
 }

 // Feed reserve ammo to the matching weapon(s) when ammo is picked up
 feedAmmoFromPickup(ammoItemType, qty) {
 const ammoMap = {
 ammo_9mm: ['Pistol', 'SMG', 'MP5', 'Vector'],
 ammo_45acp: ['Pistol', 'Revolver', 'Desert Eagle'],
 ammo_357: ['Revolver'],
 ammo_556: ['Assault Rifle', 'M4 Carbine', 'Minigun'],
 ammo_762: ['Assault Rifle', 'AK-47', 'M249 SAW', 'Marksman Rifle'],
 ammo_308: ['Sniper Rifle', 'Marksman Rifle'],
 ammo_50cal: ['Sniper Rifle', 'Barrett M82'],
 ammo_12gauge_buck: ['Shotgun', 'AA-12 Auto Shotgun'],
 ammo_12gauge_slug: ['Shotgun', 'AA-12 Auto Shotgun'],
 ammo_rockets: ['RPG-7', 'Grenade Launcher'],
 ammo_fuel: ['Flamethrower'],
 ammo_pistol: ['Pistol'],
 ammo_rifle: ['Assault Rifle'],
 };
 const targets = ammoMap[ammoItemType];
 if (!targets) return false;
 let fed = false;
 for (const weapon of this.weapons) {
 if (targets.includes(weapon.name)) {
 weapon.addAmmo(qty);
 fed = true;
 }
 }
 return fed;
 }

 // Item type -> weapon factory (null if the item isn't a weapon)
 factoryFor(itemType) {
 const map = {
 weapon_pistol_found: () => new Pistol(),
 weapon_rifle_found: () => new Rifle(),
 weapon_shotgun_found: () => new Shotgun(),
 weapon_smg_found: () => new SMG(),
 weapon_sniper_found: () => new Sniper(),
 weapon_baseball_bat: () => new Melee('bat'),
 weapon_crowbar: () => new Melee('crowbar'),
 weapon_machete: () => new Melee('machete'),
 weapon_axe: () => new Melee('axe'),
 weapon_kitchen_knife: () => new Melee('kitchen_knife'),
 weapon_fire_poker: () => new Melee('fire_poker'),
 weapon_pipe: () => new Melee('pipe'),
 weapon_crossbow: () => new Melee('crossbow'),
 weapon_golf_club: () => new Melee('golf_club'),
 weapon_sledgehammer: () => new Melee('sledgehammer'),
 weapon_meat_cleaver: () => new Melee('meat_cleaver'),
 weapon_flare_gun: () => new Pistol(),
 weapon_nail_bat: () => new Melee('nail_bat'),
 weapon_slingshot: () => new Melee('slingshot'),
 weapon_electric_baton: () => new Melee('electric_baton'),
 weapon_compound_bow: () => new Melee('compound_bow'),
 elec_stun_baton: () => new Melee('stun_baton'),
 weapon_revolver: () => new Revolver(),
 weapon_sawed_off: () => new SawedOffShotgun(),
 weapon_wooden_sword: () => new Melee('wooden_sword'),
 weapon_stone_sword: () => new Melee('stone_sword'),
 weapon_iron_sword: () => new Melee('iron_sword'),
 weapon_gold_sword: () => new Melee('gold_sword'),
 weapon_diamond_sword: () => new Melee('diamond_sword'),
 weapon_diamond_rapier: () => new Melee('diamond_rapier'),
 weapon_netherite_sword: () => new Melee('netherite_sword'),
 weapon_wooden_pickaxe: () => new Melee('wooden_pickaxe'),
 weapon_stone_pickaxe: () => new Melee('stone_pickaxe'),
 weapon_iron_pickaxe: () => new Melee('iron_pickaxe'),
 weapon_diamond_pickaxe: () => new Melee('diamond_pickaxe'),
 };
 // Full Minecraft tool set: weapon_{tier}_{sword|pickaxe|axe|shovel|hoe}
 for (const tier of MC_TOOL_TIERS) for (const kind of MC_TOOL_KINDS) {
 const id = `weapon_${tier}_${kind}`;
 map[id] ??= () => new Melee(`${tier}_${kind}`);
 }
 // Merge in the expanded mod-gun arsenal (AK-47, RPG, flamethrower, …).
 for (const [type, def] of Object.entries(MOD_GUNS)) map[type] = def.make;
 return map[itemType] ?? null;
 }

 // Minecraft: the weapon in your hand IS the item in the selected hotbar
 // slot. One persistent instance per item type (keeps its ammo/state).
 _instanceFor(itemType) {
 this._byItem ??= {};
 if (this._byItem[itemType]) return this._byItem[itemType];
 const factory = this.factoryFor(itemType);
 if (!factory) return null;
 const w = factory();
 w.itemType = itemType;
 this.weapons.push(w);
 this._byItem[itemType] = w;
 return w;
 }

 holdItem(itemType) {
 const w = itemType ? this._instanceFor(itemType) : null;
 this.currentWeaponIndex = w ? this.weapons.indexOf(w) : -1; // -1 = bare hands
 }

 // Called when a weapon item enters the inventory (pickup / craft / give).
 // The item itself lives in the inventory; this just readies the instance
 // so ammo can feed into it, and re-syncs what's in your hand.
 grantWeaponFromPickup(itemType) {
 if (!this._instanceFor(itemType)) return false;
 this.game.inventorySystem?._syncHeld?.(true);
 // Notify player
 if (!this._notifEl) this._notifEl = document.getElementById('loot-notification');
 const notif = this._notifEl;
 if (notif) {
 const names = {
 weapon_pistol_found:'Pistol equipped!', weapon_rifle_found:'Rifle equipped!',
 weapon_shotgun_found:'Shotgun equipped!', weapon_smg_found:'SMG equipped!',
 weapon_sniper_found:'Sniper equipped!', weapon_baseball_bat:'Baseball Bat equipped!',
 weapon_crowbar:'Crowbar equipped!', weapon_machete:' Machete equipped!',
 weapon_axe:'Axe equipped!', weapon_kitchen_knife:'Knife equipped!',
 weapon_fire_poker:'Fire Poker equipped!', weapon_pipe:'Pipe equipped!',
 weapon_crossbow:'Crossbow equipped!', weapon_golf_club:'Golf Club equipped!',
 weapon_sledgehammer:'Sledgehammer equipped!', weapon_meat_cleaver:'Cleaver equipped!',
 weapon_flare_gun:'Flare Gun equipped!', weapon_nail_bat:'Spiked Bat equipped!',
 weapon_slingshot:'Slingshot equipped!', weapon_electric_baton:'Electric Baton equipped!',
 weapon_compound_bow:'Compound Bow equipped!', elec_stun_baton:'Stun Baton equipped!',
 weapon_revolver:'Revolver equipped!', weapon_sawed_off:'Sawed-Off equipped!',
 weapon_wooden_sword:'Wooden Sword equipped!', weapon_stone_sword:'Stone Sword equipped!',
 weapon_iron_sword:'Iron Sword equipped!', weapon_gold_sword:'Golden Sword equipped!',
 weapon_diamond_sword:'Diamond Sword equipped!', weapon_diamond_rapier:'Diamond Rapier equipped!',
 weapon_netherite_sword:'Netherite Sword equipped!',
 weapon_wooden_pickaxe:'Wooden Pickaxe equipped!', weapon_stone_pickaxe:'Stone Pickaxe equipped!',
 weapon_iron_pickaxe:'Iron Pickaxe equipped!', weapon_diamond_pickaxe:'Diamond Pickaxe equipped!',
 };
 for (const tier of MC_TOOL_TIERS) for (const kind of MC_TOOL_KINDS) {
 const id = `weapon_${tier}_${kind}`;
 names[id] ??= `${MC_TIER_LABEL[tier]} ${kind[0].toUpperCase() + kind.slice(1)} equipped!`;
 }
 for (const [type, def] of Object.entries(MOD_GUNS)) names[type] = `${def.label} equipped!`;
 notif.textContent = names[itemType] ?? ' Weapon equipped!';
 notif.style.color = '#4499ff';
 notif.classList.remove('show'); void notif.offsetWidth; notif.classList.add('show');
 }
 // Pulse the weapon name display
 if (!this._weaponNameEl) this._weaponNameEl = document.getElementById('weapon-name-display');
 if (this._weaponNameEl) {
 this._weaponNameEl.classList.remove('equip-flash');
 void this._weaponNameEl.offsetWidth;
 this._weaponNameEl.classList.add('equip-flash');
 setTimeout(() => this._weaponNameEl?.classList.remove('equip-flash'), 650);
 }
 return true;
 }

 updateWeaponHUD() {
 if (!this._weaponHudEl) this._weaponHudEl = document.getElementById('weapon-hud');
 const container = this._weaponHudEl;
 if (!container) return;

 // Throttle full rebuild to ~10 Hz so ammo counters stay fresh without DOM spam
 const now = performance.now();
 if (this._hudLastRebuild && now - this._hudLastRebuild < 100) return;
 this._hudLastRebuild = now;

 container.innerHTML = '';
 const show = Math.min(this.weapons.length, 9);
 for (let i = 0; i < show; i++) {
 const w = this.weapons[i];
 const slot = document.createElement('div');
 slot.className = 'weapon-hud-slot' + (i === this.currentWeaponIndex ? ' active' : '');

 const keyLabel = document.createElement('div');
 keyLabel.className = 'whs-key';
 keyLabel.textContent = i + 1;

 const isMelee = w.magSize <= 0;
 const icon = document.createElement('div');
 icon.textContent = isMelee ? '' : '';
 icon.style.fontSize = '18px';

 const name = document.createElement('div');
 name.className = 'whs-name';
 name.textContent = w.name;

 slot.appendChild(keyLabel);
 slot.appendChild(icon);
 slot.appendChild(name);

 if (!isMelee) {
 const ammoEl = document.createElement('div');
 ammoEl.className = 'whs-ammo';
 ammoEl.textContent = `${w.ammoInMag}/${w.reserveAmmo}`;
 slot.appendChild(ammoEl);
 }

 container.appendChild(slot);
 }
 }

 getWeapons() {
 return this.weapons;
 }

 getWeaponCount() {
 return this.weapons.length;
 }
}
