import { ZombieBase } from './ZombieBase.js';
import { buildBug } from './ParasiteForms.js';

export class Crawler extends ZombieBase {
  constructor(x, z, game) {
    super(x, z, game, {
      type: 'crawler',
      health: 25,
      damage: 12,
      speed: 4,
      attackRange: 1.5,
      aggroRange: 30,
      attackCooldown: 1.2
    });
  }

  createMesh() {
    // Primitive skitterer: a flat segmented carapace bug on six thin jointed
    // legs (tripod gait), clacking bone mandibles, eye cluster, whip tendrils.
    const { group, root } = buildBug(this, { pal: 'crimson' });
    this._root = root;
    this.finalizeMesh(group);
  }

  // Shrink the visual body while keeping it resting on the ground plane
  // (local y = -0.9). Used by Splitter for its mini spawns.
  setMeshScale(s) {
    const root = this._root;
    if (!root) return;
    root.scale.multiplyScalar(s);
    root.position.y = -0.9 + (root.position.y + 0.9) * s;
    this.headshotY = -0.9 + (this.headshotY + 0.9) * s;
    this._healthBarHeight = -0.9 + (this._healthBarHeight + 0.9) * s;
    this._colH = Math.max(0.4, this._colH * s);
    this._colHW = Math.max(0.2, this._colHW * s);
  }
}
