import * as THREE from 'three';
import { BLOCK } from './Blocks.js';

export class BuildingGenerator {
  constructor(game, terrainGenerator, furnitureGenerator = null) {
    this.game = game;
    this.terrainGenerator = terrainGenerator;
    this.furnitureGenerator = furnitureGenerator;
    this.buildings = [];
  }

  findBuildingSites(chunkX, chunkZ, chunkSize, segmentsPerChunk) {
    const sites = [];
    const minFlatness = 0.5;
    const gridSize = 16;

    for (let gx = 0; gx < gridSize; gx++) {
      for (let gz = 0; gz < gridSize; gz++) {
        const cx = chunkX * chunkSize + (gx / gridSize) * chunkSize;
        const cz = chunkZ * chunkSize + (gz / gridSize) * chunkSize;

        const flatness = this.calculateFlatness(cx, cz, 8);

        if (flatness > minFlatness) {
          sites.push({
            x: cx,
            z: cz,
            flatness: flatness,
            biome: this.terrainGenerator.getBiome(cx, cz)
          });
        }
      }
    }

    return sites;
  }

  calculateFlatness(cx, cz, radius) {
    const center = this.terrainGenerator.getHeight(cx, cz);
    let differences = 0;

    for (let i = 0; i < 8; i++) {
      const angle = (i / 8) * Math.PI * 2;
      const px = cx + Math.cos(angle) * radius;
      const pz = cz + Math.sin(angle) * radius;
      const height = this.terrainGenerator.getHeight(px, pz);
      differences += Math.abs(height - center);
    }

    const avgDiff = differences / 8;
    return Math.max(0, 1 - avgDiff / 3);
  }

  generateBuildingsForChunk(chunkX, chunkZ, chunkSize, segmentsPerChunk) {
    const sites = this.findBuildingSites(chunkX, chunkZ, chunkSize, segmentsPerChunk);
    const buildingsToGenerate = Math.floor(sites.length * 0.15);

    // Exclude the house safe zone so buildings never spawn near the player's exit point.
    // Safe zone: |x| < 55, -30 < z < 85  (flat zone ±15 units buffer for building size)
    const SAFE_X = 55, SAFE_ZN = -30, SAFE_ZF = 85;

    const placedSites = [];
    const MIN_SPACING = 20; // prevent buildings from overlapping each other

    const candidateSites = sites
      .filter(s => Math.abs(s.x) >= SAFE_X || s.z <= SAFE_ZN || s.z >= SAFE_ZF)
      .sort((a, b) => b.flatness - a.flatness);

    for (const site of candidateSites) {
      if (placedSites.length >= buildingsToGenerate) break;
      // Skip if too close to an already-placed building
      const tooClose = placedSites.some(p => {
        const dx = p.x - site.x, dz = p.z - site.z;
        return dx * dx + dz * dz < MIN_SPACING * MIN_SPACING;
      });
      if (!tooClose) placedSites.push(site);
    }

    placedSites.forEach(site => this.createBuilding(site));
  }

  createBuilding(site) {
    const biomeType = site.biome;
    const buildingTypes = this.getBuildingTypesForBiome(biomeType);
    const buildingType = buildingTypes[Math.floor(Math.random() * buildingTypes.length)];

    // Minecraft houses live on the block grid: odd outer sizes so the door
    // and ridge sit on a centre block.
    const W = 7 + 2 * Math.floor(Math.random() * 3);   // 7, 9, 11
    const D = 7 + 2 * Math.floor(Math.random() * 2);   // 7, 9
    const H = 4;                                        // wall height in blocks
    const bx0 = Math.floor(site.x - W / 2), bz0 = Math.floor(site.z - D / 2);

    // Floor sits on the highest column of the footprint; lower columns get a
    // cobblestone foundation filled down to the ground.
    const tg = this.terrainGenerator;
    let F = -Infinity;
    for (let x = 0; x < W; x++) for (let z = 0; z < D; z++) F = Math.max(F, tg.getHeightAt(bx0 + x + 0.5, bz0 + z + 0.5));
    if (!isFinite(F)) return;

    // Skip sites that overlap an existing structure
    if (this.buildings.some(b => b.bx0 < bx0 + W + 2 && bx0 < b.bx0 + b.W + 2 && b.bz0 < bz0 + D + 2 && bz0 < b.bz0 + b.D + 2)) return;

    const building = {
      x: bx0 + W / 2,
      z: bz0 + D / 2,
      y: F + 1,               // top of the floor blocks
      type: buildingType,
      width: W, depth: D, height: H,
      floors: 1,
      bx0, bz0, W, D, F,
      mesh: null,
      physicsBody: null
    };

    this.buildBuilding(building);
    this.buildings.push(building);
  }

  // Block palette per building type (original grim survival variants)
  _palette(type) {
    const P = {
      oak:    { wall: 'oak_planks', base: 'cobblestone', roof: 'dark_oak_planks', gable: 'oak_planks', corner: 'log' },
      spruce: { wall: 'spruce_planks', base: 'cobblestone', roof: 'dark_oak_planks', gable: 'spruce_planks', corner: 'log' },
      stone:  { wall: 'stone_bricks', base: 'cobblestone', roof: 'spruce_planks', gable: 'stone_bricks', corner: 'stone_bricks' },
      cobble: { wall: 'cobblestone', base: 'cobblestone', roof: 'oak_planks', gable: 'oak_planks', corner: 'log' },
      swamp:  { wall: 'dark_oak_planks', base: 'mossy_cobblestone', roof: 'spruce_planks', gable: 'dark_oak_planks', corner: 'log' },
      bloody: { wall: 'bloody_planks', base: 'mossy_cobblestone', roof: 'dark_oak_planks', gable: 'bloody_planks', corner: 'log' },
    };
    const byType = {
      farmhouse: 'oak', barn: 'oak', stable: 'oak', cabin: 'spruce', ranger_station: 'spruce', lodge: 'spruce',
      shelter: 'stone', watchtower: 'stone', gas_station: 'cobble', motel: 'cobble', store: 'cobble',
      shack: 'swamp', trading_post: 'swamp',
    };
    return P[Math.random() < 0.12 ? 'bloody' : (byType[type] || 'oak')];
  }

  buildBuilding(building) {
    const { bx0, bz0, W, D, F, height: H } = building;
    const tg = this.terrainGenerator;
    const pal = this._palette(building.type);
    const LOG = 'oak_log';
    const vox = new Map();
    const put = (x, y, z, b) => vox.set(x + ',' + y + ',' + z, b);
    // Apocalypse wear: occasional mossy / cracked swaps
    const worn = (b) => {
      if (b === 'cobblestone' && Math.random() < 0.25) return 'mossy_cobblestone';
      if (b === 'stone_bricks') { const r = Math.random(); return r < 0.18 ? 'mossy_stone_bricks' : r < 0.32 ? 'cracked_stone_bricks' : b; }
      if (b === 'oak_planks' && Math.random() < 0.04) return 'bloody_planks';
      return b;
    };

    // Foundation + floor (local y = 0 is the floor block layer at world F)
    for (let x = 0; x < W; x++) for (let z = 0; z < D; z++) {
      const h = tg.getHeightAt(bx0 + x + 0.5, bz0 + z + 0.5);
      for (let y = h - F; y < 0; y++) put(x, y, z, worn(pal.base));
      const edge = x === 0 || z === 0 || x === W - 1 || z === D - 1;
      put(x, 0, z, edge ? worn(pal.base) : pal.wall.includes('planks') ? pal.wall : 'oak_planks');
    }

    // Walls
    const doorX = (W - 1) / 2;
    for (let y = 1; y <= H; y++) {
      for (let x = 0; x < W; x++) for (let z = 0; z < D; z++) {
        const ex = x === 0 || x === W - 1, ez = z === 0 || z === D - 1;
        if (!ex && !ez) continue;
        if (ex && ez) { put(x, y, z, pal.corner === 'log' ? LOG : worn(pal.corner)); continue; }
        if (z === 0 && x === doorX && y <= 2) continue;                    // doorway
        const along = ez ? x : z, len = ez ? W : D;
        const isWindow = (y === 2 || y === 3) && along % 2 === 0 && along > 1 && along < len - 2
          && !(z === 0 && Math.abs(x - doorX) < 2);
        if (isWindow) { if (Math.random() < 0.8) put(x, y, z, 'glass'); continue; } // some panes smashed
        put(x, y, z, y === 1 && pal.wall.includes('planks') ? worn(pal.base) : worn(pal.wall));
      }
    }
    // Cobblestone steps down from the doorway when the floor is raised
    for (let k = 1; k <= 6; k++) {
      const top = 1 - k;                                   // step top (local)
      const h = tg.getHeightAt(bx0 + doorX + 0.5, bz0 - k + 0.5) - F;
      if (h >= top) break;
      for (let y = h; y < top; y++) put(doorX, y, -k, worn('cobblestone'));
    }
    // Lintel logs over the doorway frame
    put(doorX - 1, 3, 0, LOG); put(doorX + 1, 3, 0, LOG);

    // Stepped gable roof running along X, overhanging by one block
    for (let k = 0; ; k++) {
      const zl = -1 + k, zr = D - k, y = H + 1 + k;
      if (zl > zr) break;
      for (let x = -1; x <= W; x++) {
        if (Math.random() < 0.03 && k > 0) continue;                      // a few holes
        put(x, y, zl, pal.roof); put(x, y, zr, pal.roof);
      }
      if (zl === zr) break;
      for (let z = zl + 1; z <= zr - 1; z++) { put(0, y, z, worn(pal.gable)); put(W - 1, y, z, worn(pal.gable)); }
    }

    // Hollow interior: clear terrain / plants / tree parts inside the walls
    for (let x = 1; x < W - 1; x++) for (let z = 1; z < D - 1; z++)
      for (let y = 1; y <= H + 6; y++) if (!vox.has(x + ',' + y + ',' + z)) vox.set(x + ',' + y + ',' + z, null);
    // Clear the doorway + a block in front of it
    for (let y = 1; y <= 2; y++) { vox.set(doorX + ',' + y + ',0', null); if (!vox.has(doorX + ',' + y + ',-1')) vox.set(doorX + ',' + y + ',-1', null); }

    // Furniture: crafting table, furnace and a loot chest on the back wall
    const backZ = D - 2;
    vox.set('1,1,' + backZ, 'crafting_table');
    vox.set('2,1,' + backZ, 'furnace');
    const chestX = W - 2;
    vox.set(chestX + ',1,' + backZ, 'chest');

    const vw = this.game.voxelWorld;
    building.voxKeys = [];
    for (const [key, name] of vox) {
      const [x, y, z] = key.split(',').map(Number);
      const wx = bx0 + x, wy = F + y, wz = bz0 + z;
      const id = name ? (BLOCK[name] ?? BLOCK.oak_planks) : 0;
      const front = name === 'furnace' || name === 'chest' || name === 'crafting_table' ? 2 : undefined;
      vw?.setBlock(wx, wy, wz, id, front);
      if (name) building.voxKeys.push(wx + ',' + wy + ',' + wz);
    }
    const ck = (bx0 + chestX) + ',' + (F + 1) + ',' + (bz0 + backZ);
    building.chestKey = ck;
    this.game.containerSystem?.registerLootChest?.(ck, building.type);
  }

  getBuildingTypesForBiome(biome) {
    const types = {
      plains: ['farmhouse', 'barn', 'stable'],
      forest: ['cabin', 'ranger_station', 'lodge'],
      mountain: ['shelter', 'watchtower'],
      desert: ['gas_station', 'motel', 'store'],
      swamp: ['shack', 'trading_post']
    };

    return types[biome] || types.plains;
  }

  getBuildings() {
    return this.buildings;
  }

  clear() {
    this.buildings.forEach(building => {
      if (building.mesh) {
        this.game.scene.removeObject(building.mesh);
      }
      if (building.physicsBody) {
        this.game.physicsWorld.removeBody(building.physicsBody);
      }
    });
    this.buildings = [];
  }
}
