import * as THREE from 'three';
import { PX, PARA_UV, HUMANOID_UV, sharedBox, getParasiteSkin, mobMaterial } from './MobSkin.js';

// ---------------------------------------------------------------------------
// Parasite forms — original "assimilated / pure parasite" mob designs built
// from many small textured cuboids (mod-model style) on the parasite atlas.
//
// Every builder returns a THREE.Group whose local origin is the physics body
// centre (feet at y = -0.9) and wires the animation hooks ZombieBase expects:
//   _leftArm/_rightArm/_leftLeg/_rightLeg  swing pivots (or null when the form
//                                          has none — the base walk guards null)
//   _torsoGroup/_torsoBaseRotX            optional lurch pivot
//   headshotY, _colH, _colHW              head height + block-collision box
// Procedural animation is registered with z._addAnim(fn(dt, t, speed)).
// ---------------------------------------------------------------------------

const P = PX;

/** Builder kit for one flesh palette: per-instance material + shared geometry. */
export function makeKit(pal = 'crimson', eyeHex = null, eyeI = 1.0) {
  const skin = getParasiteSkin(pal);
  const mat = mobMaterial(skin, eyeHex ?? skin.eyeHex, eyeI);
  const box = (key, parent, x = 0, y = 0, z = 0, o = {}) => {
    const b = PARA_UV[key];
    const m = new THREE.Mesh(sharedBox(b.w, b.h, b.d, b.u, b.v, o), o.mat ?? mat);
    m.position.set(x, y, z);
    if (o.rot) m.rotation.set(o.rot[0], o.rot[1], o.rot[2]);
    if (o.s) m.scale.setScalar(o.s);
    m.castShadow = o.shadow !== false; m.receiveShadow = true;
    m.userData.noVox = true;
    parent.add(m);
    return m;
  };
  const pivot = (parent, x = 0, y = 0, z = 0, rot = null) => {
    const g = new THREE.Group();
    g.position.set(x, y, z);
    if (rot) g.rotation.set(rot[0], rot[1], rot[2]);
    parent.add(g);
    return g;
  };
  return { mat, skin, box, pivot };
}

// ---------------------------------------------------------------------------
// Shared parts + animation helpers
// ---------------------------------------------------------------------------

/** A tapering chain of tendril segments growing along local +y. Returns the pivots. */
export function tendril(kit, parent, pos, rot, segs = 3, o = {}) {
  const sy = o.sy ?? 0.8, sx = o.sx ?? 1;
  const L = 6 * P * sy;
  const chain = [];
  let p = kit.pivot(parent, pos[0], pos[1], pos[2], rot);
  for (let i = 0; i < segs; i++) {
    if (i > 0) p = kit.pivot(p, 0, L, 0, [o.curl ?? 0.28, 0, 0]);
    const t = Math.pow(0.8, i);
    kit.box('tendril', p, 0, 0, 0, { pivot: [0, -0.5, 0], sx: sx * t, sz: sx * t, sy, shadow: false });
    p.userData.base = p.rotation.clone();
    chain.push(p);
  }
  return chain;
}

/** Sinuous sway for tendril chains (each segment lags the previous one). */
export function addSway(z, chain, amp = 0.25, freq = 2.2) {
  const ph = Math.random() * 10;
  for (const p of chain) if (!p.userData.base) p.userData.base = p.rotation.clone();
  z._addAnim((dt, t, sp) => {
    const k = 1 + Math.min(sp, 6) * 0.08;
    for (let i = 0; i < chain.length; i++) {
      const p = chain[i], b = p.userData.base;
      p.rotation.x = b.x + Math.sin(t * freq * k + ph + i * 0.9) * amp * (0.6 + i * 0.35);
      p.rotation.z = b.z + Math.cos(t * freq * 0.8 + ph * 1.3 + i * 1.1) * amp * 0.7 * (0.6 + i * 0.35);
    }
  });
}

/**
 * Twitchy parasite jerks: every so often snap obj to a random offset for a
 * few frames, layered on top of whatever pose it has (delta-based, so other
 * code may keep setting the pose).
 */
export function addTwitch(z, obj, amp = 0.3, every = 1.6) {
  let next = Math.random() * every, hold = 0;
  const off = new THREE.Vector3(), cur = new THREE.Vector3();
  z._addAnim((dt) => {
    next -= dt;
    if (next <= 0) {
      next = every * (0.4 + Math.random());
      hold = 0.08 + Math.random() * 0.14;
      off.set((Math.random() - 0.5) * amp, (Math.random() - 0.5) * amp * 1.4, (Math.random() - 0.5) * amp);
    }
    hold -= dt;
    const tx = hold > 0 ? off.x : 0, ty = hold > 0 ? off.y : 0, tz = hold > 0 ? off.z : 0;
    // jerk in fast, ease back out
    const k = hold > 0 ? 0.7 : 0.18;
    const nx = cur.x + (tx - cur.x) * k, ny = cur.y + (ty - cur.y) * k, nz = cur.z + (tz - cur.z) * k;
    obj.rotation.x += nx - cur.x; obj.rotation.y += ny - cur.y; obj.rotation.z += nz - cur.z;
    cur.set(nx, ny, nz);
  });
}

/** Breathing / pulsing scale for sacs and swollen parts. */
export function addPulse(z, meshes, amp = 0.08, freq = 3) {
  const ph = Math.random() * 6;
  const items = meshes.map((m, i) => ({ m, b: m.scale.clone(), p: i * 1.3 }));
  z._addAnim((dt, t) => {
    for (const { m, b, p } of items) {
      const s = 1 + Math.sin(t * freq + ph + p) * amp;
      m.scale.set(b.x * s, b.y * (2 - s), b.z * s);
    }
  });
}

/** Ring of mouth petals around local +y of a flower pivot; inner faces are toothed. */
export function petalFlower(kit, parent, n, radius, pos, rot, o = {}) {
  const flower = kit.pivot(parent, pos[0], pos[1], pos[2], rot);
  const petals = [];
  for (let i = 0; i < n; i++) {
    const a = (i / n) * Math.PI * 2 + (o.phase ?? 0);
    const yaw = kit.pivot(flower, Math.sin(a) * radius, 0, Math.cos(a) * radius, [0, a + Math.PI, 0]);
    const tilt = kit.pivot(yaw);
    kit.box('petal', tilt, 0, 0, 0, { pivot: [0, -0.5, 0.5], sx: o.sx ?? 1, sy: o.sy ?? 1, mat: o.mat });
    petals.push(tilt);
  }
  return { flower, petals };
}

/** Animate petals opening/closing; more when the mob is attacking. */
export function addBloom(z, petals, min = 0.35, max = 1.15, freq = 2) {
  const ph = Math.random() * 6;
  let open = min;
  z._addAnim((dt, t) => {
    const atk = z.state === 'attacking' ? 1 : 0;
    const target = min + (max - min) * (atk ? 0.75 + Math.sin(t * 9) * 0.25 : 0.25 + Math.sin(t * freq + ph) * 0.25);
    open += (target - open) * Math.min(1, dt * 8);
    for (let i = 0; i < petals.length; i++) petals[i].rotation.x = -(open + Math.sin(t * 7 + i * 2.1) * 0.04);
  });
}

/** Mandible clack: rotate a pair of claws toward/away from each other around y. */
function addClack(z, pair, amp = 0.35, freq = 7) {
  const base = pair.map(p => p.rotation.y);
  z._addAnim((dt, t) => {
    const atk = z.state === 'attacking' ? 1.8 : 1;
    const s = Math.max(0, Math.sin(t * freq * atk)) * amp;
    pair[0].rotation.y = base[0] + s;
    pair[1].rotation.y = base[1] - s;
  });
}

/** Jaw chatter around a base angle (rotation.x opens). */
function addChatter(z, jaw, amp = 0.15, freq = 5) {
  const base = jaw.rotation.x;
  z._addAnim((dt, t) => {
    const atk = z.state === 'attacking' ? 2.2 : 1;
    jaw.rotation.x = base + Math.abs(Math.sin(t * freq * atk)) * amp * atk;
  });
}

// ---------------------------------------------------------------------------
// Assimilated host decorations (applied to buildHumanoid output)
// ---------------------------------------------------------------------------
export function decorateHost(z, refs, ex = {}, o = {}) {
  const bulk = o.bulk ?? 1;
  const kit = makeKit(ex.pal ?? 'crimson', o.eyeHex ?? null, 1.0);
  refs.kit = kit;
  const T = refs.torsoGroup, H = refs.headGroup;

  if (ex.tendrils) {
    const n = ex.tendrils;
    for (let i = 0; i < n; i++) {
      const c = i - (n - 1) / 2;
      const chain = tendril(kit, T, [c * 2.3 * P * bulk, (8.4 + (i % 2)) * P, -2.1 * P * bulk],
        [-1.0 - Math.random() * 0.35, 0, c * 0.5 + (Math.random() - 0.5) * 0.2], 3, { sy: 0.75, curl: -0.3 });
      addSway(z, chain, 0.22, 2 + Math.random());
    }
  }
  if (ex.splitJaw) {
    const pair = [-1, 1].map(s => {
      const pv = kit.pivot(H, s * 4.2 * P, 2.4 * P, 2.6 * P, [-0.35, s * 0.25, s * 0.15]);
      kit.box('claw', pv, 0, 0, 0, { pivot: [0, 0.5, 0], sx: 1, sy: 1.2 });
      return pv;
    });
    addClack(z, pair, 0.3, 6);
  }
  if (ex.shoulderMass) {
    kit.box('eye', T, -4.6 * P * bulk, 10.8 * P, 1.2 * P, { s: 0.9 });
    kit.box('eye', T, -3.0 * P * bulk, 11.6 * P, -0.4 * P, { s: 0.7, rot: [0.4, 0.6, 0] });
    kit.box('spike', T, -4.2 * P * bulk, 12.2 * P, -1 * P, { rot: [-0.3, 0, 0.5], pivot: [0, -0.5, 0] });
  }
  if (ex.blade) {
    for (const side of ex.blade) {
      const arm = side === 'L' ? refs.armL : refs.armR;
      arm.hand.visible = false;
      kit.box('limbT', arm.elbow, 0, 0, 0, { pivot: [0, 0.5, 0], sx: 1.7, sz: 1.7, sy: 0.55 });
      kit.box('blade', arm.elbow, 0, -2.8 * P, 0.6 * P, { pivot: [0, 0.5, -0.3], sy: 1.25, rot: [-0.35, 0, 0] });
      kit.box('spike', arm.elbow, (side === 'L' ? -1 : 1) * 1.6 * P, -1 * P, -1 * P, { pivot: [0, -0.5, 0], rot: [-1.6, 0, 0] });
    }
  }
  if (ex.claw) {
    const arm = ex.claw === 'L' ? refs.armL : refs.armR;
    arm.hand.visible = false;
    kit.box('arm', arm.elbow, 0, 0, 0, { pivot: [0, 0.5, 0], sx: 0.8, sy: 0.6, sz: 0.8 });
    const tips = [];
    for (const [x, rz] of [[-1.6, 0.35], [0, 0], [1.6, -0.35]]) {
      const pv = kit.pivot(arm.elbow, x * P, -5.6 * P, 1 * P, [-0.45, 0, rz]);
      kit.box('claw', pv, 0, 0, 0, { pivot: [0, 0.5, 0], s: 1.5 });
      tips.push(pv);
    }
    z._addAnim((dt, t) => { const s = Math.sin(t * 3) * 0.12; for (const p of tips) p.rotation.x = -0.45 + s; });
  }
  if (ex.petal) {
    refs.skull.visible = false;
    refs.jaw.visible = false;
    kit.box('long', H, 0, 0, 0, { pivot: [0, -0.5, 0], sx: 1.8, sz: 1.8, sy: 0.38 });
    const fl = petalFlower(kit, H, ex.petal, 1.4 * P, [0, 2.6 * P, 0.4 * P], [0.45, 0, 0]);
    kit.box('maw', fl.flower, 0, 0.6 * P, 0, { rot: [-Math.PI / 2, 0, 0], s: 0.85 });
    const inner = tendril(kit, fl.flower, [0.5 * P, 1 * P, 0], [0.15, 0, -0.2], 2, { sy: 0.5, sx: 0.8 });
    addSway(z, inner, 0.4, 4);
    addBloom(z, fl.petals, 0.3, 1.25, 1.8);
    refs.petals = fl.petals;
    refs.flower = fl.flower;
  }
  if (ex.bigJaw) {
    // The lower jaw tears loose and distends into a long toothed trough
    refs.jaw.scale.set(1.05, 1.4, 1.2);
    refs.jaw.rotation.x = 0.9;
    const low = kit.pivot(refs.jaw, 0, -2 * P, 5.2 * P, [0.5, 0, 0]);
    kit.box('jaw', low, 0, 0, 0, { pivot: [0, 0.5, 0.5], sx: 1.25, sy: 1.4, sz: 1.3 });
    const pair = [-1, 1].map(s => {
      const pv = kit.pivot(refs.jaw, s * 4.3 * P, 0, 3 * P, [-0.2, s * 0.2, 0]);
      kit.box('claw', pv, 0, 0, 0, { pivot: [0, 0.5, 0], sy: 1.4 });
      return pv;
    });
    addClack(z, pair, 0.25, 5);
    const jaw = refs.jaw;
    z._addAnim((dt, t) => {
      const scream = z.state === 'chasing' || z.state === 'attacking' ? 1 : 0.5;
      jaw.rotation.x = 0.75 + (0.35 + Math.sin(t * 13) * 0.08) * scream + Math.sin(t * 1.3) * 0.12;
      low.rotation.x = 0.4 + Math.sin(t * 11) * 0.06;
    });
  }
  if (ex.nose) {
    const b = HUMANOID_UV.nose;
    const nose = new THREE.Mesh(sharedBox(b.w, b.h, b.d, b.u, b.v, { pivot: [0, 0.5, -0.5] }), refs.mat);
    nose.position.set(0, 4.6 * P, 4 * P);
    nose.castShadow = true; nose.userData.noVox = true;
    H.add(nose);
  }
  if (ex.headMass) {
    kit.box('big', H, 2.4 * P, 8.6 * P, -0.6 * P, { s: 0.42, rot: [0.2, 0.5, -0.35] });
    kit.box('eye', H, 3.4 * P, 9.8 * P, 1.2 * P, { s: 0.8 });
    kit.box('eye', H, 1.0 * P, 10.2 * P, 0.4 * P, { s: 0.6, rot: [0.5, 0, 0] });
    addSway(z, tendril(kit, H, [-1.4 * P, 8 * P, -1.5 * P], [-0.4, 0, 0.5], 2, { sy: 0.6 }), 0.3, 2.6);
  }
  if (ex.crown) {
    const n = ex.crown;
    for (let i = 0; i < n; i++) {
      const a = (i / n) * Math.PI * 2 + 0.3;
      const chain = tendril(kit, H, [Math.cos(a) * 2.6 * P, 7.8 * P, Math.sin(a) * 2.6 * P],
        [Math.sin(a) * 0.55, 0, -Math.cos(a) * 0.55], 3, { sy: 0.7, curl: -0.2 });
      addSway(z, chain, 0.16, 1.4 + Math.random() * 0.6);
    }
    kit.box('eye', H, 0, 8.6 * P, 0.6 * P, { s: 1.1 });
  }
  if (ex.gearSpikes) {
    kit.box('spike', T, 1.6 * P, 8 * P, 2.2 * P * bulk, { pivot: [0, -0.5, 0], rot: [1.25, 0, -0.2], s: 1.2 });
    kit.box('spike', T, -2.2 * P, 4.8 * P, 2.2 * P * bulk, { pivot: [0, -0.5, 0], rot: [1.4, 0, 0.3] });
    kit.box('sac', T, 2.6 * P * bulk, 3.4 * P, 2.4 * P * bulk, { s: 0.55 });
    kit.box('spike', refs.armR.shoulder, 0, 1.6 * P, 0, { pivot: [0, -0.5, 0], rot: [0, 0, -0.5] });
    kit.box('eye', refs.armL.shoulder, -1.6 * P, 0.4 * P, 1.2 * P, { s: 0.7 });
  }
  if (ex.backSacs) {
    const sacs = [
      kit.box('sac', T, -1.8 * P, 8 * P, -3.8 * P * bulk, { s: 1.7 }),
      kit.box('sac', T, 2.2 * P, 5 * P, -3.4 * P * bulk, { s: 1.35 }),
      kit.box('sac', T, 0.4 * P, 11.4 * P, -2.6 * P * bulk, { s: 1.1 }),
      kit.box('sac', T, 3.2 * P * bulk, 9.6 * P, 1.6 * P, { s: 0.9 }),
    ];
    addPulse(z, sacs, 0.07, 2.4);
    refs.sacs = sacs;
  }
  if (ex.bellySacs) {
    const sacs = [];
    for (let i = 0; i < ex.bellySacs; i++) {
      const a = -0.9 + (i / Math.max(1, ex.bellySacs - 1)) * 1.8;
      sacs.push(kit.box('sac', T, Math.sin(a) * 4.4 * P * bulk, (1.5 + (i % 2) * 2.4) * P, Math.cos(a) * 4.2 * P * bulk, { s: 0.75 + (i % 3) * 0.15 }));
    }
    addPulse(z, sacs, 0.09, 1.8);
  }
  if (ex.seamTeeth) {
    kit.box('maw', T, 0, 5.4 * P, 2.1 * P * bulk, { sx: 0.6, sy: 1.6, sz: 0.6 });
    for (const s of [-1, 1]) addSway(z, tendril(kit, T, [s * 0.6 * P, 6 * P, 2.4 * P * bulk], [1.0, 0, s * 0.4], 2, { sy: 0.55 }), 0.35, 3);
  }

  // Every host: head twitches and the jaw works constantly
  addTwitch(z, H, 0.32, 1.5);
  if (!ex.bigJaw && !ex.petal) addChatter(z, refs.jaw, 0.12, 4 + Math.random() * 3);
  return kit;
}

// ---------------------------------------------------------------------------
// Bug crawler: flat segmented carapace, six thin jointed legs (tripod gait),
// clacking mandibles, eye cluster and two whip tendrils on the abdomen.
// ---------------------------------------------------------------------------
export function buildBug(z, o = {}) {
  const kit = makeKit(o.pal ?? 'crimson', o.eyeHex ?? null, 1.0);
  const group = new THREE.Group();
  const root = kit.pivot(group, 0, -0.9, 0);       // feet plane
  const bodyH = 0.36;
  const body = kit.pivot(root, 0, bodyH, 0);

  kit.box('seg2', body, 0, 0, 0.04, { sx: 1.35, sy: 1.1, sz: 1.2 });           // thorax
  const abd = kit.pivot(body, 0, 0.02, -0.1, [-0.12, 0, 0]);
  kit.box('seg', abd, 0, 0.02, -0.22, { sx: 1.05, sy: 1.15, sz: 1.3 });         // abdomen
  kit.box('plate', abd, 0, 0.16, -0.2, { sx: 0.9, sz: 1.2, rot: [0.08, 0, 0] });
  kit.box('spike', abd, -0.08, 0.17, -0.3, { pivot: [0, -0.5, 0], rot: [-0.6, 0, 0.3] });
  kit.box('spike', abd, 0.08, 0.17, -0.3, { pivot: [0, -0.5, 0], rot: [-0.6, 0, -0.3] });
  const whips = [-1, 1].map(s => tendril(kit, abd, [s * 0.05, 0.08, -0.42], [-1.0, 0, s * 0.35], 2, { sy: 0.7 }));
  for (const w of whips) addSway(z, w, 0.35, 3);

  const head = kit.pivot(body, 0, 0.03, 0.2);
  kit.box('head', head, 0, 0, 0.06, { sx: 0.8, sy: 0.7, sz: 0.75 });
  kit.box('eye', head, -0.06, 0.1, 0.06, { s: 0.75 });
  kit.box('eye', head, 0.06, 0.1, 0.02, { s: 0.6 });
  const mand = [-1, 1].map(s => {
    const pv = kit.pivot(head, s * 0.06, -0.04, 0.16, [-1.35, s * 0.35, 0]);
    kit.box('claw', pv, 0, 0, 0, { pivot: [0, 0.5, 0], sy: 1.1 });
    return pv;
  });
  addClack(z, mand, 0.45, 8);
  addTwitch(z, head, 0.35, 0.9);

  // Six legs: hip yaw -> femur (up/out) -> knee -> tibia (down to the ground)
  const legs = [];
  const fem = 6 * P * 1.0, tib = 10 * P * 1.05;
  const femA = 1.0, tibA = 0.35;
  for (const [zi, dir] of [[0.12, 1], [0.0, 0], [-0.12, -1]]) {
    for (const side of [-1, 1]) {
      const yaw0 = -side * dir * 0.55;
      const hip = kit.pivot(body, side * 0.1, 0, zi, [0, yaw0, 0]);
      const lift = kit.pivot(hip, 0, 0, 0, [0, 0, -side * femA]);
      kit.box('limb', lift, 0, 0, 0, { pivot: [0, -0.5, 0], sx: 1.2, sz: 1.2 });
      const knee = kit.pivot(lift, 0, fem, 0, [0, 0, side * (femA + tibA)]);
      kit.box('limbL', knee, 0, 0, 0, { pivot: [0, 0.5, 0], sy: 1.05 });
      legs.push({ hip, lift, side, yaw0, setA: (dir === 0) === (side > 0) });
    }
  }
  // Tripod gait: alternate leg sets lift + swing forward while the other pushes
  let phase = Math.random() * 6;
  z._addAnim((dt, t, sp) => {
    const moving = sp > 0.3;
    phase += dt * (moving ? 6 + sp * 2.6 : 0);
    for (const L of legs) {
      const p = phase + (L.setA ? 0 : Math.PI);
      const swing = moving ? Math.sin(p) * 0.38 : 0;
      const up = moving ? Math.max(0, Math.cos(p)) * 0.45 : Math.max(0, Math.sin(t * 11 + L.yaw0 * 5)) * 0.08;
      L.hip.rotation.y = L.yaw0 + swing * L.side;
      L.lift.rotation.z = -L.side * (femA + up);
    }
    body.position.y = bodyH + (moving ? Math.abs(Math.sin(phase * 2)) * 0.018 : Math.sin(t * 3) * 0.006);
    abd.rotation.x = -0.12 + Math.sin(t * (moving ? 9 : 2.5)) * 0.05;
    body.rotation.z = moving ? Math.sin(phase) * 0.04 : 0;
  });

  z._leftArm = z._rightArm = z._leftLeg = z._rightLeg = null;
  z._torsoGroup = null;
  z.headshotY = -0.9 + bodyH + 0.03;
  z._healthBarHeight = 0.5;
  z._colH = 0.6;
  z._colHW = 0.35;
  return { group, root, refs: { root, body, head, mat: kit.mat, kit } };
}

// ---------------------------------------------------------------------------
// Quadruped hunter (assimilated canine host): hide-covered body torn open by
// crimson flesh, long skull whose snout has split into a 4-way petal maw with
// feeding tendrils, digitigrade legs, tendril tail.
// ---------------------------------------------------------------------------
export function buildQuadruped(z, o = {}) {
  const hide = makeKit(o.pal ?? 'hide', o.eyeHex ?? 0xffd040, 1.0);
  const fl = makeKit('crimson', o.eyeHex ?? 0xffd040, 1.0);
  const group = new THREE.Group();
  const root = hide.pivot(group, 0, -0.9, 0);
  const torso = hide.pivot(root, 0, 0.62, 0, [-0.06, 0, 0]);

  hide.box('seg', torso, 0, 0, -0.02, { sx: 1.0, sy: 1.35, sz: 2.0 });
  fl.box('seg2', torso, 0.12, -0.02, 0.06, { sx: 0.6, sy: 1.1, sz: 1.4 });       // flayed flank
  fl.box('big', torso, -0.11, 0.0, -0.12, { sx: 0.25, sy: 0.32, sz: 0.5, rot: [0, -Math.PI / 2, 0] }); // ribs bursting out
  for (let i = 0; i < 3; i++) fl.box('spike', torso, 0, 0.15, 0.2 - i * 0.18, { pivot: [0, -0.5, 0], rot: [-0.5, 0, 0], s: 1.2 - i * 0.15 });
  const backT = [-1, 1].map(s => tendril(fl, torso, [s * 0.08, 0.14, 0.16], [-0.9, 0, s * 0.6], 2, { sy: 0.65 }));
  for (const c of backT) addSway(z, c, 0.3, 2.6);

  // Neck + long skull
  hide.box('long', torso, 0, 0.04, 0.3, { pivot: [0, -0.5, 0], sx: 1.6, sz: 1.6, sy: 0.6, rot: [1.05, 0, 0] });
  const head = hide.pivot(root, 0, 0.78, 0.56, [0.12, 0, 0]);
  hide.box('head', head, 0, 0, 0.06, { sx: 0.9, sy: 0.75, sz: 1.5 });
  fl.box('eye', head, -0.09, 0.08, 0.12, { s: 0.75 });
  fl.box('eye', head, 0.09, 0.08, 0.12, { s: 0.75 });
  fl.box('eye', head, 0.02, 0.13, -0.02, { s: 0.6 });
  // Split maw: four petals around the forward axis, tendrils inside
  const maw = petalFlower(fl, head, 4, 1.3 * P, [0, -0.01, 0.3], [Math.PI / 2, 0, 0], { phase: Math.PI / 4, sx: 0.85, sy: 0.85 });
  fl.box('maw', maw.flower, 0, 0.3 * P, 0, { rot: [-Math.PI / 2, 0, 0], s: 0.8 });
  const feeders = [[-0.6, 0.3], [0.7, -0.2], [0, 0.6]].map(([x, rz]) => tendril(fl, maw.flower, [x * P, 0, 0], [0.1, 0, rz], 2, { sy: 0.55, sx: 0.8 }));
  for (const c of feeders) addSway(z, c, 0.5, 6);
  addBloom(z, maw.petals, 0.25, 1.2, 2.5);
  addTwitch(z, head, 0.3, 1.1);

  // Legs (front pivots registered as arms -> diagonal trot from the base swing)
  const mkLeg = (x, zz) => {
    const hip = hide.pivot(root, x, 0.52, zz);
    hip.userData.baseRotX = 0;
    const thigh = hide.pivot(hip, 0, 0, 0, [-0.3, 0, 0]);
    hide.box('limbT', thigh, 0, 0, 0, { pivot: [0, 0.5, 0], sx: 1.4, sz: 1.4, sy: 0.8 });
    const knee = hide.pivot(thigh, 0, -6 * P * 0.8, 0, [0.6, 0, 0]);
    hide.box('limbT', knee, 0, 0, 0, { pivot: [0, 0.5, 0], sx: 0.9, sz: 0.9, sy: 0.78 });
    return hip;
  };
  z._leftArm = mkLeg(-0.12, 0.24);
  z._rightArm = mkLeg(0.12, 0.24);
  z._leftLeg = mkLeg(-0.12, -0.26);
  z._rightLeg = mkLeg(0.12, -0.26);

  const tail = tendril(fl, torso, [0, 0.06, -0.36], [-2.0, 0, 0], 3, { sy: 0.7, curl: -0.25 });
  addSway(z, tail, 0.3, 3.5);
  // Body heave while running
  z._addAnim((dt, t, sp) => { torso.rotation.z = Math.sin(t * 10) * 0.03 * Math.min(1, sp / 3); });

  z._torsoGroup = null;
  z.headshotY = -0.12;
  z._healthBarHeight = 0.55;
  z._colH = 0.85;
  z._colHW = 0.35;
  return { group, root, refs: { root, torso, head, petals: maw.petals, mat: hide.mat, kit: hide, flesh: fl } };
}

// ---------------------------------------------------------------------------
// Long-limbed stalker. crouch=true: digitigrade pouncer folded low over long
// hind legs. crouch=false: tall, gaunt, upright thing with arms to its knees.
// ---------------------------------------------------------------------------
export function buildLongLimbed(z, o = {}) {
  const crouch = !!o.crouch;
  const kit = makeKit(o.pal ?? 'crimson', o.eyeHex ?? null, 1.0);
  const group = new THREE.Group();
  const root = kit.pivot(group, 0, -0.9, 0);

  // Legs (thigh / shin / foot claw), angles chosen so the feet stay planted
  const thighS = crouch ? 1.2 : 1.6, shinS = crouch ? 1.0 : 1.1;
  const a1 = crouch ? -0.9 : -0.1, a2 = crouch ? 0.5 : 0.12;
  const L1 = 6 * P * thighS, L2 = 10 * P * shinS;
  const hipY = L1 * Math.cos(a1) + L2 * Math.cos(a2) + 0.03;
  const legs = {};
  for (const side of [-1, 1]) {
    const hip = kit.pivot(root, side * 0.1, hipY, 0, [a1, 0, 0]);
    hip.userData.baseRotX = a1;
    kit.box('limbT', hip, 0, 0, 0, { pivot: [0, 0.5, 0], sy: thighS, sx: 1.2, sz: 1.2 });
    const knee = kit.pivot(hip, 0, -L1, 0, [a2 - a1, 0, 0]);
    kit.box('limbL', knee, 0, 0, 0, { pivot: [0, 0.5, 0], sy: shinS, sx: 1.4, sz: 1.4 });
    kit.box('claw', knee, 0, -L2, 0, { pivot: [0, 0.5, -0.5], rot: [-Math.PI / 2 - a2 + 0.2, 0, 0] });
    legs[side < 0 ? 'L' : 'R'] = hip;
  }

  // Torso: pelvis, spine strut, open ribcage
  const lean = crouch ? 0.95 : 0.22;
  const torso = kit.pivot(root, 0, hipY, 0, [lean, 0, 0]);
  kit.box('seg2', torso, 0, 0.02, 0, { sx: 1.0, sy: 0.8, sz: 0.8 });
  kit.box('long', torso, 0, 0.06, -0.02, { pivot: [0, -0.5, 0], sx: 1.3, sz: 1.1, sy: crouch ? 0.8 : 1.0 });
  const spineH = 8 * P * (crouch ? 0.8 : 1.0);
  kit.box('big', torso, 0, spineH - 0.02, 0, { sx: 0.6, sy: 0.5, sz: 0.42 });
  for (let i = 0; i < 3; i++) kit.box('spike', torso, 0, 0.12 + i * spineH * 0.3, -0.07, { pivot: [0, -0.5, 0], rot: [-1.1, 0, 0], s: 1 - i * 0.15 });
  const top = spineH + 0.1;

  // Arms: long thin upper + forearm, three long finger claws
  const armS = crouch ? 0.85 : 1.0;
  const armBase = crouch ? -0.7 : -0.15;
  const arms = {};
  for (const side of [-1, 1]) {
    const sh = kit.pivot(torso, side * 0.17, top - 0.04, 0, [armBase, 0, side * 0.08]);
    sh.userData.baseRotX = armBase;
    kit.box('limbL', sh, 0, 0, 0, { pivot: [0, 0.5, 0], sy: armS, sx: 1.5, sz: 1.5 });
    const el = kit.pivot(sh, 0, -10 * P * armS, 0, [crouch ? -0.3 : -0.2, 0, 0]);
    kit.box('limbL', el, 0, 0, 0, { pivot: [0, 0.5, 0], sy: armS, sx: 1.2, sz: 1.2 });
    const hand = kit.pivot(el, 0, -10 * P * armS, 0);
    for (const [x, rz] of [[-1, 0.3], [0, 0], [1, -0.3]]) kit.box('claw', hand, x * 0.025, 0, 0.02, { pivot: [0, 0.5, 0], sy: crouch ? 1.3 : 1.7, rot: [-0.3, 0, rz] });
    arms[side < 0 ? 'L' : 'R'] = { shoulder: sh, elbow: el, hand };
  }

  // Head: elongated skull, hinged toothed jaw, mandibles
  const head = kit.pivot(torso, 0, top + 0.02, 0.04, [crouch ? -0.85 : -0.3, 0, 0]);
  kit.box('head', head, 0, 0.12, 0.02, { sx: 0.8, sy: crouch ? 1.0 : 1.35, sz: 0.95 });
  const jaw = kit.pivot(head, 0, 0.0, -0.1, [0.35, 0, 0]);
  kit.box('jaw', jaw, 0, 0, 0, { pivot: [0, 0.5, -0.5], sx: 0.75, sy: 1.2, sz: 0.95 });
  const mand = [-1, 1].map(s => {
    const pv = kit.pivot(head, s * 0.12, 0.04, 0.14, [-0.6, s * 0.3, 0]);
    kit.box('claw', pv, 0, 0, 0, { pivot: [0, 0.5, 0], sy: 1.2 });
    return pv;
  });
  addClack(z, mand, 0.35, 6);
  addChatter(z, jaw, 0.25, 6);
  addTwitch(z, head, crouch ? 0.4 : 0.5, crouch ? 1.0 : 1.8);
  for (const s of [-1, 1]) addSway(z, tendril(kit, torso, [s * 0.06, top - 0.06, -0.08], [-0.8, 0, s * 0.5], 3, { sy: 0.7 }), 0.25, 2.4);

  // Finger flex
  z._addAnim((dt, t) => { const f = Math.sin(t * 4) * 0.1; arms.L.hand.rotation.x = f; arms.R.hand.rotation.x = -f; });

  z._leftArm = arms.L.shoulder; z._rightArm = arms.R.shoulder;
  z._leftLeg = legs.L; z._rightLeg = legs.R;
  z._torsoGroup = torso; z._torsoBaseRotX = lean;
  const headY = hipY + (top + 0.12) * Math.cos(lean);
  z.headshotY = -0.9 + headY - 0.06;
  z._healthBarHeight = -0.9 + headY + 0.3;
  z._colH = crouch ? 1.3 : 1.95;
  z._colHW = 0.3;
  return { group, root, refs: { root, torsoGroup: torso, headGroup: head, jaw, armL: arms.L, armR: arms.R, legL: legs.L, legR: legs.R, mat: kit.mat, kit } };
}

// ---------------------------------------------------------------------------
// Brute: squat legs, huge hunched torso of fused muscle and bone, small head
// sunk between the shoulders, one massive flesh claw arm. armored = carapace
// plates and a bone shield arm; boss = extra arms, tendril mane, petal maw.
// ---------------------------------------------------------------------------
export function buildBrute(z, o = {}) {
  const s = o.scale ?? 1.25;
  const kit = makeKit(o.pal ?? 'crimson', o.eyeHex ?? null, o.eyeI ?? 1.0);
  const group = new THREE.Group();
  const inner = kit.pivot(group, 0, -0.9, 0);
  inner.scale.setScalar(s);

  // Legs
  const hipY = 0.62;
  const legs = {};
  for (const side of [-1, 1]) {
    const hip = kit.pivot(inner, side * 0.2, hipY, 0, [-0.25, 0, side * 0.06]);
    hip.userData.baseRotX = -0.25;
    kit.box('limbT', hip, 0, 0, 0, { pivot: [0, 0.5, 0], sx: 2.0, sz: 2.0, sy: 0.92 });
    const knee = kit.pivot(hip, 0, -6 * P * 0.92, 0, [0.38, 0, 0]);
    kit.box('limbT', knee, 0, 0, 0, { pivot: [0, 0.5, 0], sx: 1.7, sz: 1.7, sy: 0.95 });
    legs[side < 0 ? 'L' : 'R'] = hip;
  }

  // Torso
  const hunch = o.hunch ?? 0.45;
  const torso = kit.pivot(inner, 0, hipY + 0.04, 0, [hunch, 0, 0]);
  const belly = kit.box('big', torso, 0, 0.16, 0.02, { sx: 1.05, sy: 0.75, sz: 0.95 });
  kit.box('big', torso, 0, 0.5, 0, { sx: 1.45, sy: 0.95, sz: 1.1 });
  kit.box('big', torso, 0.04, 0.68, -0.2, { sx: 0.95, sy: 0.75, sz: 0.8, rot: [0.3, 0.2, 0.1] });   // hump
  for (let i = 0; i < 3; i++) kit.box('spike', torso, (i - 1) * 0.12, 0.88 - Math.abs(i - 1) * 0.06, -0.3, { pivot: [0, -0.5, 0], rot: [-0.7, 0, (1 - i) * 0.4], s: 1.6 });
  const sacs = [kit.box('sac', torso, -0.22, 0.62, -0.26, { s: 1.2 }), kit.box('sac', torso, 0.26, 0.36, -0.2, { s: 0.9 })];
  addPulse(z, sacs, 0.08, 2);
  addPulse(z, [belly], 0.025, 1.6);

  // Head
  const head = kit.pivot(torso, 0, 0.7, 0.24, [-hunch * 0.8, 0, 0]);
  const jaw = kit.pivot(head, 0, -0.08, -0.06, [0.3, 0, 0]);
  let petals = null;
  if (o.boss) {
    kit.box('head', head, 0, 0, 0.06, { sx: 1.1, sy: 0.9, sz: 1.0 });
    const fl = petalFlower(kit, head, 5, 1.6 * P, [0, -0.02, 0.24], [Math.PI / 2, 0, 0], { sx: 1.0, sy: 0.9 });
    kit.box('maw', fl.flower, 0, 0.4 * P, 0, { rot: [-Math.PI / 2, 0, 0] });
    addBloom(z, fl.petals, 0.3, 1.1, 1.4);
    petals = fl.petals;
  } else {
    kit.box('head', head, 0, 0, 0.04, { sx: 0.95, sy: 0.85, sz: 0.9 });
    kit.box('jaw', jaw, 0, 0, 0, { pivot: [0, 0.5, -0.5], sx: 1.05, sz: 1.0 });
    addChatter(z, jaw, 0.2, 3);
  }
  const mand = [-1, 1].map(sd => {
    const pv = kit.pivot(head, sd * 0.17, -0.06, 0.12, [-0.5, sd * 0.3, 0]);
    kit.box('claw', pv, 0, 0, 0, { pivot: [0, 0.5, 0], s: 1.3 });
    return pv;
  });
  addClack(z, mand, 0.3, 4);
  addTwitch(z, head, 0.22, 1.8);
  if (o.armored) {
    kit.box('plate', head, 0, 0.16, 0.02, { sx: 1.2, sz: 1.7, sy: 2 });
    kit.box('plate', torso, 0, 0.74, 0.18, { sx: 1.6, sz: 1.2, sy: 2.5, rot: [-0.3, 0, 0] });
    kit.box('plate', torso, 0, 0.28, 0.26, { sx: 1.3, sz: 0.8, sy: 2.5, rot: [Math.PI / 2 - 0.1, 0, 0] });
  }

  // Arms
  const arms = {};
  const armBase = -0.55;
  const mkMassive = (side, clawed) => {
    const sh = kit.pivot(torso, side * 0.44, 0.62, 0.02, [armBase, 0, side * 0.12]);
    sh.userData.baseRotX = armBase;
    kit.box('arm', sh, 0, 0.05, 0, { pivot: [0, 0.5, 0], sx: 1.2, sz: 1.2, sy: 1.0 });
    kit.box('plate', sh, side * 0.06, 0.13, 0, { sx: 1.25, sz: 1.6, sy: 2.4, rot: [0, 0, -side * 0.35] });
    kit.box('spike', sh, side * 0.14, 0.12, -0.05, { pivot: [0, -0.5, 0], rot: [0, 0, -side * 0.9], s: 1.5 });
    const el = kit.pivot(sh, 0, -0.5, 0, [-0.5, 0, 0]);
    kit.box('arm', el, 0, 0, 0, { pivot: [0, 0.5, 0], sx: 1.5, sy: 0.85, sz: 1.5 });
    const hand = kit.pivot(el, 0, -0.47, 0.02);
    if (clawed) {
      for (const [x, rz] of [[-0.11, 0.35], [0, 0], [0.11, -0.35]]) kit.box('claw', hand, x, 0, 0.06, { pivot: [0, 0.5, 0], s: 2.6, rot: [-0.5, 0, rz] });
    } else {
      kit.box('plate', hand, 0, -0.04, 0.1, { sx: 1.3, sz: 1.5, sy: 5, rot: [Math.PI / 2, 0, 0] });   // bone shield slab
    }
    return { shoulder: sh, elbow: el, hand };
  };
  const mkThin = (side) => {
    const sh = kit.pivot(torso, side * 0.38, 0.6, 0.02, [armBase, 0, side * 0.1]);
    sh.userData.baseRotX = armBase;
    kit.box('limbT', sh, 0, 0, 0, { pivot: [0, 0.5, 0], sx: 1.9, sz: 1.9, sy: 1.15 });
    const el = kit.pivot(sh, 0, -6 * P * 1.15, 0, [-0.6, 0, 0]);
    kit.box('limbT', el, 0, 0, 0, { pivot: [0, 0.5, 0], sx: 1.5, sz: 1.5, sy: 1.1 });
    const hand = kit.pivot(el, 0, -6 * P * 1.1, 0);
    for (const x of [-0.035, 0.035]) kit.box('claw', hand, x, 0, 0.02, { pivot: [0, 0.5, 0], s: 1.4, rot: [-0.4, 0, 0] });
    return { shoulder: sh, elbow: el, hand };
  };
  arms.R = mkMassive(1, true);
  arms.L = o.armored ? mkMassive(-1, false) : mkThin(-1);
  // Claw flex
  z._addAnim((dt, t) => {
    const f = z.state === 'attacking' ? Math.sin(t * 8) * 0.3 : Math.sin(t * 1.7) * 0.08;
    arms.R.hand.rotation.x = f;
  });

  if (o.boss) {
    // Second pair of arms from the flanks, a mane of tendrils, eyes all over
    for (const side of [-1, 1]) {
      const sh = kit.pivot(torso, side * 0.38, 0.22, 0.12, [-0.9, 0, side * 0.5]);
      kit.box('limbT', sh, 0, 0, 0, { pivot: [0, 0.5, 0], sx: 1.4, sz: 1.4, sy: 1.0 });
      const el = kit.pivot(sh, 0, -6 * P, 0, [-0.8, 0, 0]);
      kit.box('blade', el, 0, 0, 0, { pivot: [0, 0.5, 0], sy: 0.9 });
      const ph = side * 1.5;
      z._addAnim((dt, t) => { sh.rotation.x = -0.9 + Math.sin(t * 2.4 + ph) * 0.35; el.rotation.x = -0.8 + Math.sin(t * 3.1 + ph) * 0.25; });
    }
    for (let i = 0; i < 6; i++) {
      const c = i - 2.5;
      addSway(z, tendril(kit, torso, [c * 0.09, 0.82, -0.2], [-0.5 - Math.abs(c) * 0.08, 0, c * 0.28], 3, { sy: 0.9, sx: 1.3 }), 0.18, 1.5 + i * 0.1);
    }
    for (const [x, y, zz, sc] of [[-0.3, 0.55, 0.28, 1.1], [0.18, 0.3, 0.3, 0.9], [0.32, 0.72, 0.18, 0.8], [-0.12, 0.12, 0.27, 0.8]]) kit.box('eye', torso, x, y, zz, { s: sc });
  } else {
    for (const sd of [-1, 1]) addSway(z, tendril(kit, torso, [sd * 0.14, 0.8, -0.24], [-0.7, 0, sd * 0.5], 2, { sy: 0.8, sx: 1.2 }), 0.22, 2);
  }

  z._leftArm = arms.L.shoulder; z._rightArm = arms.R.shoulder;
  z._leftLeg = legs.L; z._rightLeg = legs.R;
  z._torsoGroup = torso; z._torsoBaseRotX = hunch;
  z.headshotY = -0.9 + (hipY + 0.04 + 0.7 * Math.cos(hunch)) * s;
  z._healthBarHeight = -0.9 + 1.7 * s;
  z._colH = Math.min(3, 1.65 * s);
  z._colHW = Math.max(0.3, Math.min(0.6, 0.36 * s));
  return { group, root: inner, refs: { root: inner, torsoGroup: torso, headGroup: head, jaw, petals, armL: arms.L, armR: arms.R, legL: legs.L, legR: legs.R, mat: kit.mat, kit } };
}

// ---------------------------------------------------------------------------
// Winged flyer: lean body, long-jawed head, two-jointed membrane wings,
// dangling clawed legs and a tendril tail.
// ---------------------------------------------------------------------------
export function buildFlyer(z, o = {}) {
  const kit = makeKit(o.pal ?? 'maroon', o.eyeHex ?? null, 1.2);
  const group = new THREE.Group();
  const body = kit.pivot(group, 0, 0.05, 0, [0.15, 0, 0]);
  body.scale.setScalar(o.scale ?? 1.35);

  kit.box('long', body, 0, 0, -0.04, { rot: [Math.PI / 2, 0, 0], sx: 1.9, sz: 1.6, sy: 0.9 });
  kit.box('seg', body, 0, 0.02, 0.14, { sx: 0.7, sy: 1.0, sz: 0.7 });
  const head = kit.pivot(body, 0, 0.04, 0.3, [0.2, 0, 0]);
  kit.box('head', head, 0, 0, 0.06, { sx: 0.75, sy: 0.7, sz: 1.15 });
  const jaw = kit.pivot(head, 0, -0.07, -0.04, [0.45, 0, 0]);
  kit.box('jaw', jaw, 0, 0, 0, { pivot: [0, 0.5, -0.5], sx: 0.7, sz: 1.3, sy: 0.9 });
  addChatter(z, jaw, 0.3, 5);
  addTwitch(z, head, 0.35, 1.2);
  for (const sd of [-1, 1]) kit.box('spike', head, sd * 0.07, 0.08, -0.06, { pivot: [0, -0.5, 0], rot: [-1.1, 0, sd * 0.3], s: 1.3 });

  // Wings
  const wings = [];
  for (const side of [-1, 1]) {
    const sh = kit.pivot(body, side * 0.1, 0.08, 0.1);
    kit.box('wing', sh, 0, 0, 0, { pivot: [-0.5 * side, 0.5, 0], rot: [Math.PI / 2, 0, 0], shadow: true });
    const el = kit.pivot(sh, side * 10 * P, 0, 0);
    kit.box('wing', el, 0, 0, 0, { pivot: [-0.5 * side, 0.5, 0], rot: [Math.PI / 2, 0, 0], sx: 0.9, sy: 0.8 });
    kit.box('claw', el, 0, 0, 0.02, { pivot: [0, -0.5, 0], rot: [0.6, 0, -side * 0.6] });
    wings.push({ sh, el, side });
  }
  let flap = Math.random() * 6;
  z._addAnim((dt, t, sp) => {
    flap += dt * (z.state === 'idle' ? 6 : 10);
    for (const w of wings) {
      w.sh.rotation.z = w.side * (Math.sin(flap) * 0.6 + 0.4);
      w.el.rotation.z = w.side * Math.sin(flap - 0.9) * 0.45;
    }
    body.position.y = 0.05 - Math.sin(flap) * 0.04;
  });

  // Dangling legs + tail
  const legs = [];
  for (const side of [-1, 1]) {
    const hip = kit.pivot(body, side * 0.07, -0.04, -0.2, [0.5, 0, side * 0.1]);
    kit.box('limb', hip, 0, 0, 0, { pivot: [0, 0.5, 0], sx: 1.5, sz: 1.5 });
    const kn = kit.pivot(hip, 0, -6 * P, 0, [-0.6, 0, 0]);
    kit.box('limbL', kn, 0, 0, 0, { pivot: [0, 0.5, 0], sy: 0.6 });
    for (const x of [-0.02, 0.02]) kit.box('claw', kn, x, -6 * P, 0, { pivot: [0, 0.5, 0], rot: [-0.8, 0, 0], s: 0.8 });
    legs.push(hip);
  }
  z._addAnim((dt, t) => { legs[0].rotation.x = 0.5 + Math.sin(t * 2.3) * 0.2; legs[1].rotation.x = 0.5 + Math.sin(t * 2.3 + 1.4) * 0.2; });
  addSway(z, tendril(kit, body, [0, 0, -0.26], [-1.9, 0, 0], 3, { sy: 0.8, curl: 0.2 }), 0.3, 2.8);

  z._leftArm = z._rightArm = z._leftLeg = z._rightLeg = null;
  z._torsoGroup = null;
  return { group, refs: { root: body, headGroup: head, jaw, mat: kit.mat, kit } };
}
