import * as THREE from 'three';

// Minecraft-style mob skins for the parasites (original pixel art, painted in
// code — no external assets).
//
// Every mob is built from cuboids whose faces are UV-mapped onto a 64x64 skin
// using the standard Minecraft box unwrap:
//
//        u   u+d     u+d+w   u+2d+w   u+2d+2w
//   v    .   [ top ]  [bottom]
//   v+d  [right][front][ left ][ back ]
//   v+d+h
//
// "right" is the entity's right side (-x, it faces +z), "left" is +x.
// Each face is painted as seen from outside, upright. Top faces have the
// front edge at the bottom of their region, bottom faces at the top.
//
// Two skin families:
//   * HUMANOID skins (one per variant style) — assimilated hosts: a normal
//     Minecraft-proportioned body whose skin and clothes are being overtaken by
//     crimson parasite flesh, pus and bone.
//   * The PARASITE atlas (one per flesh palette) — a kit of generic parasite
//     parts (carapace segments, thin legs, claws, tendrils, maws, petals, wings,
//     eye globs...) used by the non-humanoid forms and by humanoid add-ons.
// Both get a baked Minecraft-entity style face shading pass (lit top, darker
// sides and back, dark underside, vertical gradient on the sides).

export const PX = 1.8 / 32;          // metres per skin pixel (32px tall humanoid = 1.8m)
const S = 64;                        // skin size

// ---------------------------------------------------------------------------
// UV helpers
// ---------------------------------------------------------------------------
export function boxRegions(w, h, d, u, v) {
  return {
    top:    { x: u + d,         y: v,     w,    h: d },
    bottom: { x: u + d + w,     y: v,     w,    h: d },
    right:  { x: u,             y: v + d, w: d, h },
    front:  { x: u + d,         y: v + d, w,    h },
    left:   { x: u + d + w,     y: v + d, w: d, h },
    back:   { x: u + 2 * d + w, y: v + d, w,    h },
  };
}

// BoxGeometry face groups are +x, -x, +y, -y, +z, -z
const FACE_ORDER = ['left', 'right', 'top', 'bottom', 'front', 'back'];
const UV_INSET = 0.02; // fraction of a texel, avoids sampling the neighbour region

/**
 * skinBox(w,h,d, u,v, skin, o) — a cuboid of w*h*d skin pixels whose six faces
 * map Minecraft-style onto the skin region starting at (u,v).
 *   o.sx/sy/sz   stretch the geometry without changing the UVs (bulk / belly)
 *   o.px         metres per pixel (default PX)
 *   o.pivot      [fx,fy,fz] in -0.5..0.5 box units: that point becomes the mesh
 *                origin, e.g. [0,0.5,0] = pivot at the top centre (limbs).
 */
export function skinBox(w, h, d, u, v, skin, o = {}) {
  const size = skin?.size ?? S;
  const p = o.px ?? PX;
  const W = w * p * (o.sx ?? 1), H = h * p * (o.sy ?? 1), D = d * p * (o.sz ?? 1);
  const geo = new THREE.BoxGeometry(W, H, D);
  const R = boxRegions(w, h, d, u, v);
  const uv = geo.attributes.uv;
  for (let f = 0; f < 6; f++) {
    const r = R[FACE_ORDER[f]];
    for (let k = 0; k < 4; k++) {
      const i = f * 4 + k;
      const u0 = uv.getX(i), v0 = uv.getY(i);
      const px = r.x + (u0 ? r.w - UV_INSET : UV_INSET);
      const py = r.y + (v0 ? UV_INSET : r.h - UV_INSET);
      uv.setXY(i, px / size, 1 - py / size);
    }
  }
  uv.needsUpdate = true;
  if (o.pivot) geo.translate(-o.pivot[0] * W, -o.pivot[1] * H, -o.pivot[2] * D);
  geo.userData.noVox = true;
  return geo;
}

// Geometry cache: every mob of a kind reuses the same BufferGeometries.
// Shared geometries are tagged so corpse cleanup never disposes them.
const _geoCache = new Map();
export function sharedBox(w, h, d, u, v, o = {}) {
  const pv = o.pivot ? o.pivot.join(',') : '';
  const key = `${w},${h},${d},${u},${v},${o.sx ?? 1},${o.sy ?? 1},${o.sz ?? 1},${o.px ?? PX},${pv}`;
  let g = _geoCache.get(key);
  if (!g) {
    g = skinBox(w, h, d, u, v, null, o);
    g.userData.shared = true;
    g.dispose = () => {}; // shared across instances: never freed by a single corpse
    _geoCache.set(key, g);
  }
  return g;
}

// ---------------------------------------------------------------------------
// Tiny pixel painter
// ---------------------------------------------------------------------------
function mulberry32(a) {
  return function () {
    a |= 0; a = (a + 0x6D2B79F5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
function hashStr(s) {
  let h = 2166136261;
  for (let i = 0; i < s.length; i++) h = Math.imul(h ^ s.charCodeAt(i), 16777619);
  return h >>> 0;
}
const rgb = (hex) => [(hex >> 16) & 255, (hex >> 8) & 255, hex & 255];
const toHex = (c) => (Math.round(Math.min(255, c[0])) << 16) | (Math.round(Math.min(255, c[1])) << 8) | Math.round(Math.min(255, c[2]));
const shade = (c, k) => [c[0] * k, c[1] * k, c[2] * k];
const mix = (a, b, t) => [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t, a[2] + (b[2] - a[2]) * t];

class Pix {
  constructor(seed, bg = null) {
    this.d = new Uint8ClampedArray(S * S * 4);
    this.r = mulberry32(seed);
    if (bg) for (let i = 0; i < S * S; i++) { this.d[i * 4] = bg[0]; this.d[i * 4 + 1] = bg[1]; this.d[i * 4 + 2] = bg[2]; this.d[i * 4 + 3] = 255; }
  }
  set(x, y, c) {
    x |= 0; y |= 0;
    if (x < 0 || y < 0 || x >= S || y >= S) return;
    const i = (y * S + x) * 4;
    this.d[i] = c[0]; this.d[i + 1] = c[1]; this.d[i + 2] = c[2]; this.d[i + 3] = 255;
  }
  mul(x, y, k) {
    if (x < 0 || y < 0 || x >= S || y >= S) return;
    const i = (y * S + x) * 4;
    this.d[i] *= k; this.d[i + 1] *= k; this.d[i + 2] *= k;
  }
  // Face-local pixel (clipped to the face rect)
  at(R, i, j, c) { i = Math.round(i); j = Math.round(j); if (i >= 0 && j >= 0 && i < R.w && j < R.h) this.set(R.x + i, R.y + j, c); }
  // Noisy fill — per-pixel brightness jitter, the core of the MC look
  fill(R, c, jit = 0.1) {
    for (let j = 0; j < R.h; j++) for (let i = 0; i < R.w; i++) {
      this.at(R, i, j, shade(c, 1 + (this.r() - 0.5) * 2 * jit));
    }
  }
  // Irregular blob
  blob(R, cx, cy, rad, c, c2 = null, jit = 0.12) {
    for (let j = Math.floor(cy - rad - 1); j <= cy + rad + 1; j++) for (let i = Math.floor(cx - rad - 1); i <= cx + rad + 1; i++) {
      const dd = Math.hypot(i - cx, j - cy) + (this.r() - 0.5) * 1.1;
      if (dd <= rad) this.at(R, i, j, shade(c2 && dd > rad - 0.9 ? c2 : c, 1 + (this.r() - 0.5) * 2 * jit));
    }
  }
  canvas() {
    const cv = document.createElement('canvas');
    cv.width = cv.height = S;
    cv.getContext('2d').putImageData(new ImageData(this.d, S, S), 0, 0);
    return cv;
  }
}

// Minecraft entity-texture shading baked per face: lit top, dark underside,
// sides/back a step darker, a soft top-to-bottom gradient and darker edges.
const FACE_SHADE = { top: 1.12, bottom: 0.6, front: 1.0, back: 0.8, left: 0.87, right: 0.87 };
function shadeBox(P, R) {
  for (const name of Object.keys(R)) {
    const f = R[name];
    const side = name !== 'top' && name !== 'bottom';
    for (let j = 0; j < f.h; j++) for (let i = 0; i < f.w; i++) {
      let k = FACE_SHADE[name];
      if (side && f.h > 2) k *= 1.08 - 0.18 * (j / (f.h - 1));
      if (side && f.w > 2 && (i === 0 || i === f.w - 1)) k *= 0.92;
      P.mul(f.x + i, f.y + j, k);
    }
  }
}

function texFrom(pix) {
  const t = new THREE.CanvasTexture(pix.canvas());
  t.magFilter = THREE.NearestFilter;
  t.minFilter = THREE.NearestFilter;
  t.generateMipmaps = false;
  t.colorSpace = THREE.SRGBColorSpace;
  t.userData.noVox = true;
  return t;
}

