// ---------------------------------------------------------------------------
// Humanoid skin painter
// ---------------------------------------------------------------------------
// Clothes the hosts died in. Each outfit is a small rule set read by the
// torso / arm / leg painters below. Original designs.
const TEE_COLS = [0x2f7f86, 0x8a2f2f, 0x5a5a62, 0xb08a2a, 0x2e3e6e, 0x3e6a3a, 0xc8c8be];
const DENIM = [0x41598a, 0x384a74, 0x52638a];
const HAIR = [[46, 32, 24], [24, 20, 20], [146, 116, 66], [118, 58, 28], [112, 108, 102], [70, 46, 30]];
function makeOutfit(style, opts, r) {
  const pick = (a) => a[Math.floor(r() * a.length)];
  const uniform = style.camo || style.robe || style.hood || style.chitin || (style.shirtColors && !style.outfits);
  const key = uniform ? 'uniform' : pick(style.outfits ?? ['tee']);
  const O = { key, sleeves: 'short', pants: rgb(pick(DENIM)), shoes: [46, 38, 32], sole: [22, 18, 16], denim: true };
  switch (key) {
    case 'tee': O.shirt = rgb(opts.shirtColor ?? pick(TEE_COLS)); break;
    case 'flannel': O.shirt = rgb(pick([0x8e2a24, 0x2e5a34, 0x2a3e6a])); O.check = [26, 22, 24]; O.sleeves = 'long'; break;
    case 'business':
      O.shirt = [212, 210, 198]; O.tie = rgb(pick([0x8a1e22, 0x1e2a5a, 0x2a2a2a])); O.sleeves = 'long';
      O.pants = [62, 62, 70]; O.denim = false; O.shoes = [28, 24, 22]; O.belt = [26, 22, 20]; break;
    case 'hoodie':
      O.shirt = rgb(opts.shirtColor ?? pick([0x6a6a72, 0x3a3a40, 0x4a6a44, 0x7a3236])); O.sleeves = 'long'; O.hood = true;
      if (r() < 0.5) { O.pants = rgb(pick([0x74747a, 0x404048])); O.denim = false; }
      O.shoes = [196, 196, 190]; O.sole = [116, 116, 112]; break;
    case 'gown': O.shirt = [150, 186, 200]; O.dots = [100, 134, 156]; O.gown = true; O.pants = null; O.shoes = null; break;
    case 'worker':
      O.shirt = [88, 88, 94]; O.vest = [228, 112, 22]; O.stripe = [222, 222, 204];
      if (r() < 0.5) { O.pants = [92, 72, 48]; O.denim = false; } O.shoes = [76, 50, 28]; break;
    case 'police':
      O.shirt = [46, 62, 108]; O.badge = [222, 186, 72]; O.belt = [22, 22, 24];
      O.pants = [40, 50, 84]; O.denim = false; O.shoes = [16, 16, 18]; break;
    default:   // uniform: the variant's own fixed shirt / trouser colours
      O.shirt = rgb(opts.shirtColor ?? pick(style.shirtColors ?? SHIRTS));
      O.pants = rgb(opts.pantsColor ?? pick(style.pantsColors ?? PANTS)); O.denim = false;
      O.sleeves = 'long'; O.camo = !!style.camo;
  }
  if (opts.pantsColor && key !== 'uniform' && O.pants) O.pants = rgb(opts.pantsColor);
  return O;
}

function palette(style, opts, r) {
  const pick = (a) => a[Math.floor(r() * a.length)];
  const skin = rgb(opts.skinColor ?? pick(style.skins ?? HOST));
  const O = makeOutfit(style, opts, r);
  return {
    ...FL,
    skin,
    skin2: mix(shade(skin, 0.72), FL.maroon, 0.3),     // bruised, purple under the skin
    skin3: shade(mix(skin, [196, 200, 170], 0.25), 1.06), // pale, waxy patches
    rot: mix(shade(skin, 0.6), [58, 46, 26], 0.45),     // dark decay
    blood: [120, 16, 16], blood2: [76, 10, 12],
    dirt: [74, 60, 42],
    pus: style.bile ? [200, 210, 70] : FL.pus,
    O,
    cloth: O.shirt, cloth2: shade(O.shirt, 0.7),
    pants: O.pants ?? skin,
    hair: pick(HAIR),
    eye: rgb(opts.eyeColor ?? 0xffc83a),
  };
}

function paintHumanoid(style, opts, seed) {
  const P = new Pix(seed);                      // colour skin
  const E = new Pix(seed + 1, [0, 0, 0]);       // emissive mask (black = no glow)
  const r = P.r;
  const C = palette(style, opts, r);
  const shirt = !opts.shirtless && style.shirt !== false;
  const U = HUMANOID_UV;
  const reg = (k) => { const b = U[k]; return boxRegions(b.w, b.h, b.d, b.u, b.v); };
  const faces = (R) => [R.top, R.bottom, R.right, R.front, R.left, R.back];
  const sides = (R) => [R.right, R.front, R.left, R.back];
  const glow = (R, i, j, k = 1) => E.at(R, i, j, [255 * k, 255 * k, 255 * k]);

  // Muscle fibre (flayed hosts): vertical crimson strands with pink sheen
  const rawPix = (i, j, q) => ((i + (j >> 2)) % 2) ? C.flesh : mix(C.flesh, C.fleshD, q < 0.3 ? 0.9 : 0.4);
  const skinFill = (R) => {
    for (let j = 0; j < R.h; j++) for (let i = 0; i < R.w; i++) {
      const q = r();
      let c = q < 0.1 ? C.skin2 : q < 0.2 ? C.skin3 : q < 0.26 ? mix(C.skin, C.rot, 0.5) : C.skin;
      if (style.raw) c = q > 0.93 ? C.fleshL : rawPix(i, j, q);
      P.at(R, i, j, shade(c, 0.9 + r() * 0.2));
    }
    if (style.raw) {                               // tatters of the host's skin
      const n = 1 + Math.floor(r() * 2);
      for (let k = 0; k < n; k++) P.blob(R, r() * R.w, r() * R.h, 0.9 + r() * 1.0, C.skin, C.skin2);
    } else {
      // rotting patches: dark decay ringed by bruising, the odd open sore
      if (R.w * R.h >= 16 && r() < 0.75) P.blob(R, r() * R.w, r() * R.h, 0.7 + r() * 0.9, C.rot, C.skin2);
      if (R.w * R.h >= 16 && r() < 0.3) { const i = r() * R.w, j = r() * R.h; P.at(R, i, j, C.blood2); P.at(R, i + 1, j, C.blood); }
    }
    if (r() < 0.55) {                              // dark maroon vein creeping across
      let i = Math.floor(r() * R.w), j = 0;
      while (j < R.h) { P.at(R, i, j, C.vein); if (style.glowVeins) { P.at(R, i, j, C.fleshL); glow(R, i, j, 0.55); } i += Math.floor(r() * 3) - 1; j++; }
    }
  };
  // Blood: a splash with drips running down the face (j grows downward)
  const splat = (R, cx, cy, n = 4) => {
    for (let k = 0; k < n; k++) P.at(R, cx + (r() - 0.5) * 2.4, cy + (r() - 0.5) * 2, r() < 0.5 ? C.blood : C.blood2);
    const drips = 1 + Math.floor(r() * 2);
    for (let k = 0; k < drips; k++) {
      const x = cx + (r() - 0.5) * 2, len = 1 + Math.floor(r() * 3);
      for (let d = 0; d < len; d++) P.at(R, x, cy + 1 + d, d === len - 1 ? C.blood2 : C.blood);
    }
  };
  const tear = (R, cx, cy, rad) => {      // ripped cloth: frayed dark edge, rotting skin under
    P.blob(R, cx, cy, rad + 0.6, shade(C.cloth2, 0.7), null, 0.1);
    P.blob(R, cx, cy, rad, C.skin, C.skin2);
    if (r() < 0.5) P.at(R, cx, cy, C.rot);
  };
  // Parasite flesh rupture: dark rim, crimson body, pink highlight, pus/bone core
  const burst = (R, cx, cy, rad) => {
    P.blob(R, cx, cy, rad + 0.8, C.fleshD, null, 0.1);
    P.blob(R, cx, cy, rad, C.flesh, null, 0.14);
    P.at(R, cx - 0.6, cy - 0.6, C.fleshL);
    const q = r();
    if (q < 0.35) { P.at(R, cx, cy, C.pus); glow(R, cx, cy, 0.4); }
    else if (q < 0.6) P.at(R, cx, cy, C.bone);
    else if (q < 0.8) P.at(R, cx, cy, C.voidC);
    if (style.glowVeins) glow(R, cx + 1, cy, 0.5);
  };
  const pustule = (R, i, j) => { P.at(R, i, j, C.pus); P.at(R, i + 1, j, C.pusD); P.at(R, i, j + 1, C.pusD); glow(R, i, j, 0.45); };
  const O = C.O;
  // Shirt pixel for torso/arm faces. part: chest|abdomen|arm, fn: face name
  const shirtPix = (part, fn, i, j) => {
    let c = O.shirt;
    if (O.camo && r() < 0.35) c = r() < 0.5 ? [58, 66, 40] : [84, 78, 52];
    if (O.check) { const a = i % 3 === 0, b = (j + (part === 'abdomen' ? 6 : 0)) % 3 === 0; if (a && b) c = O.check; else if (a || b) c = mix(c, O.check, 0.45); }
    if (O.dots && (i * 3 + j * 5) % 7 === 0) c = O.dots;
    const front = fn === 'front';
    if (part !== 'arm') {
      if (O.vest && fn !== 'bottom' && !(front && (i === 3 || i === 4))) {
        c = O.vest;
        if ((part === 'chest' && j === 3) || (part === 'abdomen' && j === 1)) c = O.stripe;
      }
      if (O.tie && front) {
        if (part === 'chest' && j === 0 && (i === 2 || i === 5)) c = shade(O.shirt, 0.72);       // collar
        if ((i === 3 || i === 4) && ((part === 'chest' && j >= 1) || (part === 'abdomen' && j <= 1))) c = (part === 'chest' && j === 1) ? shade(O.tie, 0.8) : O.tie;
        if (part === 'abdomen' && j === 2 && i === 3) c = O.tie;
      }
      if (O.hood) {
        if (part === 'chest' && fn === 'back' && j < 2) c = shade(c, 0.72);                      // hood folds
        if (part === 'chest' && fn === 'top') c = shade(c, 0.8);
        if (part === 'chest' && front && (i === 2 || i === 5) && j <= 2) c = [214, 214, 206];     // drawstrings
        if (part === 'abdomen' && front && j >= 1 && j <= 3 && i >= 1 && i <= 6) c = (j === 1 || i === 1 || i === 6) ? shade(O.shirt, 0.7) : shade(O.shirt, 0.88);
      }
      if (O.badge && part === 'chest' && front) {
        if (i === 5 && j === 1) c = O.badge;
        else if (j === 1 && (i === 1 || i === 2)) c = shade(O.shirt, 0.7);                      // pocket flap
        else if (i === 3 && j > 0) c = shade(O.shirt, 0.82);                                     // button line
      }
    }
    return shade(c, 0.9 + r() * 0.2);
  };
  const shirtFace = (part, fn, R) => {
    for (let j = 0; j < R.h; j++) for (let i = 0; i < R.w; i++) P.at(R, i, j, shirtPix(part, fn, i, j));
  };
  const stain = (R, big = false) => {           // dirt + blood on clothes, ripped holes
    if (r() < 0.55) tear(R, r() * R.w, r() * R.h, 0.6 + r() * (big ? 1 : 0.6));
    if (r() < 0.7) splat(R, r() * R.w, r() * R.h * 0.6, big ? 5 : 3);
    if (r() < 0.4) P.blob(R, r() * R.w, R.h - 1 - r() * 2, 0.8 + r() * 0.6, shade(C.dirt, 0.9 + r() * 0.2), null, 0.15);
  };
  // ---- Skull 8x6x8 ----
  {
    const R = reg('skull');
    for (const f of faces(R)) skinFill(f);
    const F = R.front;
    for (let i = 0; i < 8; i++) P.at(F, i, 0, shade(C.skin2, 0.95));   // brow
    const eye = (i, j) => { P.at(F, i, j, C.eye); glow(F, i, j); };
    const sock = (i, j) => P.at(F, i, j, C.voidC);
    switch (style.eyes) {
      case 'many':   // original eyes + parasite eyes opened in the cheeks/brow
        for (const [i, j] of [[1, 2], [2, 2], [5, 2], [6, 2], [4, 1], [3, 3], [0, 1], [7, 3]]) { sock(i, j); if (r() < 0.8) eye(i, j); }
        break;
      case 'cluster': {
        const sd = r() < 0.5 ? 1 : 5;
        for (const [i, j] of [[0, 1], [1, 1], [0, 2], [1, 2]]) sock(sd + i, j);
        eye(sd, 1); eye(sd + 1, 2); eye(sd + (sd === 1 ? 2 : -1), 1);
        burst(F, sd === 1 ? 5.5 : 1.5, 2, 1.1);       // flesh grown over the other eye
        break;
      }
      case 'slit':
        for (let i = 1; i < 7; i++) { sock(i, 2); if (i !== 3 && i !== 4) eye(i, 2); }
        break;
      case 'one':
        for (const [i, j] of [[3, 1], [4, 1], [3, 2], [4, 2]]) eye(i, j);
        sock(2, 1); sock(5, 2);
        break;
      case 'none': // eyeless, face swallowed by flesh
        for (let i = 1; i < 7; i++) P.at(F, i, 2, C.fleshD);
        break;
      default:
        sock(1, 2); sock(2, 2); sock(5, 2); sock(6, 2);
        eye(2, 2); eye(5, 2);
    }
    // Sunken, bruised eye sockets (dark rim above and below the eyes)
    if (style.eyes === 'pair' || style.eyes === undefined) {
      for (const i of [1, 2, 5, 6]) P.at(F, i, 3, mix(C.skin, C.skin2, 0.7));
    }
    // Rotted-off nose, then either a torn cheek showing the teeth or a
    // parasite rupture, upper teeth on the bottom edge
    sock(3, 3); sock(4, 3);
    const cheek = r() < 0.5 ? 0 : 6;
    if (r() < 0.55) { P.at(F, cheek, 4, C.mouth); P.at(F, cheek + 1, 4, C.tooth); P.at(F, cheek, 3, C.blood2); P.at(F, cheek + 1, 5, C.tooth); }
    else if (r() < 0.8) burst(F, cheek ? 6.2 : 0.8, 4, 0.7);
    for (let i = 1; i < 7; i++) P.at(F, i, 5, i % 2 ? C.tooth : C.mouth);
    if (r() < 0.6) P.at(F, 1 + Math.floor(r() * 6), 5, C.mouth);         // missing tooth
    if (style.seam) for (let j = 0; j < 6; j++) { P.at(F, 3 + (j % 2), j, C.fleshD); P.at(R.top, 3 + (j % 2), 7 - j, C.flesh); }
    P.fill(R.bottom, C.mouth, 0.2);
    for (let i = 1; i < 7; i++) P.at(R.bottom, i, 0, i % 2 ? C.tooth : C.fleshD);
    // Hair: long, short or balding, with the scalp rotting through in places
    const hairStyle = style.hair ? 'long' : (style.raw || style.chitin || style.hood || style.crown) ? null
      : ['short', 'short', 'long', 'bald', 'messy', null][Math.floor(r() * 6)];
    if (hairStyle) {
      const hp = (f, i, j, keep = 0.92) => { if (r() < keep) P.at(f, i, j, shade(C.hair, 0.85 + r() * 0.3)); };
      const keep = hairStyle === 'bald' ? 0.45 : 0.92;
      for (let j = 0; j < 8; j++) for (let i = 0; i < 8; i++) {
        if (hairStyle === 'bald' && i > 1 && i < 6 && j > 1 && j < 6) continue;   // bare crown
        hp(R.top, i, j, keep);
      }
      const backRows = hairStyle === 'long' ? 6 : hairStyle === 'bald' ? 2 : 3;
      for (let j = 0; j < backRows; j++) for (let i = 0; i < 8; i++) hp(R.back, i, j, keep);
      for (const f of [R.right, R.left]) for (let j = 0; j < 6; j++) for (let i = 0; i < 8; i++) {
        const back = f === R.right ? i < 4 : i >= 4;     // half of each side face nearest the back
        if (j < (hairStyle === 'bald' ? 1 : 2) || (hairStyle === 'long' && back) || (hairStyle === 'messy' && back && j < 4 && r() < 0.6)) hp(f, i, j, keep);
      }
      if (hairStyle !== 'bald') for (let i = 0; i < 8; i++) if (hairStyle === 'messy' ? r() < 0.75 : i !== 3 && i !== 4 || r() < 0.4) P.at(F, i, 0, shade(C.hair, 0.9 + r() * 0.2));
    } else if (style.hood) {
      for (const f of [R.top, R.back, R.right, R.left]) P.fill(f, C.cloth, 0.12);
      for (let i = 0; i < 8; i++) P.at(F, i, 0, C.cloth2);
      for (const f of [R.right, R.left]) for (let j = 2; j < 6; j++) P.at(f, f === R.right ? 7 : 0, j, C.cloth2);
    }
    if (style.chitin) {
      for (const f of [R.top, R.back]) for (let j = 0; j < f.h; j++) for (let i = 0; i < f.w; i++) {
        if ((i + 2 * j) % 5 === 0 || j % 3 === 0) P.at(f, i, j, C.boneD); else if (r() < 0.6) P.at(f, i, j, shade(C.bone, 0.75 + r() * 0.2));
      }
    }
    // Scalp ruptures: the parasite pushing out of the skull
    if (style.crown || r() < 0.6) burst(R.top, 2 + r() * 4, 2 + r() * 4, style.crown ? 2.2 : 1.2);
    if (style.crown) { burst(R.back, r() * 8, 1, 1.4); burst(r() < 0.5 ? R.left : R.right, 3, 1, 1.2); }
  }

  // ---- Jaw 8x2x6 ----
  {
    const R = reg('jaw');
    for (const f of faces(R)) skinFill(f);
    for (let i = 0; i < 8; i++) P.at(R.front, i, 0, (i > 0 && i < 7 && i % 2 === 0) ? C.tooth : C.fleshD);
    for (let i = 0; i < 8; i++) P.at(R.front, i, 1, r() < 0.4 ? C.fleshD : shade(C.skin, 0.85));
    P.fill(R.top, C.mouth, 0.25);
    for (let j = 1; j < 5; j++) P.at(R.top, 3 + (j % 2), j, shade(C.fleshL, 0.7));   // tongue / feeding tendril
    for (let i = 1; i < 7; i++) P.at(R.top, i, 5, i % 2 ? C.mouth : C.tooth);           // lower teeth, front edge only
    for (let j = 0; j < 6; j++) { P.at(R.top, 0, j, shade(C.skin2, 0.8)); P.at(R.top, 7, j, shade(C.skin2, 0.8)); }   // gums / lips
    for (let i = 1; i < 7; i++) if (r() < 0.45) P.at(R.front, i, 1, r() < 0.5 ? C.blood : C.blood2);   // blood on the chin
    if (style.bile) for (let i = 0; i < 3; i++) { const x = 1 + Math.floor(r() * 6); P.at(R.front, x, 1, C.pus); glow(R.front, x, 1, 0.6); }
  }

  // ---- Chest 8x6x4 / abdomen 8x4x4 ----
  const bursts = style.burst ?? 2;
  const torsoPart = (key, isChest) => {
    const R = reg(key);
    const names = ['top', 'bottom', 'right', 'front', 'left', 'back'];
    faces(R).forEach((f, k) => { if (shirt) shirtFace(key, names[k], f); else skinFill(f); });
    if (shirt) {
      for (const f of sides(R)) stain(f, f === R.front);
      if (isChest && O.key === 'tee') for (let i = 2; i < 6; i++) P.at(R.front, i, 0, i === 2 || i === 5 ? C.skin : shade(C.skin, 0.9));  // neckline
      if (isChest && !O.hood && O.key !== 'business' && O.key !== 'police') for (let i = 2; i < 6; i++) P.at(R.top, i, 3, C.skin);         // collar opening
    }
    if (isChest && r() < 0.65) splat(R.front, 3 + r() * 2, 0, 4);   // blood run off the chin
    if (shirt && !isChest && !O.gown) {            // ragged hem
      for (const f of sides(R)) for (let i = 0; i < f.w; i++) if (r() < 0.35) P.at(f, i, f.h - 1, C.skin);
    }
    if (style.robe && !isChest) for (const f of sides(R)) for (let i = 0; i < f.w; i++) P.at(f, i, f.h - 1, C.cloth2);
    const F = R.front;
    if (isChest && (style.ribs === 'full' || (style.ribs === 'some' && r() < 0.6) || style.raw)) {
      // Burst ribcage: black cavity, bone ribs, crimson tissue
      for (let j = 1; j < 5; j++) for (let i = 2; i < 6; i++) P.at(F, i, j, j % 2 ? C.bone : (i === 3 || i === 4 ? C.voidC : C.flesh));
      P.at(F, 1, 2, C.fleshD); P.at(F, 6, 3, C.fleshD); P.at(F, 1, 4, C.flesh); P.at(F, 6, 1, C.flesh);
    }
    if (style.spine || style.chitin) for (let j = 0; j < R.back.h; j += 1) P.at(R.back, 3 + (j % 2), j, j % 2 ? C.boneD : C.bone);
    if (style.chitin && isChest) for (const f of [R.top, R.left, R.right]) for (let i = 0; i < f.w; i++) P.at(f, i, 0, shade(C.bone, 0.8 + r() * 0.2));
    if (style.seam) for (let j = 0; j < F.h; j++) { P.at(F, 3, j, C.voidC); P.at(F, 4, j, j % 2 ? C.tooth : C.fleshD); P.at(F, 2, j, C.flesh); P.at(F, 5, j, C.flesh); }
    if (style.pustules) for (let k = 0; k < 3; k++) pustule(F, Math.floor(r() * 7), Math.floor(r() * (F.h - 1)));
    const n = isChest ? Math.ceil(bursts / 2) : Math.floor(bursts / 2);
    for (let k = 0; k < n; k++) {
      const f = [R.front, R.back, R.left, R.right, R.back][Math.floor(r() * 5)];
      burst(f, r() * f.w, r() * f.h, 0.8 + r() * 0.8);
    }
    if (isChest) burst(R.back, 2 + r() * 4, 1.5, 1.4);      // where the back tendrils erupt
    if (isChest && style.crown && r() < 0.8) burst(R.top, r() < 0.5 ? 1 : 6, 1.5, 1.2);
  };
  torsoPart('chest', true);
  torsoPart('abdomen', false);

  // ---- Pelvis 8x2x4 ----
  {
    const R = reg('pelvis');
    for (const f of faces(R)) { if (style.raw) skinFill(f); else P.fill(f, style.robe || O.gown ? C.cloth : C.pants, 0.12); }
    if (O.gown && !style.raw) for (const f of faces(R)) for (let j = 0; j < f.h; j++) for (let i = 0; i < f.w; i++) if ((i * 3 + j * 5) % 7 === 0) P.at(f, i, j, O.dots);
    if (!style.raw && !style.robe && !O.gown) {
      const belt = O.belt ?? [52, 40, 30];
      for (const f of sides(R)) for (let i = 0; i < f.w; i++) P.at(f, i, 0, shade(belt, 0.9 + r() * 0.2));
      P.at(R.front, 3, 0, [176, 160, 104]); P.at(R.front, 4, 0, [132, 118, 76]);   // buckle
      if (O.denim) { P.at(R.front, 1, 1, shade(C.pants, 0.7)); P.at(R.front, 6, 1, shade(C.pants, 0.7)); }  // pocket seams
    }
  }

  // ---- Arms ----
  {
    const R = reg('upperArm');
    for (const f of faces(R)) skinFill(f);
    const long = O.sleeves === 'long';
    if (shirt) for (const f of faces(R)) if (f !== R.bottom) for (let j = 0; j < f.h; j++) for (let i = 0; i < f.w; i++) {
      if (long || j < 3 || (j === 3 && r() < 0.5) || f === R.top) P.at(f, i, j, shirtPix('arm', 'side', i, j));
    }
    if (shirt) { const f = [R.front, R.left, R.right][Math.floor(r() * 3)]; if (r() < 0.6) (long ? tear : splat)(f, r() * 4, 1 + r() * 4, long ? 0.7 : 3); }
    if (style.chitin) for (let i = 0; i < 4; i++) { P.at(R.top, i, 0, C.bone); P.at(R.left, i, 0, C.boneD); P.at(R.right, i, 0, C.boneD); }
    burst(R.left, 1.5, 4, 0.8);
  }
  {
    const R = reg('forearm');
    for (const f of faces(R)) skinFill(f);
    if (style.robe || (shirt && O.sleeves === 'long')) for (const f of faces(R)) if (f !== R.bottom) for (let j = 0; j < 4; j++) for (let i = 0; i < f.w; i++) {
      if (j === 3 && !style.robe) { if (r() < 0.6) P.at(f, i, j, shade(C.cloth2, 0.85)); continue; }           // ragged cuff
      P.at(f, i, j, style.robe ? shade(C.cloth, 0.9 + r() * 0.2) : shirtPix('arm', 'side', i, j));
    }
    if (r() < 0.7) splat(R.front, r() * 4, 3, 2);                                                       // bloody hands
    // Hand: bruised fingers ending in bone claws
    for (const f of sides(R)) for (let i = 0; i < f.w; i++) { P.at(f, i, 4, shade(C.skin2, 0.95)); P.at(f, i, 5, r() < 0.3 ? C.fleshD : C.skin2); }
    for (let i = 0; i < 4; i++) P.at(R.front, i, 5, i % 2 ? C.boneD : C.bone);
    // hand end: knuckles with dark gaps between the fingers and torn nails
    for (let j = 0; j < 4; j++) for (let i = 0; i < 4; i++) P.at(R.bottom, i, j, shade(j === 3 ? C.skin2 : (i === 1 && j < 3) ? mix(C.skin, C.voidC, 0.45) : C.skin, 0.92 + r() * 0.16));
    P.at(R.bottom, 0, 3, C.boneD); P.at(R.bottom, 3, 3, C.boneD);
    burst(R.right, 2, 1.5, 0.8);
  }

  // ---- Legs 4x12x4 ----
  {
    const R = reg('leg');
    for (const f of faces(R)) {
      if (style.raw) { skinFill(f); continue; }
      if (O.gown && !style.robe) {
        // hospital gown to the knee, bare rotting shins, bare feet
        skinFill(f);
        for (let j = 0; j < 4; j++) for (let i = 0; i < f.w; i++) P.at(f, i, j, (i * 3 + j * 5) % 7 === 0 ? O.dots : shade(O.shirt, 0.9 + r() * 0.2));
        for (let i = 0; i < f.w; i++) { P.at(f, i, 11, shade(C.skin2, 0.8)); if (r() < 0.4) P.at(f, i, 4, C.cloth2); }
      } else {
        const shoe = O.shoes ?? C.skin2;
        for (let j = 0; j < f.h; j++) for (let i = 0; i < f.w; i++) {
          let c;
          if (j < 10) {
            c = r() < 0.14 ? shade(C.pants, 0.74) : C.pants;
            if (O.denim && (j === 5 || j === 6) && r() < 0.6) c = mix(C.pants, [200, 210, 220], 0.18);   // worn knees
            if (style.robe) c = r() < 0.2 ? C.cloth2 : C.cloth;
          } else c = j === 11 ? (O.sole ?? shade(shoe, 0.6)) : shoe;
          P.at(f, i, j, shade(c, 0.9 + r() * 0.2));
        }
      }
      if (f !== R.top && f !== R.bottom) {
        if (!O.gown && r() < 0.45) tear(f, r() * 4, 5 + r() * 2, 0.7);            // ripped knee
        if (r() < 0.6) P.blob(f, r() * 4, 8 + r() * 2, 0.9 + r() * 0.5, shade(C.dirt, 0.9 + r() * 0.2), null, 0.15);   // mud
        if (r() < 0.5) splat(f, r() * 4, 1 + r() * 4, 3);
        if (r() < 0.35) burst(f, r() * 4, 2 + r() * 6, 0.7);
      }
    }
    P.fill(R.bottom, [40, 34, 30], 0.15);
  }

  // ---- Growth cuboids ----
  {
    const R = reg('sac');                     // pus sac: veined yellow bladder
    for (const f of faces(R)) {
      P.fill(f, mix(C.pus, C.flesh, 0.25), 0.1);
      for (let k = 0; k < 3; k++) { const i = Math.floor(r() * f.w), j = Math.floor(r() * f.h); P.at(f, i, j, shade(C.pus, 1.15)); glow(f, i, j, 0.7); }
      for (let j = 0; j < f.h; j++) if (r() < 0.7) P.at(f, Math.floor(r() * f.w), j, C.maroon);
    }
  }
  {
    const R = reg('shelf');                   // layered flesh fold
    for (let j = 0; j < 6; j++) for (let i = 0; i < 6; i++) {
      const ring = Math.max(Math.abs(i - 2.5), Math.abs(j - 2.5));
      P.at(R.top, i, j, shade(ring > 2 ? C.fleshD : ring > 1 ? C.flesh : C.fleshL, 0.92 + r() * 0.16));
      P.at(R.bottom, i, j, shade(i % 2 ? C.voidC : C.mouth, 0.9 + r() * 0.2));
    }
    for (const f of sides(R)) { P.fill(f, C.flesh, 0.1); for (let i = 0; i < f.w; i++) P.at(f, i, 1, i % 2 ? C.tooth : C.fleshD); }
  }
  {
    const R = reg('mass');                    // tumorous flesh with parasite eyes
    for (const f of faces(R)) {
      for (let j = 0; j < f.h; j++) for (let i = 0; i < f.w; i++) {
        const q = r();
        P.at(f, i, j, shade(q < 0.3 ? C.fleshD : q < 0.75 ? C.flesh : q < 0.9 ? C.maroon : C.fleshL, 0.88 + r() * 0.24));
      }
      if (style.chitin) for (let i = 0; i < f.w; i++) P.at(f, i, (i * 2) % f.h, C.boneD);
      P.at(f, Math.floor(r() * f.w), Math.floor(r() * f.h), C.bone);
      if (f !== R.bottom && r() < 0.7) {
        const i = 1 + Math.floor(r() * 4), j = 1 + Math.floor(r() * 4);
        P.at(f, i, j, C.voidC); P.at(f, i + 1, j, C.eye); glow(f, i + 1, j);
      }
    }
  }
  {
    const R = reg('spike');
    for (const f of faces(R)) P.fill(f, C.bone, 0.08);
    for (const f of sides(R)) { P.at(f, 0, 3, C.boneD); P.at(f, 0, 2, mix(C.bone, C.fleshD, 0.3)); P.at(f, 0, 3, C.flesh); }
  }
  {
    const R = reg('horn');
    for (const f of faces(R)) P.fill(f, C.bone, 0.08);
    for (const f of sides(R)) for (let i = 0; i < 2; i++) { P.at(f, i, 1, C.boneD); P.at(f, i, 3, C.flesh); }
  }
  {
    const R = reg('nose');                    // villager nose (child host)
    for (const f of faces(R)) skinFill(f);
    P.at(R.front, 0, 3, C.voidC); P.at(R.front, 1, 3, C.voidC);
    burst(R.right, 1, 1, 0.6);
  }
  {
    const R = reg('tendril');
    for (const f of faces(R)) for (let j = 0; j < f.h; j++) for (let i = 0; i < f.w; i++) P.at(f, i, j, shade(j % 2 ? C.fleshD : C.flesh, 0.9 + r() * 0.2));
  }

  if (style.frost) {
    // rime along the top edges and over the crown, a few pale ice glazes
    const rime = [214, 234, 248], ice = [182, 214, 240], iceE = [150, 192, 228];
    for (const k of ['skull', 'jaw', 'chest', 'abdomen', 'pelvis', 'upperArm', 'forearm', 'leg']) {
      const R = reg(k);
      for (const f of faces(R)) {
        if (f === R.bottom) continue;
        if (f === R.top) { for (let j = 0; j < f.h; j++) for (let i = 0; i < f.w; i++) if (r() < 0.6) P.at(f, i, j, shade(rime, 0.92 + r() * 0.1)); continue; }
        for (let i = 0; i < f.w; i++) if (r() < 0.75) P.at(f, i, 0, shade(rime, 0.92 + r() * 0.1));
        if (f.w * f.h >= 24 && r() < 0.5) P.blob(f, r() * f.w, 1 + r() * (f.h - 2), 0.6 + r() * 0.6, ice, iceE, 0.06);
      }
    }
  }
  for (const k of Object.keys(U)) shadeBox(P, reg(k));
  return { map: texFrom(P), emissiveMap: texFrom(E), eyeHex: toHex(C.eye) };
}

const _cache = new Map();
/** Cached {map, emissiveMap} for a humanoid style. One canvas per key. */
export function getHumanoidSkin(styleKey, variantIdx, opts) {
  const key = `${styleKey}#${variantIdx}#${opts.skinColor ?? ''}#${opts.shirtColor ?? ''}#${opts.pantsColor ?? ''}#${opts.eyeColor ?? ''}#${opts.shirtless ? 1 : 0}`;
  let s = _cache.get(key);
  if (!s) {
    const style = STYLES[styleKey] ?? STYLES.walker;
    s = paintHumanoid(style, opts, hashStr(key));
    _cache.set(key, s);
  }
  return s;
}
export function getStyle(styleKey) { return STYLES[styleKey] ?? STYLES.walker; }

// ---------------------------------------------------------------------------
// Parasite part atlas (non-humanoid forms + add-ons). 64x64, original art.
// ---------------------------------------------------------------------------
export const PARA_UV = {
  head:   { w: 6, h: 5, d: 6,  u: 0,  v: 0  },  // eye-cluster head
  seg:    { w: 6, h: 4, d: 6,  u: 24, v: 0  },  // carapace body segment
  sac:    { w: 4, h: 4, d: 4,  u: 48, v: 0  },  // pus sac
  eye:    { w: 2, h: 2, d: 2,  u: 48, v: 8  },  // glowing eye glob
  spike:  { w: 1, h: 3, d: 1,  u: 56, v: 8  },
  tendril:{ w: 1, h: 6, d: 1,  u: 60, v: 8  },
  jaw:    { w: 6, h: 2, d: 6,  u: 0,  v: 11 },  // toothed lower jaw
  plate:  { w: 6, h: 1, d: 4,  u: 24, v: 10 },  // bone / chitin plate
  maw:    { w: 4, h: 4, d: 2,  u: 44, v: 12 },  // ring of teeth around a void
  seg2:   { w: 4, h: 3, d: 4,  u: 24, v: 15 },
  limb:   { w: 1, h: 6, d: 1,  u: 40, v: 15 },  // thin leg
  claw:   { w: 1, h: 4, d: 2,  u: 56, v: 15 },
  big:    { w: 8, h: 8, d: 8,  u: 0,  v: 22 },  // brute torso chunk
  arm:    { w: 6, h: 10, d: 6, u: 32, v: 22 },  // massive mutated arm
  limbT:  { w: 2, h: 6, d: 2,  u: 56, v: 22 },  // thicker limb
  limbL:  { w: 1, h: 10, d: 1, u: 56, v: 30 },  // long thin limb
  blade:  { w: 1, h: 10, d: 3, u: 0,  v: 38 },  // bone scythe
  wing:   { w: 10, h: 8, d: 1, u: 8,  v: 38 },  // membrane wing
  petal:  { w: 4, h: 6, d: 1,  u: 30, v: 38 },  // mouth petal (inside = front)
  long:   { w: 2, h: 8, d: 2,  u: 40, v: 38 },  // long neck / torso strut
  robe:   { w: 8, h: 10, d: 5, u: 8,  v: 47 },  // robe / coat skirt
};

// Flesh palettes for the pure parasites
const PALETTES = {
  crimson: { base: [150, 32, 42], plate: [70, 16, 30], belly: [206, 112, 112], eye: 0xffc83a, robe: [40, 22, 30] },
  maroon:  { base: [104, 30, 62], plate: [40, 12, 30], belly: [176, 88, 124], eye: 0xff9a2a, robe: [30, 20, 34] },
  pale:    { base: [200, 188, 176], plate: [118, 104, 100], belly: [228, 200, 196], eye: 0xff4030, robe: [36, 30, 34] },
  bile:    { base: [176, 140, 62], plate: [100, 62, 30], belly: [220, 196, 112], eye: 0xff6a30, robe: [52, 40, 26] },
  hide:    { base: [118, 104, 92], plate: [70, 60, 54], belly: [176, 120, 110], eye: 0xffd040, robe: [40, 34, 30] }, // assimilated animal hide
};

function paintParasite(palKey, seed) {
  const pal = PALETTES[palKey] ?? PALETTES.crimson;
  const P = new Pix(seed);
  const E = new Pix(seed + 1, [0, 0, 0]);
  const r = P.r;
  const base = pal.base, baseD = shade(base, 0.6), baseL = mix(base, FL.fleshL, 0.45);
  const plate = pal.plate, plateL = mix(plate, FL.bone, 0.35);
  const eyeC = rgb(pal.eye);
  const reg = (k) => { const b = PARA_UV[k]; return boxRegions(b.w, b.h, b.d, b.u, b.v); };
  const faces = (R) => [R.top, R.bottom, R.right, R.front, R.left, R.back];
  const sides = (R) => [R.right, R.front, R.left, R.back];
  const glow = (R, i, j, k = 1) => E.at(R, i, j, [255 * k, 255 * k, 255 * k]);
  const eye = (R, i, j) => { P.at(R, i, j, eyeC); glow(R, i, j); };

  // Wet flesh: noisy base, maroon veins, pink sheen, occasional pore/pus pip
  const flesh = (f, c = base) => {
    for (let j = 0; j < f.h; j++) for (let i = 0; i < f.w; i++) {
      const q = r();
      P.at(f, i, j, shade(q < 0.14 ? baseD : q < 0.2 ? baseL : q < 0.26 ? FL.maroon : c, 0.9 + r() * 0.2));
    }
    if (f.w * f.h > 6 && r() < 0.8) {
      let i = Math.floor(r() * f.w), j = 0;
      while (j < f.h) { P.at(f, i, j, FL.vein); i += Math.floor(r() * 3) - 1; j++; }
    }
    if (f.w * f.h > 30 && r() < 0.5) { const i = Math.floor(r() * f.w), j = Math.floor(r() * f.h); P.at(f, i, j, FL.pus); glow(f, i, j, 0.35); }
  };
  // Carapace: dark plates with lighter ridge lines and seams
  const carapace = (f) => {
    for (let j = 0; j < f.h; j++) for (let i = 0; i < f.w; i++) {
      const seam = j % 3 === 2;
      P.at(f, i, j, shade(seam ? shade(plate, 0.6) : (j % 3 === 0 ? plateL : plate), 0.9 + r() * 0.2));
    }
  };
  const bone = (f, dark = 0) => { for (let j = 0; j < f.h; j++) for (let i = 0; i < f.w; i++) P.at(f, i, j, shade(mix(FL.bone, FL.boneD, Math.min(1, dark + (j / Math.max(1, f.h)) * 0.4)), 0.92 + r() * 0.14)); };
  const teethRow = (f, j, a = FL.tooth, b = FL.voidC) => { for (let i = 0; i < f.w; i++) P.at(f, i, j, i % 2 ? b : a); };

  { const R = reg('head');
    for (const f of faces(R)) flesh(f);
    carapace(R.top); for (let i = 0; i < 6; i++) P.at(R.back, i, 0, plateL);
    const F = R.front;
    // Eye cluster above a toothed slit
    for (const [i, j] of [[1, 0], [4, 0], [0, 1], [2, 1], [3, 1], [5, 1], [1, 2], [4, 2]]) P.at(F, i, j, FL.voidC);
    for (const [i, j] of [[1, 0], [4, 1], [2, 1], [5, 1], [1, 2]]) eye(F, i, j);
    teethRow(F, 3, FL.tooth, FL.mouth); for (let i = 0; i < 6; i++) P.at(F, i, 4, i % 2 ? FL.tooth : FL.voidC);
    P.fill(R.bottom, FL.mouth, 0.2); teethRow(R.bottom, 0);
    for (const f of [R.left, R.right]) { P.at(f, 2, 1, FL.voidC); eye(f, 3, 1); } }
  { const R = reg('seg');
    for (const f of faces(R)) flesh(f);
    carapace(R.top);
    for (const f of sides(R)) { for (let i = 0; i < f.w; i++) { P.at(f, i, 0, plateL); P.at(f, i, 1, plate); } }
    P.fill(R.bottom, pal.belly, 0.12);
    for (let j = 1; j < 6; j += 2) for (let i = 0; i < 6; i++) P.at(R.bottom, i, j, shade(pal.belly, 0.75));
    { const f = R.back; P.at(f, 2, 2, FL.pus); glow(f, 2, 2, 0.4); P.at(f, 3, 3, FL.voidC); } }
  { const R = reg('seg2');
    for (const f of faces(R)) flesh(f);
    carapace(R.top);
    for (const f of sides(R)) for (let i = 0; i < f.w; i++) P.at(f, i, 0, plateL);
    P.fill(R.bottom, pal.belly, 0.12); }
  { const R = reg('sac');
    for (const f of faces(R)) {
      P.fill(f, mix(FL.pus, base, 0.22), 0.1);
      for (let k = 0; k < 3; k++) { const i = Math.floor(r() * f.w), j = Math.floor(r() * f.h); P.at(f, i, j, [255, 236, 120]); glow(f, i, j, 0.8); }
      for (let j = 0; j < f.h; j++) if (r() < 0.7) P.at(f, Math.floor(r() * f.w), j, FL.maroon);
    } }
  { const R = reg('eye');
    for (const f of faces(R)) flesh(f, baseD);
    const F = R.front; eye(F, 0, 0); eye(F, 1, 0); eye(F, 0, 1); P.at(F, 1, 1, FL.voidC); glow(F, 1, 1, 0.2);
    eye(R.top, 0, 1); }
  { const R = reg('spike'); for (const f of faces(R)) bone(f); for (const f of sides(R)) P.at(f, 0, 2, mix(FL.boneD, base, 0.5)); }
  { const R = reg('tendril');
    for (const f of faces(R)) for (let j = 0; j < f.h; j++) for (let i = 0; i < f.w; i++) P.at(f, i, j, shade(j % 2 ? baseD : (j < 2 ? base : baseL), 0.9 + r() * 0.2));
    for (const f of sides(R)) { P.at(f, 0, 5, FL.fleshL); } }
  { const R = reg('jaw');
    for (const f of faces(R)) flesh(f);
    P.fill(R.top, FL.mouth, 0.2);
    for (let j = 1; j < 5; j++) { P.at(R.top, 2, j, FL.fleshL); P.at(R.top, 3, j, FL.flesh); }
    for (let j = 0; j < 6; j++) { P.at(R.top, 0, j, j % 2 ? FL.tooth : FL.voidC); P.at(R.top, 5, j, j % 2 ? FL.voidC : FL.tooth); }
    teethRow(R.top, 5); teethRow(R.front, 0); carapace(R.bottom); }
  { const R = reg('plate');
    for (const f of faces(R)) bone(f, 0.1);
    for (let i = 0; i < 6; i++) for (let j = 0; j < 4; j++) if ((i + j) % 3 === 0) P.at(R.top, i, j, FL.boneD);
    P.fill(R.bottom, baseD, 0.1); }
  { const R = reg('maw');
    for (const f of faces(R)) flesh(f);
    const F = R.front;
    for (let j = 0; j < 4; j++) for (let i = 0; i < 4; i++) {
      const edge = i === 0 || j === 0 || i === 3 || j === 3;
      P.at(F, i, j, edge ? ((i + j) % 2 ? FL.tooth : FL.fleshD) : FL.voidC);
    }
    glow(F, 1, 2, 0.25); P.at(F, 1, 2, [120, 20, 30]); }
  { const R = reg('limb');
    for (const f of faces(R)) for (let j = 0; j < f.h; j++) for (let i = 0; i < f.w; i++)
      P.at(f, i, j, shade(j >= 5 ? FL.boneD : (j % 2 ? plate : baseD), 0.9 + r() * 0.2));
    P.fill(R.bottom, FL.boneD, 0.1); }
  { const R = reg('limbL');
    for (const f of faces(R)) for (let j = 0; j < f.h; j++) for (let i = 0; i < f.w; i++)
      P.at(f, i, j, shade(j >= 9 ? FL.bone : (j % 3 === 0 ? plateL : (j % 2 ? base : baseD)), 0.9 + r() * 0.2)); }
  { const R = reg('limbT');
    for (const f of faces(R)) flesh(f);
    for (const f of sides(R)) { P.at(f, 0, 0, plateL); P.at(f, 1, 0, plateL); P.at(f, 0, 5, FL.boneD); P.at(f, 1, 5, FL.bone); P.at(f, 1, 2, baseL); }
    P.fill(R.bottom, FL.bone, 0.1); }
  { const R = reg('claw'); for (const f of faces(R)) bone(f); for (const f of sides(R)) { P.at(f, 0, 0, mix(FL.boneD, base, 0.6)); P.at(f, f.w - 1, 0, mix(FL.boneD, base, 0.6)); } }
  { const R = reg('big');
    for (const f of faces(R)) {
      for (let j = 0; j < f.h; j++) for (let i = 0; i < f.w; i++) {    // bulging muscle fibre
        const q = r();
        const c = q < 0.08 ? FL.maroon : ((i + (j >> 2)) % 3 === 0 ? baseD : (q > 0.9 ? baseL : base));
        P.at(f, i, j, shade(c, 0.9 + r() * 0.2));
      }
    }
    carapace(R.top);
    { const F = R.front;  // ribs bursting out, pus core, an eye
      for (let j = 1; j < 7; j++) for (let i = 1; i < 7; i++) if (i > 1 && i < 6 && j > 1 && j < 6) P.at(F, i, j, j % 2 ? FL.bone : FL.voidC);
      P.at(F, 3, 3, FL.pus); glow(F, 3, 3, 0.5); P.at(F, 4, 4, [255, 230, 110]); glow(F, 4, 4, 0.7);
      P.at(F, 6, 1, FL.voidC); eye(F, 7, 1); }
    for (const f of [R.back, R.left, R.right]) { for (let k = 0; k < 2; k++) { const i = 1 + Math.floor(r() * 6), j = 1 + Math.floor(r() * 6); P.at(f, i, j, FL.pus); P.at(f, i + 1, j, FL.pusD); glow(f, i, j, 0.4); } }
    for (let j = 0; j < 8; j++) P.at(R.back, 3 + (j % 2), j, j % 2 ? FL.boneD : FL.bone); }
  { const R = reg('arm');
    for (const f of faces(R)) for (let j = 0; j < f.h; j++) for (let i = 0; i < f.w; i++) {
      const q = r();
      P.at(f, i, j, shade(q < 0.1 ? FL.maroon : ((i + (j >> 1)) % 3 === 0 ? baseD : (q > 0.9 ? baseL : base)), 0.9 + r() * 0.2));
    }
    carapace(R.top);
    for (const f of [R.left, R.right, R.back]) for (let j = 0; j < 4; j++) for (let i = 0; i < f.w; i++) if ((i + j) % 4 !== 3) P.at(f, i, j, shade(mix(FL.bone, plate, 0.3), 0.85 + r() * 0.2));
    for (const f of sides(R)) { const i = 1 + Math.floor(r() * 4); P.at(f, i, 6, FL.pus); glow(f, i, 6, 0.4); P.at(f, i, 7, FL.voidC); }
    P.fill(R.bottom, FL.boneD, 0.1); }
  { const R = reg('blade');
    for (const f of faces(R)) bone(f);
    for (const f of sides(R)) for (let i = 0; i < f.w; i++) { P.at(f, i, 0, base); P.at(f, i, 1, baseD); }
    for (let j = 2; j < 10; j++) { P.at(R.front, 1, j, shade(FL.bone, 1.1)); P.at(R.back, 1, j, FL.boneD); } }
  { const R = reg('wing');
    const F = R.front, B = R.back;
    for (const f of [F, B]) {
      for (let j = 0; j < 8; j++) for (let i = 0; i < 10; i++) {
        const thin = (i + j) % 5 === 0 || j > 5;
        P.at(f, i, j, shade(thin ? mix(baseD, FL.fleshL, 0.25) : mix(base, FL.maroon, 0.5), 0.88 + r() * 0.2));
      }
      for (let i = 0; i < 10; i++) P.at(f, i, 0, FL.bone);                 // leading bone
      for (const fx of [3, 6, 9]) for (let j = 0; j < 8 - (fx === 9 ? 2 : 0); j++) P.at(f, Math.max(0, fx - (j >> 2)), j, FL.boneD); // finger struts
      for (let k = 0; k < 4; k++) { let i = Math.floor(r() * 10), j = 1; while (j < 8) { P.at(f, i, j, FL.vein); i += Math.floor(r() * 3) - 1; j++; } }
    }
    for (const f of [R.top, R.bottom, R.left, R.right]) P.fill(f, FL.boneD, 0.1); }
  { const R = reg('petal');
    flesh(R.back); flesh(R.left); flesh(R.right); P.fill(R.top, baseD, 0.1); P.fill(R.bottom, baseD, 0.1);
    const F = R.front; // inner face: wet red with teeth rows and pus pores
    for (let j = 0; j < 6; j++) for (let i = 0; i < 4; i++) P.at(F, i, j, shade(j < 1 ? FL.fleshL : FL.flesh, 0.85 + r() * 0.25));
    for (let j = 1; j < 6; j += 2) { P.at(F, 0, j, FL.tooth); P.at(F, 3, j, FL.tooth); }
    P.at(F, 1, 0, FL.tooth); P.at(F, 2, 0, FL.tooth);
    P.at(F, 1, 3, FL.pus); glow(F, 1, 3, 0.6); P.at(F, 2, 4, FL.pus); glow(F, 2, 4, 0.5);
    for (let j = 0; j < 6; j++) P.at(R.back, 1 + (j % 2), j, FL.vein); }
  { const R = reg('long'); for (const f of faces(R)) flesh(f); for (const f of sides(R)) for (let j = 0; j < 8; j += 2) P.at(f, 0, j, plateL); }
  { const R = reg('robe');
    const cl = pal.robe, cl2 = shade(cl, 0.7);
    for (const f of faces(R)) for (let j = 0; j < f.h; j++) for (let i = 0; i < f.w; i++) P.at(f, i, j, shade(r() < 0.2 ? cl2 : cl, 0.88 + r() * 0.2));
    for (const f of sides(R)) {
      for (let i = 0; i < f.w; i++) if (r() < 0.55) P.at(f, i, f.h - 1, FL.voidC); // ragged hem
      for (let k = 0; k < 2; k++) {                                              // flesh pushing through the cloth
        const cx = r() * f.w, cy = 2 + r() * (f.h - 4);
        P.blob(f, cx, cy, 1.3, FL.flesh, FL.fleshD);
        if (r() < 0.6) { P.at(f, cx, cy, FL.pus); glow(f, cx, cy, 0.4); }
      }
      let i = Math.floor(r() * f.w); for (let j = 0; j < f.h; j++) { if (r() < 0.6) P.at(f, i, j, FL.maroon); i += Math.floor(r() * 3) - 1; }
    } }

  for (const k of Object.keys(PARA_UV)) shadeBox(P, reg(k));
  return { map: texFrom(P), emissiveMap: texFrom(E), eyeHex: pal.eye };
}

const _paraCache = new Map();
/** Cached parasite part atlas for a flesh palette ('crimson'|'maroon'|'pale'|'bile'|'hide'). */
export function getParasiteSkin(palKey = 'crimson') {
  let s = _paraCache.get(palKey);
  if (!s) { s = paintParasite(palKey, hashStr('para:' + palKey)); _paraCache.set(palKey, s); }
  return s;
}

/** Per-instance mob material (hit-flash/fade are per mob) sharing the cached textures. */
export function mobMaterial(skin, eyeHex, eyeIntensity = 0.9) {
  const m = new THREE.MeshLambertMaterial({
    map: skin.map,
    emissive: new THREE.Color(eyeHex),
    emissiveMap: skin.emissiveMap,
    emissiveIntensity: eyeIntensity,
  });
  m.userData.noVox = true;
  return m;
}
