// ContainerSystem.js — per-block container state (chests, furnaces).
//
// State is keyed by the block position string "x,y,z":
//   chest   { type:'chest', slots: Array(27) }
//   furnace { type:'furnace', input, fuel, output, burnLeft, burnMax, cook }
// Stacks are { type, quantity, name[, durability] } like inventory slots.
// Furnaces tick every frame (Minecraft rules: 10 s per item, fuel burn times,
// cook progress cools down while unlit). Loot chests are registered with a
// building type and filled the first time they are opened (or broken).

// Keypad lockers (labs) keep their code in `locks`; the block swaps to
// keypad_locker_open once the right code is entered.

const SMELT_TIME = 10;            // seconds per item (200 ticks)
const STACK_MAX = 64;

// input -> output
const SMELTING = {
  mc_iron_ore: 'mc_iron_ingot',
  mc_gold_ore: 'mc_gold_ingot',
  mc_copper_ore: 'mc_copper_ingot',
  mc_sand: 'mc_glass',
  mc_cobblestone: 'mc_stone',
  mc_oak_log: 'mc_charcoal', mc_birch_log: 'mc_charcoal', mc_spruce_log: 'mc_charcoal', mc_dark_oak_log: 'mc_charcoal',
  food_raw_meat: 'food_cooked_meat',
  // no cactus here: leaves smelt down to green dye instead
  mc_oak_leaves: 'mc_green_dye', mc_birch_leaves: 'mc_green_dye', mc_spruce_leaves: 'mc_green_dye', mc_dark_oak_leaves: 'mc_green_dye',
};

// fuel -> burn seconds
const FUEL = {
  mc_coal: 80, mc_charcoal: 80,
  mc_oak_planks: 15, mc_birch_planks: 15, mc_spruce_planks: 15, mc_dark_oak_planks: 15,
  mc_oak_log: 15, mc_birch_log: 15, mc_spruce_log: 15, mc_dark_oak_log: 15,
  mc_stick: 5, mc_crafting_table: 15, mc_chest: 15,
  weapon_wooden_sword: 10, weapon_wooden_pickaxe: 10, weapon_wooden_axe: 10, weapon_wooden_shovel: 10, weapon_wooden_hoe: 10,
};

// Building loot tables (mirrors FurnitureGenerator._spawnBuildingLoot) plus
// Minecraft materials. Entries whose item id is unknown are skipped at roll time.
// Brewing (vanilla): ingredient -> { input bottle -> result }. 20 s per brew,
// one blaze powder fuels 20 brews.
const BREW_TIME = 20;
const BREW = {
  mc_nether_wart: { water_bottle: 'mc_potion_awkward' },
  mc_ice_ball: { mc_potion_awkward: 'mc_potion_freezing' },
  mc_redstone: { mc_potion_freezing: 'mc_potion_freezing_long', mc_splash_potion_freezing: 'mc_splash_potion_freezing_long', mc_lingering_potion_freezing: 'mc_lingering_potion_freezing_long' },
  mc_gunpowder: { mc_potion_freezing: 'mc_splash_potion_freezing', mc_potion_freezing_long: 'mc_splash_potion_freezing_long' },
  mc_dragon_breath: { mc_splash_potion_freezing: 'mc_lingering_potion_freezing', mc_splash_potion_freezing_long: 'mc_lingering_potion_freezing_long' },
};
const BOTTLES = /^(water_bottle|mc_potion_|mc_splash_potion_|mc_lingering_potion_)/;
const BREW_SLOTS = ['b0', 'b1', 'b2'];

const MC_MATS = [
  { type: 'mc_coal', w: 4, qty: [1, 6] }, { type: 'mc_iron_ingot', w: 3, qty: [1, 4] },
  { type: 'mc_gold_ingot', w: 1, qty: [1, 3] }, { type: 'mc_oak_planks', w: 3, qty: [2, 8] },
  { type: 'mc_stick', w: 3, qty: [2, 6] }, { type: 'mc_oak_log', w: 2, qty: [1, 4] },
  { type: 'mc_diamond', w: 0.4, qty: [1, 2] }, { type: 'food_bread', w: 3, qty: [1, 3] },
  { type: 'mc_cobblestone', w: 2, qty: [4, 12] },
  { type: 'mc_string', w: 2, qty: [1, 4] }, { type: 'mc_feather', w: 2, qty: [1, 4] },
  { type: 'mc_flint', w: 1, qty: [1, 3] }, { type: 'mc_arrow', w: 1.5, qty: [2, 8] },
  { type: 'mc_glass_bottle', w: 1, qty: [1, 3] },
];
const LOOT = {
  farmhouse: ['food_crackers:4', 'food_canned_beans:3', 'food_bread:2', 'water_bottle:3', 'bandage:2', 'ammo_9mm:2:4-10', 'med_pain_killers:1', 'tool_flashlight:1', 'weapon_kitchen_knife:1', 'food_canned_soup:2', 'trap_wire_snare:1', 'gear_flare:1'],
  stable: ['food_crackers:3', 'mat_rope:4', 'tool_hammer:2', 'bandage:2', 'food_canned_beans:2', 'weapon_baseball_bat:1', 'mat_nails:2', 'ammo_12gauge_buck:1:2-6', 'trap_bear_trap:1'],
  barn: ['food_crackers:3', 'mat_rope:3', 'ammo_12gauge_buck:2:4-8', 'tool_flashlight:1', 'bandage:2', 'food_canned_beans:2', 'tool_hammer:1', 'weapon_baseball_bat:1', 'mat_nails:2', 'trap_bear_trap:1', 'trap_wire_snare:1'],
  cabin: ['food_canned_beans:3', 'water_bottle:3', 'ammo_9mm:2:6-14', 'bandage:2', 'med_pain_killers:1', 'tool_flashlight:1', 'food_beef_jerky:2', 'weapon_crowbar:1', 'ammo_556:1:4-10', 'gear_flare:1'],
  ranger_station: ['ammo_308:3:4-10', 'ammo_556:3:6-12', 'bandage:3', 'med_pain_killers:2', 'gear_binoculars:2', 'tool_flashlight:2', 'food_beef_jerky:2', 'water_bottle:2', 'gear_compass:1', 'gear_gas_mask:1', 'trap_bear_trap:1', 'gear_flare:2', 'trap_landmine:1', 'gear_ghillie_suit:1', 'food_energy_bar:2', 'tool_repair_kit:1', 'weapon_revolver:1'],
  lodge: ['food_canned_soup:3', 'food_crackers:3', 'water_bottle:3', 'bandage:2', 'med_pain_killers:2', 'cloth_jacket:1', 'food_trail_mix:2', 'gear_fire_starter:1', 'weapon_axe:1', 'trap_wire_snare:1', 'gear_sleeping_bag:1'],
  gas_station: ['drink_soda:4', 'food_crackers:3', 'ammo_9mm:3:8-16', 'ammo_556:2:8-20', 'bandage:2', 'med_caffeine_pills:2', 'food_chips:2', 'mat_duct_tape:1', 'fuel:2', 'tool_flashlight:1', 'gear_flare:1', 'explosive_smoke_grenade:1', 'food_energy_bar:2', 'tool_repair_kit:1'],
  store: ['food_canned_beans:4', 'food_canned_soup:3', 'food_bread:3', 'food_chips:3', 'water_bottle:3', 'drink_soda:2', 'bandage:2', 'food_crackers:3', 'food_cereal:2', 'food_instant_noodles:2', 'med_ibuprofen:1', 'mat_duct_tape:1'],
  motel: ['water_bottle:3', 'food_crackers:3', 'bandage:3', 'med_pain_killers:2', 'cloth_jacket:1', 'med_gauze:2', 'cloth_boots:1', 'food_instant_noodles:2', 'elec_phone:1', 'gear_headlamp:1'],
  watchtower: ['ammo_308:3:4-10', 'ammo_556:3:8-16', 'bandage:2', 'food_crackers:2', 'gear_binoculars:2', 'weapon_pistol_found:1', 'med_pain_killers:1', 'water_bottle:2', 'gear_flare:2', 'elec_tracker:1', 'explosive_flash_bang:1', 'trap_landmine:1', 'weapon_sawed_off:1'],
  shelter: ['food_canned_beans:3', 'water_bottle:3', 'bandage:3', 'med_pain_killers:2', 'ammo_9mm:1:4-8', 'med_gauze:2', 'food_crackers:2', 'med_antibiotics:1', 'gear_gas_mask:1'],
  // Research labs: storage chests (memos are pre-placed) and keypad vaults
  lab_storage: ['bandage:3', 'med_gauze:2', 'med_pain_killers:2', 'med_antibiotics:1', 'water_bottle:2', 'food_energy_bar:2', 'mat_battery:2', 'mat_wire:2', 'mat_duct_tape:1', 'tool_flashlight:1', 'mc_redstone:2:2-6', 'mc_iron_ingot:2:1-3', 'mc_spore_pod:1:1-3', 'gear_gas_mask:1', 'mc_nether_wart:2:1-4', 'mc_blaze_rod:1:1-2', 'mc_glass_bottle:2:1-3'],
  lab_vault: ['mc_diamond:3:1-3', 'mc_emerald:2:1-3', 'mc_gold_ingot:3:2-5', 'mc_iron_ingot:4:3-8', 'mc_redstone:2:4-12', 'mc_lapis:2:3-8', 'medical_kit:2', 'med_antibiotics:3:1-2', 'ammo_9mm:3:10-20', 'ammo_556:2:10-20', 'ammo_12gauge_buck:2:4-8', 'weapon_pistol_found:1', 'weapon_revolver:1', 'explosive_flash_bang:1', 'tool_repair_kit:1', 'elec_tracker:1', 'mc_blaze_rod:2:1-3', 'mc_nether_wart:2:2-6', 'mc_dragon_breath:1:1-2', 'mc_potion_freezing:1', 'mc_bow:1', 'mc_music_disc_flurry:1', 'mc_chiseled_soulshale:3:2-6'],
  _fallback: ['food_crackers:3', 'water_bottle:3', 'bandage:2', 'ammo_9mm:2:4-10', 'med_pain_killers:1', 'mat_rope:1'],
};
const parseEntry = (s) => {
  const [type, w, q] = s.split(':');
  return { type, w: +w, qty: q ? q.split('-').map(Number) : null };
};

export class ContainerSystem {
  constructor(game) {
    this.game = game;
    this.containers = new Map();   // key -> state
    this.loot = new Map();         // key -> buildingType (unopened loot chests)
    this.locks = new Map();        // key -> { code, label, unlocked, fails, lockUntil } (keypad lockers)
  }

  // ── Keypad lockers ─────────────────────────────────────────────────────
  addLock(key, code, label) { this.locks.set(key, { code: String(code), label: label ?? 'Keypad Locker', unlocked: false, fails: 0, lockUntil: 0 }); }
  lockInfo(key) {
    let L = this.locks.get(key);
    // a locker with no record (should not happen) still gets a real code
    if (!L) { this.addLock(key, String(Math.floor(Math.random() * 10000)).padStart(4, '0')); L = this.locks.get(key); }
    return L;
  }
  // Check a code. Returns 'ok' | 'wrong' | 'cooldown'. Three misses lock the
  // keypad for 10 seconds.
  tryCode(key, code) {
    const L = this.lockInfo(key), now = performance.now();
    if (L.lockUntil > now) return 'cooldown';
    if (String(code) === L.code) {
      L.unlocked = true; L.fails = 0;
      const [x, y, z] = key.split(',').map(Number);
      this.game.voxelWorld?.setBlockKeepEntity?.(x, y, z, 'keypad_locker_open');
      return 'ok';
    }
    if (++L.fails >= 3) { L.fails = 0; L.lockUntil = now + 10000; }
    return 'wrong';
  }

  // Pre-fill a chest's slots (structure generation); loot fills the rest
  presetChest(key, slots) {
    const st = { type: 'chest', slots: Array(27).fill(null) };
    slots.forEach((s, i) => { if (s && i < 27) st.slots[i] = s; });
    this.containers.set(key, st);
  }

  get items() { return this.game.inventorySystem?.itemTypes ?? {}; }

  // ── Rules (exposed for the UI) ─────────────────────────────────────────
  smeltResult(type) {
    const out = type && SMELTING[type];
    return out && this.items[out] ? out : null;
  }
  fuelTime(type) { return (type && FUEL[type]) || 0; }
  isBrewIngredient(type) { return !!(type && BREW[type]); }
  isBottle(type) { return !!type && BOTTLES.test(type); }
  brewResult(ing, bottle) { const out = ing && bottle && BREW[ing]?.[bottle]; return out && this.items[out] ? out : null; }
  isFuel(type) { return this.fuelTime(type) > 0; }

  // ── State access ───────────────────────────────────────────────────────
  // Get (and create on demand) the container at `key`. `kind` is 'chest',
  // 'furnace' or 'lit_furnace'; omit it to only look up existing state.
  get(key, kind) {
    let st = this.containers.get(key);
    const want = kind === 'lit_furnace' ? 'furnace' : kind;
    if (st && (!want || st.type === want)) { if (st.type === 'chest') this._fillLoot(key, st); return st; }
    if (!want) return null;
    if (st) this._dropAll(key, st);           // block type changed under us
    st = want === 'chest'
      ? { type: 'chest', slots: Array(27).fill(null) }
      : want === 'brewing'
        ? { type: 'brewing', b0: null, b1: null, b2: null, ing: null, fuel: null, fuelLeft: 0, brew: 0, brewIng: null }
        : want === 'jukebox' ? { type: 'jukebox', disc: null }
        : { type: 'furnace', input: null, fuel: null, output: null, burnLeft: 0, burnMax: 0, cook: 0 };
    this.containers.set(key, st);
    if (st.type === 'chest') this._fillLoot(key, st);
    return st;
  }

  has(key) { return this.containers.has(key) || this.loot.has(key); }

  registerLootChest(key, buildingType) {
    if (this.containers.get(key)?._looted) return;
    this.loot.set(key, buildingType ?? '_fallback');
  }

  // ── Furnace tick ───────────────────────────────────────────────────────
  update(dt) {
    if (!(dt > 0)) return;
    dt = Math.min(dt, 1);
    for (const [key, st] of this.containers) {
      if (st.type === 'furnace') this._tickFurnace(key, st, dt);
      else if (st.type === 'brewing') this._tickBrewing(key, st, dt);
    }
  }

  _canBrew(st) {
    const ing = st.ing?.type;
    return !!ing && BREW_SLOTS.some((f) => this.brewResult(ing, st[f]?.type));
  }

  _tickBrewing(key, st, dt) {
    // refuel: a blaze powder gives 20 brews
    if (st.fuelLeft <= 0 && st.fuel?.type === 'mc_blaze_powder') {
      st.fuelLeft = 20;
      st.fuel.quantity -= 1;
      if (st.fuel.quantity <= 0) st.fuel = null;
    }
    const ok = this._canBrew(st);
    if (st.brew > 0) {
      // swapping the ingredient (or removing every valid bottle) cancels
      if (!ok || st.ing?.type !== st.brewIng) { st.brew = 0; st.brewIng = null; return; }
      st.brew = Math.max(0, st.brew - dt);
      if (st.brew === 0) {
        const ing = st.ing.type;
        for (const f of BREW_SLOTS) {
          const out = this.brewResult(ing, st[f]?.type);
          if (out) st[f] = { type: out, quantity: 1, name: this.items[out]?.name ?? out };
        }
        st.ing.quantity -= 1;
        if (st.ing.quantity <= 0) st.ing = null;
        st.brewIng = null;
        this._brewSound(key);
      }
    } else if (ok && st.fuelLeft > 0) {
      st.fuelLeft -= 1;
      st.brew = BREW_TIME;
      st.brewIng = st.ing.type;
    }
  }

  _brewSound(key) {
    const P = this.game.player?.body?.position;
    if (!P) return;
    const [x, y, z] = key.split(',').map(Number);
    if (Math.hypot(P.x - x, P.y - y, P.z - z) > 16) return;
    this.game.blockInteraction?._sfx?.({ name: 'glass' }, 0.4);
  }

  _canSmelt(st) {
    const out = this.smeltResult(st.input?.type);
    if (!out) return null;
    if (st.output && (st.output.type !== out || st.output.quantity >= STACK_MAX)) return null;
    return out;
  }

  _tickFurnace(key, st, dt) {
    const wasLit = st.burnLeft > 0;
    if (st.burnLeft > 0) st.burnLeft = Math.max(0, st.burnLeft - dt);
    const out = this._canSmelt(st);

    // Light the next fuel item only when there is something to smelt
    if (st.burnLeft <= 0 && out && st.fuel && this.isFuel(st.fuel.type)) {
      const t = this.fuelTime(st.fuel.type);
      st.burnLeft = st.burnMax = t;
      st.fuel.quantity -= 1;
      if (st.fuel.quantity <= 0) st.fuel = null;
    }

    if (st.burnLeft > 0 && out) {
      st.cook += dt;
      if (st.cook >= SMELT_TIME) {
        st.cook = 0;
        if (st.output) st.output.quantity += 1;
        else st.output = { type: out, quantity: 1, name: this.items[out]?.name ?? out };
        st.input.quantity -= 1;
        if (st.input.quantity <= 0) st.input = null;
        st.xp = (st.xp ?? 0) + 0.7;           // banked for when the output is taken
      }
    } else if (st.burnLeft > 0) {
      st.cook = 0;                              // burning but nothing valid to smelt
    } else {
      st.cook = Math.max(0, st.cook - 2 * dt);  // unlit: progress cools down twice as fast
    }

    const lit = st.burnLeft > 0;
    if (lit !== wasLit) {
      const [x, y, z] = key.split(',').map(Number);
      this.game.voxelWorld?.setBlockKeepEntity?.(x, y, z, lit ? 'lit_furnace' : 'furnace');
    }
  }

  // ── Block broken: spill contents into the world ────────────────────────
  onBlockBroken(key, x, y, z) {
    this.game.jukebox?.onBlockBroken?.(key);
    const inv = this.game.inventorySystem;
    if (inv?.isOpen && inv.mcScreen?.key === key) inv.closeInventory();
    let st = this.containers.get(key);
    if (!st && this.loot.has(key)) st = this.get(key, 'chest');
    this.loot.delete(key);
    if (!st) return;
    this._dropAll(key, st, x, y, z);
    this.containers.delete(key);
  }

  _dropAll(key, st, x, y, z) {
    if (x === undefined) [x, y, z] = key.split(',').map(Number);
    const wis = this.game.worldItemSystem;
    if (!wis?.spawnItem) return;
    const stacks = st.type === 'chest' ? st.slots : st.type === 'brewing' ? [st.b0, st.b1, st.b2, st.ing, st.fuel] : st.type === 'jukebox' ? [st.disc] : [st.input, st.fuel, st.output];
    for (const s of stacks) {
      if (!s || s.quantity <= 0) continue;
      const jx = (Math.random() - 0.5) * 0.4, jz = (Math.random() - 0.5) * 0.4;
      wis.spawnItem(s.type, x + 0.5 + jx, y + 0.5, z + 0.5 + jz, s.quantity, s.note ? { note: s.note } : undefined);
    }
  }

  // ── Loot ───────────────────────────────────────────────────────────────
  _fillLoot(key, st) {
    if (!this.loot.has(key)) return;
    const bt = this.loot.get(key);
    this.loot.delete(key);
    st._looted = true;
    const items = this.items;
    const vault = bt === 'lab_vault';            // locked vaults: no filler, more stacks
    const table = [...(LOOT[bt] ?? LOOT._fallback).map(parseEntry), ...(vault ? [] : MC_MATS)].filter((e) => items[e.type]);
    if (!table.length) return;
    const total = table.reduce((s, e) => s + e.w, 0);
    const free = [...Array(27).keys()].filter((i) => !st.slots[i]);
    const n = vault ? 5 + Math.floor(Math.random() * 4) : 3 + Math.floor(Math.random() * 6);   // 5-8 / 3-8 stacks
    for (let k = 0; k < n && free.length; k++) {
      let r = Math.random() * total, e = table[0];
      for (const c of table) { r -= c.w; if (r <= 0) { e = c; break; } }
      const qty = e.qty ? e.qty[0] + Math.floor(Math.random() * (e.qty[1] - e.qty[0] + 1)) : 1;
      const slot = free.splice(Math.floor(Math.random() * free.length), 1)[0];
      st.slots[slot] = { type: e.type, quantity: items[e.type].stackable ? qty : 1, name: items[e.type].name ?? e.type };
    }
  }

  // ── Persistence helpers (optional) ─────────────────────────────────────
  serialize() {
    return { containers: [...this.containers], loot: [...this.loot], locks: [...this.locks] };
  }
  load(data) {
    if (!data) return;
    this.containers = new Map(data.containers ?? []);
    this.loot = new Map(data.loot ?? []);
    this.locks = new Map(data.locks ?? []);
  }
}
