const WOODS = ['oak', 'birch', 'spruce', 'dark_oak'];
const PLANKS = WOODS.map((w) => `mc_${w}_planks`);
const TOOL_MATS = [
  ['wooden', PLANKS, 'Any Planks'], ['stone', ['mc_cobblestone'], null],
  ['iron', ['mc_iron_ingot'], null], ['gold', ['mc_gold_ingot'], null], ['diamond', ['mc_diamond'], null],
];
const TOOL_SHAPES = {
  sword:   ['X', 'X', '#'],
  pickaxe: ['XXX', ' # ', ' # '],
  axe:     ['XX', 'X#', ' #'],
  shovel:  ['X', '#', '#'],
  hoe:     ['XX', ' #', ' #'],
};
const ARMOR_MATS = [['leather', ['mat_leather']], ['iron', ['mc_iron_ingot']], ['gold', ['mc_gold_ingot']], ['diamond', ['mc_diamond']]];
const ARMOR_SHAPES = {
  helmet:     ['XXX', 'X X'],
  chestplate: ['X X', 'XXX', 'XXX'],
  leggings:   ['XXX', 'X X', 'X X'],
  boots:      ['X X', 'X X'],
};

function shaped(result, qty, pattern, key, labels = null) {
  const w = Math.max(...pattern.map((r) => r.length));
  pattern = pattern.map((r) => r.padEnd(w, ' '));
  return { id: result, result, qty, pattern, key, labels, w, h: pattern.length, category: 'minecraft' };
}
function shapeless(result, qty, list, labels = null) {
  return { id: result, result, qty, shapeless: list, labels, w: Math.min(list.length, 3), h: Math.ceil(list.length / 3), category: 'minecraft' };
}
// Can each grid item be assigned to a distinct ingredient slot? (backtracking)
function shapelessFits(types, list) {
  const used = Array(list.length).fill(false);
  const go = (i) => {
    if (i === types.length) return true;
    for (let k = 0; k < list.length; k++) {
      if (used[k] || !list[k].includes(types[i])) continue;
      used[k] = true; if (go(i + 1)) return true; used[k] = false;
    }
    return false;
  };
  return go(0);
}
function buildMcRecipes() {
  const R = [];
  for (const w of WOODS) R.push(shapeless(`mc_${w}_planks`, 4, [[`mc_${w}_log`]]));
  R.push(shaped('mc_stick', 4, ['#', '#'], { '#': PLANKS }, { '#': 'Any Planks' }));
  R.push(shaped('mc_crafting_table', 1, ['##', '##'], { '#': PLANKS }, { '#': 'Any Planks' }));
  R.push(shaped('mc_furnace', 1, ['###', '# #', '###'], { '#': ['mc_cobblestone'] }));
  R.push(shaped('mc_chest', 1, ['###', '# #', '###'], { '#': PLANKS }, { '#': 'Any Planks' }));
  R.push(shaped('mc_stone_bricks', 4, ['##', '##'], { '#': ['mc_stone'] }));
  for (const [tier, mats, label] of TOOL_MATS) {
    for (const [kind, pat] of Object.entries(TOOL_SHAPES)) {
      R.push(shaped(`weapon_${tier}_${kind}`, 1, pat, { X: mats, '#': ['mc_stick'] }, label ? { X: label } : null));
    }
  }
  for (const [mat, mats] of ARMOR_MATS) {
    for (const [piece, pat] of Object.entries(ARMOR_SHAPES)) R.push(shaped(`mc_${mat}_${piece}`, 1, pat, { X: mats }));
  }
  // Dyes: one per flower, bone meal for white, lapis for blue; the rest mix
  // as in vanilla. Stand-ins for sources this world lacks: black from
  // coal/charcoal (no ink sacs), green from yellow + blue (no cactus), brown
  // from red + green (no cocoa).
  const D = (c) => [`mc_${c}_dye`];
  R.push(shapeless('mc_bone_meal', 9, [['mc_bone_block']]));
  R.push(shapeless('mc_red_dye', 1, [['mc_blood_poppy']]));
  R.push(shapeless('mc_yellow_dye', 1, [['mc_dandelion']]));
  R.push(shapeless('mc_blue_dye', 1, [['mc_cornflower']]));
  R.push(shapeless('mc_blue_dye', 1, [['mc_lapis']]));
  R.push(shapeless('mc_light_gray_dye', 1, [['mc_oxeye_daisy']]));
  R.push(shapeless('mc_white_dye', 1, [['mc_bone_meal']]));
  R.push(shapeless('mc_black_dye', 1, [['mc_coal', 'mc_charcoal']], { mc_coal: 'Coal or Charcoal' }));
  R.push(shapeless('mc_green_dye', 2, [D('yellow'), D('blue')]));
  R.push(shapeless('mc_orange_dye', 2, [D('red'), D('yellow')]));
  R.push(shapeless('mc_pink_dye', 2, [D('red'), D('white')]));
  R.push(shapeless('mc_lime_dye', 2, [D('green'), D('white')]));
  R.push(shapeless('mc_light_blue_dye', 2, [D('blue'), D('white')]));
  R.push(shapeless('mc_cyan_dye', 2, [D('blue'), D('green')]));
  R.push(shapeless('mc_purple_dye', 2, [D('red'), D('blue')]));
  R.push(shapeless('mc_magenta_dye', 2, [D('purple'), D('pink')]));
  R.push(shapeless('mc_magenta_dye', 4, [D('blue'), D('red'), D('red'), D('white')]));
  R.push(shapeless('mc_gray_dye', 2, [D('black'), D('white')]));
  R.push(shapeless('mc_light_gray_dye', 2, [D('gray'), D('white')]));
  R.push(shapeless('mc_light_gray_dye', 3, [D('black'), D('white'), D('white')]));
  R.push(shapeless('mc_brown_dye', 2, [D('red'), D('green')]));
  // Concrete powder: 1 dye + 4 sand + 4 gravel -> 8
  for (const c of DYE_COLOURS) {
    R.push(shapeless(`mc_${c}_concrete_powder`, 8, [D(c), ['mc_sand'], ['mc_sand'], ['mc_sand'], ['mc_sand'], ['mc_gravel'], ['mc_gravel'], ['mc_gravel'], ['mc_gravel']]));
  }
  // 26.4: calcite, packed ice and snow building sets
  const M = (id) => ({ '#': [id] });
  for (const [full, stem] of SETS) {
    R.push(shaped(`mc_${stem}_slab`, 6, ['###'], M(`mc_${full}`)));
    R.push(shaped(`mc_${stem}_stairs`, 4, ['#  ', '## ', '###'], M(`mc_${full}`)));
    R.push(shaped(`mc_${stem}_wall`, 6, ['###', '###'], M(`mc_${full}`)));
  }
  R.push(shaped('mc_polished_calcite', 4, ['##', '##'], M('mc_calcite')));
  R.push(shaped('mc_polished_calcite_bricks', 4, ['##', '##'], M('mc_polished_calcite')));
  R.push(shaped('mc_packed_ice_bricks', 4, ['##', '##'], M('mc_packed_ice')));
  R.push(shaped('mc_chiseled_packed_ice', 1, ['#', '#'], M('mc_packed_ice_brick_slab')));
  R.push(shaped('mc_snow_block', 1, ['##', '##'], M('mc_snowball')));
  R.push(shaped('mc_snow_bricks', 4, ['##', '##'], M('mc_snow_block')));
  R.push(shaped('mc_stonecutter', 1, [' I ', '###'], { I: ['mc_iron_ingot'], '#': ['mc_stone'] }));
  // 26.4 phase 4: brewing, bows and arrows
  R.push(shaped('mc_glass_bottle', 3, ['# #', ' # '], M('mc_glass')));
  R.push(shaped('mc_brewing_stand', 1, [' B ', '###'], { B: ['mc_blaze_rod'], '#': ['mc_cobblestone'] }));
  R.push(shapeless('mc_blaze_powder', 2, [['mc_blaze_rod']]));
  R.push(shaped('mc_bow', 1, [' #S', '# S', ' #S'], { '#': ['mc_stick'], S: ['mc_string'] }));
  R.push(shaped('mc_arrow', 4, ['F', '#', 'E'], { F: ['mc_flint'], '#': ['mc_stick'], E: ['mc_feather'] }));
  R.push(shaped('mc_arrow_freezing', 8, ['AAA', 'APA', 'AAA'], { A: ['mc_arrow'], P: ['mc_lingering_potion_freezing'] }));
  R.push(shaped('mc_arrow_freezing_long', 8, ['AAA', 'APA', 'AAA'], { A: ['mc_arrow'], P: ['mc_lingering_potion_freezing_long'] }));
  // 26.4 phase 5: jukebox for the Flurry disc
  R.push(shaped('mc_jukebox', 1, ['###', '#D#', '###'], { '#': PLANKS, D: ['mc_diamond'] }, { '#': 'Any Planks' }));
  return R;
}

// Full block -> stem of its slab / stairs / wall set
const SETS = [['calcite', 'calcite'], ['polished_calcite', 'polished_calcite'], ['polished_calcite_bricks', 'polished_calcite_brick'],
  ['packed_ice_bricks', 'packed_ice_brick'], ['snow_bricks', 'snow_brick']];

// Stonecutter: input item -> [[result, count], ...] (vanilla: one input item
// per craft; slabs give 2). Snow bricks are deliberately not cuttable.
export const STONECUTTER = (() => {
  const T = {};
  const add = (from, to, n = 1) => (T[from] ??= []).push([to, n]);
  const set = (from, stem) => { add(from, `mc_${stem}_slab`, 2); add(from, `mc_${stem}_stairs`); add(from, `mc_${stem}_wall`); };
  set('mc_calcite', 'calcite'); add('mc_calcite', 'mc_calcite_pillar');
  add('mc_calcite', 'mc_polished_calcite'); set('mc_calcite', 'polished_calcite');
  add('mc_calcite', 'mc_polished_calcite_bricks'); set('mc_calcite', 'polished_calcite_brick');
  set('mc_polished_calcite', 'polished_calcite');
  add('mc_polished_calcite', 'mc_polished_calcite_bricks'); set('mc_polished_calcite', 'polished_calcite_brick');
  set('mc_polished_calcite_bricks', 'polished_calcite_brick');
  add('mc_packed_ice', 'mc_packed_ice_bricks'); set('mc_packed_ice', 'packed_ice_brick'); add('mc_packed_ice', 'mc_chiseled_packed_ice');
  set('mc_packed_ice_bricks', 'packed_ice_brick'); add('mc_packed_ice_bricks', 'mc_chiseled_packed_ice');
  // existing stone family
  add('mc_stone', 'mc_stone_bricks');
  return T;
})();

