// FreezeSystem.js — the 26.4 Freezing status effect.
//
// While the effect lasts, the target freezes as if standing in powder snow:
// its frozen ticks climb by 1 per tick and fall by 2 per tick once the effect
// ends. Over 140 ticks (7 s) it slows to half speed; fully frozen, it takes
// damage every 40 ticks (2 s). Any worn leather armor, or being on fire,
// keeps the effect from doing anything. Frostbites are immune.
// Sources: Frostbite melee (3 s); later the potions and arrows of Freezing.

const TICK = 0.05;
const FULL = 140;
const IMMUNE = /frostbite|stray/;

// Frost on the screen edges: feathery ice crystals grown from the borders,
// denser toward the corners (painted once, original art).
function frostTexture() {
  const W = 512, H = 288, c = document.createElement('canvas');
  c.width = W; c.height = H;
  const g = c.getContext('2d');
  g.lineCap = 'round';
  const branch = (x, y, a, len, w, depth) => {
    const x2 = x + Math.cos(a) * len, y2 = y + Math.sin(a) * len;
    g.strokeStyle = `rgba(${225 + Math.random() * 30},${240 + Math.random() * 15},255,${0.18 + Math.random() * 0.25})`;
    g.lineWidth = w;
    g.beginPath(); g.moveTo(x, y); g.lineTo(x2, y2); g.stroke();
    if (depth <= 0 || len < 3) return;
    const n = 2 + Math.floor(Math.random() * 2);
    for (let i = 1; i <= n; i++) {
      const t = i / (n + 1), bx = x + (x2 - x) * t, by = y + (y2 - y) * t;
      branch(bx, by, a + 1.0 + Math.random() * 0.3, len * 0.42, w * 0.6, depth - 1);
      branch(bx, by, a - 1.0 - Math.random() * 0.3, len * 0.42, w * 0.6, depth - 1);
    }
    branch(x2, y2, a + (Math.random() - 0.5) * 0.6, len * 0.7, w * 0.8, depth - 1);
  };
  for (let i = 0; i < 120; i++) {
    const side = i % 4, u = Math.random();
    const x = side === 0 ? 0 : side === 1 ? W : u * W, y = side === 2 ? 0 : side === 3 ? H : u * H;
    const toward = Math.atan2(H / 2 - y, W / 2 - x) + (Math.random() - 0.5) * 1.2;
    const corner = Math.min(Math.hypot(x, y), Math.hypot(W - x, y), Math.hypot(x, H - y), Math.hypot(W - x, H - y));
    branch(x, y, toward, 8 + Math.random() * 16 + Math.max(0, 40 - corner * 0.3), 1.6, 3);
  }
  return c.toDataURL();
}

export class FreezeSystem {
  constructor(game) {
    this.game = game;
    this._acc = 0;
  }

  // seconds of Freezing on 'player' or a zombie (refreshes, never shortens)
  apply(target, seconds) {
    if (target === 'player' || target === this.game.player) {
      const p = this.game.player;
      if (p.godMode) return;
      p._freezeTimer = Math.max(p._freezeTimer ?? 0, seconds);
    } else if (target && !target._dead && !IMMUNE.test(target.type ?? '')) {
      target._freezeTimer = Math.max(target._freezeTimer ?? 0, seconds);
    }
  }

  playerProtected() {
    const p = this.game.player, inv = this.game.inventorySystem;
    if (p.burned || p._onFire > 0) return true;
    return !!inv?.armor && Object.values(inv.armor).some((s) => s && /^mc_leather_/.test(s.type));
  }

  update(dt) {
    const g = this.game;
    if (!g.isRunning || g.isPaused) return;
    this._acc = Math.min(this._acc + dt, TICK * 5);
    while (this._acc >= TICK) { this._acc -= TICK; this._tick(); }
  }

  _tick() {
    const g = this.game, p = g.player;
    if (p) {
      const on = (p._freezeTimer ?? 0) > 0;
      if (on) p._freezeTimer = Math.max(0, p._freezeTimer - TICK);
      const prot = this.playerProtected();
      const f = p._frozenTicks ?? 0;
      p._frozenTicks = on && !prot ? Math.min(FULL, f + 1) : Math.max(0, f - 2);
      p._freezeSlow = 1 - 0.5 * (p._frozenTicks / FULL);
      if (p._frozenTicks >= FULL && on && !prot) {
        p._freezeDmgT = (p._freezeDmgT ?? 0) + 1;
        if (p._freezeDmgT >= 40) {
          p._freezeDmgT = 0;
          if (!p.godMode) { p._deathCause = 'Froze to death'; p.takeDamage(1.125 * 5, null, true); }
        }
      } else p._freezeDmgT = 0;
      this._overlay(p._frozenTicks / FULL);
    }
    for (const z of g.zombieManager?.zombies ?? []) {
      const on = (z._freezeTimer ?? 0) > 0;
      if (!on && !z._frozenTicks) continue;
      if (on) z._freezeTimer = Math.max(0, z._freezeTimer - TICK);
      z._frozenTicks = on ? Math.min(FULL, (z._frozenTicks ?? 0) + 1) : Math.max(0, z._frozenTicks - 2);
      z._baseSpeed ??= z.speed;
      z.speed = z._baseSpeed * (1 - 0.5 * z._frozenTicks / FULL);
      if (!z._frozenTicks) { z.speed = z._baseSpeed; z._baseSpeed = undefined; }
      if (z._frozenTicks >= FULL && on && !z._dead) {
        z._freezeDmgT = (z._freezeDmgT ?? 0) + 1;
        if (z._freezeDmgT >= 40) { z._freezeDmgT = 0; z.takeDamage(1.125 * 2.5); }
      }
    }
  }

  // Frost creeping in from the screen edges as the player freezes
  _overlay(k) {
    if (!this._el) {
      if (!k) return;
      this._el = document.createElement('div');
      this._el.id = 'freeze-overlay';
      this._el.style.backgroundImage = `url(${frostTexture()}), radial-gradient(ellipse at center, transparent 45%, rgba(200,230,255,.55) 100%)`;
      const hud = document.getElementById('hud');
      if (hud) hud.before(this._el); else document.body.appendChild(this._el);
    }
    const v = k.toFixed(3);
    if (v !== this._last) { this._last = v; this._el.style.opacity = v; }
  }

  clear() {
    const p = this.game.player;
    if (p) { p._freezeTimer = 0; p._frozenTicks = 0; p._freezeSlow = 1; }
    this._overlay(0);
  }
}
