import * as THREE from 'three';
import { ZombieBase } from './ZombieBase.js';
import { buildBrute } from './ParasiteForms.js';

export class Tank extends ZombieBase {
  constructor(x, z, game) {
    super(x, z, game, {
      type: 'tank',
      health: 100,
      damage: 20,
      speed: 1.5,
      attackRange: 2.5,
      aggroRange: 35,
      attackCooldown: 2
    });
  }

  createMesh() {
    // Primitive brute: squat legs under a hunched mound of fused crimson
    // muscle and bone, a small toothed head sunk between the shoulders,
    // one massive flesh arm ending in three huge bone talons, pus sacs on
    // its hump and a pair of back tendrils.
    const { group } = buildBrute(this, { scale: 1.25, pal: 'crimson' });
    this.finalizeMesh(group);
  }
}
