 const pt = this._sim ? Math.min(1, (this._tickAcc ?? 0) / 0.05) : 1;
 const eyeT = this.isCrouching ? this.crouchEyeHeight : this.eyeHeight;
 const eyeH = this._eyeH === undefined ? eyeT : this._eyeHO + (this._eyeH - this._eyeHO) * pt;
 this._currentEyeH = eyeH;
