 // Minecraft armor points (0-20) from worn gear — drives the armor HUD row
 getArmorPoints() {
 const inv = this.game.inventorySystem;
 if (!inv) return 0;
 if (typeof inv.getArmorPoints === 'function') return Math.min(20, inv.getArmorPoints() + Math.round((this._innateArmor ?? 0) * 25));
 const has = (...t) => inv.slots.some(s => s && t.includes(s.type));
 let pct = 0;
 if (has('armor_vest', 'armor_plate')) pct += 0.32;
 if (has('armor_helmet')) pct += 0.12;
 if (has('cloth_military_jacket', 'cloth_jacket')) pct += 0.08;
 pct += (this._innateArmor ?? 0);
 return Math.min(20, Math.round(pct * 100 / 4));
 }

