import { itemIconAttrs } from '../ui/ItemIcons.js';

export class AchievementSystem {
 constructor(game) {
 this.game = game;
 this._achievements = [
 { id:'first_blood', item:'weapon_iron_sword', name:'First Blood', desc:'Purge your first parasite', icon:'', unlocked:false, condition: g => (g.zombieKills??0) >= 1 },
 { id:'survivor', item:'mc_iron_helmet', name:'Survivor', desc:'Survive 10 minutes total', icon:'', unlocked:false, condition: g => ((Date.now()-(g._sessionStartTime??Date.now()))/60000) >= 10 },
 { id:'headhunter', item:'weapon_sniper_found', name:'Headhunter', desc:'Score 10 headshots', icon:'', unlocked:false, condition: g => (g._headshotCount??0) >= 10 },
 { id:'hoarder', item:'mc_chest', name:'Hoarder', desc:'Fill 30 inventory slots', icon:'', unlocked:false, condition: g => g.inventorySystem?.slots?.filter(Boolean).length >= 30 },
 { id:'zombie_slayer', item:'weapon_diamond_sword', frame:'goal', name:'Parasite Slayer', desc:'Purge 50 parasites', icon:'', unlocked:false, condition: g => (g.zombieKills??0) >= 50 },
 { id:'well_armed', item:'weapon_ak47', name:'Well Armed', desc:'Own 4 different weapons', icon:'', unlocked:false, condition: g => (g.weaponManager?.getWeapons?.()?.length??0) >= 4 },
 { id:'medic', item:'medkit', name:'Field Medic', desc:'Use 10 medical items', icon:'', unlocked:false, condition: g => (g._medItemsUsed??0) >= 10 },
 { id:'explorer', item:'map', name:'Explorer', desc:'Travel 500m from the house', icon:'', unlocked:false, condition: g => { const p=g.player?.getPosition?.(); return p && Math.sqrt(p.x*p.x+p.z*p.z)>500; }},
 { id:'pyromaniac', item:'mc_furnace', name:'Pyromaniac', desc:'Place 3 campfires', icon:'', unlocked:false, condition: g => (g._campfires?.length??0) >= 3 },
 { id:'crafter', item:'mc_crafting_table', name:'Master Crafter', desc:'Craft 15 items', icon:'', unlocked:false, condition: g => (g._craftCount??0) >= 15 },
 { id:'armored_up', item:'mc_iron_chestplate', name:'Armored Up', desc:'Equip vest + helmet', icon:'', unlocked:false, condition: g => g.inventorySystem?.slots?.some(s=>s?.type==='armor_vest') && g.inventorySystem?.slots?.some(s=>s?.type==='armor_helmet') },
 { id:'night_owl', item:'mc_glowstone', name:'Night Owl', desc:'Survive a full night (20:00→6:00)', icon:'', unlocked:false, condition: g => (g._nightsSurvived??0) >= 1 },
 { id:'surgeon', item:'mc_keypad_locker_open', name:'Surgeon', desc:'Open the locked safe', icon:'', unlocked:false, condition: g => g._safeObjects?.some(s=>s.opened) },
 { id:'blaster', item:'grenade', frame:'challenge', name:'Demolitions Expert',desc:'Purge 5 parasites with explosives', icon:'', unlocked:false, condition: g => (g._explosiveKills??0) >= 5 },
 { id:'what_goes_around', item:'mc_ice_ball', name:'What Goes Around Comes Around', desc:'Kill a Frostbite with an ice ball', icon:'', unlocked:false, condition: () => false },
 { id:'level5', item:'mc_diamond', frame:'goal', name:'Veteran', desc:'Reach Level 5', icon:'', unlocked:false, condition: g => (g.player?.level??0) >= 5 },
 ];
 this._checkTimer = 0;
 this._createUI();
 }

 // ── Toasts (vanilla AdvancementToast / ToastComponent) ──────────────────
 // 160x32 GUI px in the top-right corner, stacked downward. Slides in over
 // 600 ms (quadratic), stays 5 s, slides back out over 600 ms. Icon at
 // (8,8); header "Advancement Made!" (yellow, purple for challenges) at
 // (30,7) and the title (white) at (30,18), no text shadow. A title wider than
 // 125 px wraps: the header shows alone for 1.5 s, then fades into the
 // wrapped title. The frame is original pixel art.
 _createUI() {
 if (!document.getElementById('mc-toasts')) {
 const el = document.createElement('div');
 el.id = 'mc-toasts';
 document.body.appendChild(el);
 }
 if (!AchievementSystem._frame) AchievementSystem._frame = toastFrameURI();
 this._queue = [];
 this._live = [];
 }

 _showUnlock(ach) {
 this._queue.push(ach);
 this._pump();
 }

 _pump() {
 const host = document.getElementById('mc-toasts'); if (!host) return;
 while (this._queue.length && this._live.length < 5) {
 const slot = [0, 1, 2, 3, 4].find((k) => !this._live.some((t) => t.slot === k));
 const ach = this._queue.shift();
 const frame = ach.frame ?? 'task';
 const el = document.createElement('div');
 el.className = 'mc-toast' + (frame === 'challenge' ? ' challenge' : '');
 el.style.setProperty('--slot', slot);
 el.style.backgroundImage = `url('${AchievementSystem._frame}')`;
 const icon = document.createElement('div'); icon.className = 'mc-toast-icon';
 const attrs = ach.item ? itemIconAttrs(ach.item) : '';
 const m = attrs.match(/style="([^"]*)"/); if (m) icon.style.cssText = m[1];
 const head = document.createElement('div'); head.className = 'mc-toast-head';
 head.textContent = frame === 'challenge' ? 'Challenge Complete!' : frame === 'goal' ? 'Goal Reached!' : 'Advancement Made!';
 const title = document.createElement('div'); title.className = 'mc-toast-title';
 title.textContent = ach.name;
 el.append(icon, head, title);
 host.appendChild(el);
 // wrap check: the title is laid out at 1 GUI px = 1 CSS px scale
 const u = parseFloat(getComputedStyle(document.documentElement).getPropertyValue('--u')) || 2;
 if (title.scrollWidth / u > 125) { el.classList.add('wrap'); title.style.setProperty('--lines', Math.ceil(title.scrollWidth / u / 125)); }
 void el.offsetWidth; el.classList.add('in');
 if (frame === 'challenge') this._challengeSound();
 const t = { slot, el };
 this._live.push(t);
 setTimeout(() => { el.classList.remove('in'); el.classList.add('out'); }, 600 + 5000);
 setTimeout(() => { el.remove(); this._live = this._live.filter((x) => x !== t); this._pump(); }, 600 + 5000 + 600);
 }
 }

 // a short rising fanfare (original), only for challenges like vanilla
 _challengeSound() {
 const am = this.game.audioManager, ac = am?.audioContext; if (!ac) return;
 const dest = am.sfxGain ?? ac.destination, t0 = ac.currentTime + 0.05;
 [[523.25, 0], [659.25, 0.12], [783.99, 0.24], [1046.5, 0.36], [783.99, 0.6], [1046.5, 0.72]].forEach(([f, d], i) => {
 const o = ac.createOscillator(), g = ac.createGain();
 o.type = 'triangle'; o.frequency.value = f;
 const len = i === 5 ? 0.9 : 0.22;
 g.gain.setValueAtTime(0, t0 + d); g.gain.linearRampToValueAtTime(0.12, t0 + d + 0.015); g.gain.exponentialRampToValueAtTime(0.001, t0 + d + len);
 o.connect(g); g.connect(dest); o.start(t0 + d); o.stop(t0 + d + len + 0.05);
 });
 }

 update(dt) {
 this._checkTimer += dt;
 if (this._checkTimer < 2) return;
 this._checkTimer = 0;
 const g = this.game;
 for (const ach of this._achievements) {
 if (ach.unlocked) continue;
 try {
 if (ach.condition(g)) {
 ach.unlocked = true;
 this._showUnlock(ach);
 g.player?.gainXP?.(50, 'achievement');
 break; // one at a time
 }
 } catch(e) {}
 }
 }

 // event-driven unlocks (no polled condition)
 grant(id) {
 const ach = this._achievements.find(a => a.id === id);
 if (!ach || ach.unlocked) return false;
 ach.unlocked = true;
 this._showUnlock(ach);
 this.game.player?.gainXP?.(50, 'achievement');
 return true;
 }

 getUnlocked() { return this._achievements.filter(a => a.unlocked); }
 getAll() { return this._achievements; }
}

// Toast frame, 160x32: original pixel art in the vanilla toast's shape (dark
// panel, rounded 1px corners, bevelled light/dark rim).
function toastFrameURI() {
 const W = 160, H = 32, c = document.createElement('canvas'); c.width = W; c.height = H;
 const g = c.getContext('2d');
 const px = (x, y, w, h, col) => { g.fillStyle = col; g.fillRect(x, y, w, h); };
 px(1, 0, W - 2, H, '#0d0d0f'); px(0, 1, W, H - 2, '#0d0d0f');            // outline, corners cut
 px(1, 1, W - 2, H - 2, '#2b2a30');                                        // panel
 px(1, 1, W - 2, 1, '#55535c'); px(1, 1, 1, H - 2, '#55535c');              // light rim
 px(1, H - 2, W - 2, 1, '#18171b'); px(W - 2, 1, 1, H - 2, '#18171b');      // shadow rim
 px(2, 2, W - 4, 1, '#3a3940');                                            // inner highlight
 px(1, 1, 1, 1, '#6c6a74'); px(W - 2, H - 2, 1, 1, '#0d0d0f');
 return c.toDataURL();
}
