import * as THREE from 'three';
import { blockify } from '../systems/VoxelStyle.js';
import { EffectComposer } from 'three/examples/jsm/postprocessing/EffectComposer.js';
import { RenderPass } from 'three/examples/jsm/postprocessing/RenderPass.js';
import { UnrealBloomPass } from 'three/examples/jsm/postprocessing/UnrealBloomPass.js';
import { ShaderPass } from 'three/examples/jsm/postprocessing/ShaderPass.js';
import { OutputPass } from 'three/examples/jsm/postprocessing/OutputPass.js';
import { Atmosphere, ATMOS_GLSL } from '../render/Atmosphere.js';

// Horror color-grade: desaturate + crush blacks, sickly tint, radial chromatic
// aberration, animated film grain and a heavy vignette — the "realistic shader"
// pass that makes the whole world feel wrong.
const HorrorGradeShader = {
  uniforms: {
    tDiffuse:    { value: null },
    uTime:       { value: 0 },
    uResolution: { value: new THREE.Vector2(1, 1) },
    uVignette:   { value: 0.85 },
    uGrain:      { value: 0.0 }  ,   // was 0.07 — the 'blurry' muddiness; keep crisp
    uAberration: { value: 0.0 } ,    // was 0.65 — subtle edge color, not smeary
    uTint:       { value: new THREE.Color(0.92, 0.98, 0.9) },
    uDesat:      { value: 0.2 },
  },
  vertexShader: /* glsl */`
    varying vec2 vUv;
    void main(){ vUv = uv; gl_Position = projectionMatrix * modelViewMatrix * vec4(position,1.0); }
  `,
  fragmentShader: /* glsl */`
    uniform sampler2D tDiffuse;
    uniform float uTime, uVignette, uGrain, uAberration, uDesat;
    uniform vec2 uResolution;
    uniform vec3 uTint;
    varying vec2 vUv;
    float hash(vec2 p){ p = fract(p*vec2(443.897,441.423)); p += dot(p, p+19.19); return fract((p.x+p.y)*p.x); }
    void main(){
      vec2 uv = vUv;
      vec2 d = uv - 0.5;
      float r2 = dot(d, d);
      vec2 off = d * r2 * uAberration;              // radial chromatic aberration
      vec3 col;
      col.r = texture2D(tDiffuse, uv + off).r;
      col.g = texture2D(tDiffuse, uv).g;
      col.b = texture2D(tDiffuse, uv - off).b;
      float l = dot(col, vec3(0.299,0.587,0.114));  // desaturate toward luma
      col = mix(col, vec3(l), uDesat);
      col = pow(max(col, 0.0), vec3(1.14));          // crush blacks / contrast
      col *= uTint;                                   // sickly cast
      float vig = smoothstep(0.95, 0.28, length(d) * 1.35);
      col *= mix(1.0, vig, uVignette);
      float g = hash(uv * uResolution + fract(uTime) * 100.0);
      col += (g - 0.5) * uGrain;
      gl_FragColor = vec4(col, 1.0);
    }
  `,
};

const _cloudC = new THREE.Color();
export class Scene {
  constructor() {
    this.scene = new THREE.Scene();

    // Single global choke point for the voxel look: wrap the THREE scene's own
    // add() so EVERYTHING entering the world is blockified + de-curved, even the
    // systems that reach straight past Scene.addObject to game.scene.scene
    // (world items, house interiors, etc.). Circles are illegal here.
    const _rawAdd = this.scene.add.bind(this.scene);
    this.scene.add = (...objs) => {
      for (const o of objs) {
        if (!o || !o.traverse) continue;
        blockify(o);
        // anything that casts a shadow (mobs, players, items) joins the sun
        // shadow map's entity pass; terrain has its own alpha-tested pass
        o.traverse((m) => { if (m.isMesh && m.castShadow && !m.layers.isEnabled(1)) m.layers.enable(2); });
      }
      return _rawAdd(...objs);
    };
    this.camera = null;
    this.renderer = null;
    this.width = window.innerWidth;
    this.height = window.innerHeight;
    this.skyMesh = null;
    this.skyUniforms = null;
    this.atmosphere = new Atmosphere();
    this.preRender = [];              // hooks run after game updates, right before drawing

    this.setupRenderer();
    this.setupCamera();
    this.setupSky();
    this.setupStars();
    this.setupLights();
    this.setupClouds();
    this.setupEventListeners();
    this.setupPostFX();
  }

  setupPostFX() {
    this.composer = null;
    // Vanilla look: render straight to the MSAA canvas. The bloom + horror
    // grade chain (no MSAA, vignette, desaturation) made blocks look muddy.
    if (!window.__DL_POSTFX) return;
    try {
      const composer = new EffectComposer(this.renderer);
      composer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
      composer.setSize(this.width, this.height);

      composer.addPass(new RenderPass(this.scene, this.camera));

      // Bloom — only the brightest things (spore glow, eyes, fire, muzzle) bleed.
      // Half-res bloom buffer — big GPU saving on integrated graphics, no
      // meaningful quality loss for a soft glow.
      this.bloomPass = new UnrealBloomPass(
        new THREE.Vector2(this.width * 0.5, this.height * 0.5), 0.65, 0.55, 0.82);
      composer.addPass(this.bloomPass);

      // Custom horror grade.
      this.gradePass = new ShaderPass(HorrorGradeShader);
      this.gradePass.uniforms.uResolution.value.set(this.width, this.height);
      composer.addPass(this.gradePass);

      // Final tone-map + sRGB.
      composer.addPass(new OutputPass());

      this.composer = composer;
      this._fxTime = 0;
    } catch (e) {
      console.warn('Post-FX unavailable, falling back to direct render:', e);
      this.composer = null;
    }
  }

  setupRenderer() {
    this.renderer = new THREE.WebGLRenderer({
      canvas: document.getElementById('game-canvas'),
      antialias: true,
      powerPreference: 'high-performance',
      alpha: false
    });

    this.renderer.setSize(this.width, this.height);
    this.renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    this.renderer.shadowMap.enabled = true;
    this.renderer.shadowMap.type = THREE.PCFShadowMap;
    this.renderer.shadowMap.autoUpdate = true;
    this.renderer.outputColorSpace = THREE.SRGBColorSpace;
    this.renderer.toneMapping = THREE.ACESFilmicToneMapping;
    // Grimmer exposure — the world sits a touch darker and more oppressive.
    this.renderer.toneMappingExposure = 0.92;
    this.renderer.setClearColor(0x000000, 1);
    // Thicker fog so parasites loom out of the murk instead of popping in clearly.
    this.scene.fog = new THREE.FogExp2(0x6a7680, 0.0013);
  }

  setupCamera() {
    this.camera = new THREE.PerspectiveCamera(
      70,
      this.width / this.height,
      0.05,
      8000
    );
    this.camera.position.set(0, 2, 0);
  }

  setupSky() {
    // Sky dome drawn from the shared atmosphere model (same function the
    // terrain fog uses, so the horizon blends seamlessly), plus a square
    // sun and moon. The dome follows the camera.
    const skyGeo = new THREE.SphereGeometry(4000, 32, 15);
    this.skyUniforms = {
      ...this.atmosphere.uniforms,
      // legacy fields still written by setSkyTime (unused by the shader)
      topColor: { value: new THREE.Color() }, horizonColor: { value: new THREE.Color() }, groundColor: { value: new THREE.Color() },
      sunDirection: { value: new THREE.Vector3(0, 1, 0) }, sunColor: { value: new THREE.Color() }, sunStrength: { value: 1 },
      moonDirection: { value: new THREE.Vector3(0, -1, 0) }, moonStrength: { value: 0 },
      uTime: { value: 0 }, uStormStrength: { value: 0 },
    };
    const skyMat = new THREE.ShaderMaterial({
      uniforms: this.skyUniforms,
      vertexShader: `
        varying vec3 vDir;
        void main() {
          vDir = position;
          gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
        }`,
      fragmentShader: `
        varying vec3 vDir;
        uniform float uStormStrength;
        uniform float uTime;
        ${ATMOS_GLSL}
        // square disc of angular half-size s around direction c
        float squareDisc(vec3 d, vec3 c, float s, float soft) {
          vec3 up = abs(c.y) > 0.99 ? vec3(1.0, 0.0, 0.0) : vec3(0.0, 1.0, 0.0);
          vec3 t = normalize(cross(up, c)), b = cross(c, t);
          float k = dot(d, c);
          if (k <= 0.0) return 0.0;
          vec2 q = vec2(dot(d, t), dot(d, b)) / k;
          float m = max(abs(q.x), abs(q.y));
          return 1.0 - smoothstep(s - soft, s + soft, m);
        }
        void main() {
          vec3 dir = normalize(vDir);
          vec3 c = atmosSky(dir);
          float above = smoothstep(-0.02, 0.02, dir.y);
          // sun: hot white core with the atmosphere's tint
          float sun = squareDisc(dir, uSunDir, 0.042, 0.0015) * above;
          c += (vec3(1.0, 0.92, 0.78) * 6.0 + uSunGlow * 8.0) * sun * smoothstep(-0.06, 0.02, uSunDir.y);
          // moon: pale square opposite the sun, with a faint halo
          vec3 md = -uSunDir;
          float moon = squareDisc(dir, md, 0.03, 0.001) * above;
          float moonUp = smoothstep(-0.04, 0.12, md.y);
          float crater = 0.85 + 0.15 * step(0.5, fract(sin(dot(floor(dir.xz * 260.0), vec2(12.9898, 78.233))) * 43758.5453));
          c += vec3(0.82, 0.86, 0.95) * 1.6 * moon * moonUp * crater;
          c += vec3(0.30, 0.36, 0.5) * pow(max(dot(dir, md), 0.0), 220.0) * 0.6 * moonUp;
          // storms: heavy grey overcast
          float l = dot(c, vec3(0.2126, 0.7152, 0.0722));
          c = mix(c, vec3(l) * 0.35, uStormStrength * 0.75);
          c *= mix(0.04, 1.0, uEyeSky);
          gl_FragColor = linearToOutputTexel(vec4(atmosTonemap(c), 1.0));
        }`,
      side: THREE.BackSide, depthWrite: false, fog: false,
    });
    this.skyMesh = new THREE.Mesh(skyGeo, skyMat);
    this.skyMesh.renderOrder = -10;
    // The sky dome is the one legal sphere — it's the background gradient, not a
    // world object. Keep it round; everything else gets boxified.
    this.skyMesh.userData.noVox = true;
    this.skyMesh.frustumCulled = false;
    this.scene.add(this.skyMesh);
  }

  setupStars() {
    const starCount = 2000;
    const geometry = new THREE.BufferGeometry();
    const positions = new Float32Array(starCount * 3);
    const brightnesses = new Float32Array(starCount);

    for (let i = 0; i < starCount; i++) {
      // Random point on upper hemisphere
      const theta = Math.random() * Math.PI * 2;
      const phi = Math.acos(Math.random() * 0.9); // bias toward top
      const r = 3800;
      positions[i * 3]     = r * Math.sin(phi) * Math.cos(theta);
      positions[i * 3 + 1] = r * Math.cos(phi);
      positions[i * 3 + 2] = r * Math.sin(phi) * Math.sin(theta);
      brightnesses[i] = 0.4 + Math.random() * 0.6;
    }

    geometry.setAttribute('position', new THREE.BufferAttribute(positions, 3));
    geometry.setAttribute('brightness', new THREE.BufferAttribute(brightnesses, 1));

    this._starTimeUniform = { value: 0.0 };
    const starMaterial = new THREE.ShaderMaterial({
      uniforms: {
        uTime:    this._starTimeUniform,
        uOpacity: { value: 0.0 },
      },
      vertexShader: `
        attribute float brightness;
        varying float vBrightness;
        void main() {
          vBrightness = brightness;
          gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
          gl_PointSize = 1.5 + brightness * 2.0;
        }
      `,
      fragmentShader: `
        uniform float uTime;
        uniform float uOpacity;
        varying float vBrightness;
        void main() {
          vec2 uv = gl_PointCoord - vec2(0.5);
          float d = length(uv);
          if (d > 0.5) discard;
          float soft = 1.0 - smoothstep(0.2, 0.5, d);
          float twinkle = 0.72 + 0.28 * sin(uTime * (2.0 + vBrightness * 1.2) + vBrightness * 12.566);
          gl_FragColor = vec4(vec3(0.9 + vBrightness * 0.1, 0.93, 1.0), vBrightness * twinkle * soft * uOpacity);
        }
      `,
      transparent: true,
      depthWrite: false,
    });

    this.stars = new THREE.Points(geometry, starMaterial);
    this.scene.add(this.stars);
  }

  setupLights() {
    // Hemisphere for realistic sky/ground ambient
    this.hemiLight = new THREE.HemisphereLight(0x87ceeb, 0x6a6458, 0.5);
    this.scene.add(this.hemiLight);

    // Main sun (directional)
    this.sunLight = new THREE.DirectionalLight(0xfffaee, 2.0);
    this.sunLight.position.set(200, 300, 100);
    this.sunLight.castShadow = true;
    this.sunLight.shadow.mapSize.width = 2048;
    this.sunLight.shadow.mapSize.height = 2048;
    this.sunLight.shadow.camera.left = -120;
    this.sunLight.shadow.camera.right = 120;
    this.sunLight.shadow.camera.top = 120;
    this.sunLight.shadow.camera.bottom = -120;
    this.sunLight.shadow.camera.near = 0.1;
    this.sunLight.shadow.camera.far = 500;
    this.sunLight.shadow.bias = -0.0003;
    this.sunLight.shadow.normalBias = 0.03;
    this.scene.add(this.sunLight);

    // Blue sky fill from opposite side
    const fillLight = new THREE.DirectionalLight(0x8ab4cc, 0.4);
    fillLight.position.set(-150, 100, -100);
    this.scene.add(fillLight);

    this.directionalLight = this.sunLight;
  }

  // Called by DayNightCycle to update sky colors — no per-frame allocations
  setSkyTime(t) {
    if (!this.skyUniforms) return;

    // Cached color palette instances
    if (!this._skyPalette) {
      this._skyPalette = {
        // vanilla overworld: deep sky-blue zenith, pale haze at the horizon
        day:   { top: new THREE.Color(0x6e9cf5), horizon: new THREE.Color(0xc0d8ff), ground: new THREE.Color(0x3a4a66) },
        dusk:  { top: new THREE.Color(0x2a3466), horizon: new THREE.Color(0xd9733a), ground: new THREE.Color(0x1a1a20) },
        night: { top: new THREE.Color(0x02040c), horizon: new THREE.Color(0x0a0f1c), ground: new THREE.Color(0x020308) },
        _tmp:  { top: new THREE.Color(), horizon: new THREE.Color(), ground: new THREE.Color() },
      };
    }
    const { day, dusk, night, _tmp } = this._skyPalette;

    if (t < 0.2 || t > 0.85) {
      _tmp.top.copy(night.top); _tmp.horizon.copy(night.horizon); _tmp.ground.copy(night.ground);
      if (this.sunLight) this.sunLight.intensity = 0.05;
      if (this.hemiLight) { this.hemiLight.intensity = 0.1; this.hemiLight.color.set(0x1a2a4a); }
    } else if (t < 0.3 || t > 0.75) {
      const f = t < 0.3 ? (t - 0.2) / 0.1 : (0.85 - t) / 0.1;
      _tmp.top.copy(night.top).lerp(dusk.top, f);
      _tmp.horizon.copy(night.horizon).lerp(dusk.horizon, f);
      _tmp.ground.copy(night.ground).lerp(dusk.ground, f);
      if (this.sunLight) this.sunLight.intensity = f * 1.5;
      if (this.hemiLight) this.hemiLight.intensity = 0.1 + f * 0.3;
    } else if (t < 0.4 || t > 0.65) {
      const f = t < 0.4 ? (t - 0.3) / 0.1 : (0.75 - t) / 0.1;
      _tmp.top.copy(dusk.top).lerp(day.top, f);
      _tmp.horizon.copy(dusk.horizon).lerp(day.horizon, f);
      _tmp.ground.copy(dusk.ground).lerp(day.ground, f);
      if (this.sunLight) this.sunLight.intensity = 1.5 + f * 0.5;
      if (this.hemiLight) this.hemiLight.intensity = 0.4 + f * 0.9;
    } else {
      _tmp.top.copy(day.top); _tmp.horizon.copy(day.horizon); _tmp.ground.copy(day.ground);
      if (this.sunLight) this.sunLight.intensity = 2.0;
      if (this.hemiLight) { this.hemiLight.intensity = 1.3; this.hemiLight.color.set(0xb8d4ec); } // Minecraft: shaded faces ~60%, never black
    }

    this.skyUniforms.topColor.value.copy(_tmp.top);
    this.skyUniforms.horizonColor.value.copy(_tmp.horizon);
    this.skyUniforms.groundColor.value.copy(_tmp.ground);
    this.scene.fog.color.copy(_tmp.horizon);

    // Sun direction: elevates at noon, sinks at dawn/dusk
    if (this.skyUniforms.sunDirection && this.sunLight) {
      this.skyUniforms.sunDirection.value.copy(this.sunLight.position).normalize();
      const sunEl = this.sunLight.position.y > 0 ? 1 : 0;
      this.skyUniforms.sunStrength.value = Math.max(0, sunEl) * (this.sunLight.intensity / 2.0);
      // Sun color: white at noon, orange at dawn/dusk
      if (t < 0.38 || t > 0.63) this.skyUniforms.sunColor.value.set(0xff8833);
      else this.skyUniforms.sunColor.value.set(0xfff4cc);
    }

    // Tint clouds: white at day, orange at dawn/dusk, dim at night
    if (this.cloudGroup) {
      // follow the sun's actual brightness so clouds never glow on a black sky
      const k = Math.max(0, Math.min(1, (this.sunLight?.intensity ?? 2) / 2));
      const dusk = (t > 0.2 && t < 0.3) || (t > 0.75 && t < 0.85);
      _cloudC.setRGB(0.1 + 0.9 * k, 0.11 + 0.89 * k * (dusk ? 0.86 : 1), 0.15 + 0.85 * k * (dusk ? 0.74 : 1));
      const cloudColor = _cloudC, cloudOpacity = 0.8;
      void cloudColor; void cloudOpacity;   // clouds are lit by the atmosphere shader now
    }

    // Stars: visible at night, fade at dawn/dusk and near bright moon
    if (this.stars) {
      let starOpacity = 0;
      if (t < 0.2 || t > 0.85) starOpacity = 0.9;
      else if (t < 0.28) starOpacity = 0.9 * (1 - (t - 0.2) / 0.08);
      else if (t > 0.77) starOpacity = 0.9 * ((t - 0.77) / 0.08);
      const moonStr = this.skyUniforms?.moonStrength?.value ?? 0;
      starOpacity *= (1.0 - moonStr * 0.55);
      this.stars.material.uniforms.uOpacity.value = starOpacity;
    }

    // Moon: opposite direction from sun, visible at night
    if (this.skyUniforms.moonDirection && this.sunLight) {
      const su = this.skyUniforms;
      su.moonDirection.value.copy(this.sunLight.position).negate().normalize();
      const isMoonUp = su.moonDirection.value.y > 0;
      const nightDepth = Math.max(0, -this.sunLight.position.y / 300);
      su.moonStrength.value = isMoonUp ? Math.min(1.0, nightDepth * 1.4) : 0.0;
    }
  }

  updateStars(dt) {
    if (this._starTimeUniform) this._starTimeUniform.value += dt;
    if (this.skyUniforms?.uTime) this.skyUniforms.uTime.value += dt;
  }

  setStormStrength(strength) {
    if (this.skyUniforms?.uStormStrength) {
      this.skyUniforms.uStormStrength.value = Math.max(0, Math.min(1, strength));
    }
  }

  // Vanilla-style cloud layer: flat 12x12-block cells, 4 blocks thick, at a
  // fixed height, drifting +X. One merged mesh with inner faces culled.
  setupClouds() {
    this.cloudGroup = new THREE.Group();
    const G = 64, CELL = 12, TH = 4;                       // 64x64 cells = 768 blocks, tiled
    const seedRand = (i, j) => { let h = Math.imul(i * 73856093 ^ j * 19349663, 2654435761) >>> 0; h ^= h >>> 15; return (h & 0xffff) / 65536; };
    const on = new Uint8Array(G * G);
    for (let j = 0; j < G; j++) for (let i = 0; i < G; i++) {
      // blobby mask: smooth sum of a few hashed octaves
      let v = 0;
      for (const [s, w] of [[8, 0.6], [4, 0.3], [2, 0.1]]) {
        const a = Math.floor(i / s), b = Math.floor(j / s), fx = (i % s) / s, fy = (j % s) / s;
        const q = (x, y) => seedRand(((x % (G / s)) + G / s) % (G / s), ((y % (G / s)) + G / s) % (G / s) + s * 1000);
        const top = q(a, b) * (1 - fx) + q(a + 1, b) * fx, bot = q(a, b + 1) * (1 - fx) + q(a + 1, b + 1) * fx;
        v += (top * (1 - fy) + bot * fy) * w;
      }
      on[j * G + i] = v > 0.56 ? 1 : 0;
    }
    const pos = [], nrm = [];
    const at = (i, j) => on[((j + G) % G) * G + ((i + G) % G)];
    const NRM = { 1.0: [0, 1, 0], 0.7: [0, -1, 0] };
    let side = null;
    const quad = (pts, k) => { const n = NRM[k] ?? side; for (const t of [0, 1, 2, 0, 2, 3]) { pos.push(...pts[t]); nrm.push(...n); } };
    for (let j = 0; j < G; j++) for (let i = 0; i < G; i++) {
      if (!at(i, j)) continue;
      const x0 = i * CELL, x1 = x0 + CELL, z0 = j * CELL, z1 = z0 + CELL;
      quad([[x0, TH, z1], [x1, TH, z1], [x1, TH, z0], [x0, TH, z0]], 1.0);
      quad([[x0, 0, z0], [x1, 0, z0], [x1, 0, z1], [x0, 0, z1]], 0.7);
      side = [1, 0, 0]; if (!at(i + 1, j)) quad([[x1, 0, z1], [x1, 0, z0], [x1, TH, z0], [x1, TH, z1]], 0.9);
      side = [-1, 0, 0]; if (!at(i - 1, j)) quad([[x0, 0, z0], [x0, 0, z1], [x0, TH, z1], [x0, TH, z0]], 0.9);
      side = [0, 0, 1]; if (!at(i, j + 1)) quad([[x0, 0, z1], [x1, 0, z1], [x1, TH, z1], [x0, TH, z1]], 0.8);
      side = [0, 0, -1]; if (!at(i, j - 1)) quad([[x1, 0, z0], [x0, 0, z0], [x0, TH, z0], [x1, TH, z0]], 0.8);
    }
    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
    geo.setAttribute('normal', new THREE.Float32BufferAttribute(nrm, 3));
    geo.computeBoundingSphere();
    // Lit like everything else: sunlit tops, skylit sides, darker bellies,
    // warm at sunset, and fading into the real sky colour with distance.
    this._cloudMat = new THREE.ShaderMaterial({
      uniforms: { ...this.atmosphere.uniforms, uOpacity: { value: 0.82 } },
      vertexShader: `
        varying vec3 vN; varying vec3 vW;
        void main() {
          vN = normal;
          vec4 w = modelMatrix * vec4(position, 1.0);
          vW = w.xyz;
          gl_Position = projectionMatrix * viewMatrix * w;
        }`,
      fragmentShader: `
        varying vec3 vN; varying vec3 vW;
        uniform float uOpacity;
        ${ATMOS_GLSL}
        void main() {
          float ndl = max(dot(vN, uLightDir), 0.0);
          float belly = vN.y < -0.5 ? 0.8 : (vN.y > 0.5 ? 1.0 : 0.9);
          vec3 Vd = normalize(vW - cameraPosition);
          // clouds scatter sunlight through themselves: bright even on the
          // shaded side, with a silver lining when looking towards the sun
          float fwd = pow(max(dot(Vd, uSunDir), 0.0), 8.0);
          vec3 c = uAmbCol * 1.7 * belly + uSunCol * (0.42 + 0.45 * ndl + 0.9 * fwd) * belly + uSunGlow * 0.3;
          c *= mix(0.45, 1.0, smoothstep(-0.12, 0.12, uSunDir.y));   // moonlit clouds stay dim
          vec3 V = vW - cameraPosition;
          float d = length(V);
          vec3 sky = atmosSky(V / d);
          c = mix(c, sky, smoothstep(250.0, 1000.0, d));
          float a = uOpacity * (1.0 - smoothstep(800.0, 1150.0, d));
          gl_FragColor = linearToOutputTexel(vec4(atmosTonemap(c), a));
        }`,
      transparent: true, depthWrite: false, fog: false,
    });
    this._cloudSize = G * CELL;
    // 3x3 copies so the tiled layer always surrounds the player
    for (let a = -1; a <= 1; a++) for (let b = -1; b <= 1; b++) {
      const m = new THREE.Mesh(geo, this._cloudMat);
      m.position.set(a * this._cloudSize, 0, b * this._cloudSize);
      m.userData.noHit = true; m.userData.noVox = true;
      m.frustumCulled = false;
      this.cloudGroup.add(m);
    }
    this.cloudGroup.position.y = 128;
    this._cloudDrift = 0;
    this.scene.add(this.cloudGroup);
  }

  updateClouds(deltaTime) {
    if (!this.cloudGroup || !this.camera) return;
    this._cloudDrift = (this._cloudDrift + deltaTime * 0.6) % this._cloudSize;
    const S = this._cloudSize, c = this.camera.position;
    const ox = Math.floor((c.x - this._cloudDrift) / S) * S + this._cloudDrift - S / 2;
    const oz = Math.floor(c.z / S) * S - S / 2;
    this.cloudGroup.position.x = ox; this.cloudGroup.position.z = oz;
  }

  setupEventListeners() {
    window.addEventListener('resize', () => this.onWindowResize());
  }

  onWindowResize() {
    this.width = window.innerWidth;
    this.height = window.innerHeight;
    this.camera.aspect = this.width / this.height;
    this.camera.updateProjectionMatrix();
    this.renderer.setSize(this.width, this.height);
    this.renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    if (this.composer) {
      this.composer.setSize(this.width, this.height);
      this.bloomPass?.resolution?.set(this.width * 0.5, this.height * 0.5);
      this.gradePass?.uniforms.uResolution.value.set(this.width, this.height);
    }
  }

  // Reskin everything entering the world into the voxel (Minecraft/Hytale) look.
  // (scene.add is itself wrapped to blockify, so this is just a named alias.)
  addObject(object) { this.scene.add(object); }
  removeObject(object) { this.scene.remove(object); }

  render() {
    for (const f of this.preRender) { try { f(); } catch (e) { console.error('[preRender]', e); } }
    if (this.composer) {
      this._fxTime += 0.016;
      if (this.gradePass) this.gradePass.uniforms.uTime.value = this._fxTime;
      this.composer.render();
    } else {
      this.renderer.render(this.scene, this.camera);
    }
  }

  getSkyColor() {
    return this.skyUniforms ? this.skyUniforms.horizonColor.value.getHex() : 0x87ceeb;
  }

  setSkyColor(color) {
    if (this.skyUniforms) {
      const c = new THREE.Color(color);
      this.skyUniforms.horizonColor.value.copy(c);
    }
  }

  getScene() { return this.scene; }
  getCamera() { return this.camera; }
  getRenderer() { return this.renderer; }
}
