// GeoModel.js — builds THREE meshes from Bedrock/GeckoLib ".geo.json" models.
//
// Used for the gun models from Greenboy's Legendary Guns (MIT License,
// Copyright (c) GreenBoyGamerr; see CREDITS.md), imported into
// public/models/glg/ by tools/import_glg.py.
//
// Geometry follows GeckoLib's conventions (which match Blockbench): the model
// is built in Bedrock space (cube origins are absolute, in pixels; bones
// rotate about absolute pivots, Z then Y then X) and the result is mirrored on
// X, exactly like GeckoLib renders it. Faces get vanilla-style directional
// shading through vertex colours (up 1.0, N/S 0.8, E/W 0.6, down 0.5).

import * as THREE from 'three';
import MANIFEST from './glg_manifest.json';

const BASE = (import.meta.env?.BASE_URL ?? '/') + 'models/glg/';
const D2R = Math.PI / 180;
const SHADE = { up: 1, down: 0.5, north: 0.8, south: 0.8, east: 0.6, west: 0.6 };

export function hasGunModel(type) { return !!MANIFEST[type]; }
export function gunDisplay(type, kind) { return MANIFEST[type]?.[kind] ?? null; }

// corners as seen from outside the face: TL, TR, BL, BR
function faceCorners(f, x0, y0, z0, x1, y1, z1) {
  switch (f) {
    case 'north': return [[x1, y1, z0], [x0, y1, z0], [x1, y0, z0], [x0, y0, z0]];
    case 'south': return [[x0, y1, z1], [x1, y1, z1], [x0, y0, z1], [x1, y0, z1]];
    case 'east': return [[x1, y1, z1], [x1, y1, z0], [x1, y0, z1], [x1, y0, z0]];
    case 'west': return [[x0, y1, z0], [x0, y1, z1], [x0, y0, z0], [x0, y0, z1]];
    case 'up': return [[x0, y1, z0], [x1, y1, z0], [x0, y1, z1], [x1, y1, z1]];
    default: return [[x0, y0, z1], [x1, y0, z1], [x0, y0, z0], [x1, y0, z0]];   // down
  }
}

// One cube's quads appended to arrays, positions relative to `off` (px).
function addCube(c, off, tw, th, A) {
  const inf = c.inflate ?? 0;
  const x0 = c.origin[0] - inf - off[0], y0 = c.origin[1] - inf - off[1], z0 = c.origin[2] - inf - off[2];
  const x1 = x0 + c.size[0] + 2 * inf, y1 = y0 + c.size[1] + 2 * inf, z1 = z0 + c.size[2] + 2 * inf;
  for (const [f, uvf] of Object.entries(c.uv ?? {})) {
    if (!uvf?.uv) continue;
    const [u, v] = uvf.uv, [w, h] = uvf.uv_size ?? [0, 0];
    if (!w || !h) continue;
    const u0 = u / tw, u1 = (u + w) / tw, v0 = 1 - v / th, v1 = 1 - (v + h) / th;
    const P = faceCorners(f, x0, y0, z0, x1, y1, z1);
    const UV = [[u0, v0], [u1, v0], [u0, v1], [u1, v1]];
    const base = A.pos.length / 3, s = SHADE[f] ?? 1;
    for (let i = 0; i < 4; i++) { A.pos.push(P[i][0] / 16, P[i][1] / 16, P[i][2] / 16); A.uv.push(UV[i][0], UV[i][1]); A.col.push(s, s, s); }
    A.idx.push(base, base + 2, base + 1, base + 1, base + 2, base + 3);
  }
}

function meshFrom(A, mat) {
  if (!A.idx.length) return null;
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(A.pos, 3));
  g.setAttribute('uv', new THREE.Float32BufferAttribute(A.uv, 2));
  g.setAttribute('color', new THREE.Float32BufferAttribute(A.col, 3));
  g.setIndex(A.idx);
  const m = new THREE.Mesh(g, mat);
  m.userData.noVox = true; m.userData.noHit = true;
  return m;
}

const rotOf = (r) => new THREE.Euler(-(r?.[0] ?? 0) * D2R, (r?.[1] ?? 0) * D2R, -(r?.[2] ?? 0) * D2R, 'ZYX');

// Build the bone hierarchy. Returns a group (in blocks) whose origin is the
// model origin, already mirrored on X like GeckoLib.
function buildGeo(geo, mat) {
  const root = new THREE.Group();
  const byName = new Map(), pivotOf = new Map();
  // bones may be listed before their parents: create all, then link
  for (const b of geo.bones) { byName.set(b.name, new THREE.Group()); pivotOf.set(b.name, b.pivot ?? [0, 0, 0]); }
  for (const b of geo.bones) {
    const pv = pivotOf.get(b.name), grp = byName.get(b.name);
    grp.name = b.name;
    const parent = b.parent && byName.get(b.parent);
    const ppv = parent ? pivotOf.get(b.parent) : [0, 0, 0];
    const p = b.pose?.position ?? [0, 0, 0];
    grp.position.set((pv[0] - ppv[0] + p[0]) / 16, (pv[1] - ppv[1] + p[1]) / 16, (pv[2] - ppv[2] + p[2]) / 16);
    const r = b.rotation ?? [0, 0, 0], pr = b.pose?.rotation ?? [0, 0, 0];
    grp.rotation.copy(rotOf([r[0] + pr[0], r[1] + pr[1], r[2] + pr[2]]));
    if (b.pose?.scale) grp.scale.set(...b.pose.scale.map((v) => v || 1e-4));
    (parent || root).add(grp);
    // unrotated cubes merge into one mesh per bone; rotated ones get a pivot group
    const flat = { pos: [], uv: [], col: [], idx: [] };
    for (const c of b.cubes ?? []) {
      if (c.rotation && c.rotation.some((x) => x)) {
        const cp = c.pivot ?? pv;
        const cg = new THREE.Group();
        cg.position.set((cp[0] - pv[0]) / 16, (cp[1] - pv[1]) / 16, (cp[2] - pv[2]) / 16);
        cg.rotation.copy(rotOf(c.rotation));
        const A = { pos: [], uv: [], col: [], idx: [] };
        addCube(c, cp, geo.tw, geo.th, A);
        const m = meshFrom(A, mat); if (m) cg.add(m);
        grp.add(cg);
      } else addCube(c, pv, geo.tw, geo.th, flat);
    }
    const m = meshFrom(flat, mat); if (m) grp.add(m);
    if (b.pose?.scale?.some((v) => !v)) grp.visible = false;   // idle pose hides it
  }
  const outer = new THREE.Group();
  root.scale.x = -1;
  outer.add(root);
  return outer;
}

const _geo = new Map(), _tex = new Map();
const loader = new THREE.TextureLoader();

function loadTexture(type) {
  if (!_tex.has(type)) {
    const t = loader.load(BASE + type + '.png');
    t.magFilter = THREE.NearestFilter; t.minFilter = THREE.NearestFilter; t.generateMipmaps = false;
    t.colorSpace = THREE.SRGBColorSpace;
    _tex.set(type, t);
  }
  return _tex.get(type);
}
function loadGeo(type) {
  if (!_geo.has(type)) _geo.set(type, fetch(BASE + type + '.json').then((r) => r.json()));
  return _geo.get(type);
}

// Material: unlit + vertex shading. `overlay` squeezes the depth into the
// nearest 2% of the depth range so a held gun always draws over the world
// but still sorts its own faces correctly.
export function gunMaterial(type, { overlay = false } = {}) {
  const mat = new THREE.MeshBasicMaterial({ map: loadTexture(type), vertexColors: true, alphaTest: 0.1, side: THREE.DoubleSide, toneMapped: false });
  if (overlay) {
    mat.onBeforeCompile = (sh) => {
      sh.vertexShader = sh.vertexShader.replace('#include <project_vertex>', '#include <project_vertex>\n  gl_Position.z = mix(-gl_Position.w, gl_Position.z, 0.02);');
    };
    mat.customProgramCacheKey = () => 'gun-overlay';
  }
  return mat;
}

// Async: a THREE.Group for the gun (origin = model origin, in blocks).
export async function buildGunModel(type, opts = {}) {
  if (!MANIFEST[type]) return null;
  const geo = await loadGeo(type);
  const g = buildGeo(geo, gunMaterial(type, opts));
  g.userData.noVox = true; g.userData.noHit = true;
  g.traverse((o) => { o.userData.noVox = true; o.userData.noHit = true; if (opts.overlay) o.renderOrder = 1000; });
  return g;
}

// Vanilla ItemTransform as a matrix: translate (px, clamped +-80), rotate XYZ, scale.
export function displayMatrix(d, out = new THREE.Matrix4()) {
  const t = (d?.translation ?? [0, 0, 0]).map((v) => Math.max(-80, Math.min(80, v)) / 16);
  const r = (d?.rotation ?? [0, 0, 0]).map((v) => v * D2R);
  const s = d?.scale ?? [1, 1, 1];
  const q = new THREE.Quaternion().setFromEuler(new THREE.Euler(r[0], r[1], r[2], 'XYZ'));
  return out.compose(new THREE.Vector3(t[0], t[1], t[2]), q, new THREE.Vector3(s[0], s[1], s[2]));
}
