// ViewModel.js — first-person hand and held item, vanilla style.
//
//  Empty hand : the right arm (skin + jacket sleeve, original texture) reaching
//               in from the bottom-right corner.
//  Block      : a small textured cube held in front of the arm.
//  Item/tool  : the 16x16 item sprite extruded 1 px thick (front/back faces
//               textured, every opaque pixel edge gets a side quad in that
//               pixel's colour) — how vanilla builds item models.
// Swing, equip-dip and eating animations follow vanilla timing.

import * as THREE from 'three';
import { BLOCKS, ITEM_TO_BLOCK, blockTexture } from '../world/Blocks.js';
import { SHAPE, shapeGeometry } from '../world/Shapes.js';
import { mcTexture } from '../content/McContent.js';
import { extrudeSprite } from '../content/ItemMesh.js';
import { itemIconCanvas } from '../ui/ItemIcons.js';
import { hasGunModel, buildGunModel, gunDisplay, displayMatrix } from '../content/GeoModel.js';

// Non-Minecraft items use the UI pixel icons (overridable for tests)
let itemIconCanvasFor = itemIconCanvas;
export function setItemIconSource(fn) { itemIconCanvasFor = fn; }

const PX = 1 / 16;

function canvas(w, h, paint) {
  const c = document.createElement('canvas'); c.width = w; c.height = h;
  const g = c.getContext('2d'); paint(g); return c;
}
function tex(c) {
  const t = new THREE.CanvasTexture(c);
  t.magFilter = THREE.NearestFilter; t.minFilter = THREE.NearestFilter; t.generateMipmaps = false;
  t.colorSpace = THREE.SRGBColorSpace;
  return t;
}

// Arm skin, 4 px wide x 12 px long; row 0 = fist end. Original survivor look:
// tanned skin, dark-teal jacket sleeve with a lighter cuff stripe.
const SKIN = ['#b98a62', '#c69872', '#d2a47e', '#ddb08a'];
const SLEEVE = ['#1f2e33', '#273a40', '#2f454c'];
function armSide(shade) {
  return canvas(4, 12, (g) => {
    for (let y = 0; y < 12; y++) for (let x = 0; x < 4; x++) {
      let c;
      if (y >= 7) c = y === 7 ? '#3d5a62' : SLEEVE[(x + y) % 3 === 0 ? 0 : (x * 7 + y) % 5 === 0 ? 2 : 1];
      else c = SKIN[y === 0 ? 3 : (x * 5 + y * 3) % 7 === 0 ? 0 : (x + y) % 4 === 0 ? 2 : 1];
      g.fillStyle = c; g.fillRect(x, y, 1, 1);
    }
    if (shade < 1) { g.fillStyle = `rgba(0,0,0,${1 - shade})`; g.fillRect(0, 0, 4, 12); }
  });
}
function armEnd(sleeve) {
  return canvas(4, 4, (g) => {
    for (let y = 0; y < 4; y++) for (let x = 0; x < 4; x++) {
      g.fillStyle = sleeve ? SLEEVE[(x + y) % 3] : SKIN[(x === 0 || y === 0) ? 3 : (x + y) % 3 ? 1 : 2];
      g.fillRect(x, y, 1, 1);
    }
  });
}

// Extruded item mesh (shared builder), cached per item id
const _itemCache = new Map();
const _gunCache = new Map();

function itemModel(id) {
  if (_itemCache.has(id)) return _itemCache.get(id);
  const src = mcTexture(id)?.image || itemIconCanvasFor(id);
  const m = extrudeSprite(src, { overlay: true });
  _itemCache.set(id, m);
  return m;
}


export class ViewModel {
  constructor(game) {
    this.game = game;
    this.root = new THREE.Group();
    this.root.userData.noVox = true; this.root.userData.noHit = true;

    // arm: the player model's right arm box, 4x12x4 px spanning x -3..1,
    // y -2..10, z -2..2 (1 px = 1/16 block), fist at +y. Posed every frame by
    // the vanilla first-person arm transform chain (see _armMatrix).
    const geo = new THREE.BoxGeometry(4 / 16, 12 / 16, 4 / 16);
    geo.translate(-1 / 16, 4 / 16, 0);
    const m = (c, k = 1) => new THREE.MeshBasicMaterial({ map: tex(c), color: new THREE.Color(k, k, k), depthTest: false, toneMapped: false });
    // BoxGeometry groups: +x, -x, +y, -y, +z, -z (pre-rotation; +y is the fist end)
    this.arm = new THREE.Mesh(geo, [m(armSide(1), 0.72), m(armSide(1), 0.6), m(armEnd(false), 1), m(armEnd(true), 0.5), m(armSide(1), 1), m(armSide(1), 0.82)]);
    this.arm.renderOrder = 999;

    this.block = new THREE.Mesh(new THREE.BoxGeometry(1, 1, 1), [0, 1, 2, 3, 4, 5].map(() => new THREE.MeshBasicMaterial({ depthTest: false, toneMapped: false })));
    this.block.renderOrder = 999;
    this.itemSlot = new THREE.Group();

    for (const o of [this.arm, this.block]) { o.userData.noHit = true; o.userData.noVox = true; }
    this.root.add(this.arm, this.block, this.itemSlot);
    game.scene.scene.add(this.root);

    this._key = null;
    this._equip = 1;           // 0..1, dips the hand when the held item changes
  }

  _setHeld(item) {
    const key = item ? item.type : '';
    if (key === this._key) return;
    this._key = key; this._equip = 0; this._lit = -1;
    this.itemSlot.clear();
    const blockId = item ? (ITEM_TO_BLOCK[item.type] ?? 0) : 0;
    this.mode = 'arm';
    if (blockId && BLOCKS[blockId].render !== 'cross') {
      const b = BLOCKS[blockId], tx = b.tex;
      const order = [tx.side, tx.side, tx.top, tx.bottom, tx.front || tx.side, tx.side];
      const shade = [0.6, 0.8, 1, 0.5, 0.6, 0.6];   // +x,-x,top,bottom,+z,-z; left face (-x) lit, right (+z) shaded
      this._cubeGeo ??= this.block.geometry;
      this.block.geometry = (b.shape && b.shape !== SHAPE.pillar && shapeGeometry(b.shape)) || this._cubeGeo;
      this.block.material.forEach((mm, i) => { mm.map = blockTexture(order[i]); mm.color.setScalar(shade[i]); mm.userData.base = mm.color.clone(); mm.alphaTest = b.render === 'cube' ? 0 : 0.5; mm.transparent = false; mm.needsUpdate = true; });
      this.mode = 'block';
    } else if (item && hasGunModel(item.type)) {
      // 3D gun model (Greenboy's Legendary Guns, MIT): the flat icon stands in
      // until the model has loaded
      const type = item.type;
      this.mode = 'gun';
      this._gunDisp = displayMatrix(gunDisplay(type, 'firstperson_righthand'));
      const cached = _gunCache.get(type);
      if (cached) this.itemSlot.add(cached);
      else buildGunModel(type, { overlay: true }).then((m) => {
        if (!m) return;
        _gunCache.set(type, m);
        if (this._key === type) this.itemSlot.add(m);
      }).catch((e) => console.warn('[ViewModel] gun model', type, e));
    } else if (item) {
      const model = itemModel(item.type);
      if (model) { this.itemSlot.add(model); this.mode = 'item'; }
    }
  }

  update(dt, cam, st) {
    const show = st.show;
    this.root.visible = show;
    if (!show) return;
    this._setHeld(st.item);
    this._equip = Math.min(1, this._equip + dt * 5);
    const s = st.swing, eat = st.eating;
    // The hand hangs off the un-bobbed view: vanilla applies the same view
    // bob to the world and the hand, so the hand sways on screen exactly as
    // much as the world does (the camera carries the inverse bob).
    const pl = this.game?.player, bx = 0, by = 0;
    this.root.position.copy(pl?._viewBasePos ?? cam.position);
    this.root.quaternion.copy(pl?._viewBaseQuat ?? cam.quaternion);

    this.arm.visible = this.mode === 'arm';
    this.block.visible = this.mode === 'block';
    this.itemSlot.visible = this.mode === 'item' || this.mode === 'gun';
    // gun feedback: kick back on each shot, dip down while reloading
    if (this.mode === 'gun') {
      const w = this.game.weaponManager?.getCurrentWeapon?.();
      if (w && this._lastAmmo != null && w.ammoInMag < this._lastAmmo) this._kick = 1;
      this._lastAmmo = w?.ammoInMag ?? null;
      this._kick = Math.max(0, (this._kick ?? 0) - dt * 12);
      this._reloadDip = w?.isReloading ? Math.sin(Math.min(1, w.reloadProgress ?? 0) * Math.PI) : 0;
    }

    if (this.mode === 'arm') {
      this.arm.matrixAutoUpdate = false;
      this._armMatrix(s, 1 - this._equip, bx, by);
    }
    const o = this.mode === 'arm' ? null : this.mode === 'block' ? this.block : this.itemSlot;
    if (o) {
      o.matrixAutoUpdate = false;
      this._heldMatrix(o, this.mode === 'gun' ? 0 : s, 1 - this._equip, bx, by, this.mode === 'block', eat ? st.eatT : null, this.mode === 'gun' ? this._gunDisp : null);
    }
    // held things darken with the daylight like the world around them
    // ...and with the light level where the player stands (dark in caves)
    const vw = this.game.voxelWorld, e = cam.position;
    const l = vw?.brightnessAt ? vw.brightnessAt(e.x, e.y, e.z) : (vw?._daylight ?? 1);
    // per material, so meshes swapped in later (hand, new held item) catch up
    this._lit = l;
    this.root.traverse((m) => {
      if (!m.material) return;
      for (const mm of [].concat(m.material)) {
        if (mm.userData.lit !== undefined && Math.abs(mm.userData.lit - l) < 0.004) continue;
        mm.userData.base ??= mm.color.clone();
        mm.color.copy(mm.userData.base).multiplyScalar(l);
        mm.userData.lit = l;
      }
    });
    this.root.updateMatrixWorld();
  }

  // Vanilla held-item pose (ItemInHandRenderer, right hand), camera space:
  // swing offset -> item-arm transform (0.56, -0.52, -0.72) -> attack
  // rotation -> the model's firstperson_righthand display transform
  // (block: rot 0/45/0 scale 0.4; flat item: rot 0/-90/25, move 1.13/3.2/1.13 px, scale 0.68).
  _heldMatrix(o, swing, equip, bx, by, isBlock, eatT, gunDisp = null) {
    const M = this._hm ??= new THREE.Matrix4(), T = this._ht ??= new THREE.Matrix4();
    const D = Math.PI / 180, PI = Math.PI;
    if (eatT != null) {
      // eating/drinking: item raised toward the mouth, bobbing (vanilla eat transform at full use)
      const f2 = Math.abs(Math.cos(eatT * 10)) * 0.1;
      M.makeTranslation(0.6 + bx, f2 - 0.5 + by, 0);
      M.multiply(T.makeRotationY(90 * D)); M.multiply(T.makeRotationX(10 * D)); M.multiply(T.makeRotationZ(30 * D));
      M.multiply(T.makeTranslation(0.56, -0.52 - equip * 0.6, -0.72));
    } else {
      const r = Math.sqrt(swing);
      M.makeTranslation(-0.4 * Math.sin(r * PI) + bx, 0.2 * Math.sin(r * PI * 2) + by, -0.2 * Math.sin(swing * PI));
      M.multiply(T.makeTranslation(0.56, -0.52 - equip * 0.6, -0.72));
      const f = Math.sin(swing * swing * PI), f1 = Math.sin(r * PI);
      M.multiply(T.makeRotationY((45 - f * 20) * D));
      M.multiply(T.makeRotationZ(-f1 * 20 * D));
      M.multiply(T.makeRotationX(-f1 * 80 * D));
      M.multiply(T.makeRotationY(-45 * D));
    }
    if (gunDisp) {
      // the model's own firstperson_righthand transform; GeckoLib then sits
      // the model origin 0.01 above the transform origin
      const k = this._kick ?? 0, dip = this._reloadDip ?? 0;
      M.multiply(T.makeTranslation(0, -dip * 0.35, k * 0.06));
      M.multiply(T.makeRotationX(k * 4 * D - dip * 25 * D));
      M.multiply(gunDisp);
      M.multiply(T.makeTranslation(0, 0.01, 0));
    } else if (isBlock) {
      M.multiply(T.makeRotationY(45 * D));
      M.multiply(T.makeScale(0.4, 0.4, 0.4));
    } else {
      M.multiply(T.makeTranslation(1.13 / 16, 3.2 / 16, 1.13 / 16));
      M.multiply(T.makeRotationFromEuler(this._he ??= new THREE.Euler(0, -90 * D, 25 * D, 'XYZ')));
      M.multiply(T.makeScale(0.68, 0.68, 0.68));
    }
    o.matrix.copy(M);
  }

  // Vanilla empty-hand pose (right arm), in camera space. swing 0..1,
  // equip 0..1 (1 = fully lowered while switching), plus view bob offset.
  _armMatrix(swing, equip, bx = 0, by = 0) {
    const M = this._am ??= new THREE.Matrix4(), T = this._at ??= new THREE.Matrix4();
    const D = Math.PI / 180, PI = Math.PI;
    const f1 = Math.sqrt(swing);
    const f2 = -0.3 * Math.sin(f1 * PI), f3 = 0.4 * Math.sin(f1 * PI * 2), f4 = -0.4 * Math.sin(swing * PI);
    const f5 = Math.sin(swing * swing * PI), f6 = Math.sin(f1 * PI);
    M.makeTranslation(f2 + 0.64 + bx, f3 - 0.6 - equip * 0.6 + by, f4 - 0.72);
    M.multiply(T.makeRotationY(45 * D));
    M.multiply(T.makeRotationY(f6 * 70 * D));
    M.multiply(T.makeRotationZ(-f5 * 20 * D));
    M.multiply(T.makeTranslation(-1, 3.6, 3.5));
    M.multiply(T.makeRotationZ(120 * D));
    M.multiply(T.makeRotationX(200 * D));
    M.multiply(T.makeRotationY(-135 * D));
    M.multiply(T.makeTranslation(5.6, 0, 0));
    M.multiply(T.makeTranslation(-5 / 16, 2 / 16, 0));    // shoulder pivot
    M.multiply(T.makeRotationZ(0.1));                     // idle arm bob at rest
    this.arm.matrix.copy(M);
  }
}
