// BlockInteraction.js — vanilla-style mining, placing and "use" (right-click).
//
//  LMB hold  : break the targeted block. Per-tick damage = speed / hardness /
//              (30 if harvestable, 100 if not), x0.2 while airborne. A 10-stage
//              crack overlay shows progress; 5-tick delay between blocks.
//  RMB       : talk to the NPC under the crosshair > open the targeted
//              crafting table / furnace / chest (unless sneaking) > eat held
//              food (hold 1.6 s) > place the held block against the face.
//  Guns never break blocks; LMB on a mob closer than the block attacks it.

import * as THREE from 'three';
import { BLOCKS, ITEM_TO_BLOCK, crackTextures, blockTexture } from '../world/Blocks.js';
import { mcToolInfo } from '../content/McContent.js';
import { SHAPE } from '../world/Shapes.js';
import { ViewModel } from './ViewModel.js';

const FULL_BOX = [[0, 0, 0, 1, 1, 1]];
// Crack overlay geometry for a block's boxes (block-local 0..1). Each face's
// UV is its position on the face plane, in blocks, with the same axes the
// chunk mesher uses for block textures (+x: 1-z,y  -x: z,y  +y: x,1-z
// -y: x,z  +z: x,y  -z: 1-x,y), so the 16x16 crack lands on the block's
// own pixel grid.
function crackGeometry(boxes) {
  const pos = [], uv = [], idx = [];
  const face = (P, U) => {
    const n = pos.length / 3;
    for (let i = 0; i < 4; i++) { pos.push(...P[i]); uv.push(...U(P[i])); }
    idx.push(n, n + 1, n + 2, n, n + 2, n + 3);
  };
  for (const b of boxes) {
    const [x0, y0, z0, x1, y1, z1] = b;
    face([[x1, y0, z1], [x1, y0, z0], [x1, y1, z0], [x1, y1, z1]], (p) => [1 - p[2], p[1]]);   // +x
    face([[x0, y0, z0], [x0, y0, z1], [x0, y1, z1], [x0, y1, z0]], (p) => [p[2], p[1]]);       // -x
    face([[x0, y1, z1], [x1, y1, z1], [x1, y1, z0], [x0, y1, z0]], (p) => [p[0], 1 - p[2]]);   // +y
    face([[x0, y0, z0], [x1, y0, z0], [x1, y0, z1], [x0, y0, z1]], (p) => [p[0], p[2]]);       // -y
    face([[x0, y0, z1], [x1, y0, z1], [x1, y1, z1], [x0, y1, z1]], (p) => [p[0], p[1]]);       // +z
    face([[x1, y0, z0], [x0, y0, z0], [x0, y1, z0], [x1, y1, z0]], (p) => [1 - p[0], p[1]]);   // -z
  }
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
  g.setAttribute('uv', new THREE.Float32BufferAttribute(uv, 2));
  g.setIndex(idx);
  return g;
}

const REACH = 4.5, MOB_REACH = 3.0;
const TIER = {
  wooden: { level: 1, speed: 2 }, gold: { level: 1, speed: 12 }, stone: { level: 2, speed: 4 },
  iron: { level: 3, speed: 6 }, diamond: { level: 4, speed: 8 }, netherite: { level: 5, speed: 9 },
};

export class BlockInteraction {
  constructor(game) {
    this.game = game;
    this.target = null;            // { x, y, z, id, nx, ny, nz, dist, name }
    this.breaking = null;          // { key, progress, ticks }
    this.isEating = false;
    this._eatTime = 0;
    this._breakDelay = 0;
    this._placeDelay = 0;
    this._rmbWas = false;
    this._mobTargeted = false;
    this._swing = 0;

    const scene = game.scene.scene;
    // Thin black outline around the targeted block (vanilla selection box)
    const eg = new THREE.EdgesGeometry(new THREE.BoxGeometry(1.004, 1.004, 1.004));
    this.outline = new THREE.LineSegments(eg, new THREE.LineBasicMaterial({ color: 0x000000, transparent: true, opacity: 0.55 }));
    this.outline.visible = false;
    this.outline.userData.noVox = true; this.outline.userData.noHit = true;
    scene.add(this.outline);

    // Crack overlay: vanilla blends the destroy stages with a 2x multiply
    // (result = 2 * src * dst), so grey 128 leaves the block unchanged, dark
    // crack pixels darken it and light rim pixels brighten it, in any light.
    this.cracks = crackTextures();
    this.crackMat = new THREE.ShaderMaterial({
      uniforms: { map: { value: this.cracks[0] } },
      vertexShader: 'varying vec2 vUv; void main(){ vUv = uv; gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0); }',
      fragmentShader: 'uniform sampler2D map; varying vec2 vUv; void main(){ vec4 c = texture2D(map, vUv); if (c.a < 0.5) discard; gl_FragColor = vec4(c.rgb, 1.0); }',
      transparent: true, depthWrite: false,
      blending: THREE.CustomBlending, blendEquation: THREE.AddEquation,
      blendSrc: THREE.DstColorFactor, blendDst: THREE.SrcColorFactor,
      polygonOffset: true, polygonOffsetFactor: -1, polygonOffsetUnits: -10,   // vanilla POLYGON_OFFSET_LAYERING
    });
    // The overlay is rebuilt from the block's own boxes with UVs taken from
    // block-space position (vanilla's SheetedDecalTextureGenerator), so a
    // crack pixel always covers exactly one block-texture pixel: a slab's
    // side shows the lower half of the crack, never a squashed copy.
    this.crack = new THREE.Mesh(new THREE.BufferGeometry(), this.crackMat);
    this.crack.visible = false;
    this.crack.userData.noVox = true; this.crack.userData.noHit = true;
    scene.add(this.crack);

    // Break particles
    this.particles = [];
    // terrain particles: camera-facing quads showing a random 4x4 px patch
    // of the block's texture (one geometry per patch offset, shared)
    this._pGeos = [];
    for (let i = 0; i < 16; i++) {
      const g = new THREE.PlaneGeometry(1, 1), uv = g.attributes.uv;
      const u0 = (i % 4) / 4, v0 = Math.floor(i / 4) / 4;
      for (let k = 0; k < uv.count; k++) uv.setXY(k, u0 + uv.getX(k) * 0.25, v0 + uv.getY(k) * 0.25);
      this._pGeos.push(g);
    }
    this._pMats = new Map();

    // First-person hand / held item (vanilla view model)
    this.viewModel = new ViewModel(game);
    this._bobT = 0;


    this._dir = new THREE.Vector3();
    this._eye = new THREE.Vector3();
  }

  // ── held item helpers ─────────────────────────────────────────────────────
  held() {
    const inv = this.game.inventorySystem;
    return inv?.slots?.[inv.heldSlot ?? 0] ?? null;
  }
  _gunInHand() {
    const w = this.game.weaponManager?.getCurrentWeapon?.();
    return !!w && w.magSize !== -1 && !(w.toolKind);
  }
  _isFood(item) {
    const def = item && this.game.inventorySystem?.itemTypes?.[item.type];
    return !!def && def.usable && (def.category === 'food' || def.category === 'drink');
  }

  // Called by Game.handleWeaponInput: should LMB break a block instead of swinging/firing?
  consumesLeftClick() {
    if (this._gunInHand()) return false;
    return !!this.target && !this._mobTargeted;
  }

  // ── per-frame ─────────────────────────────────────────────────────────────
  update(dt) {
    const g = this.game, im = g.inputManager;
    const cam = g.scene.getCamera();
    this._updateParticles(dt);
    this._updateView(dt, cam);
    if (g.inFriendHouse || !g.voxelWorld || !g.player) return this._hide();
    const locked = im.isPointerLocked?.();
    const uiOpen = g.inventorySystem?.isOpen || g.commandSystem?.isOpen || g.settingsMenu?.isOpen || g.isPaused;

    cam.getWorldPosition(this._eye);
    cam.getWorldDirection(this._dir);
    const hit = g.voxelWorld.raycast(this._eye, this._dir, REACH);
    this.target = hit ? { ...hit, name: BLOCKS[hit.id].name } : null;
    this._mobTargeted = this._mobUnderCrosshair(hit ? hit.dist : REACH);

    if (this.target && !uiOpen) {
      const b = BLOCKS[this.target.id], t = this.target;
      const cross = b.render === 'cross';
      this.outline.visible = true;
      if (b.shape && b.shape !== SHAPE.pillar) {
        // outline every box of the shape (slab half, stair L, wall post/arms)
        this._setOutline(g.voxelWorld.selBoxes(t.x, t.y, t.z, t.id));
        this.outline.position.set(t.x, t.y, t.z); this.outline.scale.set(1, 1, 1);
      } else {
        this._setOutline(null);
        this.outline.position.set(t.x + 0.5, t.y + (cross ? 0.4 : 0.5), t.z + 0.5);
        this.outline.scale.set(cross ? 0.7 : 1, cross ? 0.8 : 1, cross ? 0.7 : 1);
      }
    } else this.outline.visible = false;

    if (this._breakDelay > 0) this._breakDelay -= dt;
    if (this._placeDelay > 0) this._placeDelay -= dt;

    // ── breaking ──
    const lmb = locked && !uiOpen && im.mouse.leftClick;
    if (lmb && this.consumesLeftClick() && this._breakDelay <= 0) this._mine(dt);
    else this._resetBreak();
    if (lmb && !this._gunInHand() && this._swing === 0 && this.consumesLeftClick()) this._swing = 0.001;   // mining keeps swinging; attacks swing per click (Melee.fire)

    // ── using ──
    const rmb = locked && !uiOpen && im.mouse.rightClick;
    const rmbDown = rmb && !this._rmbWas;
    this._rmbWas = rmb;
    const item = this.held();
    if (rmb && this._isFood(item) && !this._gunInHand() && (g.player.hunger < g.player.maxHunger || /golden|potion|drink|water/.test(item.type))) {
      if (!this.isEating) { this.isEating = true; this._eatTime = 0; }
      this._eatTime += dt;
      this._swing = 0;
      if ((this._eatSound = (this._eatSound ?? 0) - dt) <= 0) { this._eatSound = 0.22; g.audioManager?.playEat?.(); }
      if (this._eatTime >= 1.6) {
        this.game.inventorySystem.useItem(this.game.inventorySystem.heldSlot ?? 0);
        this.isEating = false; this._eatTime = 0;
      }
      return;
    }
    this.isEating = false; this._eatTime = 0;
    // bow: hold to draw, release to shoot (full power after 1 s, vanilla curve)
    if (item?.type === 'mc_bow') {
      if (rmb) {
        if (this._bowDraw == null) this._bowDraw = this._arrowSlot() ? 0 : null;
        if (this._bowDraw != null) this._bowDraw += dt;
        return;
      }
      if (this._bowDraw != null) { this._shootBow(this._bowDraw); this._bowDraw = null; }
    } else this._bowDraw = null;
    if (!rmb || this._gunInHand()) return;
    if (rmbDown && this._tryNPC()) return;
    // jukebox: insert a disc / eject the one playing
    if (rmbDown && this.target && !im.isKeyPressed('shift') && BLOCKS[this.target.id].interact === 'jukebox') {
      const t = this.target;
      if (g.jukebox?.use(`${t.x},${t.y},${t.z}`, t.x, t.y, t.z, item)) { this._swingNow(); return; }
    }
    // SecurityCraft devices: keypad, panic button, username logger
    if (rmbDown && this.target && !im.isKeyPressed('shift') && /^sc_/.test(BLOCKS[this.target.id].interact ?? '')) {
      const t = this.target;
      if (g.security?.interact(BLOCKS[t.id].interact, t.x, t.y, t.z)) { this._swingNow(); return; }
    }
    // spawn eggs: hatch the mob on the clicked face
    if (rmbDown && this.target && /_spawn_egg$/.test(item?.type ?? '')) {
      const t = this.target, zm = g.zombieManager;
      const kind = item.type.replace(/^mc_|_spawn_egg$/g, '');
      const z = zm?.spawn(kind, t.x + 0.5 + t.nx, t.z + 0.5 + t.nz);
      if (z) {
        const y = t.y + (t.ny < 0 ? -2 : t.ny > 0 ? 1 : 0);
        z.position.y = y + 0.9; if (z.body) z.body.position.y = y + 0.9; z._blockPos = null;
        if (!g.player?.godMode) g.inventorySystem.removeItem(g.inventorySystem.heldSlot ?? 0, 1);
        this._swingNow();
      }
      return;
    }
    if (rmbDown && this.target && !im.isKeyPressed('shift') && BLOCKS[this.target.id].interact && BLOCKS[this.target.id].interact !== 'jukebox' && !/^sc_/.test(BLOCKS[this.target.id].interact)) {
      const t = this.target, key = `${t.x},${t.y},${t.z}`;
      this._swingNow();
      g.inventorySystem?.mcScreen?.openContainer?.(BLOCKS[t.id].interact, key);
      return;
    }
    // a glass bottle on water fills it (the crosshair passes through water)
    if (rmbDown && item?.type === 'mc_glass_bottle' && this._lookingAtWater()) {
      g.inventorySystem.removeItem(g.inventorySystem.heldSlot ?? 0, 1);
      g.inventorySystem.addItem('water_bottle', 1);
      this._swingNow();
      this._sfx({ name: 'water' }, 0.3);
      return;
    }
    // throwing snowballs / ice balls / splash and lingering potions:
    // on click, then every 4 ticks while held (potions: once per click)
    const pot = /^mc_(splash|lingering)_potion_/.test(item?.type ?? '');
    if ((pot && rmbDown || /^mc_(snowball|ice_ball)$/.test(item?.type ?? '')) && g.throwables) {
      if (rmbDown || (this._throwDelay -= dt) <= 0) {
        g.throwables.playerThrow(item.type);
        g.inventorySystem.removeItem(g.inventorySystem.heldSlot ?? 0, 1);
        this._swingNow();
        this._throwDelay = 0.2;
      }
      return;
    }
    // placing: first click immediately, then every 4 ticks while held (vanilla)
    if (this.target && (rmbDown || this._placeDelay <= 0)) {
      if (this._place(item)) this._placeDelay = rmbDown ? 0.25 : 0.2;
    }
  }

  // First arrow the bow would use: offhand, then hotbar, then the rest
  _arrowSlot() {
    const inv = this.game.inventorySystem;
    if (!inv) return null;
    if (/^mc_arrow/.test(inv.offhand?.type ?? '')) return { off: true };
    for (let i = 0; i < inv.slots.length; i++) if (/^mc_arrow/.test(inv.slots[i]?.type ?? '')) return { i };
    return null;
  }

  _shootBow(t) {
    const g = this.game, inv = g.inventorySystem;
    const f = Math.min(1, t), power = Math.min(1, (f * f + f * 2) / 3);
    if (power < 0.1) return;
    const s = this._arrowSlot();
    if (!s) return;
    let kind;
    if (s.off) { kind = inv.offhand.type; inv.offhand.quantity -= 1; if (inv.offhand.quantity <= 0) inv.offhand = null; inv.mcScreen?._renderEquip?.(); }
    else { kind = inv.slots[s.i].type; inv.removeItem(s.i, 1); }
    g.throwables?.playerShoot(kind, power);
    this._swingNow();
  }

  // Is there water along the crosshair before the targeted block (5 blocks)?
  _lookingAtWater() {
    const vw = this.game.voxelWorld, cam = this.game.scene.getCamera?.();
    if (!vw?.isFluid || !cam) return false;
    const o = new THREE.Vector3(), d = new THREE.Vector3();
    cam.getWorldPosition(o); cam.getWorldDirection(d);
    const max = Math.min(5, this.target?.dist ?? 5);
    for (let s = 0; s <= max; s += 0.1) {
      const x = Math.floor(o.x + d.x * s), y = Math.floor(o.y + d.y * s), z = Math.floor(o.z + d.z * s);
      if (vw.isFluid(x, y, z)) return true;
    }
    return false;
  }

  // Swap the outline geometry: null = the unit cube, else block-local boxes
  _setOutline(boxes) {
    const sig = boxes ? boxes.map((b) => b.join(',')).join('|') : '';
    if (this._outlineSig === sig) return;
    this._outlineSig = sig;
    if (!this._cubeOutline) this._cubeOutline = this.outline.geometry;
    if (!boxes) { if (this.outline.geometry !== this._cubeOutline) { this.outline.geometry.dispose(); this.outline.geometry = this._cubeOutline; } return; }
    const pts = [], e = 0.002;
    for (const b of boxes) {
      const x0 = b[0] - e, y0 = b[1] - e, z0 = b[2] - e, x1 = b[3] + e, y1 = b[4] + e, z1 = b[5] + e;
      const c = [[x0, y0, z0], [x1, y0, z0], [x1, y0, z1], [x0, y0, z1], [x0, y1, z0], [x1, y1, z0], [x1, y1, z1], [x0, y1, z1]];
      for (const [i, j] of [[0, 1], [1, 2], [2, 3], [3, 0], [4, 5], [5, 6], [6, 7], [7, 4], [0, 4], [1, 5], [2, 6], [3, 7]]) pts.push(...c[i], ...c[j]);
    }
    const g = new THREE.BufferGeometry();
    g.setAttribute('position', new THREE.Float32BufferAttribute(pts, 3));
    if (this.outline.geometry !== this._cubeOutline) this.outline.geometry.dispose();
    this.outline.geometry = g;
  }

  _hide() { this.outline.visible = false; this.crack.visible = false; this.target = null; }

  // ── mining ────────────────────────────────────────────────────────────────
  _breakTicks(block) {
    if (block.hardness < 0) return Infinity;                 // bedrock
    if (block.hardness === 0) return 0;
    const item = this.held();
    const info = item ? mcToolInfo(item.type) : null;
    let speed = 1, level = 0;
    if (info) {
      const tier = TIER[info.tier] ?? TIER.wooden;
      if (info.kind === block.tool || (block.tool === 'hoe' && info.kind === 'hoe')) { speed = tier.speed; level = tier.level; }
      else if (info.kind === 'sword') speed = /leaves/.test(block.name) ? 1.5 : 1.5;
    }
    const harvest = block.level === 0 || level >= block.level;
    if (!this.game.player.isGrounded) speed /= 5;
    const dmg = speed / block.hardness / (harvest ? 30 : 100);
    if (dmg >= 1) return 0;
    return Math.ceil(1 / dmg);
  }
  _canHarvest(block) {
    if (block.needsTool) { const i = mcToolInfo(this.held()?.type ?? ''); if (!i || i.kind !== block.tool) return false; }
    if (block.level === 0) return true;
    const info = mcToolInfo(this.held()?.type ?? '');
    return !!info && info.kind === block.tool && (TIER[info.tier]?.level ?? 0) >= block.level;
  }

  _mine(dt) {
    const t = this.target, key = `${t.x},${t.y},${t.z}`;
    const block = BLOCKS[t.id];
    if (!this.breaking || this.breaking.key !== key) this.breaking = { key, progress: 0 };
    const ticks = this._breakTicks(block);
    if (!isFinite(ticks)) return;
    this._swing = Math.max(this._swing, 0.001);
    // progress advances once per 20 TPS tick, so stages change on ticks
    if (ticks === 0) this.breaking.progress = 1;
    else for (this.breaking.acc = (this.breaking.acc ?? 0) + dt * 20; this.breaking.acc >= 1; this.breaking.acc--) this.breaking.progress += 1 / ticks;
    // vanilla spawns one hit particle off the struck face every tick
    this._hitAcc = (this._hitAcc ?? 0) + dt * 20;
    for (; this._hitAcc >= 1; this._hitAcc--) this._hitParticle(block, t);
    // dig sound every 4 ticks
    if ((this._digSound = (this._digSound ?? 0) - dt) <= 0) { this._digSound = 0.2; this._sfx(block, 0.25); }
    if (this.breaking.progress >= 1) { this._break(t, block); return; }
    const stage = Math.min(9, Math.floor(this.breaking.progress * 10));
    this.crackMat.uniforms.map.value = this.cracks[stage];
    const boxes = block.shape && block.shape !== SHAPE.pillar ? this.game.voxelWorld.selBoxes(t.x, t.y, t.z, t.id) : FULL_BOX;
    const gk = key + '|' + JSON.stringify(boxes);
    if (this._crackKey !== gk) {
      this._crackKey = gk;
      this.crack.geometry.dispose();
      this.crack.geometry = crackGeometry(boxes);
    }
    this.crack.position.set(t.x, t.y, t.z);
    this.crack.visible = block.render !== 'cross' && block.render !== 'liquid';
  }
  _bbox(boxes) {
    const r = [1, 1, 1, 0, 0, 0];
    for (const b of boxes) for (let i = 0; i < 3; i++) { r[i] = Math.min(r[i], b[i]); r[i + 3] = Math.max(r[i + 3], b[i + 3]); }
    return r;
  }
  _resetBreak() { this.breaking = null; this.crack.visible = false; }

  _break(t, block) {
    const g = this.game, vw = g.voxelWorld, key = `${t.x},${t.y},${t.z}`;
    const doubleSlab = block.shape === SHAPE.slab && vw.stateAt(t.x, t.y, t.z) === 2;
    vw.setBlock(t.x, t.y, t.z, 0);
    // plants on top pop off with the block below
    const above = vw.getBlock(t.x, t.y + 1, t.z);
    if (above && BLOCKS[above].render === 'cross' && !BLOCKS[above].hang && !BLOCKS[above].attach) { vw.setBlock(t.x, t.y + 1, t.z, 0); this._drop(BLOCKS[above], t.x, t.y + 1, t.z); }
    g.fallingBlocks?.blockChanged(t.x, t.y, t.z);
    if (block.interact === 'chest' || block.interact === 'furnace' || block.interact === 'brewing' || block.interact === 'jukebox') g.containerSystem?.onBlockBroken?.(key, t.x, t.y, t.z);
    if (this._canHarvest(block)) this._drop(block, t.x, t.y, t.z, doubleSlab ? 2 : 1);
    this._burst(block, t.x, t.y, t.z);
    this._sfx(block, 0.6);
    const info = mcToolInfo(this.held()?.type ?? '');
    if (info && block.hardness > 0) g.inventorySystem?.damageHeld?.(info.kind === 'sword' ? 2 : 1);
    g.player.hunger = Math.max(0, g.player.hunger - 0.025);  // 0.005 exhaustion
    g.achievementSystem?.onBlockMined?.(block.name);
    this._resetBreak();
    this._breakDelay = block.hardness === 0 ? 0 : 0.25;      // 5-tick delay
  }

  _drop(block, x, y, z, mult = 1) {
    const wis = this.game.worldItemSystem;
    if (!wis || !block.drop) return;
    let type = block.drop, qty = (block.dropQty ?? 1) * mult;
    if (type === 'leaves') {
      const r = Math.random();
      if (block.name === 'oak_leaves' || block.name === 'dark_oak_leaves') { if (r < 0.005) type = 'mc_apple'; else if (r < 0.025) type = 'mc_stick'; else return; }
      else if (r < 0.02) type = 'mc_stick'; else return;
      if (!this.game.inventorySystem?.itemTypes?.[type]) type = 'mc_stick';
    } else if (type === 'seeds') {
      if (Math.random() > 0.125) return;
      type = this.game.inventorySystem?.itemTypes?.mc_wheat_seeds ? 'mc_wheat_seeds' : null;
      if (!type) return;
    } else if (block.name === 'gravel' && Math.random() < 0.1) type = 'mc_flint';   // vanilla 10%
    else if (block.name === 'redstone_ore') qty = 4 + ((Math.random() * 2) | 0);
    else if (block.name === 'lapis_ore') qty = 4 + ((Math.random() * 5) | 0);
    else if (block.name === 'copper_ore') qty = 2 + ((Math.random() * 4) | 0);
    if (!this.game.inventorySystem?.itemTypes?.[type]) return;
    const it = wis.spawnItem(type, x + 0.5, y + 0.25, z + 0.5, qty);
    if (it) { it._vy = 2.5; it._noPickupUntil = performance.now() + 250; }
  }

  // ── placing ───────────────────────────────────────────────────────────────
  _place(item) {
    if (!item) return false;
    const id = ITEM_TO_BLOCK[item.type];
    if (!id) return false;
    const g = this.game, vw = g.voxelWorld, t = this.target;
    const tb = BLOCKS[t.id];
    const nb = BLOCKS[id];
    const hy = this._eye.y + this._dir.y * t.dist;                // where the crosshair hit
    // a slab clicked on its open half (or a slab placed into a half-filled
    // cell of the same slab) becomes a double slab
    const merge = (x, y, z) => {
      if (nb.shape !== SHAPE.slab || vw.getBlock(x, y, z) !== id) return false;
      const st = vw.stateAt(x, y, z);
      if (st === 2) return false;
      vw.setBlock(x, y, z, id, 2);
      return true;
    };
    let merged = t.id === id && nb.shape === SHAPE.slab && ((vw.stateAt(t.x, t.y, t.z) === 0 && t.ny === 1) || (vw.stateAt(t.x, t.y, t.z) === 1 && t.ny === -1)) && merge(t.x, t.y, t.z);
    // clicking a replaceable plant replaces it; otherwise place against the face
    let x = t.x, y = t.y, z = t.z;
    // (icicles and crystals are not replaceable: place against them instead)
    const soft = (b) => b.render === 'cross' && !b.hang && !b.attach;
    if (!merged && !soft(tb)) { x += t.nx; y += t.ny; z += t.nz; }
    if (!merged) merged = merge(x, y, z);
    if (merged) {
      g.fallingBlocks?.blockChanged(x, y, z);
      g.inventorySystem.removeItem(g.inventorySystem.heldSlot ?? 0, 1);
      this._sfx(nb, 0.5); this._swingNow();
      return true;
    }
    const cur = vw.getBlock(x, y, z);
    if (cur && !soft(BLOCKS[cur]) && !BLOCKS[cur].fluid) return false;
    if (nb.hang) { const up = vw.getBlock(x, y + 1, z); if (!vw.isSolid(x, y + 1, z) && up !== id) return false; }
    else if (nb.attach) { if (!vw.isSolid(t.x, t.y, t.z)) return false; }
    else if (nb.render === 'cross' && !vw.isSolid(x, y - 1, z)) return false;
    if (nb.solid && this._occupied(x, y, z)) return false;
    // front faces the player (furnace, chest, crafting table)
    const yaw = g.player.yaw, lx = -Math.sin(yaw), lz = -Math.cos(yaw);
    const facing = Math.abs(lx) > Math.abs(lz) ? (lx > 0 ? 3 : 1) : (lz > 0 ? 2 : 0);
    // shape state: slabs/stairs go to the upper half when placed against a
    // ceiling or high on a wall; pillars follow the clicked face's axis
    const upper = t.ny === -1 || (t.ny === 0 && hy - y > 0.5);
    let state = nb.tex.front ? facing : undefined;
    if (nb.shape === SHAPE.slab) state = upper ? 1 : 0;
    else if (nb.shape === SHAPE.stairs) state = facing | (upper ? 4 : 0);
    else if (nb.shape === SHAPE.pillar) state = t.nx ? 1 : t.nz ? 2 : 0;
    vw.setBlock(x, y, z, id, state);
    g.fallingBlocks?.blockChanged(x, y, z);
    g.inventorySystem.removeItem(g.inventorySystem.heldSlot ?? 0, 1);
    this._sfx(nb, 0.5);
    this._swingNow();
    return true;
  }

  // Would a block at (x,y,z) intersect the player or a mob?
  _occupied(x, y, z) {
    const g = this.game, P = g.player.body.position;
    const overlap = (cx, feet, cz, hw, h) => cx + hw > x && cx - hw < x + 1 && cz + hw > z && cz - hw < z + 1 && feet + h > y && feet < y + 1;
    if (overlap(P.x, P.y - 0.9, P.z, 0.3, 1.8)) return true;
    for (const zb of g.zombieManager?.getZombies?.() ?? []) {
      if (!zb.isAlive?.() || !zb.position) continue;
      const feet = zb.mesh?.position?.y ?? zb.position.y - 0.9;
      if (overlap(zb.position.x, feet, zb.position.z, 0.35, 1.9)) return true;
    }
    return false;
  }

  // ── targets other than blocks ─────────────────────────────────────────────
  // Is a mob or NPC's hitbox under the crosshair closer than the block?
  // Ray vs each entity's AABB (feet = body centre - 0.9, size from _colHW/_colH).
  _mobUnderCrosshair(maxDist) {
    const o = this._eye, d = this._dir, lim = Math.min(maxDist, MOB_REACH);
    const hits = (p, hw, h) => {
      const feet = p.y - 0.9;
      let t0 = 0, t1 = lim;
      for (const [oc, dc, lo, hi] of [[o.x, d.x, p.x - hw, p.x + hw], [o.y, d.y, feet, feet + h], [o.z, d.z, p.z - hw, p.z + hw]]) {
        if (Math.abs(dc) < 1e-8) { if (oc < lo || oc > hi) return false; continue; }
        let a = (lo - oc) / dc, b = (hi - oc) / dc;
        if (a > b) [a, b] = [b, a];
        t0 = Math.max(t0, a); t1 = Math.min(t1, b);
        if (t0 > t1) return false;
      }
      return true;
    };
    for (const z of this.game.zombieManager?.getZombies?.() ?? []) {
      if (!z.isAlive?.() || !z.position) continue;
      if (hits(z.position, (z._colHW ?? 0.3) + 0.1, z._colH ?? 1.8)) return true;   // vanilla pads hitboxes by 0.1
    }
    for (const n of this.game.npcManager?.npcs ?? []) {
      if (!n.isAlive?.() || !n.position) continue;
      if (hits(n.position, 0.4, 1.8)) return true;
    }
    return false;
  }
  _tryNPC() {
    const g = this.game, npc = g.npcManager?.getNearestNPC?.(4);
    if (!npc) return false;
    const p = npc.position ?? npc.mesh?.position;
    if (p) {
      const vx = p.x - this._eye.x, vz = p.z - this._eye.z;
      const len = Math.hypot(vx, vz) || 1;
      if ((vx * this._dir.x + vz * this._dir.z) / len < 0.85) return false;  // must look at them
    }
    g.interactionSystem?.handleNPCInteraction?.();
    return true;
  }

  // ── feedback ──────────────────────────────────────────────────────────────
  _swingNow() { this._swing = 0.001; }

  _updateView(dt, cam) {
    const g = this.game, p = g.player;
    const show = !g.inFriendHouse && g.isRunning && !g.inventorySystem?.isOpen && !document.body.classList.contains('mc-hide-hud');
    // swing animation (6 ticks like vanilla); keeps looping while mining
    if (this._swing > 0) { this._swing += dt / 0.3; if (this._swing >= 1) this._swing = g.inputManager.mouse.leftClick && !this._gunInHand() && g.inputManager.isPointerLocked?.() && this.consumesLeftClick() ? 0.001 : 0; }
    const moving = !!(p?.isMoving?.() && p.isGrounded);
    if (moving) this._bobT += dt * (p.isSprinting ? 11 : 8.5);
    this.viewModel.update(dt, cam, { show, item: this.held(), swing: this._swing, eating: this.isEating, eatT: this._eatTime, moving, bobT: this._bobT });
  }

  // ── terrain particles (vanilla numbers, per tick -> per second) ─────────
  _particleMat(block) {
    let mat = this._pMats.get(block.id);
    if (!mat) {
      const tx = block.tex, name = tx.particle || (/grass_block|grass$/.test(block.name) && tx.bottom) || tx.side || tx.top;
      mat = new THREE.MeshBasicMaterial({ map: blockTexture(name), alphaTest: 0.5, side: THREE.DoubleSide });
      this._pMats.set(block.id, mat);
    }
    return mat;
  }
  // xa/ya/za: initial direction hint like vanilla's Particle constructor
  _spawnParticle(block, x, y, z, xa, ya, za, power = 1, scale = 1) {
    if (this.particles.length > 600) return;
    const r = Math.random;
    let vx = xa + (r() * 2 - 1) * 0.4, vy = ya + (r() * 2 - 1) * 0.4, vz = za + (r() * 2 - 1) * 0.4;
    const f = (r() + r() + 1) * 0.15, d = Math.hypot(vx, vy, vz) || 1;
    vx = vx / d * f * 0.4; vy = vy / d * f * 0.4 + 0.1; vz = vz / d * f * 0.4;
    vx *= power; vy = (vy - 0.1) * power + 0.1; vz *= power;
    const m = new THREE.Mesh(this._pGeos[(r() * 16) | 0], this._particleMat(block));
    m.userData.noVox = true; m.userData.noHit = true;
    m.position.set(x, y, z);
    m.scale.setScalar((0.1 + r() * 0.1) * scale);
    this.game.scene.scene.add(m);
    this.particles.push({ m, vx: vx * 20, vy: vy * 20, vz: vz * 20, life: Math.floor(4 / (r() * 0.9 + 0.1)) / 20, ground: false });
  }
  // block broken: 4x4x4 particles spread through the block, flying outward
  _burst(block, x, y, z) {
    for (let i = 0; i < 4; i++) for (let j = 0; j < 4; j++) for (let k = 0; k < 4; k++) {
      const dx = (i + 0.5) / 4, dy = (j + 0.5) / 4, dz = (k + 0.5) / 4;
      this._spawnParticle(block, x + dx, y + dy, z + dz, dx - 0.5, dy - 0.5, dz - 0.5);
    }
  }
  // while mining: one small, slow particle just off the struck face
  _hitParticle(block, t) {
    if (block.render === 'cross') return;
    const r = Math.random, e = 0.1;
    let px = t.x + e + r() * (1 - 2 * e), py = t.y + e + r() * (1 - 2 * e), pz = t.z + e + r() * (1 - 2 * e);
    if (t.nx) px = t.x + (t.nx > 0 ? 1 + e : -e);
    if (t.ny) py = t.y + (t.ny > 0 ? 1 + e : -e);
    if (t.nz) pz = t.z + (t.nz > 0 ? 1 + e : -e);
    this._spawnParticle(block, px, py, pz, 0, 0, 0, 0.2, 0.6);
  }
  _updateParticles(dt) {
    const vw = this.game.voxelWorld, cam = this.game.camera;
    const light = vw?.brightnessAt && cam ? Math.round(vw.brightnessAt(cam.position.x, cam.position.y, cam.position.z) * 50) / 50 : (vw?._daylight ?? 1);
    if (this._pLight !== light) { this._pLight = light; for (const m of this._pMats.values()) m.color.setScalar(light); }
    const drag = Math.pow(0.98, dt * 20), gdrag = Math.pow(0.7, dt * 20);
    const solid = (x, y, z) => vw && vw.isSolid(Math.floor(x), Math.floor(y), Math.floor(z));
    for (let i = this.particles.length - 1; i >= 0; i--) {
      const p = this.particles[i];
      p.life -= dt;
      if (p.life <= 0) { this.game.scene.scene.remove(p.m); this.particles.splice(i, 1); continue; }
      p.vy -= 16 * dt;                                   // 0.04 blocks/tick^2
      const m = p.m.position, h = p.m.scale.x / 2;
      let nx = m.x + p.vx * dt, ny = m.y + p.vy * dt, nz = m.z + p.vz * dt;
      p.ground = false;
      if (solid(m.x, ny - h, m.z)) { if (p.vy < 0) { ny = Math.floor(ny - h) + 1 + h; p.ground = true; } else ny = m.y; p.vy = 0; }
      if (solid(nx, ny, m.z)) { nx = m.x; p.vx = 0; }
      if (solid(nx, ny, nz)) { nz = m.z; p.vz = 0; }
      m.set(nx, ny, nz);
      p.vx *= drag; p.vy *= drag; p.vz *= drag;
      if (p.ground) { p.vx *= gdrag; p.vz *= gdrag; }
      if (cam) p.m.quaternion.copy(cam.quaternion);
    }
  }

  // Short procedural dig / place sound tuned by material
  _sfx(block, vol) {
    try {
      const ctx = this._ctx ??= new (window.AudioContext || window.webkitAudioContext)();
      const n = block.name;
      const freq = /glass|ice/.test(n) ? 2400 : /stone|cobble|ore|brick|bedrock|furnace/.test(n) ? 900 : /log|plank|table|chest/.test(n) ? 500 : /sand|gravel/.test(n) ? 1500 : /leaves|grass|bush|poppy|stalk/.test(n) ? 3000 : 700;
      const len = 0.09, buf = ctx.createBuffer(1, Math.floor(ctx.sampleRate * len), ctx.sampleRate);
      const d = buf.getChannelData(0);
      for (let i = 0; i < d.length; i++) d[i] = (Math.random() * 2 - 1) * Math.pow(1 - i / d.length, 2);
      const src = ctx.createBufferSource(); src.buffer = buf;
      const f = ctx.createBiquadFilter(); f.type = 'bandpass'; f.frequency.value = freq * (0.85 + Math.random() * 0.3); f.Q.value = 1.2;
      const gn = ctx.createGain(); gn.gain.value = vol * (this.game.settings?.get?.('audio.sfxVolume') ?? 0.8);
      src.connect(f); f.connect(gn); gn.connect(ctx.destination); src.start();
    } catch (e) { /* audio unavailable */ }
  }
}
