// Frostbite.js — the 26.4 zombie variant of snowy biomes and Ice Caves.
//
//  - 24 HP vanilla (x2.5 here), 3 HP melee (x5) whose hits apply 3 s of
//    Freezing; it is immune to Freezing itself.
//  - About a quarter spawn holding an ice ball: those lob ice balls from up to
//    16 blocks while closing in, then switch to melee within 2 blocks.
//  - Burns in daylight under open sky (unless in water).
//  - Light-footed: never cracks brittle ice (FrostSystem).
//  - Underwater for 30 s it thaws back into an ordinary zombie.
//  - Drops 0-2 rotten flesh and 0-3 ice balls.
//  - About 5% are babies: smaller, faster (0.315 vs 0.21 speed).

import * as THREE from 'three';
import { ZombieBase } from './ZombieBase.js';
import { mcTexture } from '../../content/McContent.js';

export class Frostbite extends ZombieBase {
  constructor(x, z, game, opts = {}) {
    const baby = opts.baby ?? Math.random() < 0.05;
    super(x, z, game, {
      type: baby ? 'baby_frostbite' : 'frostbite',
      health: 60,
      damage: 15,
      speed: baby ? 2.75 : 1.85,          // walker 2 (vanilla zombie 0.23); x1.5 for babies
      attackRange: baby ? 1.5 : 2,
      aggroRange: 40,
      attackCooldown: 1.0,
      baby,
    });
    this._throwT = 1 + Math.random();
    this._wetT = 0;
    this._burnT = 0;
    if (this._hasIceBall === undefined) this._setIceBall(opts.iceBall ?? Math.random() < 0.25);
  }

  createMesh() {
    // constructor fields are not set yet here: read the baby flag from config
    const baby = this.type === 'baby_frostbite';
    const { group, refs } = this.buildHumanoid({
      style: 'frostbite',
      scale: baby ? 0.55 : 1,
      bulk: 0.95,
      hunch: 0.16,
      gore: 1,
      eyeColor: 0x9fe8ff,
    });
    if (baby) refs.headGroup.scale.setScalar(1.3);
    this._handRef = refs.armR?.hand ?? null;
    if (baby) { this._colHW = 0.245; this._colH = 0.98; } else this._colH = 1.95;
    this.finalizeMesh(group);
  }

  _setIceBall(on) {
    this._hasIceBall = on;
    if (!on || !this.mesh) return;
    const hand = this._handRef;
    if (!hand) return;
    const s = new THREE.Sprite(new THREE.SpriteMaterial({ map: mcTexture('mc_ice_ball'), transparent: true, alphaTest: 0.3 }));
    // forearm box hangs from its top pivot: the ball sits just past the fist
    const scl = new THREE.Vector3(); hand.getWorldScale(scl);
    s.scale.setScalar(0.3 / Math.max(0.01, scl.y));
    hand.geometry.computeBoundingBox();
    s.position.set(0, hand.geometry.boundingBox.min.y - 0.06 / Math.max(0.01, scl.y), 0);
    s.userData.noVox = true;
    s.raycast = () => {};
    hand.add(s);
    this._heldBall = s;
  }

  update(dt) {
    super.update(dt);
    if (this._dead) return;
    const g = this.game, vw = g.voxelWorld, p = g.player;
    if (!vw || !p) return;
    const x = this.position.x, z = this.position.z, head = this.position.y - 0.9 + (this._colH ?? 1.95) - 0.2;
    const headWet = vw.isFluid?.(Math.floor(x), Math.floor(head), Math.floor(z));

    // ── thaw: 30 s fully under water converts it into a plain zombie ──
    this._wetT = headWet ? this._wetT + dt : 0;
    if (this._wetT >= 30) { this._thaw(); return; }

    // ── daylight burning ──
    const hour = g.dayNightCycle?.time ?? 12;
    const L = vw.lightLevelAt(x, head, z);
    const raining = /rain|storm/.test(g.weatherSystem?.weather ?? '');
    if (hour > 6.5 && hour < 17.5 && !raining && !headWet && L && L.sky >= 15) {
      this._burnT += dt;
      if (this._burnT >= 1) {
        this._burnT = 0;
        this.takeDamage(2.5);
        g.particleSystem?.createFireEffect?.(this.position.clone().add(new THREE.Vector3(0, 0.6, 0)));
      }
    } else this._burnT = 0;

    // ── ranged: lob ice balls while approaching, 2..16 blocks out ──
    if (!this._hasIceBall) return;
    this._throwT -= dt;
    const d = this.position.distanceTo(p.getPosition());
    if (this._throwT <= 0 && d > 2.5 && d <= 16 && this.state !== 'idle' && !p.godMode && p.health > 0) {
      this._throwT = 2 + Math.random();
      this._throwAt(p);
    }
  }

  _throwAt(p) {
    const g = this.game;
    if (!g.throwables) return;
    const from = this.position.clone(); from.y += (this._colH ?? 1.95) - 1.3;
    const target = p.getPosition().clone();            // body centre
    const dx = target.x - from.x, dz = target.z - from.z, h = Math.hypot(dx, dz);
    // lead for gravity: ~h/1.6 ticks of flight, 0.03 per tick squared
    const n = h / 1.6, drop = 0.03 * n * n / 2;
    const dir = new THREE.Vector3(dx, target.y - from.y + drop, dz).normalize();
    dir.x += (Math.random() - 0.5) * 0.05; dir.z += (Math.random() - 0.5) * 0.05;
    g.throwables.spawn('mc_ice_ball', from.addScaledVector(dir, 0.5), dir.normalize(), this, null, 1.6);
    if (this._rightArm) { this._rightArm.rotation.x = -2.2; setTimeout(() => { if (this._rightArm) this._rightArm.rotation.x = this._rightArm.userData?.baseRotX ?? 0; }, 200); }
  }

  checkAttack(player, dist) {
    const before = this.lastAttackTime;
    super.checkAttack(player, dist);
    // a landed melee hit resets the cooldown: inflict 3 s of Freezing
    if (this.lastAttackTime === 0 && before > 0 && !player.godMode && !(player.spawnProtectionTime > 0)) {
      this.game.freeze?.apply('player', 3);
    }
  }

  // Thaw into a walker in place: a quiet swap, not a kill (no loot, no score)
  _thaw() {
    const g = this.game, zm = g.zombieManager;
    const { x, y, z } = this.position;
    const w = zm?.spawn('walker', x, z);
    if (w) {
      w.position.y = y; w.body.position.y = y; w._blockPos = null;
      w.health = w.maxHealth * Math.max(0.2, this.health / this.maxHealth);
      w.state = this.state === 'idle' ? 'idle' : 'chasing';
    }
    this._dead = true;
    if (this.body) { g.physicsWorld.removeBody(this.body); this.body = null; }
    if (this.mesh) { g.scene.removeObject(this.mesh); this.mesh = null; }
    g.particleSystem?.createSmoke?.(new THREE.Vector3(x, y + 0.5, z), 8);
  }

  dropLoot() {
    const wi = this.game.worldItemSystem;
    if (wi) {
      const px = this.position.x, pz = this.position.z, py = this.groundYAt(px, pz) + 0.12;
      const flesh = Math.floor(Math.random() * 3), balls = Math.floor(Math.random() * 4);
      const put = (type, n) => { if (n > 0) { const it = wi.spawnItem(type, px + (Math.random() - 0.5) * 0.6, py, pz + (Math.random() - 0.5) * 0.6, n); if (it) it.respawnsLeft = 0; } };
      put('food_rotten_flesh', flesh);
      put('mc_ice_ball', balls);
    }
    super.dropLoot();
  }
}
