export const MC_ITEM_DEFS = MC_CONTENT.reduce((acc, e) => {
  acc[e.id] = { name: e.name, stackable: e.stackable ?? e.kind !== 'tool', rarity: e.rarity, effect: e.effect, usable: !!e.usable, category: e.category };
  return acc;
}, {});

const _byId = new Map(MC_CONTENT.map((e) => [e.id, e]));
export function isMcItem(id) { return _byId.has(id); }

// Inline style for an inventory .item-icon (crisp pixel texture background)
export function mcIconCSS(id) {
  const e = _byId.get(id); if (!e) return '';
  return `background-image:url('${dataURI(e)}');background-size:contain;background-repeat:no-repeat;background-position:center;image-rendering:pixelated;`;
}

// Build the 3D world pickup model (textured block / metal bar / glowing gem)
export function buildMcModel(id, glow = { color: 0x000000, intensity: 0 }) {
  const e = _byId.get(id); if (!e) return null;
  const g = new THREE.Group();
  const emissive = new THREE.Color(glow.color);

  // flat items drop as the extruded 3D sprite, like vanilla
  if (spriteFor(e) || e.kind === 'tool') {
    const m = extrudeSprite(buildCanvas(e));
    if (m) { m.scale.setScalar(0.4); g.add(m); return g; }
  }

  if (e.kind === 'gem') {
    const mat = new THREE.MeshStandardMaterial({ color: e.color, emissive: new THREE.Color(e.color), emissiveIntensity: 0.5, roughness: 0.1, metalness: 0.3 });
    const core = new THREE.Mesh(new THREE.BoxGeometry(0.14, 0.14, 0.14), mat); core.userData.noVox = true;
    for (const [x, y, z, s] of [[0.09, 0.04, 0, 0.07], [-0.08, -0.03, 0.05, 0.06], [0.02, -0.08, -0.06, 0.05]]) {
      const bit = new THREE.Mesh(new THREE.BoxGeometry(s, s, s), mat); bit.position.set(x, y, z); bit.userData.noVox = true; g.add(bit);
    }
    g.add(core);
    return g;
  }

  if (e.kind === 'ingot' || e.kind === 'dust') {
    const tex = threeTexture(e);
    const mat = new THREE.MeshStandardMaterial({ map: tex, color: 0xffffff, emissive, emissiveIntensity: glow.intensity, roughness: e.kind === 'dust' ? 0.9 : 0.35, metalness: e.kind === 'dust' ? 0 : 0.7 });
    const bar = new THREE.Mesh(new THREE.BoxGeometry(0.26, 0.09, 0.14), mat); bar.userData.noVox = true;
    g.add(bar);
    if (e.kind === 'ingot') { const b = new THREE.Mesh(new THREE.BoxGeometry(0.2, 0.02, 0.1), mat); b.position.y = 0.055; b.userData.noVox = true; g.add(b); }
    return g;
  }

  if (e.kind === 'tool') {
    const mat = new THREE.MeshBasicMaterial({ map: threeTexture(e), transparent: true, alphaTest: 0.5, side: THREE.DoubleSide });
    const sprite = new THREE.Mesh(new THREE.PlaneGeometry(0.5, 0.5), mat); sprite.userData.noVox = true;
    g.add(sprite);
    return g;
  }

  // placeable block → a mini block with real per-face textures
  if (e.blockId) {
    const b = BLOCKS[e.blockId];
    const m = (n) => { const mm = new THREE.MeshLambertMaterial({ map: blockTexture(n), transparent: b.render !== 'cube', alphaTest: 0.5, side: b.render === 'cross' ? THREE.DoubleSide : THREE.FrontSide }); mm.userData.noVox = true; return mm; };
    if (b.render === 'cross') {
      const sp = new THREE.Mesh(new THREE.PlaneGeometry(0.4, 0.4), m(b.tex.side)); sp.userData.noVox = true; g.add(sp); return g;
    }
    const side = m(b.tex.side), mats = [side, side, m(b.tex.top), m(b.tex.bottom), b.tex.front ? m(b.tex.front) : side, side];
    const sg = b.shape && b.shape !== SHAPE.pillar ? shapeGeometry(b.shape) : null;
    const cube = new THREE.Mesh(sg ?? new THREE.BoxGeometry(0.25, 0.25, 0.25), mats); cube.userData.noVox = true;
    if (sg) cube.scale.setScalar(0.25);
    g.add(cube); return g;
  }

  // ore / block → a textured Minecraft cube
  const tex = threeTexture(e);
  const mat = new THREE.MeshStandardMaterial({ map: tex, color: 0xffffff, emissive, emissiveIntensity: glow.intensity, roughness: 0.85, metalness: 0.05 });
  const cube = new THREE.Mesh(new THREE.BoxGeometry(0.3, 0.3, 0.3), mat);
  cube.userData.noVox = true;
  g.add(cube);
  return g;
}

export const MC_ITEM_IDS = MC_CONTENT.map((e) => e.id);

// THREE.CanvasTexture for an entry id (NearestFilter) — used by the mining
// system to texture full-size resource blocks. Returns null if unknown.
export function mcTexture(id) {
  const e = _byId.get(id);
  return e ? threeTexture(e) : null;
}

// Name of an entry (for loot notifications etc.)
export function mcName(id) { return _byId.get(id)?.name ?? id; }

// ── Durability (vanilla max uses) ───────────────────────────────────────────
export const MC_TOOL_DURABILITY = { wooden: 59, stone: 131, iron: 250, gold: 32, diamond: 1561, netherite: 2031 };
const _TOOL_RE = /^weapon_(wooden|stone|iron|gold|diamond|netherite)_(sword|pickaxe|axe|shovel|hoe|rapier)$/;
// Max durability for a tool/armor item id, or 0 if the item does not wear out.
export function mcMaxDurability(id) {
  if (!id) return 0;
  if (MC_ARMOR[id]) return MC_ARMOR[id].durability;
  const m = _TOOL_RE.exec(id);
  return m ? MC_TOOL_DURABILITY[m[1]] : 0;
}
// { tier, kind } for a Minecraft tool id (rapier counts as a sword), else null.
export function mcToolInfo(id) {
  const m = _TOOL_RE.exec(id ?? '');
  return m ? { tier: m[1], kind: m[2] === 'rapier' ? 'sword' : m[2] } : null;
}
