// VoxelWorld.js — editable Minecraft-style block world.
//
// 16x16 chunk columns, Y from YMIN to YMAX. Every block is stored (Uint8 id),
// so anything can be mined or placed. Generation: terrain height + biome from
// TerrainGenerator, dirt/stone layers, bedrock floor, noise caves, ore veins,
// Minecraft-shaped trees, grass/flowers, and parasite-infested patches.
// Lighting works like modern Minecraft: per-cell sky light (0-15, flooding in
// from open sky) and block light (0-15, from emissive blocks) are flood-filled
// at mesh time, averaged per vertex ("smooth lighting") and packed with the
// face shade + ambient occlusion into a Uint8 vertex colour:
//   r = sky level, g = block level, b = face shade * AO.
// The material shader turns those into colour through a vanilla-style
// lightmap (brightness curve, day/night sky factor, warm block light, gamma
// lift), so caves are dark, labs glow under their light panels, and night
// falls on the terrain instead of on a flat material tint.

import * as THREE from 'three';
import { SimplexNoise } from 'simplex-noise';
import { BLOCKS, BLOCK, atlasTexture, tileUV } from './Blocks.js';
import { SHAPE, shapeBoxes, rayBoxes } from './Shapes.js';
import { ATMOS_GLSL } from '../render/Atmosphere.js';
import { SunShadows, SHADOW_GLSL, SHADOW_LAYER_TERRAIN } from '../render/SunShadows.js';

export const CS = 16;
export const YMIN = -32;
export const YMAX = 64;
const H = YMAX - YMIN;
const VOL = CS * CS * H;
const idx = (x, y, z) => ((y - YMIN) * CS + z) * CS + x;
const ICE_WL = -6;                      // crevasse waterline
const ckey = (cx, cz) => cx + ',' + cz;

function srand(seed) {
  let s = (seed >>> 0) || 1;
  return () => { s ^= s << 13; s >>>= 0; s ^= s >> 17; s ^= s << 5; s >>>= 0; return s / 4294967296; };
}
function hash2(a, b, c = 0) { let h = 2166136261 ^ c; h = Math.imul(h ^ a, 16777619); h = Math.imul(h ^ b, 16777619); return h >>> 0; }

// Face table. u x v = n so quads wind CCW seen from outside; v is "up" on sides.
const FACES = [
  { n: [1, 0, 0], u: [0, 0, -1], v: [0, 1, 0], o: [1, 0, 1], shade: 0.6, tex: 'side', dir: 1 },
  { n: [-1, 0, 0], u: [0, 0, 1], v: [0, 1, 0], o: [0, 0, 0], shade: 0.6, tex: 'side', dir: 3 },
  { n: [0, 1, 0], u: [1, 0, 0], v: [0, 0, -1], o: [0, 1, 1], shade: 1.0, tex: 'top' },
  { n: [0, -1, 0], u: [1, 0, 0], v: [0, 0, 1], o: [0, 0, 0], shade: 0.5, tex: 'bottom' },
  { n: [0, 0, 1], u: [1, 0, 0], v: [0, 1, 0], o: [0, 0, 1], shade: 0.8, tex: 'side', dir: 0 },
  { n: [0, 0, -1], u: [-1, 0, 0], v: [0, 1, 0], o: [1, 0, 0], shade: 0.8, tex: 'side', dir: 2 },
];
const AO = [0.42, 0.6, 0.8, 1.0];

const OPAQUE = new Uint8Array(256), SOLID = new Uint8Array(256), RENDER = new Uint8Array(256); // 0 none 1 cube 2 cutout 3 cross 4 shape 5 pillar 6 liquid
const FLUID = new Uint8Array(256);
const STILL = new Uint8Array(256);   // cross blocks that never sway (icicles, crystals)
for (const b of BLOCKS) if (b) {
  OPAQUE[b.id] = b.opaque ? 1 : 0; SOLID[b.id] = b.solid ? 1 : 0;
  RENDER[b.id] = b.render === 'cube' ? 1 : b.render === 'cross' ? 3 : b.render === 'shape' ? 4 : b.render === 'pillar' ? 5 : b.render === 'liquid' ? 6 : 2;
  FLUID[b.id] = b.fluid ? 1 : 0;
  STILL[b.id] = b.hang || b.attach ? 1 : 0;
}
const SHP = new Uint8Array(256);       // Shapes.SHAPE kind per block id
for (const b of BLOCKS) if (b) SHP[b.id] = b.shape;
const FULL_BOX = [[0, 0, 0, 1, 1, 1]];
// Light tables: emission level, and whether a block stops the open-sky
// column (anything opaque, plus leaves like vanilla).
const EMIT = new Uint8Array(256), SKYB = new Uint8Array(256);
const LEAVES = new Uint8Array(256);   // sway in the wind
for (const b of BLOCKS) if (b && /leaves/.test(b.name)) LEAVES[b.id] = 1;
for (const b of BLOCKS) if (b) {
  EMIT[b.id] = b.light ?? 0;
  SKYB[b.id] = b.opaque || /leaves/.test(b.name) ? 1 : 0;
}
const STONE_ID = BLOCK.stone;

// Scratch buffers for the light flood fill: the chunk plus a 15-block margin
// (light travels at most 15 blocks, so the chunk's own cells come out exact).
const LM = 15, LW = CS + 2 * LM, LWW = LW * LW;
const LSKY = new Uint8Array(LWW * H), LBLK = new Uint8Array(LWW * H);
const LHM = new Int16Array(LWW);          // per column: highest sky-blocking y
const LQ = new Int32Array(1 << 19), LQM = LQ.length - 1;   // ring-buffer BFS queue
const LGRID = new Array(9);

// Growable typed-array mesh builder (no per-vertex JS array pushes)
class MeshBuf {
  constructor() { this.pos = new Float32Array(3 * 4096); this.col = new Uint8Array(3 * 4096); this.uv = new Float32Array(2 * 4096); this.w = new Uint8Array(4096); this.idx = new Uint32Array(6 * 1024); this.nv = 0; this.ni = 0; this.cw = 0; }
  reset() { this.nv = 0; this.ni = 0; }
  _grow() {
    const g = (a, n) => { const b = new a.constructor(n); b.set(a); return b; };
    if ((this.nv + 4) * 3 > this.pos.length) { const n = this.pos.length * 2; this.pos = g(this.pos, n); this.col = g(this.col, n); this.uv = g(this.uv, n / 3 * 2); this.w = g(this.w, n / 3); }
    if (this.ni + 6 > this.idx.length) this.idx = g(this.idx, this.idx.length * 2);
  }
  vert(x, y, z, r, gg, b, u, v) {
    const i = this.nv++;
    this.pos[i * 3] = x; this.pos[i * 3 + 1] = y; this.pos[i * 3 + 2] = z;
    this.col[i * 3] = r; this.col[i * 3 + 1] = gg; this.col[i * 3 + 2] = b;
    this.uv[i * 2] = u; this.uv[i * 2 + 1] = v;
    this.w[i] = this.cw;
  }
  quad(a, b, c, d) { const I = this.idx, n = this.ni; I[n] = a; I[n + 1] = b; I[n + 2] = c; I[n + 3] = a; I[n + 4] = c; I[n + 5] = d; this.ni += 6; }
}
const MBUF = [new MeshBuf(), new MeshBuf(), new MeshBuf()];   // opaque, cutout, translucent water

// Per-block per-face UV rects, resolved once
const UVS = BLOCKS.map((b) => b && {
  top: tileUV(b.tex.top), bottom: tileUV(b.tex.bottom), side: tileUV(b.tex.side), front: tileUV(b.tex.front || b.tex.side),
  // variants: the texture plus horizontally mirrored copies of each one
  vars: b.variants && b.variants.flatMap((n) => { const t = tileUV(n); return [t, [t[2], t[1], t[0], t[3]]]; }),
});
const ICICLE_UV = ['icicle_base', 'icicle_middle', 'icicle_tip'].map(tileUV);
// stable per-face hash for picking texture variants
const faceHash = (x, y, z, f) => {
  let h = Math.imul(x, 73856093) ^ Math.imul(y, 19349663) ^ Math.imul(z, 83492791) ^ Math.imul(f + 1, 2654435761);
  h = Math.imul(h ^ (h >>> 15), 2246822519); h ^= h >>> 13;
  return h >>> 0;
};

class Chunk {
  constructor(cx, cz) {
    this.cx = cx; this.cz = cz; this.x0 = cx * CS; this.z0 = cz * CS;
    this.data = new Uint8Array(VOL);
    this.mesh = null; this.dirty = true; this.modified = false; this.maxY = YMIN;
  }
}

export class VoxelWorld {
  constructor(game, terrain) {
    this.game = game;
    this.terrain = terrain;
    this.chunks = new Map();
    this.pending = new Map();       // chunkKey -> [[x,y,z,id]] edits for ungenerated chunks
    this.facing = new Map();        // "x,y,z" -> 0..3 for blocks with a front face
    this.radius = 8;                // render distance in chunks
    this.seed = terrain?.seed ?? ((Math.random() * 1e9) | 0);
    this.caveA = new SimplexNoise(srand(hash2(11, 7, this.seed)));
    this.caveB = new SimplexNoise(srand(hash2(13, 5, this.seed)));
    this.patch = new SimplexNoise(srand(hash2(17, 3, this.seed)));
    this.cavern = new SimplexNoise(srand(hash2(19, 23, this.seed)));   // ice cave caverns
    this.iceMat = new SimplexNoise(srand(hash2(29, 31, this.seed)));   // packed ice / calcite
    this.crev = new SimplexNoise(srand(hash2(37, 41, this.seed)));     // crevasse lines
    this._treeCache = new Map();    // chunkKey -> tree block lists (deterministic)
    this.structures = null;         // LabGenerator, set by Game

    const atlas = atlasTexture();
    this.matOpaque = new THREE.MeshBasicMaterial({ map: atlas, vertexColors: true, fog: false });
    this.matCutout = new THREE.MeshBasicMaterial({ map: atlas, vertexColors: true, fog: false, alphaTest: 0.3, alphaToCoverage: true, side: THREE.DoubleSide });
    // sharp grazing-angle detail via anisotropic filtering
    atlas.anisotropy = game.scene?.renderer?.capabilities?.getMaxAnisotropy?.() ?? 1;
    // lighting, fog and the filmic curve all happen in the patched shader
    this.matWater = new THREE.MeshBasicMaterial({ map: atlas, vertexColors: true, fog: false, transparent: true, depthWrite: false, side: THREE.DoubleSide });
    this.matOpaque.toneMapped = false; this.matCutout.toneMapped = false; this.matWater.toneMapped = false;
    const sc = game.scene;
    this.shadows = sc?.renderer ? new SunShadows(sc.renderer, atlas) : null;
    this._lightU = {
      ...(sc?.atmosphere?.uniforms ?? {}),
      ...(this.shadows?.uniforms ?? {}),
      uGamma: { value: 0.5 },                            // Brightness setting (0 moody .. 1 bright)
      uTime: { value: 0 },
      uFogStart: { value: 60 }, uFogEnd: { value: 92 },
    };
    for (const m of [this.matOpaque, this.matCutout, this.matWater]) { m.userData.noVox = true; this._patchLighting(m); }
    this._daylight = 1;
    this._t0 = performance.now(); this._tPrev = this._t0;
    sc?.preRender?.push(() => this._preRender());
  }

  // Terrain shader (patched into MeshBasicMaterial). Vertex colour carries
  // (sky level, block level, face shade * AO) from the voxel light engine;
  // aWave marks plants (1 base, 2 tip) and leaves (3) for wind sway.
  // Lighting is modern and physically flavoured, all in linear HDR:
  //   skylight ambient (sky colour, scaled by the voxel sky level and AO)
  // + direct sun/moon (N.L, real shadow map, only where the sky is open)
  // + warm block light (torches, lamps) from the voxel block level
  // then aerial-perspective fog toward the actual sky colour in that
  // direction, then the shared filmic curve.
  _patchLighting(m) {
    m.onBeforeCompile = (sh) => {
      Object.assign(sh.uniforms, this._lightU);
      sh.vertexShader = sh.vertexShader
        .replace('#include <common>', `#include <common>
attribute float aWave;
uniform float uTime;
varying vec3 vWPos;
varying float vWave;`)
        .replace('#include <begin_vertex>', `#include <begin_vertex>
vWave = aWave;
if (aWave > 1.5) {
  vec3 wp0 = (modelMatrix * vec4(transformed, 1.0)).xyz;
  float ph = uTime * 1.6 + wp0.x * 0.37 + wp0.z * 0.29;
  float gust = 0.65 + 0.35 * sin(uTime * 0.23 + wp0.x * 0.02);
  float amp = (aWave > 2.5 ? 0.028 : 0.085) * gust;
  transformed.x += (sin(ph) + 0.35 * sin(ph * 2.7 + 1.3)) * amp;
  transformed.z += (cos(ph * 0.83 + 0.6)) * amp * 0.8;
  if (aWave > 2.5) transformed.y += sin(ph * 1.3 + 0.5) * amp * 0.5;
}`)
        .replace('#include <project_vertex>', `#include <project_vertex>
vWPos = (modelMatrix * vec4(transformed, 1.0)).xyz;`);
      sh.fragmentShader = sh.fragmentShader
        .replace('#include <common>', `#include <common>
varying vec3 vWPos;
varying float vWave;
uniform float uGamma; uniform float uFogStart; uniform float uFogEnd;
${ATMOS_GLSL}
${SHADOW_GLSL}
float mcCurve(float f) { return f / (4.0 - 3.0 * f); }`)
        .replace('#include <color_fragment>', `
  vec3 N = normalize(cross(dFdx(vWPos), dFdy(vWPos)));
  bool plant = vWave > 0.5 && vWave < 2.5;
  bool leaf = vWave > 2.5;
  float fs = N.y > 0.5 ? 1.0 : (N.y < -0.5 ? 0.5 : (abs(N.x) > 0.5 ? 0.6 : 0.8));
  float ao = plant ? 1.0 : clamp(vColor.b / fs, 0.0, 1.0);
  float sky = vColor.r, blk = vColor.g;
  vec3 Ld = uLightDir;
  float ndl = plant ? 0.8 : (leaf ? clamp(dot(N, Ld) * 0.5 + 0.5, 0.0, 1.0) : max(dot(N, Ld), 0.0));
  vec3 Ns = plant ? vec3(0.0, 1.0, 0.0) : N;
  float sunVis = smoothstep(0.45, 0.93, sky);
  float shd = (ndl > 0.0 && sunVis > 0.0) ? shadowAt(vWPos, Ns, plant ? 1.0 : ndl) : 0.0;
  float ambShade = plant ? 0.92 : (N.y > 0.5 ? 1.0 : (N.y < -0.5 ? 0.42 : (abs(N.x) > 0.5 ? 0.7 : 0.78)));
  float bl = mcCurve(blk);
  vec3 light = uAmbCol * mcCurve(sky) * ambShade * ao
             + uSunCol * ndl * shd * sunVis * mix(1.0, ao, 0.4)
             // sunlight bounced off the lit ground into walls and undersides
             + uSunCol * sunVis * (N.y > 0.5 ? 0.0 : (N.y < -0.5 ? 0.08 : 0.14)) * ao
             + vec3(1.0, 0.68, 0.4) * (1.5 * bl + 0.6 * bl * bl) * ao
             + vec3(0.034, 0.034, 0.042) * (0.5 + uGamma) * ao;
  vec3 col = diffuseColor.rgb * light;
  // aerial perspective: distance haze + render-distance fade into the sky
  vec3 V = vWPos - cameraPosition;
  float dist = length(V);
  vec3 vd = V / max(dist, 1e-4);
  vec3 fogC = atmosSky(normalize(vec3(vd.x, max(vd.y, -0.08), vd.z))) * mix(0.03, 1.0, uEyeSky);
  float edge = smoothstep(uFogStart, uFogEnd, dist);
  float haze = (1.0 - exp(-dist * 0.0055)) * 0.55 * uEyeSky;
  col = mix(col, fogC, max(edge, haze));
  diffuseColor.rgb = atmosTonemap(col);`);
    };
    m.needsUpdate = true;
  }

  // Per frame, after all game updates: atmosphere, shadow map, fog range,
  // and the scene lights other materials (mobs, items) use.
  _preRender() {
    const sc = this.game.scene, cam = sc?.camera, atm = sc?.atmosphere, sun = sc?.sunLight;
    if (!cam || !atm || !sun) return;
    const now = performance.now(), dt = Math.min(0.1, (now - this._tPrev) / 1000);
    this._tPrev = now;
    this._lightU.uTime.value = (now - this._t0) / 1000;
    const camPos = cam.getWorldPosition(this._camPos ??= new THREE.Vector3());
    // A clean sun arc from the clock, tilted 28 degrees off the zenith so walls
    // facing the sun get light and shadows always have some length.
    const sunDir = (this._sunDir ??= new THREE.Vector3());
    const dnc = this.game.dayNightCycle;
    if (dnc && Number.isFinite(dnc.time)) {
      const a = (dnc.time / 24) * Math.PI * 2 - Math.PI / 2, el = Math.sin(a), T = 0.49;
      sunDir.set(Math.cos(a), el * Math.cos(T), el * Math.sin(T)).normalize();
    } else sunDir.copy(sun.position).normalize();
    const Le = this.lightLevelAt(camPos.x, camPos.y, camPos.z);
    atm.update(sunDir, dt, Le ? Math.max(Le.sky / 15, 0) : 1);
    const far = this.radius * CS - 2;
    this._lightU.uFogEnd.value = far;
    this._lightU.uFogStart.value = far * 0.62;
    // mobs / items / hand use three's lights + Fog: keep them in step
    const U = atm.uniforms, sc3 = sc.scene;
    if (sc3.fog) {
      sc3.fog.color.copy(U.uHorizon.value).multiplyScalar(atm.uniforms.uEyeSky.value * 0.9 + 0.1);
      sc3.fog.near = far * 0.62; sc3.fog.far = far;
    }
    if (this.shadows) {
      const s = U.uSunCol.value, lum = s.r * 0.2126 + s.g * 0.7152 + s.b * 0.0722;
      this.shadows.render(sc3, camPos, U.uLightDir.value, lum);
    }
    sc.skyMesh?.position.copy(camPos);
    sc.stars?.position.copy(camPos);
  }

  // Light level (sky, block) of the cell holding a world point, from the
  // last mesh pass. Null when that chunk has not been lit yet.
  lightLevelAt(x, y, z) {
    const bx = Math.floor(x), by = Math.floor(y), bz = Math.floor(z);
    if (by >= YMAX) return { sky: 15, blk: 0 };
    if (by < YMIN) return { sky: 0, blk: 0 };
    const c = this.chunkAt(bx, bz);
    if (!c?.light) return null;
    const v = c.light[idx(bx - c.x0, by, bz - c.z0)];
    return { sky: v >> 4, blk: v & 15 };
  }
  // Linear-space brightness multiplier for things standing at a point
  // (held item, block particles) so they roughly match lit terrain there.
  brightnessAt(x, y, z) {
    const L = this.lightLevelAt(x, y, z);
    return L ? this._brightness(L.sky, L.blk) : this._daylight;
  }
  _brightness(sky, blk) {
    const U = this._lightU, a = U.uAmbCol?.value, s = U.uSunCol?.value;
    if (!a || !s) return 1;
    const c = (f) => f / (4 - 3 * f);
    const lum = (v) => v.r * 0.2126 + v.g * 0.7152 + v.b * 0.0722;
    const bl = c(blk / 15);
    let l = lum(a) * c(sky / 15) * 0.85 + lum(s) * 0.85 * Math.max(0, (sky / 15 - 0.45) / 0.48) + (1.5 * bl + 0.6 * bl * bl) * 0.55 + 0.015;
    // through the same filmic curve, relative to a mid-grey surface
    const tm = (x) => { x *= U.uExposure?.value ?? 0.62; return Math.min(1, (x * (2.51 * x + 0.03)) / (x * (2.43 * x + 0.59) + 0.14)); };
    // the curve's output is already linear light: ratio against a sunlit
    // mid-grey surface at noon (about 0.59 through the curve)
    return Math.min(1.25, tm(l * 0.4) / 0.59);
  }

  // ── block access ─────────────────────────────────────────────────────────
  chunkAt(bx, bz) { return this.chunks.get(ckey(Math.floor(bx / CS), Math.floor(bz / CS))); }

  getBlock(bx, by, bz) {
    if (by < YMIN || by >= YMAX) return 0;
    const c = this.chunkAt(bx, bz);
    if (!c) return by < this.terrain.columnHeight(bx, bz) ? BLOCK.stone : 0; // not generated yet: estimate
    return c.data[idx(bx - c.x0, by, bz - c.z0)];
  }
  isSolid(bx, by, bz) { return SOLID[this.getBlock(bx, by, bz)] === 1; }
  isOpaque(bx, by, bz) { return OPAQUE[this.getBlock(bx, by, bz)] === 1; }
  isFluid(bx, by, bz) { return FLUID[this.getBlock(bx, by, bz)] === 1; }

  // ── block shapes ─────────────────────────────────────────────────────────
  shapeOf(id) { return SHP[id]; }
  stateAt(bx, by, bz) { return this.facing.get(bx + ',' + by + ',' + bz) ?? 0; }
  // Walls join other walls and full solid blocks on each side; a block on
  // top makes the sides full height.
  _wallConn(x, y, z) {
    let m = 0;
    const joins = (id) => id && (SHP[id] === SHAPE.wall || (OPAQUE[id] && SOLID[id]));
    if (joins(this.getBlock(x, y, z - 1))) m |= 1;
    if (joins(this.getBlock(x + 1, y, z))) m |= 2;
    if (joins(this.getBlock(x, y, z + 1))) m |= 4;
    if (joins(this.getBlock(x - 1, y, z))) m |= 8;
    const up = this.getBlock(x, y + 1, z);
    if (up && SOLID[up]) m |= 16;
    return m;
  }
  // Selection / outline boxes (block-local 0..1) of the block at a cell
  selBoxes(x, y, z, id = this.getBlock(x, y, z)) {
    const k = SHP[id];
    if (!k || k === SHAPE.pillar) return FULL_BOX;
    return k === SHAPE.wall ? shapeBoxes(k, 0, this._wallConn(x, y, z)) : shapeBoxes(k, this.stateAt(x, y, z));
  }
  // Collision boxes (block-local), null for passable cells. Walls are 1.5
  // tall like vanilla, so they cannot be jumped over.
  collisionBoxes(x, y, z) {
    const id = this.getBlock(x, y, z);
    if (!SOLID[id]) return null;
    const k = SHP[id];
    if (!k || k === SHAPE.pillar) return FULL_BOX;
    const b = this.selBoxes(x, y, z, id);
    return k === SHAPE.wall ? b.map((q) => [q[0], q[1], q[2], q[3], 1.5, q[5]]) : b;
  }

  setBlock(bx, by, bz, id, facing) {
    if (by < YMIN || by >= YMAX) return false;
    const cx = Math.floor(bx / CS), cz = Math.floor(bz / CS), key = ckey(cx, cz);
    const k3 = bx + ',' + by + ',' + bz;
    if (facing !== undefined) this.facing.set(k3, facing); else this.facing.delete(k3);
    const c = this.chunks.get(key);
    if (!c) {
      if (!this.pending.has(key)) this.pending.set(key, []);
      this.pending.get(key).push([bx, by, bz, id]);
      return true;
    }
    const lx = bx - c.x0, lz = bz - c.z0;
    const old = c.data[idx(lx, by, lz)];
    c.data[idx(lx, by, lz)] = id;
    if (id && by > c.maxY) c.maxY = by;
    c.dirty = true; c.modified = true; c.urgent = true;
    if (EMIT[old] || EMIT[id]) c.emit = null;
    // Light reaches 15 blocks, so an edit that changes how light flows also
    // relights the surrounding chunks (they remesh over the next frames)
    if (EMIT[old] !== EMIT[id] || OPAQUE[old] !== OPAQUE[id] || SKYB[old] !== SKYB[id]) {
      for (let dx = -1; dx <= 1; dx++) for (let dz = -1; dz <= 1; dz++) {
        const n = (dx || dz) && this.chunks.get(ckey(cx + dx, cz + dz));
        if (n) n.dirty = true;
      }
    }
    // neighbours share faces / AO along borders
    const mark = (dx, dz) => { const n = this.chunks.get(ckey(cx + dx, cz + dz)); if (n) { n.dirty = true; n.urgent = true; } };
    if (lx === 0) mark(-1, 0); if (lx === CS - 1) mark(1, 0); if (lz === 0) mark(0, -1); if (lz === CS - 1) mark(0, 1);
    if (lx === 0 && lz === 0) mark(-1, -1); if (lx === CS - 1 && lz === CS - 1) mark(1, 1);
    if (lx === 0 && lz === CS - 1) mark(-1, 1); if (lx === CS - 1 && lz === 0) mark(1, -1);
    this.terrain._heightCache?.clear?.();
    return true;
  }
  // Swap a block's id without touching block-entity state (furnace lit/unlit)
  setBlockKeepEntity(bx, by, bz, name) {
    const f = this.facing.get(bx + ',' + by + ',' + bz);
    return this.setBlock(bx, by, bz, BLOCK[name] ?? 0, f);
  }

  // Top of the highest solid block at/below maxY in the column (x,z)
  surfaceBelow(x, z, maxY) {
    const bx = Math.floor(x), bz = Math.floor(z);
    const c = this.chunkAt(bx, bz);
    if (!c) return Math.min(this.terrain.columnHeight(bx, bz), Math.floor(maxY));
    const lx = bx - c.x0, lz = bz - c.z0;
    for (let by = Math.min(Math.floor(maxY) - 1, YMAX - 1); by >= YMIN; by--)
      if (SOLID[c.data[idx(lx, by, lz)]]) return by + 1;
    return YMIN;
  }
  // Ground level ignoring tree parts (spawning, item drops, legacy callers)
  groundHeight(x, z) {
    const bx = Math.floor(x), bz = Math.floor(z);
    const c = this.chunkAt(bx, bz);
    if (!c) return this.terrain.columnHeight(bx, bz);
    const lx = bx - c.x0, lz = bz - c.z0;
    for (let by = c.maxY; by >= YMIN; by--) {
      const id = c.data[idx(lx, by, lz)];
      if (SOLID[id] && !/_log$|_leaves$/.test(BLOCKS[id].name)) return by + 1;
    }
    return YMIN;
  }

  // Voxel DDA raycast. Returns the first non-air block hit (plants included).
  raycast(origin, dir, maxDist = 5, solidOnly = false) {
    let x = Math.floor(origin.x), y = Math.floor(origin.y), z = Math.floor(origin.z);
    const sx = Math.sign(dir.x), sy = Math.sign(dir.y), sz = Math.sign(dir.z);
    const tdx = sx ? Math.abs(1 / dir.x) : Infinity, tdy = sy ? Math.abs(1 / dir.y) : Infinity, tdz = sz ? Math.abs(1 / dir.z) : Infinity;
    let tx = sx ? ((sx > 0 ? x + 1 - origin.x : origin.x - x) * tdx) : Infinity;
    let ty = sy ? ((sy > 0 ? y + 1 - origin.y : origin.y - y) * tdy) : Infinity;
    let tz = sz ? ((sz > 0 ? z + 1 - origin.z : origin.z - z) * tdz) : Infinity;
    let nx = 0, ny = 0, nz = 0, t = 0;
    for (let i = 0; i < 256 && t <= maxDist; i++) {
      const id = this.getBlock(x, y, z);
      if (id && !FLUID[id] && (!solidOnly || SOLID[id])) {
        if (!SHP[id] || SHP[id] === SHAPE.pillar) return { x, y, z, id, nx, ny, nz, dist: t };
        // partial blocks: only a hit on one of the shape's boxes counts
        const h = rayBoxes(origin, dir, this.selBoxes(x, y, z, id), x, y, z, maxDist);
        if (h) return { x, y, z, id, nx: h.nx, ny: h.ny, nz: h.nz, dist: h.t };
      }
      if (tx < ty && tx < tz) { x += sx; t = tx; tx += tdx; nx = -sx; ny = 0; nz = 0; }
      else if (ty < tz) { y += sy; t = ty; ty += tdy; nx = 0; ny = -sy; nz = 0; }
      else { z += sz; t = tz; tz += tdz; nx = 0; ny = 0; nz = -sz; }
    }
    return null;
  }

  // ── generation ───────────────────────────────────────────────────────────
  _biomeTop(type, wx, wz) {
    const inf = this._infest(wx, wz);
    if (inf > 0.62 && type !== 'sand' && type !== 'snow' && type !== 'stone') return inf > 0.8 ? BLOCK.biomass : BLOCK.infested_grass;
    switch (type) {
      case 'sand': return BLOCK.sand;
      case 'snow': return BLOCK.snowy_grass;
      case 'stone': return BLOCK.stone;
      case 'forest': return BLOCK.grass_forest;
      case 'swamp': return BLOCK.grass_swamp;
      default: return BLOCK.grass_plains;
    }
  }
  _infest(wx, wz) {
    if (wx * wx + wz * wz < 60 * 60) return 0;               // spawn area stays clean
    return (this.patch.noise2D(wx * 0.012, wz * 0.012) + 1) / 2;
  }

  // Spaghetti caves: where two noise fields both cross zero. Never in the
  // bedrock layers, and not in the top 8 blocks around spawn.
  _cave(wx, y, wz, h) {
    if (y <= YMIN + 4 || y >= h) return false;
    if (wx * wx + wz * wz < 24 * 24 && y >= h - 8) return false;
    const a = this.caveA.noise3D(wx * 0.04, y * 0.07, wz * 0.04), b = this.caveB.noise3D(wx * 0.04, y * 0.07, wz * 0.04);
    return a * a + b * b < 0.011;
  }

  // Height + surface block of a column (pure function of the seed)
  _column(wx, wz) {
    const T = this.terrain;
    const h = Math.max(YMIN + 6, Math.min(YMAX - 12, T.columnHeight(wx, wz)));
    let type = T.surfaceType(wx, wz, h);
    // the ground over the Ice Caves is snow-covered at any altitude
    if (type === 'forest' && this._iceZone(wx, wz) > 0.3) type = 'snow';
    return { h, type, top: this._biomeTop(type, wx, wz) };
  }

  _generate(c) {
    const d = c.data;
    const heights = new Int16Array(CS * CS), tops = new Uint8Array(CS * CS);
    let maxY = YMIN;
    for (let lz = 0; lz < CS; lz++) for (let lx = 0; lx < CS; lx++) {
      const wx = c.x0 + lx, wz = c.z0 + lz;
      const { h, type, top } = this._column(wx, wz);
      const filler = type === 'sand' ? BLOCK.sand : type === 'stone' ? BLOCK.stone : BLOCK.dirt;
      heights[lz * CS + lx] = h; tops[lz * CS + lx] = top;
      const r = hash2(wx, wz, this.seed);
      const bedTop = YMIN + 1 + (r % 3);
      for (let y = YMIN; y < h; y++) {
        let id;
        if (y < bedTop) id = BLOCK.bedrock;
        else if (y === h - 1) id = top;
        else if (y >= h - 4) id = filler;
        else id = BLOCK.stone;
        if (id !== BLOCK.bedrock && this._cave(wx, y, wz, h)) id = 0;
        d[idx(lx, y, lz)] = id;
      }
      // a cave right under the surface would leave a 1-block crust (often a
      // lone floating grass block): open it into a cave mouth instead
      if (h - 2 > YMIN && d[idx(lx, h - 2, lz)] === 0) d[idx(lx, h - 1, lz)] = 0;
      if (h - 1 > maxY) maxY = h - 1;
    }
    c.maxY = maxY;
    this._ores(c, srand(hash2(c.cx, c.cz, this.seed)));
    this._iceCaves(c, heights, srand(hash2(c.cx, c.cz, this.seed ^ 0x1ce)));
    // Trees are planned per chunk from the seed and every chunk stamps the
    // parts of its own + its 8 neighbours' trees that fall inside it. No
    // cross-chunk writes, so trees are never cut at chunk borders, never
    // overwrite a neighbour's hillside, and survive unload/regenerate.
    for (let dx = -1; dx <= 1; dx++) for (let dz = -1; dz <= 1; dz++) {
      for (const t of this._trees(c.cx + dx, c.cz + dz)) {
        for (let i = 0; i < t.length; i += 5) {
          const lx = t[i] - c.x0, y = t[i + 1], lz = t[i + 2] - c.z0;
          if (lx < 0 || lx >= CS || lz < 0 || lz >= CS || y < YMIN || y >= YMAX) continue;
          const k = idx(lx, y, lz);
          if (t[i + 4] && d[k] !== 0 && RENDER[d[k]] !== 3) continue;
          d[k] = t[i + 3]; if (y > c.maxY) c.maxY = y;
        }
      }
    }
    this._decorate(c, srand(hash2(c.cx, c.cz, this.seed ^ 0x9e37)), heights, tops);
    // apply edits made before this chunk existed (structures)
    const pend = this.pending.get(ckey(c.cx, c.cz));
    if (pend) {
      for (const [x, y, z, id] of pend) { d[idx(x - c.x0, y, z - c.z0)] = id; if (id && y > c.maxY) c.maxY = y; }
      this.pending.delete(ckey(c.cx, c.cz));
      c.modified = true;
    }
  }

  // Deterministic tree list for chunk (cx, cz): arrays of [x,y,z,id,onlyAir]*
  _trees(cx, cz) {
    const key = ckey(cx, cz);
    const hit = this._treeCache.get(key);
    if (hit) return hit;
    const out = [];
    const x0 = cx * CS, z0 = cz * CS;
    const rnd = srand(hash2(cx, cz, this.seed ^ 0x7ee5));
    const biome = this.terrain.getBiome(x0 + 8, z0 + 8);
    const plainsTree = rnd() < 0.35 ? 1 : 0;
    const count = { forest: 6, plains: plainsTree, swamp: 2, mountain: 2, desert: 0 }[biome] ?? 0;
    const grassy = (id) => id === BLOCK.grass_plains || id === BLOCK.grass_forest || id === BLOCK.grass_swamp || id === BLOCK.snowy_grass || id === BLOCK.infested_grass;
    const trunks = [];
    for (let t = 0; t < count; t++) {
      const lx = 2 + ((rnd() * 12) | 0), lz = 2 + ((rnd() * 12) | 0);
      const kindRoll = rnd(), treeSeed = (rnd() * 4294967296) >>> 0;
      const wx = x0 + lx, wz = z0 + lz;
      if (wx * wx + wz * wz < 8 * 8) continue;
      if (trunks.some(([a, b]) => Math.abs(a - lx) <= 1 && Math.abs(b - lz) <= 1)) continue; // no fused trunks
      const { h, top } = this._column(wx, wz);
      // must stand on real ground: skip if a cave opened the top blocks
      if (!grassy(top) || this._cave(wx, h - 1, wz, h) || this._cave(wx, h - 2, wz, h)) continue;
      if (this._crevasse(wx, wz, h)) continue;
      const kind = biome === 'mountain' || top === BLOCK.snowy_grass ? 'spruce'
        : biome === 'swamp' ? 'dark_oak' : (biome === 'forest' && kindRoll < 0.3) ? 'birch' : 'oak';
      const b = [wx, h - 1, wz, BLOCK.dirt, 0];
      this._tree(kind, wx, h, wz, srand(treeSeed), (x, y, z, id, onlyAir = true) => b.push(x, y, z, id, onlyAir ? 1 : 0));
      trunks.push([lx, lz]);
      out.push(b);
    }
    if (this._treeCache.size > 4096) this._treeCache.clear();
    this._treeCache.set(key, out);
    return out;
  }

  // ── Ice Caves ────────────────────────────────────────────────────────────
  // Under the coldest part of the mountains: 0 outside, ramping to 1.
  _iceZone(wx, wz) {
    const v = this.terrain._biomeValue(wx, wz);
    return v < 0.83 ? 0 : Math.min(1, (v - 0.83) / 0.04);
  }
  // Crevasse columns: thin winding cracks down from the snow to a still
  // waterline (y = ICE_WL) a few blocks deep.
  _crevasse(wx, wz, h) {
    const z = this._iceZone(wx, wz);
    if (z < 0.5 || h < ICE_WL + 12 || wx * wx + wz * wz < 48 * 48) return false;
    return Math.abs(this.crev.noise2D(wx * 0.018, wz * 0.018)) < 0.04;
  }

  _iceCaves(c, heights, rnd) {
    const d = c.data;
    const zone = new Float32Array(CS * CS);
    let any = false;
    for (let lz = 0; lz < CS; lz++) for (let lx = 0; lx < CS; lx++) {
      const k = this._iceZone(c.x0 + lx, c.z0 + lz);
      zone[lz * CS + lx] = k; if (k > 0) any = true;
    }
    if (!any) return;
    const solidRock = (id) => id === BLOCK.stone || id === BLOCK.packed_ice || id === BLOCK.calcite || id === BLOCK.blue_ice;

    // 1. caverns + icy rock
    for (let lz = 0; lz < CS; lz++) for (let lx = 0; lx < CS; lx++) {
      const k = zone[lz * CS + lx]; if (!k) continue;
      const wx = c.x0 + lx, wz = c.z0 + lz, h = heights[lz * CS + lx];
      const yTop = h - 10;
      for (let y = YMIN + 6; y < h - 6; y++) {
        const i = idx(lx, y, lz), id = d[i];
        if (!id || id === BLOCK.bedrock) continue;
        if (y <= yTop) {
          const cv = this.cavern.noise3D(wx * 0.022, y * 0.05, wz * 0.022) + 0.3 * this.cavern.noise3D(wx * 0.08, y * 0.12, wz * 0.08);
          const thr = 0.38 + (1 - k) * 0.5 + Math.max(0, y - (yTop - 5)) * 0.08 + Math.max(0, YMIN + 12 - y) * 0.06;
          if (cv > thr) { d[i] = 0; continue; }
        }
        if (id !== BLOCK.stone) continue;            // ores stay embedded
        const m = this.iceMat.noise3D(wx * 0.05, y * 0.08, wz * 0.05) + (k - 1) * 0.6;
        d[i] = m > 0.6 ? BLOCK.blue_ice : m > 0.02 ? BLOCK.packed_ice : m < -0.3 ? BLOCK.calcite : BLOCK.stone;
      }
    }

    // 2. crevasses (decided per column, with a 1-column margin for the walls)
    const W = CS + 2, crack = new Uint8Array(W * W);
    for (let lz = -1; lz <= CS; lz++) for (let lx = -1; lx <= CS; lx++) {
      const wx = c.x0 + lx, wz = c.z0 + lz;
      const h = lx >= 0 && lx < CS && lz >= 0 && lz < CS ? heights[lz * CS + lx] : this._column(wx, wz).h;
      if (this._crevasse(wx, wz, h)) crack[(lz + 1) * W + lx + 1] = 1;
    }
    const isCrack = (lx, lz) => crack[(lz + 1) * W + lx + 1] === 1;
    for (let lz = 0; lz < CS; lz++) for (let lx = 0; lx < CS; lx++) {
      const wx = c.x0 + lx, wz = c.z0 + lz, h = heights[lz * CS + lx];
      if (isCrack(lx, lz)) {
        d[idx(lx, ICE_WL - 3, lz)] = BLOCK.packed_ice;                       // floor
        for (let y = ICE_WL - 2; y < h; y++) d[idx(lx, y, lz)] = y <= ICE_WL ? BLOCK.water : 0;
        // a thin brittle-ice crust hides part of the crack at the surface
        if (this.crev.noise2D(wx * 0.11 + 40, wz * 0.11) > -0.05) d[idx(lx, h - 1, lz)] = BLOCK.brittle_ice;
        // brittle ice forms on the water where it touches blue ice
        let byBlue = false;
        for (const [dx, dz] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) if (!isCrack(lx + dx, lz + dz)) byBlue = true;
        if (byBlue) d[idx(lx, ICE_WL, lz)] = BLOCK.brittle_ice;
      } else if (isCrack(lx + 1, lz) || isCrack(lx - 1, lz) || isCrack(lx, lz + 1) || isCrack(lx, lz - 1)) {
        // walls: blue ice at the waterline (sealing the water in), packed ice above
        for (let y = ICE_WL - 3; y < h - 2; y++) {
          const i = idx(lx, y, lz);
          if (y <= ICE_WL + 1) d[i] = BLOCK.blue_ice;
          else if (d[i] && d[i] !== BLOCK.bedrock && rnd() < 0.7) d[i] = BLOCK.packed_ice;
        }
      }
    }

    // 3. cave dressing: icicles from icy ceilings, crystals, snow patches
    const pk = (id) => id === BLOCK.packed_ice || id === BLOCK.blue_ice;
    for (let lz = 0; lz < CS; lz++) for (let lx = 0; lx < CS; lx++) {
      const k = zone[lz * CS + lx]; if (!k) continue;
      const h = heights[lz * CS + lx], wx = c.x0 + lx, wz = c.z0 + lz;
      const snowy = this.patch.noise2D(wx * 0.09, wz * 0.09) > 0.25;
      for (let y = YMIN + 7; y < h - 8; y++) {
        const i = idx(lx, y, lz);
        if (d[i] !== 0) continue;
        const up = d[idx(lx, y + 1, lz)], dn = d[idx(lx, y - 1, lz)];
        const r = rnd();
        if (pk(up) && r < 0.09 * k) {
          let n = 1 + ((rnd() * rnd() * 5) | 0);
          for (let yy = y; n > 0 && yy > YMIN + 2 && d[idx(lx, yy, lz)] === 0 && d[idx(lx, yy - 1, lz)] === 0; yy--, n--) d[idx(lx, yy, lz)] = BLOCK.icicle;
        } else if (solidRock(dn)) {
          if (snowy && r < 0.85) d[idx(lx, y - 1, lz)] = BLOCK.snow_block;
          else if (r > 0.985) d[i] = BLOCK.ice_crystal;
        } else if (solidRock(up) && r < 0.012) d[i] = BLOCK.ice_crystal;
      }
    }
  }

  _ores(c, rnd) {
    const d = c.data;
    // [block, veins per chunk, vein size, yMin, yMax]
    const TABLE = [
      [BLOCK.coal_ore, 14, 9, YMIN, 30], [BLOCK.iron_ore, 9, 7, YMIN, 8], [BLOCK.copper_ore, 7, 8, -20, 10],
      [BLOCK.gold_ore, 3, 7, YMIN, -10], [BLOCK.redstone_ore, 4, 6, YMIN, -16], [BLOCK.lapis_ore, 2, 6, YMIN, -4],
      [BLOCK.diamond_ore, 1, 5, YMIN, -20], [BLOCK.emerald_ore, 1, 2, -10, 20],
    ];
    for (const [ore, veins, size, y0, y1] of TABLE) {
      for (let v = 0; v < veins; v++) {
        let x = (rnd() * CS) | 0, z = (rnd() * CS) | 0, y = y0 + ((rnd() * (y1 - y0)) | 0);
        for (let s = 0; s < size; s++) {
          if (x >= 0 && x < CS && z >= 0 && z < CS && y > YMIN && y < YMAX) {
            const i = idx(x, y, z);
            if (d[i] === BLOCK.stone) d[i] = ore;
          }
          const r = rnd();
          if (r < 0.33) x += rnd() < 0.5 ? 1 : -1; else if (r < 0.66) z += rnd() < 0.5 ? 1 : -1; else y += rnd() < 0.5 ? 1 : -1;
        }
      }
    }
  }

  // Ground cover (grass, flowers, parasite growths): always inside the chunk
  _decorate(c, rnd, heights, tops) {
    const d = c.data;
    const put = (lx, y, lz, id) => {
      if (y < YMIN || y >= YMAX || lx < 0 || lx >= CS || lz < 0 || lz >= CS) return;
      const i = idx(lx, y, lz);
      if (d[i] === 0 || RENDER[d[i]] === 3) { d[i] = id; if (y > c.maxY) c.maxY = y; }
    };

    // Ground cover
    for (let lz = 0; lz < CS; lz++) for (let lx = 0; lx < CS; lx++) {
      const h = heights[lz * CS + lx], top = tops[lz * CS + lx];
      if (d[idx(lx, h - 1, lz)] !== top || d[idx(lx, h, lz)] !== 0) continue;
      const r = rnd();
      if (top === BLOCK.grass_plains) {
        if (r < 0.22) put(lx, h, lz, BLOCK.tall_grass);
        else if (r < 0.228) put(lx, h, lz, BLOCK.blood_poppy);
        else if (r < 0.237) put(lx, h, lz, BLOCK.dandelion);
        else if (r < 0.241) put(lx, h, lz, BLOCK.oxeye_daisy);
        else if (r < 0.244) put(lx, h, lz, BLOCK.cornflower);
      }
      else if (top === BLOCK.grass_forest) { if (r < 0.12) put(lx, h, lz, BLOCK.tall_grass); else if (r < 0.125) put(lx, h, lz, BLOCK.blood_poppy); else if (r < 0.13) put(lx, h, lz, BLOCK.dandelion); }
      else if (top === BLOCK.grass_swamp) { if (r < 0.1) put(lx, h, lz, BLOCK.tall_grass); else if (r < 0.112) put(lx, h, lz, BLOCK.fungal_stalk); }
      else if (top === BLOCK.sand) { if (r < 0.008) put(lx, h, lz, BLOCK.dead_bush); }
      else if (top === BLOCK.infested_grass || top === BLOCK.biomass) {
        if (r < 0.05) put(lx, h, lz, BLOCK.fungal_stalk);
        else if (r < 0.058) { put(lx, h, lz, BLOCK.flesh_block); if (rnd() < 0.5) put(lx, h + 1, lz, BLOCK.flesh_block); }
        else if (r < 0.062) { for (let k = 0; k < 2 + ((rnd() * 2) | 0); k++) put(lx, h + k, lz, BLOCK.bone_block); }
      }
    }
  }

  _tree(kind, lx, y0, lz, rnd, put) {
    const LOG = BLOCK[`${kind}_log`], LEAF = BLOCK[`${kind}_leaves`];
    if (kind === 'spruce') {
      const h = 6 + ((rnd() * 4) | 0);
      for (let i = 0; i < h; i++) put(lx, y0 + i, lz, LOG, false);
      let r = 0;
      for (let y = y0 + h; y >= y0 + 2; y--) {
        for (let dx = -r; dx <= r; dx++) for (let dz = -r; dz <= r; dz++) {
          if (Math.abs(dx) === r && Math.abs(dz) === r && r > 0) continue;
          put(lx + dx, y, lz + dz, LEAF);
        }
        r = r >= 2 ? 1 : r + 1;
      }
      put(lx, y0 + h, lz, LEAF); put(lx, y0 + h + 1, lz, LEAF);
      return;
    }
    const h = kind === 'birch' ? 5 + ((rnd() * 3) | 0) : kind === 'dark_oak' ? 5 + ((rnd() * 2) | 0) : 4 + ((rnd() * 3) | 0);
    const top = y0 + h - 1;
    // vanilla oak blob: two wide layers, two narrow layers, random missing corners
    for (let y = top - 2; y <= top + 1; y++) {
      const r = y <= top - 1 ? 2 : 1;
      for (let dx = -r; dx <= r; dx++) for (let dz = -r; dz <= r; dz++) {
        const corner = Math.abs(dx) === r && Math.abs(dz) === r;
        if (corner && (y === top + 1 || rnd() < 0.5)) continue;
        put(lx + dx, y, lz + dz, LEAF);
      }
    }
    for (let i = 0; i < h; i++) put(lx, y0 + i, lz, LOG, false);
  }

  // ── lighting ─────────────────────────────────────────────────────────────
  // Flood-fills sky + block light over the chunk and a 15-block margin, then
  // keeps the chunk's own levels in c.light (sky << 4 | block).
  _computeLight(c) {
    const grid = LGRID;
    for (let gz = 0; gz < 3; gz++) for (let gx = 0; gx < 3; gx++) grid[gz * 3 + gx] = this.chunks.get(ckey(c.cx + gx - 1, c.cz + gz - 1)) ?? null;
    const T = this.terrain;
    // 1. heightmap: highest sky-blocking block per column (ungenerated
    //    neighbours fall back to the terrain estimate, solid below it)
    let col = 0;
    for (let rz = 0; rz < LW; rz++) for (let rx = 0; rx < LW; rx++, col++) {
      const wx = rx - LM, wz = rz - LM;
      const g = grid[((wz + 16) >> 4) * 3 + ((wx + 16) >> 4)];
      if (!g) { LHM[col] = T.columnHeight(c.x0 + wx, c.z0 + wz) - 1; continue; }
      const d = g.data, base = (wz & 15) * CS + (wx & 15);
      let y = Math.min(YMAX - 1, g.maxY);
      for (; y >= YMIN; y--) if (SKYB[d[(y - YMIN) * CS * CS + base]]) break;
      LHM[col] = y;
    }
    const blockAt = (rx, y, rz) => {
      const wx = rx - LM, wz = rz - LM;
      const g = grid[((wz + 16) >> 4) * 3 + ((wx + 16) >> 4)];
      if (!g) return y <= LHM[rz * LW + rx] ? STONE_ID : 0;
      return g.data[((y - YMIN) * CS + (wz & 15)) * CS + (wx & 15)];
    };
    const flood = (L, head, tail, isSky) => {
      while (head !== tail) {
        const i = LQ[head]; head = (head + 1) & LQM;
        const lv = L[i];
        if (lv <= 1) continue;
        const yi = (i / LWW) | 0, r = i - yi * LWW, rz = (r / LW) | 0, rx = r - rz * LW, y = yi + YMIN;
        const nl = lv - 1;
        for (let k = 0; k < 6; k++) {
          let nx = rx, ny = y, nz = rz;
          if (k === 0) nx++; else if (k === 1) nx--; else if (k === 2) ny++; else if (k === 3) ny--; else if (k === 4) nz++; else nz--;
          if (nx < 0 || nx >= LW || nz < 0 || nz >= LW || ny < YMIN || ny >= YMAX) continue;
          const nc = nz * LW + nx;
          if (isSky && ny > LHM[nc]) continue;              // open sky: already 15
          const ni = (ny - YMIN) * LWW + nc;
          if (L[ni] >= nl) continue;
          if (OPAQUE[blockAt(nx, ny, nz)]) continue;
          L[ni] = nl; LQ[tail] = ni; tail = (tail + 1) & LQM;
        }
      }
    };
    // 2. sky light: seed the open-sky cells that border shaded ones, flood
    LSKY.fill(0);
    let tail = 0;
    col = 0;
    for (let rz = 0; rz < LW; rz++) for (let rx = 0; rx < LW; rx++, col++) {
      const h = LHM[col];
      let top = h + 1;
      if (rx > 0 && LHM[col - 1] > top) top = LHM[col - 1];
      if (rx < LW - 1 && LHM[col + 1] > top) top = LHM[col + 1];
      if (rz > 0 && LHM[col - LW] > top) top = LHM[col - LW];
      if (rz < LW - 1 && LHM[col + LW] > top) top = LHM[col + LW];
      if (top >= YMAX) top = YMAX - 1;
      for (let y = Math.max(YMIN, h + 1); y <= top; y++) {
        const i = (y - YMIN) * LWW + col;
        LSKY[i] = 15; LQ[tail] = i; tail = (tail + 1) & LQM;
      }
    }
    flood(LSKY, 0, tail, true);
    // 3. block light from emitters (each chunk caches its emitter list)
    LBLK.fill(0);
    tail = 0;
    for (let gi = 0; gi < 9; gi++) {
      const g = grid[gi];
      if (!g) continue;
      if (!g.emit) {
        g.emit = [];
        const d = g.data;
        for (let i = 0; i < VOL; i++) if (EMIT[d[i]]) g.emit.push(i);
      }
      const ox = (gi % 3 - 1) * CS + LM, oz = (((gi / 3) | 0) - 1) * CS + LM;
      for (const i of g.emit) {
        const lx = i % CS, lz = ((i / CS) | 0) % CS, yi = (i / (CS * CS)) | 0;
        const rx = ox + lx, rz = oz + lz;
        if (rx < 0 || rx >= LW || rz < 0 || rz >= LW) continue;
        const li = yi * LWW + rz * LW + rx, e = EMIT[g.data[i]];
        if (LBLK[li] < e) { LBLK[li] = e; LQ[tail] = li; tail = (tail + 1) & LQM; }
      }
    }
    flood(LBLK, 0, tail, false);
    // 4. keep this chunk's own levels for lightLevelAt
    const out = c.light ?? (c.light = new Uint8Array(VOL));
    for (let yi = 0; yi < H; yi++) for (let lz = 0; lz < CS; lz++) {
      const rowL = yi * LWW + (lz + LM) * LW + LM, rowC = (yi * CS + lz) * CS, y = yi + YMIN;
      for (let lx = 0; lx < CS; lx++) {
        const sky = y > LHM[(lz + LM) * LW + lx + LM] ? 15 : LSKY[rowL + lx];
        out[rowC + lx] = (sky << 4) | LBLK[rowL + lx];
      }
    }
  }

  // ── meshing ──────────────────────────────────────────────────────────────
  _mesh(c) {
    this._computeLight(c);
    const d = c.data, x0 = c.x0, z0 = c.z0;
    MBUF[0].reset(); MBUF[1].reset(); MBUF[2].reset();
    // neighbour id lookup (fast path inside this chunk)
    const get = (lx, y, lz) => {
      if (y < YMIN || y >= YMAX) return 0;
      if (lx >= 0 && lx < CS && lz >= 0 && lz < CS) return d[idx(lx, y, lz)];
      return this.getBlock(x0 + lx, y, z0 + lz);
    };
    const op = (lx, y, lz) => OPAQUE[get(lx, y, lz)];
    // light at a chunk-local cell (always inside the lit margin)
    const skyL = (lx, y, lz) => {
      if (y >= YMAX) return 15; if (y < YMIN) return 0;
      const colI = (lz + LM) * LW + lx + LM;
      return y > LHM[colI] ? 15 : LSKY[(y - YMIN) * LWW + colI];
    };
    const blkL = (lx, y, lz) => (y < YMIN || y >= YMAX) ? 0 : LBLK[(y - YMIN) * LWW + (lz + LM) * LW + lx + LM];
    const yTop = Math.min(YMAX - 1, c.maxY + 1);
    const ao = [0, 0, 0, 0], ls = [0, 0, 0, 0], lb = [0, 0, 0, 0];
    // Smooth lighting for a face whose outside cell is (nx,ny,nz): AO and
    // light from the 4 cells around each corner, in the plane just outside
    // the face. A dark (opaque) neighbour borrows the face cell's light, like
    // vanilla's blend(). Fills ao / ls / lb for corners k = 0..3.
    const corners = (nx, ny, nz, F) => {
      const s0 = skyL(nx, ny, nz), b0 = blkL(nx, ny, nz);
      for (let k = 0; k < 4; k++) {
        const a = (k === 1 || k === 2) ? 1 : -1, b = (k >= 2) ? 1 : -1;
        const ax = nx + F.u[0] * a, ay = ny + F.u[1] * a, az = nz + F.u[2] * a;
        const bx = nx + F.v[0] * b, by = ny + F.v[1] * b, bz = nz + F.v[2] * b;
        const cx = ax + F.v[0] * b, cy = ay + F.v[1] * b, cz = az + F.v[2] * b;
        const s1 = op(ax, ay, az), s2 = op(bx, by, bz), cc = s1 && s2 ? 1 : op(cx, cy, cz);
        ao[k] = s1 && s2 ? 0 : 3 - (s1 + s2 + cc);
        let sa = s0, ba = b0;
        let t;
        t = s1 ? 0 : skyL(ax, ay, az); sa += t || s0; t = s1 ? 0 : blkL(ax, ay, az); ba += t || b0;
        t = s2 ? 0 : skyL(bx, by, bz); sa += t || s0; t = s2 ? 0 : blkL(bx, by, bz); ba += t || b0;
        t = cc ? 0 : skyL(cx, cy, cz); sa += t || s0; t = cc ? 0 : blkL(cx, cy, cz); ba += t || b0;
        ls[k] = sa; lb[k] = ba;            // 0..60 (sum of four 0..15 levels)
      }
    };
    // Shaped blocks (slabs, stairs, walls, pillars): each box face is a
    // sub-rectangle of the cell face, lit by interpolating the full face's
    // corner light (boundary faces) or the cell's own light (inner faces).
    const shaped = (B, lx, y, lz, id, uv) => {
      const wx = x0 + lx, wz = z0 + lz, st = this.facing.get(wx + ',' + y + ',' + wz) ?? 0;
      const kind = SHP[id];
      const boxes = kind === SHAPE.wall ? shapeBoxes(kind, 0, this._wallConn(wx, y, wz)) : shapeBoxes(kind, st);
      const pillarAxis = kind === SHAPE.pillar ? [1, 0, 2][st] ?? 1 : 1;
      const own = [skyL(lx, y, lz) * 4, blkL(lx, y, lz) * 4];
      for (const bx of boxes) for (let f = 0; f < 6; f++) {
        const F = FACES[f], ax = F.n[0] ? 0 : F.n[1] ? 1 : 2, pos = F.n[ax] > 0;
        const pc = pos ? bx[ax + 3] : bx[ax];
        const boundary = pos ? pc >= 1 : pc <= 0;
        if (boundary && op(lx + F.n[0], y + F.n[1], lz + F.n[2])) continue;
        if (boundary) corners(lx + F.n[0], y + F.n[1], lz + F.n[2], F);
        else { for (let k = 0; k < 4; k++) { ao[k] = 3; ls[k] = own[0]; lb[k] = own[1]; } }
        // face-parameter ranges of this box along the face's u and v axes
        const ua = F.u[0] ? 0 : F.u[1] ? 1 : 2, us = F.u[ua], va = F.v[0] ? 0 : F.v[1] ? 1 : 2, vs = F.v[va];
        const pa = (q) => (q - F.o[ua]) * us, pb = (q) => (q - F.o[va]) * vs;
        const a0 = Math.min(pa(bx[ua]), pa(bx[ua + 3])), a1 = Math.max(pa(bx[ua]), pa(bx[ua + 3]));
        const b0 = Math.min(pb(bx[va]), pb(bx[va + 3])), b1 = Math.max(pb(bx[va]), pb(bx[va + 3]));
        // texture: pillar ends use the top tile, its sides run along the axis
        let tile, rot = false;
        if (kind === SHAPE.pillar) { tile = ax === pillarAxis ? uv.top : uv.side; rot = ax !== pillarAxis && ua === pillarAxis; }
        else tile = F.tex === 'side' ? uv.side : uv[F.tex];
        const v0 = B.nv;
        if (B.nv + 4 > B.pos.length / 3 || B.ni + 6 > B.idx.length) B._grow();
        const q = [0, 0, 0, 0];
        for (let k = 0; k < 4; k++) {
          const a = (k === 1 || k === 2) ? a1 : a0, b = k >= 2 ? b1 : b0;
          const w0 = (1 - a) * (1 - b), w1 = a * (1 - b), w2 = a * b, w3 = (1 - a) * b;
          const L = (arr) => arr[0] * w0 + arr[1] * w1 + arr[2] * w2 + arr[3] * w3;
          const sky = L(ls), blk = L(lb), aoV = AO[ao[0]] * w0 + AO[ao[1]] * w1 + AO[ao[2]] * w2 + AO[ao[3]] * w3;
          q[k] = aoV * 192 + sky + blk;
          const P = [lx + F.o[0] + F.u[0] * a + F.v[0] * b, y + F.o[1] + F.u[1] * a + F.v[1] * b, lz + F.o[2] + F.u[2] * a + F.v[2] * b];
          P[ax] = (ax === 1 ? y : ax === 0 ? lx : lz) + pc;
          const tu = rot ? b : a, tv = rot ? 1 - a : b;
          B.vert(P[0], P[1], P[2], (sky * 4.25 + 0.5) | 0, (blk * 4.25 + 0.5) | 0, (F.shade * aoV * 255 + 0.5) | 0,
            tile[0] + (tile[2] - tile[0]) * tu, tile[3] - (tile[3] - tile[1]) * tv);
        }
        if (q[0] + q[2] < q[1] + q[3]) B.quad(v0 + 1, v0 + 2, v0 + 3, v0 + 0);
        else B.quad(v0, v0 + 1, v0 + 2, v0 + 3);
      }
    };

    // Still water: faces toward anything that is neither water nor opaque;
    // the surface sits 2px below the cell top unless more water is above.
    // Flat (per-face) light, drawn in the translucent pass.
    const liquid = (lx, y, lz, id, tile) => {
      const B = MBUF[2]; B.cw = 0;
      const topH = get(lx, y + 1, lz) === id ? 1 : 0.875;
      for (let f = 0; f < 6; f++) {
        const F = FACES[f];
        const nx = lx + F.n[0], ny = y + F.n[1], nz = lz + F.n[2];
        const nid = get(nx, ny, nz);
        if (nid === id || (OPAQUE[nid] && !(F.n[1] === 1 && topH < 1))) continue;
        const s = skyL(nx, ny, nz), bl = blkL(nx, ny, nz);
        const ox = lx + F.o[0], oy = y + F.o[1], oz = lz + F.o[2];
        const v0 = B.nv;
        if (B.nv + 4 > B.pos.length / 3 || B.ni + 6 > B.idx.length) B._grow();
        for (let k = 0; k < 4; k++) {
          const a = (k === 1 || k === 2) ? 1 : 0, b = k >= 2 ? 1 : 0;
          let vy = oy + F.u[1] * a + F.v[1] * b;
          if (vy > y + 0.5) vy = y + topH;
          B.vert(ox + F.u[0] * a + F.v[0] * b, vy, oz + F.u[2] * a + F.v[2] * b,
            (s * 4.25 + 0.5) | 0, (bl * 4.25 + 0.5) | 0, (F.shade * 255 + 0.5) | 0,
            tile[0] + (tile[2] - tile[0]) * a, tile[3] - (tile[3] - tile[1]) * b);
        }
        B.quad(v0, v0 + 1, v0 + 2, v0 + 3);
      }
    };

    for (let y = YMIN; y <= yTop; y++) for (let lz = 0; lz < CS; lz++) for (let lx = 0; lx < CS; lx++) {
      const id = d[idx(lx, y, lz)];
      if (!id) continue;
      const rt = RENDER[id], uv = UVS[id];
      if (rt === 6) { liquid(lx, y, lz, id, uv.side); continue; }
      if (rt === 3) {
        // icicles pick base / middle / tip from what hangs above and below
        let tile = uv.side;
        if (id === BLOCK.icicle) {
          const below = get(lx, y - 1, lz) === id, above = get(lx, y + 1, lz) === id;
          tile = !below ? ICICLE_UV[2] : above ? ICICLE_UV[1] : ICICLE_UV[0];
        }
        this._cross(MBUF[1], lx, y, lz, tile, skyL(lx, y, lz), blkL(lx, y, lz), x0 + lx, z0 + lz, id === BLOCK.tall_grass, STILL[id] === 1); continue; }
      if (rt >= 4) { MBUF[0].cw = 0; shaped(MBUF[0], lx, y, lz, id, uv); continue; }
      const B = MBUF[rt === 1 ? 0 : 1];
      B.cw = LEAVES[id] ? 3 : 0;
      const front = BLOCKS[id].tex.front ? (this.facing.get((x0 + lx) + ',' + y + ',' + (z0 + lz)) ?? 2) : -1;
      for (let f = 0; f < 6; f++) {
        const F = FACES[f];
        const nx = lx + F.n[0], ny = y + F.n[1], nz = lz + F.n[2];
        const nid = get(nx, ny, nz);
        if (OPAQUE[nid]) continue;
        if (rt === 2 && nid === id && BLOCKS[id].render === 'glass') continue;
        const tile = uv.vars ? uv.vars[faceHash(x0 + lx, y, z0 + lz, f) % uv.vars.length]
          : F.tex === 'side' ? (F.dir === front ? uv.front : uv.side) : uv[F.tex];
        // Smooth lighting: AO and light from the 4 cells around each corner,
        // in the plane just outside the face. A dark (opaque) neighbour
        // borrows the face cell's light, like vanilla's blend().
        corners(nx, ny, nz, F);
        const v0 = B.nv;
        const ox = lx + F.o[0], oy = y + F.o[1], oz = lz + F.o[2];
        for (let k = 0; k < 4; k++) {
          const a = (k === 1 || k === 2) ? 1 : 0, b = k >= 2 ? 1 : 0;
          if (B.nv + 4 > B.pos.length / 3 || B.ni + 6 > B.idx.length) B._grow();
          B.vert(ox + F.u[0] * a + F.v[0] * b, oy + F.u[1] * a + F.v[1] * b, oz + F.u[2] * a + F.v[2] * b,
            (ls[k] * 4.25 + 0.5) | 0, (lb[k] * 4.25 + 0.5) | 0, (F.shade * AO[ao[k]] * 255 + 0.5) | 0,
            tile[0] + (tile[2] - tile[0]) * a, tile[3] - (tile[3] - tile[1]) * b);
        }
        // flip the diagonal along the brighter corners (no AO/light "creases")
        const q0 = ao[0] * 64 + ls[0] + lb[0], q1 = ao[1] * 64 + ls[1] + lb[1], q2 = ao[2] * 64 + ls[2] + lb[2], q3 = ao[3] * 64 + ls[3] + lb[3];
        if (q0 + q2 < q1 + q3) B.quad(v0 + 1, v0 + 2, v0 + 3, v0 + 0);
        else B.quad(v0, v0 + 1, v0 + 2, v0 + 3);
      }
    }

    // Pack both groups into exact-size typed attributes
    let nv = 0, ni = 0;
    for (const M of MBUF) { nv += M.nv; ni += M.ni; }
    const pos = new Float32Array(nv * 3), col = new Uint8Array(nv * 3), uvs = new Float32Array(nv * 2);
    const wav = new Uint8Array(nv);
    const ind = nv > 65535 ? new Uint32Array(ni) : new Uint16Array(ni);
    const geo = new THREE.BufferGeometry();
    let vo = 0, io = 0;
    MBUF.forEach((M, g) => {
      pos.set(M.pos.subarray(0, M.nv * 3), vo * 3); col.set(M.col.subarray(0, M.nv * 3), vo * 3);
      uvs.set(M.uv.subarray(0, M.nv * 2), vo * 2); wav.set(M.w.subarray(0, M.nv), vo);
      for (let i = 0; i < M.ni; i++) ind[io + i] = M.idx[i] + vo;
      if (M.ni) geo.addGroup(io, M.ni, g);
      vo += M.nv; io += M.ni;
    });
    geo.setAttribute('position', new THREE.BufferAttribute(pos, 3));
    geo.setAttribute('color', new THREE.BufferAttribute(col, 3, true));   // normalized bytes
    geo.setAttribute('uv', new THREE.BufferAttribute(uvs, 2));
    geo.setAttribute('aWave', new THREE.BufferAttribute(wav, 1));   // 0 solid, 1/2 plant base/tip, 3 leaves
    geo.setIndex(new THREE.BufferAttribute(ind, 1));
    geo.computeBoundingSphere();
    geo.computeBoundingBox();

    if (c.mesh) { this.game.scene.scene.remove(c.mesh); c.mesh.geometry.dispose(); }
    const mesh = new THREE.Mesh(geo, [this.matOpaque, this.matCutout, this.matWater]);
    mesh.userData.noVox = true; mesh.userData.voxelChunk = true;
    mesh.position.set(x0, 0, z0);         // chunk-local vertices: smaller floats, better precision
    mesh.matrixAutoUpdate = false; mesh.updateMatrix();
    mesh.raycast = () => {};            // hits use the voxel DDA, never triangle tests
    mesh.layers.enable(SHADOW_LAYER_TERRAIN);
    this.game.scene.scene.add(mesh);
    c.mesh = mesh; c.dirty = false; c.urgent = false;
  }

  // Vanilla "cross" model: two planes spanning the full block diagonals,
  // shifted by a per-position hash (up to +-0.25 on X/Z like vanilla's
  // offset_type; short grass also sinks up to 0.2 so tufts vary in height).
  _cross(B, x, y, z, tile, sky, blk, wx, wz, sink, still = false) {
    let h = Math.imul(wx, 3129871) ^ Math.imul(wz, 116129781);
    h = (Math.imul(Math.imul(h, h), 42317861) + Math.imul(h, 11)) | 0;
    const ox = (((h >> 16) & 15) / 15 - 0.5) * 0.5, oz = (((h >> 24) & 15) / 15 - 0.5) * 0.5;
    const oy = sink ? (((h >> 20) & 15) / 15 - 1) * 0.2 : 0;
    const X = x + ox, Z = z + oz, Y = y + oy;
    const r = sky * 17, g = blk * 17, sh = 242;
    for (const [ax, az, bx, bz] of [[0, 0, 1, 1], [0, 1, 1, 0]]) {
      if (B.nv + 4 > B.pos.length / 3 || B.ni + 6 > B.idx.length) B._grow();
      const v0 = B.nv;
      B.cw = still ? 0 : 1;
      B.vert(X + ax, Y, Z + az, r, g, sh, tile[0], tile[3]);
      B.vert(X + bx, Y, Z + bz, r, g, sh, tile[2], tile[3]);
      B.cw = still ? 0 : 2;
      B.vert(X + bx, Y + 1, Z + bz, r, g, sh, tile[2], tile[1]);
      B.vert(X + ax, Y + 1, Z + az, r, g, sh, tile[0], tile[1]);
      B.cw = 0;
      B.quad(v0, v0 + 1, v0 + 2, v0 + 3);
    }
  }

  // ── streaming ────────────────────────────────────────────────────────────
  ensureChunk(cx, cz) {
    const key = ckey(cx, cz);
    let c = this.chunks.get(key);
    if (c) return c;
    this.structures?.planAround?.(cx, cz);
    c = new Chunk(cx, cz);
    this.chunks.set(key, c);
    this._generate(c);
    for (const [dx, dz] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) { const n = this.chunks.get(ckey(cx + dx, cz + dz)); if (n && n.mesh) n.dirty = true; }
    return c;
  }

  // Synchronously generate + mesh around a point (game start / teleports)
  preload(x, z, r = 3) {
    const pcx = Math.floor(x / CS), pcz = Math.floor(z / CS);
    for (let dx = -r - 1; dx <= r + 1; dx++) for (let dz = -r - 1; dz <= r + 1; dz++) this.ensureChunk(pcx + dx, pcz + dz);
    for (let dx = -r; dx <= r; dx++) for (let dz = -r; dz <= r; dz++) this._mesh(this.chunks.get(ckey(pcx + dx, pcz + dz)));
  }

  update(playerPos) {
    const pcx = Math.floor(playerPos.x / CS), pcz = Math.floor(playerPos.z / CS), R = this.radius;
    // 1. edited chunks remesh immediately (block break/place feedback)
    for (const c of this.chunks.values()) if (c.urgent && c.mesh) this._mesh(c);
    // 2. generate + mesh nearest missing chunks within a per-frame budget
    let gen = 0, meshed = 0;
    for (let ring = 0; ring <= R + 1 && (gen < 3 || meshed < 2); ring++) {
      for (let dx = -ring; dx <= ring; dx++) for (let dz = -ring; dz <= ring; dz++) {
        if (Math.max(Math.abs(dx), Math.abs(dz)) !== ring) continue;
        const cx = pcx + dx, cz = pcz + dz, key = ckey(cx, cz);
        let c = this.chunks.get(key);
        if (!c) { if (gen >= 3) continue; c = this.ensureChunk(cx, cz); gen++; }
        if (ring <= R && (c.dirty || !c.mesh) && meshed < 2) {
          // need all 4 neighbours generated for correct border faces
          let ok = true;
          for (const [ax, az] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) if (!this.chunks.has(ckey(cx + ax, cz + az))) ok = false;
          if (ok) { this._mesh(c); meshed++; }
        }
      }
    }
    // 3. unload far chunks (keep data of edited ones)
    if ((this._unloadTick = (this._unloadTick ?? 0) + 1) % 30 === 0) {
      for (const [key, c] of this.chunks) {
        const dist = Math.max(Math.abs(c.cx - pcx), Math.abs(c.cz - pcz));
        if (dist > R + 2 && c.mesh) { this.game.scene.scene.remove(c.mesh); c.mesh.geometry.dispose(); c.mesh = null; c.dirty = true; }
        if (dist > R + 10 && !c.modified) this.chunks.delete(key);
      }
    }
    this._updateLight();
  }

  // Fog object for non-terrain materials; open-sky brightness for things
  // outside any lit chunk
  _updateLight() {
    const sc = this.game.scene?.scene;
    if (sc && (!sc.fog || !sc.fog.isFog)) sc.fog = new THREE.Fog(0xa8c4dc, 60, 92);
    this._daylight = this._brightness(15, 0);
  }

  clear() {
    for (const c of this.chunks.values()) if (c.mesh) { this.game.scene.scene.remove(c.mesh); c.mesh.geometry.dispose(); }
    this.chunks.clear(); this.pending.clear(); this.facing.clear();
    this.game.fallingBlocks?.clear();
    this.game.frost?.clear(); this.game.throwables?.clear(); this.game.freeze?.clear(); this.game.jukebox?.clear(); this.game.security?.clear();
  }
}
