// SecuritySystem.js — SecurityCraft-style lab security.
//
// Device art is from SecurityCraft (MIT License, Copyright (c) 2025 The
// SecurityCraft development team; see CREDITS.md). Behaviour is our own:
//   Laser blocks facing each other (up to 8 blocks apart, nothing solid in
//     between) project a beam. Walking through it trips every alarm nearby
//     and releases specimens in the closest research lab.
//   Alarms light up and wail while tripped.
//   Mines explode under anything that steps on them.
//   A keypad opens the code prompt of the locker it is wired to (any locker
//     touching it) and turns green once that locker is open.
//   The panic button raises the alarm by hand.
//   The username logger lists everyone who walked past it.
//
// Devices are found by scanning the blocks around the player once a second,
// so placed, broken and generated devices all work the same way.

import * as THREE from 'three';
import { BLOCK, BLOCKS } from '../world/Blocks.js';

const ID = (n) => BLOCK[n];
const LASER = ID('sc_laser_block'), MINE = ID('sc_mine');
const ALARM = ID('sc_alarm'), ALARM_LIT = ID('sc_alarm_lit');
const KEYPAD = ID('sc_keypad'), KEYPAD_ON = ID('sc_keypad_active');
const PANIC_ON = ID('sc_panic_button_powered');
const LOGGER = ID('sc_username_logger');
const LOCKER = ID('keypad_locker'), LOCKER_OPEN = ID('keypad_locker_open');

const SCAN_R = 14, SCAN_Y = 6, BEAM_MAX = 8;
const ALARM_TIME = 12, ALARM_RANGE = 24;
const MINE_R = 4, MINE_DMG = 60;
const STAFF = ['Dr. H. Okafor', 'Dr. M. Varga', 'Tech R. Lindqvist', 'Dr. A. Sato', 'Tech J. Mbeki', 'Dr. E. Calloway', 'Guard T. Novak', 'Dr. L. Brandt'];

export class SecuritySystem {
  constructor(game) {
    this.game = game;
    this.beams = new Map();      // "x,y,z|axis|len" -> { mesh, a, axis, len }
    this.devices = { mine: [], alarm: [], keypad: [], logger: [] };
    this.scanT = 0;
    this.alarmT = 0;             // seconds left on the current alarm
    this.alarmAt = null;         // where it was tripped
    this.lit = new Set();        // alarm keys switched to the lit block
    this.released = new Map();   // lab name -> time specimens were last released
    this.logs = new Map();       // logger key -> names
    this.timers = [];            // [secondsLeft, fn]
    this.t = 0;
  }

  get vw() { return this.game.voxelWorld; }
  get scene() { return this.game.scene?.scene; }

  // ── interaction (right-click) ──────────────────────────────────────────
  interact(kind, x, y, z) {
    if (kind === 'sc_keypad') {
      const lk = this._lockerNear(x, y, z);
      if (!lk) { this._toast('Keypad: not wired to a locker', '#ff8a7a'); return true; }
      this.game.inventorySystem?.mcScreen?.openContainer?.('keypad', lk);
      return true;
    }
    if (kind === 'sc_panic') {
      this.vw.setBlockKeepEntity(x, y, z, 'sc_panic_button_powered');
      this.timers.push([1.5, () => { if (this.vw.getBlock(x, y, z) === PANIC_ON) this.vw.setBlockKeepEntity(x, y, z, 'sc_panic_button'); }]);
      this._click();
      this.trigger(x, y, z, 'Panic button pressed', false);
      return true;
    }
    if (kind === 'sc_logger') {
      const names = this._log(`${x},${y},${z}`);
      this._toast(`Username Logger: ${names.join(', ')}`, '#c8f0ff');
      return true;
    }
    return false;
  }

  _lockerNear(x, y, z) {
    for (let dy = -1; dy <= 1; dy++) for (let dx = -1; dx <= 1; dx++) for (let dz = -1; dz <= 1; dz++) {
      const id = this.vw.getBlock(x + dx, y + dy, z + dz);
      if (id === LOCKER || id === LOCKER_OPEN) return `${x + dx},${y + dy},${z + dz}`;
    }
    return null;
  }

  _log(key) {
    if (!this.logs.has(key)) {
      // the staff who badged in before the outbreak, fixed per logger
      const [x, , z] = key.split(',').map(Number);
      let h = (Math.imul(x, 73856093) ^ Math.imul(z, 19349663)) >>> 0;
      const names = [];
      for (let i = 0; i < 2 + (h % 2); i++) { const n = STAFF[(h >>> (i * 5)) % STAFF.length]; if (!names.includes(n)) names.push(n); }
      this.logs.set(key, names);
    }
    return this.logs.get(key);
  }

  // ── alarm ──────────────────────────────────────────────────────────────
  trigger(x, y, z, reason, release = true) {
    const fresh = this.alarmT <= 0;
    this.alarmT = ALARM_TIME;
    this.alarmAt = new THREE.Vector3(x + 0.5, y + 0.5, z + 0.5);
    for (const a of this.devices.alarm) {
      if (Math.hypot(a[0] - x, a[1] - y, a[2] - z) > ALARM_RANGE) continue;
      const k = a.join(',');
      if (this.vw.getBlock(a[0], a[1], a[2]) === ALARM) this.vw.setBlockKeepEntity(a[0], a[1], a[2], 'sc_alarm_lit');
      this.lit.add(k);
    }
    if (fresh) { this._toast(`ALARM: ${reason}`, '#ff4a3a'); this._siren(true); }
    if (release) this._release(x, y, z);
  }

  // the nearest lab opens its specimen tanks (at most once a minute)
  _release(x, y, z) {
    const labs = this.game.labGenerator?.labs ?? [];
    let best = null, bd = 40;
    for (const l of labs) {
      if (!l.hall) continue;
      const d = Math.hypot(l.hall[0] - x, l.hall[1] - z);
      if (d < bd) { bd = d; best = l; }
    }
    if (!best) return;
    const last = this.released.get(best.name) ?? -1e9;
    if (this.t - last < 60) return;
    this.released.set(best.name, this.t);
    const zm = this.game.zombieManager;
    if (!zm?.spawn) return;
    for (const kind of ['runner', 'walker']) {
      const zb = zm.spawn(kind, best.hall[0] - 3 + Math.random(), best.hall[1] + (Math.random() * 2 - 1));
      if (!zb) continue;
      const fy = best.y + 1;
      zb.position.y = fy + 0.9; if (zb.body) zb.body.position.y = fy + 0.9; zb._blockPos = null;
    }
  }

  _endAlarm() {
    for (const k of this.lit) {
      const [x, y, z] = k.split(',').map(Number);
      if (this.vw.getBlock(x, y, z) === ALARM_LIT) this.vw.setBlockKeepEntity(x, y, z, 'sc_alarm');
    }
    this.lit.clear();
    this._siren(false);
  }

  _audio() {
    const am = this.game.audioManager, ac = am?.audioContext;
    if (!ac) return null;
    if (ac.state === 'suspended') ac.resume?.();
    return { ac, dest: am.sfxGain ?? am.masterGain ?? ac.destination };
  }

  // two-tone wail: a square wave swept by a slow LFO, loudness by distance
  _siren(on) {
    if (!on) {
      if (this._sir) { const { ac, gain, osc, lfo } = this._sir; gain.gain.setTargetAtTime(0, ac.currentTime, 0.05); osc.stop(ac.currentTime + 0.3); lfo.stop(ac.currentTime + 0.3); this._sir = null; }
      return;
    }
    if (this._sir) return;
    const A = this._audio(); if (!A) return;
    const { ac, dest } = A;
    const osc = ac.createOscillator(), lfo = ac.createOscillator(), depth = ac.createGain(), gain = ac.createGain(), lp = ac.createBiquadFilter();
    osc.type = 'square'; osc.frequency.value = 760;
    lfo.type = 'triangle'; lfo.frequency.value = 0.9; depth.gain.value = 220;
    lfo.connect(depth); depth.connect(osc.frequency);
    lp.type = 'lowpass'; lp.frequency.value = 2400;
    gain.gain.value = 0;
    osc.connect(lp); lp.connect(gain); gain.connect(dest);
    osc.start(); lfo.start();
    this._sir = { ac, osc, lfo, gain };
  }

  _click() {
    const A = this._audio(); if (!A) return;
    const { ac, dest } = A, o = ac.createOscillator(), g = ac.createGain(), t = ac.currentTime;
    o.type = 'square'; o.frequency.setValueAtTime(1400, t); o.frequency.exponentialRampToValueAtTime(500, t + 0.06);
    g.gain.setValueAtTime(0.12, t); g.gain.exponentialRampToValueAtTime(0.001, t + 0.08);
    o.connect(g); g.connect(dest); o.start(t); o.stop(t + 0.1);
  }

  // ── mines ──────────────────────────────────────────────────────────────
  _explodeMine(x, y, z) {
    const g = this.game;
    if (this.vw.getBlock(x, y, z) !== MINE) return;
    this.vw.setBlock(x, y, z, 0);
    const c = new THREE.Vector3(x + 0.5, y + 0.2, z + 0.5);
    g.particleSystem?.createExplosion?.(c);
    g.audioManager?.playExplosion?.();
    const p = g.player;
    if (p && !p.godMode) {
      const d = Math.hypot(p.position.x - c.x, p.position.y - 0.9 - c.y, p.position.z - c.z);
      if (d < MINE_R) { p._deathCause = 'Stepped on a mine'; p.takeDamage(MINE_DMG * (1 - d / MINE_R), c); }
    }
    for (const zb of g.zombieManager?.getZombies?.() ?? []) {
      if (!zb?.isAlive?.() || !zb.position) continue;
      const d = zb.position.distanceTo(c);
      if (d < MINE_R) zb.takeDamage(MINE_DMG * 1.5 * (1 - d / MINE_R), false);
    }
  }

  // ── scanning + beams ───────────────────────────────────────────────────
  _scan() {
    const p = this.game.player?.position; if (!p) return;
    const vw = this.vw, px = Math.floor(p.x), py = Math.floor(p.y - 0.9), pz = Math.floor(p.z);
    const D = { mine: [], alarm: [], keypad: [], logger: [], laser: [] };
    for (let x = px - SCAN_R; x <= px + SCAN_R; x++) for (let z = pz - SCAN_R; z <= pz + SCAN_R; z++) for (let y = py - SCAN_Y; y <= py + SCAN_Y; y++) {
      const id = vw.getBlock(x, y, z);
      if (!id) continue;
      if (id === LASER) D.laser.push([x, y, z]);
      else if (id === MINE) D.mine.push([x, y, z]);
      else if (id === ALARM || id === ALARM_LIT) D.alarm.push([x, y, z]);
      else if (id === KEYPAD || id === KEYPAD_ON) D.keypad.push([x, y, z, id]);
      else if (id === LOGGER) D.logger.push([x, y, z]);
    }
    this.devices = D;
    // keypads show green once their locker is open
    for (const [x, y, z, id] of D.keypad) {
      const lk = this._lockerNear(x, y, z);
      const open = lk && vw.getBlock(...lk.split(',').map(Number)) === LOCKER_OPEN;
      if (open && id === KEYPAD) vw.setBlockKeepEntity(x, y, z, 'sc_keypad_active');
      else if (!open && id === KEYPAD_ON) vw.setBlockKeepEntity(x, y, z, 'sc_keypad');
    }
    // loggers note the player walking past
    for (const [x, y, z] of D.logger) {
      if (Math.hypot(x + 0.5 - p.x, z + 0.5 - p.z) > 4 || Math.abs(y - py) > 3) continue;
      const names = this._log(`${x},${y},${z}`);
      if (!names.includes('You')) names.push('You');
    }
    // beams: from each emitter towards +x and +z to the next emitter
    const want = new Map();
    for (const [x, y, z] of D.laser) for (const axis of [0, 2]) {
      for (let k = 1; k <= BEAM_MAX + 1; k++) {
        const bx = x + (axis === 0 ? k : 0), bz = z + (axis === 2 ? k : 0), id = vw.getBlock(bx, y, bz);
        if (id === LASER) { if (k > 1) want.set(`${x},${y},${z}|${axis}|${k - 1}`, { a: [x, y, z], axis, len: k - 1 }); break; }
        if (id && BLOCKS[id]?.solid) break;
      }
    }
    for (const [k, b] of this.beams) if (!want.has(k)) { this.scene?.remove(b.mesh); b.mesh.geometry.dispose(); this.beams.delete(k); }
    for (const [k, b] of want) if (!this.beams.has(k)) { b.mesh = this._beamMesh(b); this.scene?.add(b.mesh); this.beams.set(k, b); }
  }

  _laserTex() {
    if (!this._tex) {
      const t = new THREE.TextureLoader().load((import.meta.env?.BASE_URL ?? '/') + 'textures/securitycraft/laser.png');
      t.magFilter = THREE.NearestFilter; t.minFilter = THREE.NearestFilter; t.generateMipmaps = false;
      t.wrapS = THREE.RepeatWrapping; t.repeat.set(1, 1 / 8); t.colorSpace = THREE.SRGBColorSpace;
      this._tex = t;
      this._mat = new THREE.MeshBasicMaterial({ map: t, color: 0xff3a24, transparent: true, blending: THREE.AdditiveBlending, depthWrite: false, side: THREE.DoubleSide, toneMapped: false });
    }
    return this._mat;
  }

  // two crossed quads, 4px of beam in a 16px-tall strip, along the run
  _beamMesh(b) {
    const L = b.len, h = 0.25, pos = [], uv = [], idx = [];
    const quad = (P) => { const n = pos.length / 3; P.forEach((q) => pos.push(...q)); uv.push(0, 1, L, 1, L, 0, 0, 0); idx.push(n, n + 2, n + 1, n, n + 3, n + 2); };
    quad([[0, h / 2, 0], [L, h / 2, 0], [L, -h / 2, 0], [0, -h / 2, 0]]);
    quad([[0, 0, -h / 2], [L, 0, -h / 2], [L, 0, h / 2], [0, 0, h / 2]]);
    const g = new THREE.BufferGeometry();
    g.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
    g.setAttribute('uv', new THREE.Float32BufferAttribute(uv, 2));
    g.setIndex(idx);
    const m = new THREE.Mesh(g, this._laserTex());
    const [x, y, z] = b.a;
    if (b.axis === 0) m.position.set(x + 1, y + 0.5, z + 0.5);
    else { m.position.set(x + 0.5, y + 0.5, z + 1); m.rotation.y = -Math.PI / 2; }
    m.raycast = () => {}; m.userData.noHit = true; m.userData.noVox = true;
    m.renderOrder = 5;
    return m;
  }

  // ── per frame ──────────────────────────────────────────────────────────
  update(dt) {
    const g = this.game, p = g.player?.position;
    if (!this.vw || !p) return;
    this.t += dt;
    for (let i = this.timers.length - 1; i >= 0; i--) if ((this.timers[i][0] -= dt) <= 0) { const f = this.timers[i][1]; this.timers.splice(i, 1); f(); }
    if ((this.scanT -= dt) <= 0) { this.scanT = 1; this._scan(); }
    if (this._tex) this._tex.offset.y = 1 - (((this.t * 20 / 3) | 0) % 8 + 1) / 8;

    // beams: the player's body box against each beam line
    const fy = p.y - 0.9;
    for (const b of this.beams.values()) {
      const [x, y, z] = b.a, ly = y + 0.5;
      if (ly < fy || ly > fy + 1.8) continue;
      const along = b.axis === 0 ? p.x : p.z, across = b.axis === 0 ? p.z : p.x;
      const lo = (b.axis === 0 ? x : z) + 1, c = (b.axis === 0 ? z : x) + 0.5;
      if (along + 0.3 > lo && along - 0.3 < lo + b.len && Math.abs(across - c) < 0.33) {
        if (this.alarmT < ALARM_TIME - 1) this.trigger(x, y, z, 'Laser tripwire broken');
        break;
      }
    }

    // mines: the player or a parasite standing on one
    if (this.devices.mine.length) {
      const zs = g.zombieManager?.getZombies?.() ?? [];
      for (const [x, y, z] of this.devices.mine) {
        const on = (q, h) => Math.abs(q.x - x - 0.5) < 0.6 && Math.abs(q.z - z - 0.5) < 0.6 && q.y - h >= y - 0.2 && q.y - h <= y + 0.5;
        if (!g.player.godMode && on(p, 0.9)) { this._explodeMine(x, y, z); continue; }
        for (const zb of zs) if (zb?.isAlive?.() && zb.position && on(zb.position, 0.9)) { this._explodeMine(x, y, z); break; }
      }
    }

    // alarm: louder the closer the nearest lit alarm
    if (this.alarmT > 0) {
      this.alarmT -= dt;
      if (this._sir) {
        let d = 1e9;
        for (const k of this.lit) { const [x, y, z] = k.split(',').map(Number); d = Math.min(d, Math.hypot(x + 0.5 - p.x, y + 0.5 - p.y, z + 0.5 - p.z)); }
        if (!this.lit.size && this.alarmAt) d = this.alarmAt.distanceTo(p);
        const v = Math.max(0, 1 - d / 40) * 0.09;
        this._sir.gain.gain.setTargetAtTime(v, this._sir.ac.currentTime, 0.1);
      }
      if (this.alarmT <= 0) this._endAlarm();
    }
  }

  _toast(text, color) {
    const el = document.getElementById('loot-notification');
    if (!el) return;
    el.textContent = text; el.style.color = color;
    el.classList.remove('show'); void el.offsetWidth; el.classList.add('show');
  }

  clear() {
    for (const b of this.beams.values()) { this.scene?.remove(b.mesh); b.mesh.geometry.dispose(); }
    this.beams.clear();
    this.devices = { mine: [], alarm: [], keypad: [], logger: [] };
    this.alarmT = 0; this.lit.clear(); this._siren(false);
    this.logs.clear(); this.released.clear(); this.timers = [];
  }
}
