export class AudioManager {
  constructor(game) {
    this.game = game;
    this.audioContext = null;
    this.masterVolume = 0.8;
    this.sfxVolume = 0.8;
    this.musicVolume = 0.6;
    this.sounds = new Map();
    this.musicTracks = new Map();
    this.initialized = false;

    this.initializeAudio();
  }

  initializeAudio() {
    const AudioContext = window.AudioContext || window.webkitAudioContext;
    if (!AudioContext) {
      console.warn('Web Audio API not supported');
      return;
    }

    try {
      this.audioContext = new AudioContext();
      this.initialized = true;
      this.setupMasterGain();
    } catch (e) {
      console.error('Failed to initialize audio:', e);
    }
  }

  setupMasterGain() {
    if (!this.audioContext) return;

    this.masterGain = this.audioContext.createGain();
    this.masterGain.gain.value = this.masterVolume;
    this.masterGain.connect(this.audioContext.destination);

    this.sfxGain = this.audioContext.createGain();
    this.sfxGain.gain.value = this.sfxVolume;
    this.sfxGain.connect(this.masterGain);

    this.musicGain = this.audioContext.createGain();
    this.musicGain.gain.value = this.musicVolume;
    this.musicGain.connect(this.masterGain);
  }

  createSoundEffect(type) {
    if (!this.audioContext || !this.masterGain) return null;

    const now = this.audioContext.currentTime;
    const osc = this.audioContext.createOscillator();
    const env = this.audioContext.createGain();

    osc.connect(env);
    env.connect(this.sfxGain);

    switch (type) {
      case 'gunshot':
        osc.frequency.value = 100;
        env.gain.setValueAtTime(0.3, now);
        env.gain.exponentialRampToValueAtTime(0.01, now + 0.1);
        osc.start(now);
        osc.stop(now + 0.1);
        break;

      case 'impact':
        osc.frequency.value = 80;
        env.gain.setValueAtTime(0.2, now);
        env.gain.exponentialRampToValueAtTime(0.01, now + 0.05);
        osc.start(now);
        osc.stop(now + 0.05);
        break;

      case 'footstep':
        osc.frequency.value = 150;
        env.gain.setValueAtTime(0.1, now);
        env.gain.exponentialRampToValueAtTime(0.01, now + 0.1);
        osc.start(now);
        osc.stop(now + 0.1);
        break;

      case 'zombiegroan':
        osc.frequency.value = 60;
        env.gain.setValueAtTime(0.15, now);
        env.gain.exponentialRampToValueAtTime(0.02, now + 0.5);
        osc.start(now);
        osc.stop(now + 0.5);
        break;

      case 'pickup':
        osc.frequency.setValueAtTime(400, now);
        osc.frequency.exponentialRampToValueAtTime(600, now + 0.06);
        osc.frequency.exponentialRampToValueAtTime(800, now + 0.12);
        env.gain.setValueAtTime(0.15, now);
        env.gain.exponentialRampToValueAtTime(0.01, now + 0.15);
        osc.start(now);
        osc.stop(now + 0.15);
        break;

      case 'reload':
        osc.type = 'square';
        osc.frequency.setValueAtTime(180, now);
        osc.frequency.linearRampToValueAtTime(120, now + 0.08);
        env.gain.setValueAtTime(0.12, now);
        env.gain.exponentialRampToValueAtTime(0.01, now + 0.12);
        osc.start(now);
        osc.stop(now + 0.12);
        break;

      case 'heartbeat': {
        // Two-thump heartbeat: lub-dub
        const osc2 = this.audioContext.createOscillator();
        const env2 = this.audioContext.createGain();
        osc2.connect(env2);
        env2.connect(this.sfxGain);
        osc.type = 'sine'; osc2.type = 'sine';
        osc.frequency.value = 55; osc2.frequency.value = 50;
        env.gain.setValueAtTime(0, now);
        env.gain.linearRampToValueAtTime(0.35, now + 0.04);
        env.gain.exponentialRampToValueAtTime(0.01, now + 0.22);
        env2.gain.setValueAtTime(0, now + 0.25);
        env2.gain.linearRampToValueAtTime(0.2, now + 0.30);
        env2.gain.exponentialRampToValueAtTime(0.01, now + 0.45);
        osc.start(now); osc.stop(now + 0.22);
        osc2.start(now + 0.25); osc2.stop(now + 0.45);
        break;
      }

      case 'zombiehit':
        osc.type = 'sawtooth';
        osc.frequency.setValueAtTime(90, now);
        osc.frequency.linearRampToValueAtTime(40, now + 0.18);
        env.gain.setValueAtTime(0.22, now);
        env.gain.exponentialRampToValueAtTime(0.01, now + 0.18);
        osc.start(now);
        osc.stop(now + 0.18);
        break;

      case 'scream': {
        // High-pitched rising wail with vibrato
        const lfo = this.audioContext.createOscillator();
        const lfoGain = this.audioContext.createGain();
        lfo.frequency.value = 8;
        lfoGain.gain.value = 40;
        lfo.connect(lfoGain);
        lfoGain.connect(osc.frequency);
        osc.type = 'sawtooth';
        osc.frequency.setValueAtTime(400, now);
        osc.frequency.linearRampToValueAtTime(900, now + 0.4);
        osc.frequency.linearRampToValueAtTime(600, now + 0.8);
        env.gain.setValueAtTime(0.3, now);
        env.gain.exponentialRampToValueAtTime(0.01, now + 0.9);
        lfo.start(now); lfo.stop(now + 0.9);
        osc.start(now); osc.stop(now + 0.9);
        break;
      }

      case 'eat':
        osc.type = 'sine';
        osc.frequency.setValueAtTime(300, now);
        osc.frequency.linearRampToValueAtTime(200, now + 0.08);
        env.gain.setValueAtTime(0.08, now);
        env.gain.exponentialRampToValueAtTime(0.01, now + 0.12);
        osc.start(now);
        osc.stop(now + 0.12);
        break;

      case 'whistle':
        osc.type = 'sine';
        osc.frequency.setValueAtTime(1200, now);
        osc.frequency.linearRampToValueAtTime(1600, now + 0.1);
        osc.frequency.linearRampToValueAtTime(1400, now + 0.25);
        osc.frequency.linearRampToValueAtTime(1800, now + 0.35);
        env.gain.setValueAtTime(0.2, now);
        env.gain.exponentialRampToValueAtTime(0.01, now + 0.4);
        osc.start(now);
        osc.stop(now + 0.4);
        break;

      case 'item_use':
        osc.type = 'sine';
        osc.frequency.setValueAtTime(500, now);
        osc.frequency.exponentialRampToValueAtTime(300, now + 0.15);
        env.gain.setValueAtTime(0.1, now);
        env.gain.exponentialRampToValueAtTime(0.01, now + 0.15);
        osc.start(now);
        osc.stop(now + 0.15);
        break;

      case 'explosion':
        osc.type = 'sawtooth';
        osc.frequency.setValueAtTime(200, now);
        osc.frequency.exponentialRampToValueAtTime(30, now + 0.6);
        env.gain.setValueAtTime(0.5, now);
        env.gain.exponentialRampToValueAtTime(0.01, now + 0.7);
        osc.start(now);
        osc.stop(now + 0.7);
        break;

      default:
        // Unknown type — clean up without playing
        osc.disconnect();
        env.disconnect();
        return;
    }
  }

  playGunshot() { this.createSoundEffect('gunshot'); }
  playReload()   { this.createSoundEffect('reload');  }
  playZombieHit()   { this.playPlayerHurt(); }

  // Melee landing on a mob: dull body thump plus a short slap (noise only)
  playMeleeHit() {
    const ac = this.audioContext;
    if (!ac || !this.sfxGain) return;
    const now = ac.currentTime, k = 0.92 + Math.random() * 0.16;
    this._burst(now, { type: 'lowpass', freq: 320 * k, to: 110, q: 0.7, vol: 0.5, len: 0.12 });
    this._burst(now, { freq: 900 * k, q: 0.8, vol: 0.25, attack: 0.003, len: 0.05 });
  }

  // 1.9+ attack sounds, picked per swing like vanilla: crit > knockback >
  // sweep > strong > weak; 'nodamage' = hit landed inside the target's
  // invulnerability window without out-damaging the previous hit.
  playAttack(kind = 'strong') {
    const ac = this.audioContext;
    if (!ac || !this.sfxGain) return;
    const t = ac.currentTime, k = 0.93 + Math.random() * 0.14;
    switch (kind) {
      case 'crit':      // sharp crack with a bright ring
        this._burst(t, { type: 'highpass', freq: 2600 * k, q: 0.7, vol: 0.32, attack: 0.002, len: 0.07 });
        this._burst(t + 0.012, { freq: 5200 * k, q: 6, vol: 0.14, attack: 0.002, len: 0.16 });
        this._burst(t, { type: 'lowpass', freq: 420 * k, to: 120, q: 0.8, vol: 0.45, len: 0.12 });
        break;
      case 'knockback': // heavy shove
        this._burst(t, { type: 'lowpass', freq: 260 * k, to: 70, q: 0.9, vol: 0.6, len: 0.2 });
        this._burst(t, { freq: 700 * k, q: 0.6, vol: 0.2, attack: 0.004, len: 0.09 });
        break;
      case 'sweep':     // airy whoosh that rises then falls
        this._burst(t, { freq: 900 * k, to: 2800 * k, q: 1.4, vol: 0.28, attack: 0.03, len: 0.22 });
        this._burst(t + 0.05, { type: 'highpass', freq: 3000 * k, q: 0.5, vol: 0.1, attack: 0.02, len: 0.14 });
        break;
      case 'weak':      // limp tap
        this._burst(t, { type: 'lowpass', freq: 600 * k, to: 250, q: 0.6, vol: 0.18, len: 0.06 });
        break;
      case 'nodamage':  // dull glancing tick
        this._burst(t, { freq: 1300 * k, q: 3, vol: 0.12, attack: 0.002, len: 0.04 });
        break;
      default:          // strong: solid punch
        this._burst(t, { freq: 1100 * k, q: 0.9, vol: 0.22, attack: 0.002, len: 0.05 });
    }
  }

  // Shared white-noise buffer for all non-tonal effects
  _noise() {
    const ac = this.audioContext;
    if (!this._noiseBuf) {
      const len = Math.floor(ac.sampleRate * 1.0);
      this._noiseBuf = ac.createBuffer(1, len, ac.sampleRate);
      const d = this._noiseBuf.getChannelData(0);
      for (let i = 0; i < len; i++) d[i] = Math.random() * 2 - 1;
    }
    const src = ac.createBufferSource(); src.buffer = this._noiseBuf;
    src.loopStart = 0; src.loop = true;
    return src;
  }

  // One filtered noise burst: no oscillators, so nothing reads as a "blerp"
  _burst(t, { type = 'bandpass', freq = 800, q = 1, vol = 0.3, attack = 0.004, len = 0.08, to = null, out = null }) {
    const ac = this.audioContext;
    const n = this._noise(), f = ac.createBiquadFilter(), g = ac.createGain();
    f.type = type; f.frequency.setValueAtTime(freq, t); f.Q.value = q;
    if (to) f.frequency.exponentialRampToValueAtTime(to, t + len);
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(vol, t + attack);
    g.gain.exponentialRampToValueAtTime(0.0001, t + len);
    n.connect(f); f.connect(g); g.connect(out || this.sfxGain);
    n.start(t, Math.random() * 0.5); n.stop(t + len + 0.02);
    return g;
  }

  // Player hurt: a blunt body hit (low thump + short crunchy smack).
  // Purely noise-based; repeat hits inside 0.25s are merged.
  playPlayerHurt() {
    const ac = this.audioContext;
    if (!ac || !this.sfxGain) return;
    const now = ac.currentTime;
    if (now - (this._lastHurt ?? -1) < 0.25) return;
    this._lastHurt = now;
    const p = 0.9 + Math.random() * 0.2;
    this._burst(now, { type: 'lowpass', freq: 380 * p, to: 140, q: 0.7, vol: 0.55, len: 0.14 });
    this._burst(now, { type: 'bandpass', freq: 1700 * p, q: 0.9, vol: 0.22, attack: 0.002, len: 0.045 });
  }

  // Footstep: a soft scuff whose colour follows the ground material
  playFootstep(material = 'grass') {
    const ac = this.audioContext;
    if (!ac || !this.sfxGain) return;
    const now = ac.currentTime, r = 0.85 + Math.random() * 0.3;
    const m = String(material);
    const [freq, q, len, vol] =
      /stone|cobble|ore|brick|bedrock|furnace/.test(m) ? [1300, 1.4, 0.06, 0.09] :
      /log|plank|wood|table|chest|door/.test(m)        ? [650, 1.6, 0.07, 0.10] :
      /sand|gravel/.test(m)                            ? [2200, 0.8, 0.09, 0.07] :
      /snow|wool/.test(m)                              ? [900, 0.6, 0.10, 0.06] :
      /glass/.test(m)                                  ? [2600, 2.0, 0.05, 0.06] :
                                                         [1500, 0.7, 0.08, 0.06];   // grass, dirt, leaves
    this._burst(now, { freq: freq * r, q, vol, len, attack: 0.006 });
  }

  // Parasite growl: raspy band-passed noise with a fast tremble, no pitch
  playZombieGroan() {
    const ac = this.audioContext;
    if (!ac || !this.sfxGain) return;
    const now = ac.currentTime, len = 0.55 + Math.random() * 0.3;
    const trem = ac.createGain(); trem.gain.value = 0.5; trem.connect(this.sfxGain);
    const lfo = ac.createOscillator(), depth = ac.createGain();
    lfo.frequency.value = 22 + Math.random() * 10; depth.gain.value = 0.5;
    lfo.connect(depth); depth.connect(trem.gain);
    this._burst(now, { freq: 420 + Math.random() * 120, to: 260, q: 3, vol: 0.16, attack: 0.08, len, out: trem });
    lfo.start(now); lfo.stop(now + len + 0.05);
  }

  playImpact()   { this.createSoundEffect('impact');  }
  playPickup()   { this.createSoundEffect('pickup');  }
  playHeartbeat() { this.createSoundEffect('heartbeat'); }
  playScream()   { this.createSoundEffect('scream');  }
  playEat()       { this.createSoundEffect('eat');       }
  playWhistle()   { this.createSoundEffect('whistle');  }
  playItemUse()   { this.createSoundEffect('item_use'); }
  playExplosion() { this.createSoundEffect('explosion');}

  // Vanilla-style GUI button click: short bright tick with a fast decay
  playClick() {
    const ctx = this.audioContext; if (!ctx || !this.sfxGain) return;
    const t = ctx.currentTime, o = ctx.createOscillator(), g = ctx.createGain();
    o.type = 'square'; o.frequency.setValueAtTime(1900, t); o.frequency.exponentialRampToValueAtTime(700, t + 0.03);
    g.gain.setValueAtTime(0.0001, t); g.gain.exponentialRampToValueAtTime(0.12, t + 0.002); g.gain.exponentialRampToValueAtTime(0.0001, t + 0.05);
    const f = ctx.createBiquadFilter(); f.type = 'bandpass'; f.frequency.value = 1400; f.Q.value = 0.8;
    o.connect(f); f.connect(g); g.connect(this.sfxGain); o.start(t); o.stop(t + 0.06);
  }

  // Short square-wave beeps, one per frequency (keypad granted / denied)
  playTone(freqs = [880], dur = 0.08) {
    const ctx = this.audioContext; if (!ctx || !this.sfxGain) return;
    freqs.forEach((f, i) => {
      const t = ctx.currentTime + i * (dur + 0.02), o = ctx.createOscillator(), g = ctx.createGain();
      o.type = 'square'; o.frequency.setValueAtTime(f, t);
      g.gain.setValueAtTime(0.0001, t); g.gain.exponentialRampToValueAtTime(0.08, t + 0.005);
      g.gain.setValueAtTime(0.08, t + dur - 0.01); g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
      o.connect(g); g.connect(this.sfxGain); o.start(t); o.stop(t + dur + 0.01);
    });
  }

  setSFXVolume(value) {
    this.sfxVolume = Math.max(0, Math.min(1, value));
    if (this.sfxGain) this.sfxGain.gain.value = this.sfxVolume;
  }

  getMasterVolume() {
    return this.masterVolume;
  }

  getSFXVolume() {
    return this.sfxVolume;
  }

  getMusicVolume() {
    return this.musicVolume;
  }

  isInitialized() {
    return this.initialized;
  }

  playMusic(src) {
    if (this._musicEl) {
      this._musicEl.pause();
      this._musicEl.src = '';
    }
    const audio = document.createElement('audio');
    audio.src = src;
    audio.loop = true;
    audio.volume = Math.min(1, this.musicVolume * this.masterVolume);
    this._musicEl = audio;

    const tryPlay = () => {
      this.resume();
      audio.play().catch(() => {});
    };
    tryPlay();
    // Browsers block autoplay until a user gesture — retry on first click
    document.addEventListener('click', tryPlay, { once: true });
  }

  stopMusic() {
    if (this._musicEl) {
      this._musicEl.pause();
      this._musicEl.src = '';
      this._musicEl = null;
    }
  }

  setMusicVolume(value) {
    this.musicVolume = Math.max(0, Math.min(1, value));
    if (this.musicGain) this.musicGain.gain.value = this.musicVolume;
    if (this._musicEl) this._musicEl.volume = Math.min(1, this.musicVolume * this.masterVolume);
  }

  setMasterVolume(value) {
    this.masterVolume = Math.max(0, Math.min(1, value));
    if (this.masterGain) this.masterGain.gain.value = this.masterVolume;
    if (this._musicEl) this._musicEl.volume = Math.min(1, this.musicVolume * this.masterVolume);
  }

  resume() {
    if (this.audioContext && this.audioContext.state === 'suspended') {
      this.audioContext.resume();
    }
  }
}
