// Atmosphere.js — one shared model of sky, sun, moon, fog and exposure.
//
// The sky dome, terrain, clouds and fog all read the same uniforms and the
// same GLSL (ATMOS_GLSL), so the far terrain fades into exactly the colour
// of the sky behind it and sunsets tint everything consistently. Lighting is
// computed in linear HDR and mapped to the screen with one filmic curve.
//
// Model (cheap analytic approximations, not a full scattering sim):
//  - sun colour = solar white attenuated by an airmass term per channel, so
//    it goes warm and dim as the sun sets;
//  - sky = zenith -> horizon gradient (whose colours follow the sun height)
//    plus a forward-scattering glow around the sun;
//  - skylight ambient = the sky's average colour, used for every surface
//    that can see the sky (scaled by its voxel sky-light level);
//  - at night the moon takes over as a dim, cool, shadow-casting light.

import * as THREE from 'three';

const L = (h) => new THREE.Color(h).convertSRGBToLinear();
const SKY = {
  // [zenith, horizon] (sRGB authored, converted to linear)
  day:   [L(0x4f86e8), L(0xb4d0f2)],
  low:   [L(0x3c63b4), L(0xd6b8a6)],   // sun ~10 degrees up: warm horizon
  dusk:  [L(0x24305e), L(0xc86a48)],   // sun on the horizon
  blue:  [L(0x0c1430), L(0x2a3458)],   // civil twilight, sun just below
  night: [L(0x040917), L(0x0b1428)],
};

export const ATMOS_GLSL = /* glsl */`
uniform vec3 uSunDir;        // towards the sun (normalised)
uniform vec3 uLightDir;      // towards the active shadow light (sun by day, moon by night)
uniform vec3 uSunCol;        // direct light colour * intensity (linear HDR)
uniform vec3 uSunGlow;       // forward-scatter glow colour around the sun
uniform vec3 uAmbCol;        // skylight ambient for fully sky-lit surfaces
uniform vec3 uZenith;
uniform vec3 uHorizon;
uniform float uExposure;
uniform float uEyeSky;       // 0..1, how much sky the camera can see (caves dim the fog)

vec3 atmosSky(vec3 dir) {
  float h = dir.y;
  float up = clamp(h, 0.0, 1.0);
  vec3 c = mix(uHorizon, uZenith, pow(up, 0.55));
  // below the horizon: a slightly darker haze instead of a hard edge
  c = mix(c, uHorizon * 0.72, smoothstep(0.0, -0.35, h));
  float mu = max(dot(dir, uSunDir), 0.0);
  float band = pow(1.0 - abs(h), 5.0);
  c += uSunGlow * (pow(mu, 6.0) * (0.25 + 0.75 * band) + pow(mu, 48.0) * 0.8);
  return c * 1.25;
}
// Filmic curve (Narkowicz ACES fit) with a touch of extra saturation
vec3 atmosTonemap(vec3 x) {
  x *= uExposure;
  vec3 m = (x * (2.51 * x + 0.03)) / (x * (2.43 * x + 0.59) + 0.14);
  float l = dot(m, vec3(0.2126, 0.7152, 0.0722));
  return clamp(mix(vec3(l), m, 1.12), 0.0, 1.0);
}
`;

export class Atmosphere {
  constructor() {
    this.uniforms = {
      uSunDir: { value: new THREE.Vector3(0, 1, 0) },
      uLightDir: { value: new THREE.Vector3(0, 1, 0) },
      uSunCol: { value: new THREE.Color(3, 3, 3) },
      uSunGlow: { value: new THREE.Color(1, 1, 1) },
      uAmbCol: { value: new THREE.Color(0.5, 0.6, 0.8) },
      uZenith: { value: new THREE.Color() },
      uHorizon: { value: new THREE.Color() },
      uExposure: { value: 0.75 },
      uEyeSky: { value: 1 },
    };
    this.daylight = 1;          // 0 night .. 1 noon (for gameplay-facing code)
    this.moonUp = 0;
    this._z = new THREE.Color(); this._h = new THREE.Color();
    this._eyeSky = 1;
  }

  // sunDir: normalised vector towards the sun
  update(sunDir, dt = 0.016, eyeSky = 1) {
    const U = this.uniforms, e = sunDir.y;
    U.uSunDir.value.copy(sunDir);

    // sky gradient keyed on sun elevation
    const key = (a, b, t) => { this._z.copy(a[0]).lerp(b[0], t); this._h.copy(a[1]).lerp(b[1], t); };
    if (e > 0.35) key(SKY.day, SKY.day, 0);
    else if (e > 0.12) key(SKY.low, SKY.day, (e - 0.12) / 0.23);
    else if (e > 0.0) key(SKY.dusk, SKY.low, e / 0.12);
    else if (e > -0.12) key(SKY.blue, SKY.dusk, (e + 0.12) / 0.12);
    else if (e > -0.3) key(SKY.night, SKY.blue, (e + 0.3) / 0.18);
    else key(SKY.night, SKY.night, 0);
    U.uZenith.value.copy(this._z); U.uHorizon.value.copy(this._h);

    // direct sunlight: airmass-attenuated white, fading out at the horizon
    const air = 1 / (Math.max(e, 0) + 0.11);
    const sunUp = smooth(-0.04, 0.12, e);
    const sr = Math.exp(-0.035 * air), sg = Math.exp(-0.085 * air), sb = Math.exp(-0.2 * air);
    const sunI = 1.65 * sunUp;
    // moon: opposite the sun, cool and dim
    const moonUp = smooth(-0.04, 0.15, -e);
    this.moonUp = moonUp;
    const moonI = 0.16 * moonUp;
    if (sunUp >= moonUp) {
      U.uSunCol.value.setRGB(sr * sunI, sg * sunI, sb * sunI);
      U.uLightDir.value.copy(sunDir);
    } else {
      U.uSunCol.value.setRGB(0.55 * moonI, 0.68 * moonI, 1.0 * moonI);
      U.uLightDir.value.copy(sunDir).negate();
    }
    // the light fades to zero at the swap, so the hand-over is invisible
    if (Math.abs(e) < 0.04) U.uSunCol.value.multiplyScalar(Math.abs(e) / 0.04);

    // glow around the sun: strongest (and reddest) at sunset
    const glowK = (0.35 + 1.4 * smooth(0.4, 0.0, e)) * smooth(-0.15, 0.02, e);
    U.uSunGlow.value.setRGB(sr * glowK, sg * glowK * 0.9, sb * glowK * 0.75);

    // skylight ambient: average sky colour, lifted so shade is never murky
    const zen = this._z, hor = this._h;
    // Real skylight is far less saturated than the zenith colour (it is
    // the whole hemisphere, clouds and bounce light included), so keep only
    // a cool tint of the sky hue at roughly the sky's brightness.
    const ar = zen.r * 0.45 + hor.r * 0.55, ag = zen.g * 0.45 + hor.g * 0.55, ab = zen.b * 0.45 + hor.b * 0.55;
    const al = ar * 0.2126 + ag * 0.7152 + ab * 0.0722, sat = 0.2, k = 1.3;
    U.uAmbCol.value.setRGB(
      (al + (ar - al) * sat) * k + 0.010,
      (al + (ag - al) * sat) * k + 0.013,
      (al + (ab - al) * sat) * k + 0.024,
    );

    // eye adaptation for caves: fog/sky darken smoothly underground
    this._eyeSky += (eyeSky - this._eyeSky) * Math.min(1, dt * 2);
    U.uEyeSky.value = this._eyeSky;
    // exposure opens up a little at night so moonlit terrain stays readable
    // ...and eyes adapt underground: up to ~2x exposure with no sky in view
    U.uExposure.value = (0.62 + 0.75 * smooth(0.1, -0.25, e)) * (1 + 0.9 * (1 - this._eyeSky));
    this.daylight = Math.max(sunUp, 0.12 * moonUp);
  }
}

function smooth(a, b, x) {
  const t = Math.max(0, Math.min(1, (x - a) / (b - a)));
  return t * t * (3 - 2 * t);
}
