import * as THREE from 'three';
import { ZombieBase } from './ZombieBase.js';

export class Armored extends ZombieBase {
  constructor(x, z, game) {
    super(x, z, game, {
      type: 'armored',
      health: 180,
      maxHealth: 180,
      damage: 25,
      speed: 1.6,
      attackRange: 2.2,
      aggroRange: 28,
      attackCooldown: 2.2
    });
    this._armorIntact = true;
  }

  createMesh() {
    // Dead riot cop: dark navy uniform under salvaged riot gear
    const { group, refs } = this.buildHumanoid({
      shirtColor: 0x23272e,
      pantsColor: 0x1d2025,
      bald: true, // helmet covers the skull
      gore: 2,
      hunch: 0.18
    });

    const gearMat = new THREE.MeshStandardMaterial({ color: 0x181b1f, metalness: 0.35, roughness: 0.6 });
    const helmMat = new THREE.MeshStandardMaterial({ color: 0x2a2d31, metalness: 0.35, roughness: 0.55 });
    const addGear = (mesh, parent) => {
      mesh.castShadow = true;
      mesh.receiveShadow = true;
      parent.add(mesh);
      this._armorMeshes.push(mesh);
      return mesh;
    };
    this._armorMeshes = [];

    // Salvaged riot gear the host died in, with chitin bursting through the gaps
    const hb = refs.headBox;
    const plate = addGear(new THREE.Mesh(new THREE.BoxGeometry(0.48, 0.3, 0.06), gearMat), refs.torsoGroup);
    plate.position.set(0, 0.39, 0.14);

    // Shoulder pads riding the shoulder pivots (swing with the arms)
    for (const arm of [refs.armL, refs.armR]) {
      const pad = addGear(new THREE.Mesh(new THREE.BoxGeometry(0.28, 0.1, 0.28), gearMat), arm.shoulder);
      pad.position.set(0, 0.08, 0);
    }

    // Helmet shell over the upper skull + dark visor slab
    const helm = addGear(new THREE.Mesh(new THREE.BoxGeometry(hb.w + 0.05, 0.14, hb.d + 0.05), helmMat), refs.headGroup);
    helm.position.set(0, hb.cy + hb.h / 2 - 0.03, 0);
    const visorMat = new THREE.MeshStandardMaterial({
      color: 0x88aacc, transparent: true, opacity: 0.35,
      metalness: 0.2, roughness: 0.25
    });
    const visor = addGear(new THREE.Mesh(new THREE.BoxGeometry(hb.w, 0.1, 0.03), visorMat), refs.headGroup);
    visor.position.set(0, hb.cy + 0.02, hb.d / 2 + 0.03);
    visor.castShadow = false;

    this.finalizeMesh(group);
  }

  takeDamage(amount, isHeadshot = false) {
    // Armor reduces bullet damage 70% unless headshot
    const reduced = isHeadshot ? amount : amount * 0.3;
    if (!isHeadshot && this._armorIntact) {
      // Spark flash on armor hit
      if (this.game.particleSystem) {
        const pos = this.position.clone();
        pos.y += 0.7;
        this.game.particleSystem.createSpark?.(pos) ?? this.game.particleSystem.createBlood(pos, 3);
      }
    }
    super.takeDamage(reduced);
  }

  dropLoot() {
    const wi = this.game.worldItemSystem;
    if (!wi) return;
    const px = this.position.x, pz = this.position.z;
    const py = this.groundYAt(px, pz) + 0.12;
    wi.spawnItem('armor_vest', px, py, pz, 1);
    wi.spawnItem('armor_helmet', px + 0.3, py, pz, 1);
    if (Math.random() < 0.5) wi.spawnItem('ammo_556', px, py, pz + 0.3, 15);
    if (Math.random() < 0.35) wi.spawnItem('weapon_rifle_found', px - 0.3, py, pz, 1);
  }
}
