// McHud.js — vanilla-layout survival HUD.
//
// Laid out on vanilla's GUI-pixel grid (one "u" = one GUI pixel, scaled by
// the Minecraft "Auto" GUI-scale rule): 182x22 hotbar on the bottom edge, 5u
// XP bar above it, 10 hearts (left, top edge 39u above the screen bottom) and
// 10 hunger haunches (right, filling right-to-left) as 9x9 sprites spaced 8u,
// armor row above the hearts that only appears while armor is worn.
// Vanilla (Gui.java / wiki) behaviour: health shows rounded UP to the next
// half heart; the row blinks for 20 ticks after damage and 10 after healing
// (flipping every 3 ticks) with lost health drawn as white ghosts; at <= 2
// hearts every heart drops 0-1px each tick; haunches only shake once
// saturation is gone, every (food*3+1) ticks. Poison/infection turns hearts
// green, hypothermia ice blue. All sprites are original pixel art drawn in
// code (see GuiSprites.js); no game assets are used.

import { installGuiSprites, statIcon } from './GuiSprites.js';

// Minecraft "Auto" GUI scale: largest integer with width/s >= 320 and
// height/s >= 240 (capped at 4 so very large monitors stay usable).
function applyGuiScale() {
  const auto = Math.max(1, Math.min(4, Math.floor(innerWidth / 320), Math.floor(innerHeight / 240)));
  const s = window.__mcGuiScale ? Math.min(auto, window.__mcGuiScale) : auto;
  document.documentElement.style.setProperty('--u', s + 'px');
  document.documentElement.style.setProperty('--us', String(s));
}

const ROWS = {
  health: { kind: 'heart', half: 'left' },
  hunger: { kind: 'food', half: 'right' },
  armor:  { kind: 'armor', half: 'left' },
};

let _els = null, _icons = null;
let _lastHp = null, _ghostFrom = 0, _blinkUntil = 0, _tick = 0, _lastTickAt = 0;
const VARIANTS = [null, 'poison', 'frozen', 'wither', 'gold'];

export function initMcHud() {
  if (_els) return;
  const hud = document.getElementById('hud');
  if (!hud) return;
  installGuiSprites();
  applyGuiScale();
  addEventListener('resize', applyGuiScale);

  const wrap = document.createElement('div');
  wrap.id = 'mc-stats';
  _els = {}; _icons = {};
  for (const [key, row] of Object.entries(ROWS)) {
    const k = row.kind, h = row.half;
    const set = (variant) => ({
      full: statIcon(k, 'full', { variant }), half: statIcon(k, 'half', { halfSide: h, variant }), empty: statIcon(k, 'empty'),
      // blink frames: white rim, health lost since the hit shown as white ghosts
      fullF: statIcon(k, 'full', { flash: true, variant }), halfF: statIcon(k, 'half', { halfSide: h, flash: true, variant }),
      emptyF: statIcon(k, 'empty', { flash: true }), ghostF: statIcon(k, 'empty', { flash: true, ghost: true }),
      halfGhostF: statIcon(k, 'half', { halfSide: h, flash: true, ghost: true, variant }),
    });
    _icons[key] = {};
    for (const v of (k === 'heart' ? VARIANTS : [null])) _icons[key][v || 'normal'] = set(v);
    const rowEl = document.createElement('div');
    rowEl.className = 'mc-row mc-' + key;
    const spans = [];
    for (let i = 0; i < 10; i++) {
      const s = document.createElement('span');
      s.className = 'mc-icon';
      rowEl.appendChild(s);
      spans.push(s);
    }
    _els[key] = { row: rowEl, spans };
    wrap.appendChild(rowEl);
  }
  // air bubbles above the hunger bar, only while the head is under water
  {
    const rowEl = document.createElement('div');
    rowEl.className = 'mc-row mc-air';
    const spans = [];
    for (let i = 0; i < 10; i++) { const sp = document.createElement('span'); sp.className = 'mc-icon'; rowEl.appendChild(sp); spans.push(sp); }
    _els.air = { row: rowEl, spans };
    _icons.air = statIcon('bubble', 'full');
    wrap.appendChild(rowEl);
  }
  hud.appendChild(wrap);
}

function setImg(span, want) { if (span._w !== want) { span.style.backgroundImage = want; span._w = want; } }

// pts: 0..20 half-icons; blink: { from } when the row is in a white frame
function renderRow(key, pts, blink = null, variant = null) {
  const r = _els?.[key];
  if (!r) return;
  const ic = _icons[key][variant || 'normal'] || _icons[key].normal;
  for (let i = 0; i < 10; i++) {
    const left = pts - i * 2;
    let want;
    if (blink) {
      const was = blink.from - i * 2;
      if (left >= 2) want = ic.fullF;
      else if (left === 1) want = was >= 2 ? ic.halfGhostF : ic.halfF;
      else want = was >= 1 ? ic.ghostF : ic.emptyF;
    } else {
      want = left >= 2 ? ic.full : left === 1 ? ic.half : ic.empty;
    }
    setImg(r.spans[i], want);
  }
}

function offset(spans, fn) {
  for (const s of spans) {
    const dy = fn();
    if (s._dy !== dy) { s._dy = dy; s.style.transform = dy ? `translateY(calc(var(--u) * ${dy}))` : ''; }
  }
}

const pts20 = (pct) => Math.max(0, Math.min(20, Math.ceil(Math.max(0, pct) / 5 - 1e-6)));

export function updateMcHud(stats) {
  if (!_els) return;
  const now = performance.now();
  // advance the 20 Hz GUI tick
  const newTick = now - _lastTickAt >= 50;
  if (newTick) { _lastTickAt = now; _tick++; }

  const hpPts = pts20(stats.health);
  if (_lastHp !== null && hpPts !== _lastHp) {
    if (hpPts < _lastHp) {
      // damage: 20-tick blink; remember the pre-hit value for the ghosts
      _ghostFrom = _tick < _blinkUntil ? Math.max(_ghostFrom, _lastHp) : _lastHp;
      _blinkUntil = _tick + 20;
    } else {
      _ghostFrom = hpPts;
      _blinkUntil = _tick + 10;
    }
  }
  _lastHp = hpPts;
  const blinking = _blinkUntil > _tick && Math.floor((_blinkUntil - _tick) / 3) % 2 === 1;
  renderRow('health', hpPts, blinking ? { from: Math.max(_ghostFrom, hpPts) } : null, stats.heart);
  const food = pts20(stats.hunger);
  renderRow('hunger', food);
  const ar = pts20(stats.armor ?? 0);
  renderRow('armor', ar);
  _els.armor.row.style.visibility = ar > 0 ? 'visible' : 'hidden';
  // vanilla: 10 bubbles of 30 ticks each, shown only below full air
  const air = stats.air ?? 300, bubbles = Math.max(0, Math.ceil(air / 30));
  _els.air.row.style.visibility = air < 300 ? 'visible' : 'hidden';
  _els.air.spans.forEach((sp, i) => setImg(sp, i < bubbles ? _icons.air : 'none'));

  if (!newTick) return;
  // Low health (<= 2 hearts): each heart independently drops 0 or 1px
  if (hpPts <= 4) offset(_els.health.spans, () => (Math.random() < 0.5 ? 0 : 1));
  else offset(_els.health.spans, () => 0);
  // Out of saturation: haunches shake -1..+1px, more often the emptier the bar
  const shake = (stats.saturation ?? 1) <= 0 && _tick % (food * 3 + 1) === 0;
  offset(_els.hunger.spans, () => (shake ? Math.floor(Math.random() * 3) - 1 : 0));
}
